INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('itzzjustmateo/polris/web-design-guidelines', 'web-design-guidelines', 'itzzjustmateo', 'polris', 'community', 'web-design-guidelines itzzjustmateo polris community Polaris是一款基于AI的代码编辑器，提供高效的编码体验 PolarisはAIエージェントを搭載したコードエディター Polaris는 AI 기술을 기반으로 하는 코드 편집기 Polaris es un editor de código completo con tecnología de IA para mejorar tu diseño web Polaris est un éditeur de code complet avec technologie d''IA pour améliorer votre conception web Polaris ist ein vollständiger Code-Editor mit KI-Technologie für verbessertes Webdesign Polaris é um editor de código completo alimentado por IA para desenvolvedores web, oferecendo recursos avançados de design e desenvolvimento Polaris - полный ИИ-поддерживающий редактор кода для веб-разработчиков, предлагающий расширенные возможности дизайна и разработки Polaris هو محرر رمز كامل مدعوم بالذكاء الاصطناعي لمنشئي الويب، يقدم ميزات متقدمة من التصميم والتنمية Polaris, a complete AI-powered code editor AI代码编辑器 Polaris代码编辑器 如何使用Polaris Polaris安装教程 Polaris与其他编辑器的比较 代码编辑器推荐 AI代码补全 智能代码检查 Polaris, a complete AI-powered code editor');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Gstxxx/Cantina/tailwind-design-system', 'community', 'Gstxxx', 'Cantina', 'Gstxxx/Cantina', 'tailwind-design-system', 0, 0, 57, '2026-03-04T13:07:01.905Z', '2026-03-04T14:58:45.909Z', 'd010d2f9bb19b6aca7c51f460fb9b32564dbebc09610ea873abb636232d2fe26', '{"id":"Gstxxx/Cantina/tailwind-design-system","name":"tailwind-design-system","description":{"zh":"Tailwind设计系统AI工具是一个帮助开发者构建控制台和客户管理系统的项目，使用React和Node.js等技术","ja":"TailwindデザインシステムAIエージェントは、ReactやNode.jsなどの技術を使用してコンソールと顧客管理システムを構築するためのプロジェクトです","ko":"Tailwind 디자인 시스템 AI 에이전트는 React와 Node.js 등을 사용하여 콘솔과 고객 관리 시스템을 구축하는 프로젝트입니다","es":"Tailwind es una herramienta de diseño que puede ayudar en la creación de sistemas de gestión para cantinas y negocios pequeños","fr":"Tailwind est un outil de conception qui peut aider à créer des systèmes de gestion pour les cantines et les petites entreprises","de":"Tailwind ist ein Design-Tool, das bei der Erstellung von Verwaltungssystemen für Kantinen und kleine Unternehmen helfen kann","pt":"O sistema de design Tailwind é uma ferramenta para ajudar no desenvolvimento de interfaces de usuário","ru":"Система дизайна Tailwind - это инструмент для помощи в разработке интерфейсов пользователя","ar":"نظام تصميم تيلويند هو أداة لمساعدة في تطوير واجهات المستخدم","en":"Projeto que fiz pra ajudar minha mãe na cantina dela com controle de caixa e cadastro de clientes"},"seo":{"title":{"zh":"Tailwind设计系统AI工具","ja":"TailwindデザインシステムAIエージェント","ko":"Tailwind 디자인 시스템 AI 에이전트","es":"Herramientas de diseño de Tailwind para sistemas de gestión","fr":"Outils de conception Tailwind pour systèmes de gestion","de":"Tailwind-Design-Tools für Verwaltungssysteme","pt":"Ferramentas de Design Tailwind para Desenvolvedores","ru":"ИИ Агенты: Система Дизайна Tailwind","ar":"أدوات تصميم تيلويند للبرمجة","en":"tailwind-design-system"},"description":{"zh":"Tailwind设计系统AI工具是一个帮助开发者构建控制台和客户管理系统的项目，使用React和Node.js等技术","ja":"TailwindデザインシステムAIエージェントは、ReactやNode.jsなどの技術を使用してコンソールと顧客管理システムを構築するためのプロジェクトです","ko":"Tailwind 디자인 시스템 AI 에이전트는 React와 Node.js 등을 사용하여 콘솔과 고객 관리 시스템을 구축하는 프로젝트입니다","es":"Tailwind es una herramienta de diseño que puede ayudar en la creación de sistemas de gestión para cantinas y negocios pequeños","fr":"Tailwind est un outil de conception qui peut aider à créer des systèmes de gestion pour les cantines et les petites entreprises","de":"Tailwind ist ein Design-Tool, das bei der Erstellung von Verwaltungssystemen für Kantinen und kleine Unternehmen helfen kann","pt":"O sistema de design Tailwind é uma ferramenta para ajudar no desenvolvimento de interfaces de usuário","ru":"Система дизайна Tailwind - это инструмент для помощи в разработке интерфейсов пользователя","ar":"نظام تصميم تيلويند هو أداة لمساعدة في تطوير واجهات المستخدم","en":"Projeto que fiz pra ajudar minha mãe na cantina dela com controle de caixa e cadastro de clientes"},"definition":{"en":"Projeto que fiz pra ajudar minha mãe na cantina dela com controle de caixa e cadastro de clientes"},"features":{"zh":["使用Tailwind CSS构建响应式设计","支持React和Node.js等技术","提供强大的控制台和客户管理系统","易于安装和设置","支持多种语言和框架"],"ja":["Tailwind CSSを使用したレスポンシブデザインの構築","ReactやNode.jsなどの技術をサポート","強力なコンソールと顧客管理システムを提供","簡単なインストールと設定","多くの言語とフレームワークをサポート"],"ko":["Tailwind CSS를 사용한 반응형 디자인 구축","React와 Node.js 등 기술 지원","강력한 콘솔과 고객 관리 시스템 제공","쉬운 설치와 설정","다수의 언어와 프레임워크 지원"],"es":["Diseño personalizable","Control de caixa y gestión de clientes","Integración con tecnologías web como React y Node.js","Interfaz de usuario intuitiva","Código abierto y extensible"],"fr":["Conception personnalisable","Contrôle de caisse et gestion de clients","Intégration avec des technologies web comme React et Node.js","Interface utilisateur intuitive","Code open source et extensible"],"de":["Anpassbares Design","Kassen- und Kundenverwaltung","Integration mit Web-Technologien wie React und Node.js","Intuitive Benutzeroberfläche","Open-Source-Code und erweiterbar"],"pt":["Controle de caixa","Cadastro de clientes","Desenvolvimento de interfaces de usuário","Integração com React","Compatibilidade com Node.js","CLI para desenvolvedores"],"ru":["Контроль кассы","Регистрация клиентов","Разработка интерфейсов пользователя","Интеграция с React","Совместимость с Node.js","CLI для разработчиков"],"ar":["مراقبة الصندوق","تسجيل العملاء","تطوير واجهات المستخدم","التكامل مع React","التوافق مع Node.js","CLI للبرمجة"]},"keywords":{"zh":["Tailwind设计系统","AI工具","React","Node.js","控制台","客户管理系统","如何使用Tailwind设计系统","Tailwind设计系统安装","Tailwind设计系统设置指南"],"ja":["Tailwindデザインシステム","AIエージェント","React","Node.js","コンソール","顧客管理システム","Tailwindデザインシステムの使い方","Tailwindデザインシステムのインストール","Tailwindデザインシステムの設定ガイド"],"ko":["Tailwind 디자인 시스템","AI 에이전트","React","Node.js","콘솔","고객 관리 시스템","Tailwind 디자인 시스템 사용법","Tailwind 디자인 시스템 설치","Tailwind 디자인 시스템 설정 가이드"],"es":["herramientas de diseño de Tailwind","sistemas de gestión para cantinas","cómo usar Tailwind","alternativas a Tailwind","Tailwind vs Bootstrap","instalación de Tailwind","guía de configuración de Tailwind"],"fr":["outils de conception Tailwind","systèmes de gestion pour les cantines","comment utiliser Tailwind","alternatives à Tailwind","Tailwind vs Bootstrap","installation de Tailwind","guide de configuration de Tailwind"],"de":["Tailwind-Design-Tools","Verwaltungssysteme für Kantinen","wie man Tailwind verwendet","Alternativen zu Tailwind","Tailwind vs Bootstrap","Installation von Tailwind","Konfigurationsanleitung für Tailwind"],"pt":["como usar Tailwind","o que é Tailwind","Tailwind vs Bootstrap","instalar Tailwind","guia de configuração do Tailwind","alternativas para Tailwind"],"ru":["как использовать Tailwind","что такое Tailwind","Tailwind vs Bootstrap","установить Tailwind","руководство по настройке Tailwind","альтернативы для Tailwind"],"ar":["كيفية استخدام تيلويند","ما هو تيلويند","تيلويند مقابل بوتستрап","تثبيت تيلويند","دليل إعداد تيلويند","بديل لتيلويند"]}},"owner":"Gstxxx","repo":"Cantina","repoPath":"Gstxxx/Cantina","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.905Z","topics":[],"category":"community","skillMd":{"name":"tailwind-design-system","description":"Build scalable design systems with Tailwind CSS v4, design tokens, component libraries, and responsive patterns. Use when creating component libraries, implementing design systems, or standardizing UI patterns.","bodyPreview":"# Tailwind Design System (v4)\n\nBuild production-ready design systems with Tailwind CSS v4, including CSS-first configuration, design tokens, component variants, responsive patterns, and accessibility.\n\n> **Note**: This skill targets Tailwind CSS v4 (2024+). For v3 projects, refer to the [upgrade guide](https://tailwindcss.com/docs/upgrade-guide).\n\n## When to Use This Skill\n\n- Creating a component library with Tailwind v4\n- Implementing design tokens and theming with CSS-first configuration\n- Bui","body":"# Tailwind Design System (v4)\n\nBuild production-ready design systems with Tailwind CSS v4, including CSS-first configuration, design tokens, component variants, responsive patterns, and accessibility.\n\n> **Note**: This skill targets Tailwind CSS v4 (2024+). For v3 projects, refer to the [upgrade guide](https://tailwindcss.com/docs/upgrade-guide).\n\n## When to Use This Skill\n\n- Creating a component library with Tailwind v4\n- Implementing design tokens and theming with CSS-first configuration\n- Building responsive and accessible components\n- Standardizing UI patterns across a codebase\n- Migrating from Tailwind v3 to v4\n- Setting up dark mode with native CSS features\n\n## Key v4 Changes\n\n| v3 Pattern                            | v4 Pattern                                                            |\n| ------------------------------------- | --------------------------------------------------------------------- |\n| `tailwind.config.ts`                  | `@theme` in CSS                                                       |\n| `@tailwind base/components/utilities` | `@import \"tailwindcss\"`                                               |\n| `darkMode: \"class\"`                   | `@custom-variant dark (&:where(.dark, .dark *))`                      |\n| `theme.extend.colors`                 | `@theme { --color-*: value }`                                         |\n| `require(\"tailwindcss-animate\")`      | CSS `@keyframes` in `@theme` + `@starting-style` for entry animations |\n\n## Quick Start\n\n```css\n/* app.css - Tailwind v4 CSS-first configuration */\n@import \"tailwindcss\";\n\n/* Define your theme with @theme */\n@theme {\n  /* Semantic color tokens using OKLCH for better color perception */\n  --color-background: oklch(100% 0 0);\n  --color-foreground: oklch(14.5% 0.025 264);\n\n  --color-primary: oklch(14.5% 0.025 264);\n  --color-primary-foreground: oklch(98% 0.01 264);\n\n  --color-secondary: oklch(96% 0.01 264);\n  --color-secondary-foreground: oklch(14.5% 0.025 264);\n\n  --color-muted: oklch(96% 0.01 264);\n  --color-muted-foreground: oklch(46% 0.02 264);\n\n  --color-accent: oklch(96% 0.01 264);\n  --color-accent-foreground: oklch(14.5% 0.025 264);\n\n  --color-destructive: oklch(53% 0.22 27);\n  --color-destructive-foreground: oklch(98% 0.01 264);\n\n  --color-border: oklch(91% 0.01 264);\n  --color-ring: oklch(14.5% 0.025 264);\n\n  --color-card: oklch(100% 0 0);\n  --color-card-foreground: oklch(14.5% 0.025 264);\n\n  /* Ring offset for focus states */\n  --color-ring-offset: oklch(100% 0 0);\n\n  /* Radius tokens */\n  --radius-sm: 0.25rem;\n  --radius-md: 0.375rem;\n  --radius-lg: 0.5rem;\n  --radius-xl: 0.75rem;\n\n  /* Animation tokens - keyframes inside @theme are output when referenced by --animate-* variables */\n  --animate-fade-in: fade-in 0.2s ease-out;\n  --animate-fade-out: fade-out 0.2s ease-in;\n  --animate-slide-in: slide-in 0.3s ease-out;\n  --animate-slide-out: slide-out 0.3s ease-in;\n\n  @keyframes fade-in {\n    from {\n      opacity: 0;\n    }\n    to {\n      opacity: 1;\n    }\n  }\n\n  @keyframes fade-out {\n    from {\n      opacity: 1;\n    }\n    to {\n      opacity: 0;\n    }\n  }\n\n  @keyframes slide-in {\n    from {\n      transform: translateY(-0.5rem);\n      opacity: 0;\n    }\n    to {\n      transform: translateY(0);\n      opacity: 1;\n    }\n  }\n\n  @keyframes slide-out {\n    from {\n      transform: translateY(0);\n      opacity: 1;\n    }\n    to {\n      transform: translateY(-0.5rem);\n      opacity: 0;\n    }\n  }\n}\n\n/* Dark mode variant - use @custom-variant for class-based dark mode */\n@custom-variant dark (&:where(.dark, .dark *));\n\n/* Dark mode theme overrides */\n.dark {\n  --color-background: oklch(14.5% 0.025 264);\n  --color-foreground: oklch(98% 0.01 264);\n\n  --color-primary: oklch(98% 0.01 264);\n  --color-primary-foreground: oklch(14.5% 0.025 264);\n\n  --color-secondary: oklch(22% 0.02 264);\n  --color-secondary-foreground: oklch(98% 0.01 264);\n\n  --color-muted: oklch(22% 0.02 264);\n  --color-muted-foreground: oklch(65% 0.02 264);\n\n  --color-accent: oklch(22% 0.02 264);\n  --color-accent-foreground: oklch(98% 0.01 264);\n\n  --color-destructive: oklch(42% 0.15 27);\n  --color-destructive-foreground: oklch(98% 0.01 264);\n\n  --color-border: oklch(22% 0.02 264);\n  --color-ring: oklch(83% 0.02 264);\n\n  --color-card: oklch(14.5% 0.025 264);\n  --color-card-foreground: oklch(98% 0.01 264);\n\n  --color-ring-offset: oklch(14.5% 0.025 264);\n}\n\n/* Base styles */\n@layer base {\n  * {\n    @apply border-border;\n  }\n\n  body {\n    @apply bg-background text-foreground antialiased;\n  }\n}\n```\n\n## Core Concepts\n\n### 1. Design Token Hierarchy\n\n```\nBrand Tokens (abstract)\n    └── Semantic Tokens (purpose)\n        └── Component Tokens (specific)\n\nExample:\n    oklch(45% 0.2 260) → --color-primary → bg-primary\n```\n\n### 2. Component Architecture\n\n```\nBase styles → Variants → Sizes → States → Overrides\n```\n\n## Patterns\n\n### Pattern 1: CVA (Class Variance Authority) Components\n\n```typescript\n// components/ui/button.tsx\nimport { Slot } from ''@radix-ui/react-slot''\nimport { cva, type VariantProps } from ''class-variance-authority''\nimport { cn } from ''@/lib/utils''\n\nconst buttonVariants = cva(\n  // Base styles - v4 uses native CSS variables\n  ''inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50'',\n  {\n    variants: {\n      variant: {\n        default: ''bg-primary text-primary-foreground hover:bg-primary/90'',\n        destructive: ''bg-destructive text-destructive-foreground hover:bg-destructive/90'',\n        outline: ''border border-border bg-background hover:bg-accent hover:text-accent-foreground'',\n        secondary: ''bg-secondary text-secondary-foreground hover:bg-secondary/80'',\n        ghost: ''hover:bg-accent hover:text-accent-foreground'',\n        link: ''text-primary underline-offset-4 hover:underline'',\n      },\n      size: {\n        default: ''h-10 px-4 py-2'',\n        sm: ''h-9 rounded-md px-3'',\n        lg: ''h-11 rounded-md px-8'',\n        icon: ''size-10'',\n      },\n    },\n    defaultVariants: {\n      variant: ''default'',\n      size: ''default'',\n    },\n  }\n)\n\nexport interface ButtonProps\n  extends React.ButtonHTMLAttributes<HTMLButtonElement>,\n    VariantProps<typeof buttonVariants> {\n  asChild?: boolean\n}\n\n// React 19: No forwardRef needed\nexport function Button({\n  className,\n  variant,\n  size,\n  asChild = false,\n  ref,\n  ...props\n}: ButtonProps & { ref?: React.Ref<HTMLButtonElement> }) {\n  const Comp = asChild ? Slot : ''button''\n  return (\n    <Comp\n      className={cn(buttonVariants({ variant, size, className }))}\n      ref={ref}\n      {...props}\n    />\n  )\n}\n\n// Usage\n<Button variant=\"destructive\" size=\"lg\">Delete</Button>\n<Button variant=\"outline\">Cancel</Button>\n<Button asChild><Link href=\"/home\">Home</Link></Button>\n```\n\n### Pattern 2: Compound Components (React 19)\n\n```typescript\n// components/ui/card.tsx\nimport { cn } from ''@/lib/utils''\n\n// React 19: ref is a regular prop, no forwardRef\nexport function Card({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div\n      ref={ref}\n      className={cn(\n        ''rounded-lg border border-border bg-card text-card-foreground shadow-sm'',\n        className\n      )}\n      {...props}\n    />\n  )\n}\n\nexport function CardHeader({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div\n      ref={ref}\n      className={cn(''flex flex-col space-y-1.5 p-6'', className)}\n      {...props}\n    />\n  )\n}\n\nexport function CardTitle({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLHeadingElement> & { ref?: React.Ref<HTMLHeadingElement> }) {\n  return (\n    <h3\n      ref={ref}\n      className={cn(''text-2xl font-semibold leading-none tracking-tight'', className)}\n      {...props}\n    />\n  )\n}\n\nexport function CardDescription({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLParagraphElement> & { ref?: React.Ref<HTMLParagraphElement> }) {\n  return (\n    <p\n      ref={ref}\n      className={cn(''text-sm text-muted-foreground'', className)}\n      {...props}\n    />\n  )\n}\n\nexport function CardContent({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div ref={ref} className={cn(''p-6 pt-0'', className)} {...props} />\n  )\n}\n\nexport function CardFooter({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div\n      ref={ref}\n      className={cn(''flex items-center p-6 pt-0'', className)}\n      {...props}\n    />\n  )\n}\n\n// Usage\n<Card>\n  <CardHeader>\n    <CardTitle>Account</CardTitle>\n    <CardDescription>Manage your account settings</CardDescription>\n  </CardHeader>\n  <CardContent>\n    <form>...</form>\n  </CardContent>\n  <CardFooter>\n    <Button>Save</Button>\n  </CardFooter>\n</Card>\n```\n\n### Pattern 3: Form Components\n\n```typescript\n// components/ui/input.tsx\nimport { cn } from ''@/lib/utils''\n\nexport interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {\n  error?: string\n  ref?: React.Ref<HTMLInputElement>\n}\n\nexport function Input({ className, type, error, ref, ...props }: InputProps) {\n  return (\n    <div className=\"relative\">\n      <input\n        type={type}\n        className={cn(\n          ''flex h-10 w-full rounded-md border border-border bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50'',\n          error && ''border-destructive focus-visible:ring-destructive'',\n          className\n        )}\n        ref={ref}\n        aria-invalid={!!error}\n        aria-describedby={error ? `${props.id}-error` : undefined}\n        {...props}\n      />\n      {error && (\n        <p\n          id={`${props.id}-error`}\n          className=\"mt-1 text-sm text-destructive\"\n          role=\"alert\"\n        >\n          {error}\n        </p>\n      )}\n    </div>\n  )\n}\n\n// components/ui/label.tsx\nimport { cva, type VariantProps } from ''class-variance-authority''\n\nconst labelVariants = cva(\n  ''text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70''\n)\n\nexport function Label({\n  className,\n  ref,\n  ...props\n}: React.LabelHTMLAttributes<HTMLLabelElement> & { ref?: React.Ref<HTMLLabelElement> }) {\n  return (\n    <label ref={ref} className={cn(labelVariants(), className)} {...props} />\n  )\n}\n\n// Usage with React Hook Form + Zod\nimport { useForm } from ''react-hook-form''\nimport { zodResolver } from ''@hookform/resolvers/zod''\nimport { z } from ''zod''\n\nconst schema = z.object({\n  email: z.string().email(''Invalid email address''),\n  password: z.string().min(8, ''Password must be at least 8 characters''),\n})\n\nfunction LoginForm() {\n  const { register, handleSubmit, formState: { errors } } = useForm({\n    resolver: zodResolver(schema),\n  })\n\n  return (\n    <form onSubmit={handleSubmit(onSubmit)} className=\"space-y-4\">\n      <div className=\"space-y-2\">\n        <Label htmlFor=\"email\">Email</Label>\n        <Input\n          id=\"email\"\n          type=\"email\"\n          {...register(''email'')}\n          error={errors.email?.message}\n        />\n      </div>\n      <div className=\"space-y-2\">\n        <Label htmlFor=\"password\">Password</Label>\n        <Input\n          id=\"password\"\n          type=\"password\"\n          {...register(''password'')}\n          error={errors.password?.message}\n        />\n      </div>\n      <Button type=\"submit\" className=\"w-full\">Sign In</Button>\n    </form>\n  )\n}\n```\n\n### Pattern 4: Responsive Grid System\n\n```typescript\n// components/ui/grid.tsx\nimport { cn } from ''@/lib/utils''\nimport { cva, type VariantProps } from ''class-variance-authority''\n\nconst gridVariants = cva(''grid'', {\n  variants: {\n    cols: {\n      1: ''grid-cols-1'',\n      2: ''grid-cols-1 sm:grid-cols-2'',\n      3: ''grid-cols-1 sm:grid-cols-2 lg:grid-cols-3'',\n      4: ''grid-cols-1 sm:grid-cols-2 lg:grid-cols-4'',\n      5: ''grid-cols-2 sm:grid-cols-3 lg:grid-cols-5'',\n      6: ''grid-cols-2 sm:grid-cols-3 lg:grid-cols-6'',\n    },\n    gap: {\n      none: ''gap-0'',\n      sm: ''gap-2'',\n      md: ''gap-4'',\n      lg: ''gap-6'',\n      xl: ''gap-8'',\n    },\n  },\n  defaultVariants: {\n    cols: 3,\n    gap: ''md'',\n  },\n})\n\ninterface GridProps\n  extends React.HTMLAttributes<HTMLDivElement>,\n    VariantProps<typeof gridVariants> {}\n\nexport function Grid({ className, cols, gap, ...props }: GridProps) {\n  return (\n    <div className={cn(gridVariants({ cols, gap, className }))} {...props} />\n  )\n}\n\n// Container component\nconst containerVariants = cva(''mx-auto w-full px-4 sm:px-6 lg:px-8'', {\n  variants: {\n    size: {\n      sm: ''max-w-screen-sm'',\n      md: ''max-w-screen-md'',\n      lg: ''max-w-screen-lg'',\n      xl: ''max-w-screen-xl'',\n      ''2xl'': ''max-w-screen-2xl'',\n      full: ''max-w-full'',\n    },\n  },\n  defaultVariants: {\n    size: ''xl'',\n  },\n})\n\ninterface ContainerProps\n  extends React.HTMLAttributes<HTMLDivElement>,\n    VariantProps<typeof containerVariants> {}\n\nexport function Container({ className, size, ...props }: ContainerProps) {\n  return (\n    <div className={cn(containerVariants({ size, className }))} {...props} />\n  )\n}\n\n// Usage\n<Container>\n  <Grid cols={4} gap=\"lg\">\n    {products.map((product) => (\n      <ProductCard key={product.id} product={product} />\n    ))}\n  </Grid>\n</Container>\n```\n\n### Pattern 5: Native CSS Animations (v4)\n\n```css\n/* In your CSS file - native @starting-style for entry animations */\n@theme {\n  --animate-dialog-in: dialog-fade-in 0.2s ease-out;\n  --animate-dialog-out: dialog-fade-out 0.15s ease-in;\n}\n\n@keyframes dialog-fade-in {\n  from {\n    opacity: 0;\n    transform: scale(0.95) translateY(-0.5rem);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n@keyframes dialog-fade-out {\n  from {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n  to {\n    opacity: 0;\n    transform: scale(0.95) translateY(-0.5rem);\n  }\n}\n\n/* Native popover animations using @starting-style */\n[popover] {\n  transition:\n    opacity 0.2s,\n    transform 0.2s,\n    display 0.2s allow-discrete;\n  opacity: 0;\n  transform: scale(0.95);\n}\n\n[popover]:popover-open {\n  opacity: 1;\n  transform: scale(1);\n}\n\n@starting-style {\n  [popover]:popover-open {\n    opacity: 0;\n    transform: scale(0.95);\n  }\n}\n```\n\n```typescript\n// components/ui/dialog.tsx - Using native popover API\nimport * as DialogPrimitive from ''@radix-ui/react-dialog''\nimport { cn } from ''@/lib/utils''\n\nconst DialogPortal = DialogPrimitive.Portal\n\nexport function DialogOverlay({\n  className,\n  ref,\n  ...props\n}: React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay> & {\n  ref?: React.Ref<HTMLDivElement>\n}) {\n  return (\n    <DialogPrimitive.Overlay\n      ref={ref}\n      className={cn(\n        ''fixed inset-0 z-50 bg-black/80'',\n        ''data-[state=open]:animate-fade-in data-[state=closed]:animate-fade-out'',\n        className\n      )}\n      {...props}\n    />\n  )\n}\n\nexport function DialogContent({\n  className,\n  children,\n  ref,\n  ...props\n}: React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & {\n  ref?: React.Ref<HTMLDivElement>\n}) {\n  return (\n    <DialogPortal>\n      <DialogOverlay />\n      <DialogPrimitive.Content\n        ref={ref}\n        className={cn(\n          ''fixed left-1/2 top-1/2 z-50 grid w-full max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 border border-border bg-background p-6 shadow-lg sm:rounded-lg'',\n          ''data-[state=open]:animate-dialog-in data-[state=closed]:animate-dialog-out'',\n          className\n        )}\n        {...props}\n      >\n        {children}\n      </DialogPrimitive.Content>\n    </DialogPortal>\n  )\n}\n```\n\n### Pattern 6: Dark Mode with CSS (v4)\n\n```typescript\n// providers/ThemeProvider.tsx - Simplified for v4\n''use client''\n\nimport { createContext, useContext, useEffect, useState } from ''react''\n\ntype Theme = ''dark'' | ''light'' | ''system''\n\ninterface ThemeContextType {\n  theme: Theme\n  setTheme: (theme: Theme) => void\n  resolvedTheme: ''dark'' | ''light''\n}\n\nconst ThemeContext = createContext<ThemeContextType | undefined>(undefined)\n\nexport function ThemeProvider({\n  children,\n  defaultTheme = ''system'',\n  storageKey = ''theme'',\n}: {\n  children: React.ReactNode\n  defaultTheme?: Theme\n  storageKey?: string\n}) {\n  const [theme, setTheme] = useState<Theme>(defaultTheme)\n  const [resolvedTheme, setResolvedTheme] = useState<''dark'' | ''light''>(''light'')\n\n  useEffect(() => {\n    const stored = localStorage.getItem(storageKey) as Theme | null\n    if (stored) setTheme(stored)\n  }, [storageKey])\n\n  useEffect(() => {\n    const root = document.documentElement\n    root.classList.remove(''light'', ''dark'')\n\n    const resolved = theme === ''system''\n      ? (window.matchMedia(''(prefers-color-scheme: dark)'').matches ? ''dark'' : ''light'')\n      : theme\n\n    root.classList.add(resolved)\n    setResolvedTheme(resolved)\n\n    // Update meta theme-color for mobile browsers\n    const metaThemeColor = document.querySelector(''meta[name=\"theme-color\"]'')\n    if (metaThemeColor) {\n      metaThemeColor.setAttribute(''content'', resolved === ''dark'' ? ''#09090b'' : ''#ffffff'')\n    }\n  }, [theme])\n\n  return (\n    <ThemeContext.Provider value={{\n      theme,\n      setTheme: (newTheme) => {\n        localStorage.setItem(storageKey, newTheme)\n        setTheme(newTheme)\n      },\n      resolvedTheme,\n    }}>\n      {children}\n    </ThemeContext.Provider>\n  )\n}\n\nexport const useTheme = () => {\n  const context = useContext(ThemeContext)\n  if (!context) throw new Error(''useTheme must be used within ThemeProvider'')\n  return context\n}\n\n// components/ThemeToggle.tsx\nimport { Moon, Sun } from ''lucide-react''\nimport { useTheme } from ''@/providers/ThemeProvider''\n\nexport function ThemeToggle() {\n  const { resolvedTheme, setTheme } = useTheme()\n\n  return (\n    <Button\n      variant=\"ghost\"\n      size=\"icon\"\n      onClick={() => setTheme(resolvedTheme === ''dark'' ? ''light'' : ''dark'')}\n    >\n      <Sun className=\"size-5 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0\" />\n      <Moon className=\"absolute size-5 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100\" />\n      <span className=\"sr-only\">Toggle theme</span>\n    </Button>\n  )\n}\n```\n\n## Utility Functions\n\n```typescript\n// lib/utils.ts\nimport { type ClassValue, clsx } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n\n// Focus ring utility\nexport const focusRing = cn(\n  \"focus-visible:outline-none focus-visible:ring-2\",\n  \"focus-visible:ring-ring focus-visible:ring-offset-2\",\n);\n\n// Disabled utility\nexport const disabled = \"disabled:pointer-events-none disabled:opacity-50\";\n```\n\n## Advanced v4 Patterns\n\n### Custom Utilities with `@utility`\n\nDefine reusable custom utilities:\n\n```css\n/* Custom utility for decorative lines */\n@utility line-t {\n  @apply relative before:absolute before:top-0 before:-left-[100vw] before:h-px before:w-[200vw] before:bg-gray-950/5 dark:before:bg-white/10;\n}\n\n/* Custom utility for text gradients */\n@utility text-gradient {\n  @apply bg-gradient-to-r from-primary to-accent bg-clip-text text-transparent;\n}\n```\n\n### Theme Modifiers\n\n```css\n/* Use @theme inline when referencing other CSS variables */\n@theme inline {\n  --font-sans: var(--font-inter), system-ui;\n}\n\n/* Use @theme static to always generate CSS variables (even when unused) */\n@theme static {\n  --color-brand: oklch(65% 0.15 240);\n}\n\n/* Import with theme options */\n@import \"tailwindcss\" theme(static);\n```\n\n### Namespace Overrides\n\n```css\n@theme {\n  /* Clear all default colors and define your own */\n  --color-*: initial;\n  --color-white: #fff;\n  --color-black: #000;\n  --color-primary: oklch(45% 0.2 260);\n  --color-secondary: oklch(65% 0.15 200);\n\n  /* Clear ALL defaults for a minimal setup */\n  /* --*: initial; */\n}\n```\n\n### Semi-transparent Color Variants\n\n```css\n@theme {\n  /* Use color-mix() for alpha variants */\n  --color-primary-50: color-mix(in oklab, var(--color-primary) 5%, transparent);\n  --color-primary-100: color-mix(\n    in oklab,\n    var(--color-primary) 10%,\n    transparent\n  );\n  --color-primary-200: color-mix(\n    in oklab,\n    var(--color-primary) 20%,\n    transparent\n  );\n}\n```\n\n### Container Queries\n\n```css\n@theme {\n  --container-xs: 20rem;\n  --container-sm: 24rem;\n  --container-md: 28rem;\n  --container-lg: 32rem;\n}\n```\n\n## v3 to v4 Migration Checklist\n\n- [ ] Replace `tailwind.config.ts` with CSS `@theme` block\n- [ ] Change `@tailwind base/components/utilities` to `@import \"tailwindcss\"`\n- [ ] Move color definitions to `@theme { --color-*: value }`\n- [ ] Replace `darkMode: \"class\"` with `@custom-variant dark`\n- [ ] Move `@keyframes` inside `@theme` blocks (ensures keyframes output with theme)\n- [ ] Replace `require(\"tailwindcss-animate\")` with native CSS animations\n- [ ] Update `h-10 w-10` to `size-10` (new utility)\n- [ ] Remove `forwardRef` (React 19 passes ref as prop)\n- [ ] Consider OKLCH colors for better color perception\n- [ ] Replace custom plugins with `@utility` directives\n\n## Best Practices\n\n### Do''s\n\n- **Use `@theme` blocks** - CSS-first configuration is v4''s core pattern\n- **Use OKLCH colors** - Better perceptual uniformity than HSL\n- **Compose with CVA** - Type-safe variants\n- **Use semantic tokens** - `bg-primary` not `bg-blue-500`\n- **Use `size-*`** - New shorthand for `w-* h-*`\n- **Add accessibility** - ARIA attributes, focus states\n\n### Don''ts\n\n- **Don''t use `tailwind.config.ts`** - Use CSS `@theme` instead\n- **Don''t use `@tailwind` directives** - Use `@import \"tailwindcss\"`\n- **Don''t use `forwardRef`** - React 19 passes ref as prop\n- **Don''t use arbitrary values** - Extend `@theme` instead\n- **Don''t hardcode colors** - Use semantic tokens\n- **Don''t forget dark mode** - Test both themes\n\n## Resources\n\n- [Tailwind CSS v4 Documentation](https://tailwindcss.com/docs)\n- [Tailwind v4 Beta Announcement](https://tailwindcss.com/blog/tailwindcss-v4-beta)\n- [CVA Documentation](https://cva.style/docs)\n- [shadcn/ui](https://ui.shadcn.com/)\n- [Radix Primitives](https://www.radix-ui.com/primitives)\n"},"lastSynced":"2026-03-04T14:58:45.909Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined CSS-first design system configuration with Tailwind CSS v4","zh":"非常适合需要使用Tailwind CSS v4进行流线型CSS-first设计系统配置的前端代理","ja":"Tailwind CSS v4を使用したストリームライン化されたCSS-firstデザインシステム構成を必要とするフロントエンドエージェントに最適","ko":"Tailwind CSS v4를 사용하여 스트림 라인화된 CSS-첫 번째 디자인 시스템 구성을 필요로하는 프론트엔드 에이전트에 적합","es":"Perfecto para Agentes Frontend que necesitan una configuración de sistema de diseño con CSS en primer lugar y Tailwind CSS v4 optimizada","fr":"Parfait pour les agents Frontend qui ont besoin d''une configuration de système de conception CSS en premier avec Tailwind CSS v4 optimisée","de":"Perfekt für Frontend-Agents, die eine optimierte CSS-erstes Designsystem-Konfiguration mit Tailwind CSS v4 benötigen","pt":"Perfeito para Agentes Frontend que precisam de configuração de sistema de design CSS-first simplificada com Tailwind CSS v4","ru":"Идеально для агентов Frontend, которым требуется упрощенная конфигурация системы дизайна CSS-first с Tailwind CSS v4","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى تكوين نظام التصميم الأول للتصميم مع Tailwind CSS v4"},"recommendation":{"en":"Empowers agents to build production-ready design systems with CSS-first configuration, design tokens, component variants, responsive patterns, and accessibility using Tailwind CSS v4, enabling seamless implementation of responsive and accessible UI components","zh":"赋予代理构建生产就绪的设计系统的能力，具有CSS-first配置、设计令牌、组件变体、响应式模式和使用Tailwind CSS v4的无障碍功能，实现响应式和无障碍的UI组件的无缝实现","ja":"CSS-first構成、デザイントークン、コンポーネントバリアント、レスポンシブパターン、およびTailwind CSS v4を使用したアクセシビリティを備えた、生産就緒のデザインシステムを構築するエージェントの能力を付与し、レスポンシブでアクセシブルなUIコンポーネントのシームレスな実装を可能にします","ko":"CSS-첫 번째 구성, 디자인 토큰, 컴포넌트 변형, 반응형 패턴 및 Tailwind CSS v4를 사용한 접근성을 갖춘 생산 준비가 된 디자인 시스템을 구축할 수 있는 에이전트의 능력을 부여하여 반응형 및 접근 가능한 UI 구성 요소의 무중단 구현을 가능하게 함","es":"Habilita a los agentes a crear sistemas de diseño listos para producción con configuración CSS en primer lugar, tokens de diseño, variantes de componentes, patrones responsivos y accesibilidad utilizando Tailwind CSS v4, lo que permite una implementación sin problemas de componentes de interfaz de usuario responsivos y accesibles","fr":"Permet aux agents de créer des systèmes de conception prêts pour la production avec une configuration CSS en premier, des jetons de conception, des variantes de composants, des modèles responsives et une accessibilité en utilisant Tailwind CSS v4, ce qui permet une mise en œuvre sans problème de composants d''interface utilisateur responsives et accessibles","de":"Ermächtigt Agenten, produktionsbereite Designsysteme mit CSS-erstes Konfiguration, Design-Tokens, Komponenten-Varianten, responsiven Mustern und Accessibility unter Verwendung von Tailwind CSS v4 zu erstellen, was eine reibungslose Implementierung von responsiven und zugänglichen Benutzeroberflächen-Komponenten ermöglicht","pt":"Habilita os agentes a criar sistemas de design prontos para produção com configuração CSS-first, tokens de design, variantes de componentes, padrões responsivos e acessibilidade usando Tailwind CSS v4, permitindo implementação sem problemas de componentes de interface do usuário responsivos e acessíveis","ru":"Наделяет агентов возможностью создавать системы дизайна, готовые к производству, с конфигурацией CSS-first, токенами дизайна, вариантами компонентов, отзывчивыми шаблонами и доступностью, используя Tailwind CSS v4, обеспечивая беспроблемную реализацию отзывчивых и доступных компонентов пользовательского интерфейса","ar":"تمكّن العملاء م