INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Gstxxx/Cantina/tailwind-design-system', 'tailwind-design-system', 'Gstxxx', 'Cantina', 'community', 'tailwind-design-system Gstxxx Cantina community Tailwind设计系统AI工具是一个帮助开发者构建控制台和客户管理系统的项目，使用React和Node.js等技术 TailwindデザインシステムAIエージェントは、ReactやNode.jsなどの技術を使用してコンソールと顧客管理システムを構築するためのプロジェクトです Tailwind 디자인 시스템 AI 에이전트는 React와 Node.js 등을 사용하여 콘솔과 고객 관리 시스템을 구축하는 프로젝트입니다 Tailwind es una herramienta de diseño que puede ayudar en la creación de sistemas de gestión para cantinas y negocios pequeños Tailwind est un outil de conception qui peut aider à créer des systèmes de gestion pour les cantines et les petites entreprises Tailwind ist ein Design-Tool, das bei der Erstellung von Verwaltungssystemen für Kantinen und kleine Unternehmen helfen kann O sistema de design Tailwind é uma ferramenta para ajudar no desenvolvimento de interfaces de usuário Система дизайна Tailwind - это инструмент для помощи в разработке интерфейсов пользователя نظام تصميم تيلويند هو أداة لمساعدة في تطوير واجهات المستخدم Projeto que fiz pra ajudar minha mãe na cantina dela com controle de caixa e cadastro de clientes Tailwind设计系统 AI工具 React Node.js 控制台 客户管理系统 如何使用Tailwind设计系统 Tailwind设计系统安装 Tailwind设计系统设置指南 Projeto que fiz pra ajudar minha mãe na cantina dela com controle de caixa e cadastro de clientes');
