INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HaoNgo232/Synapse-Desktop/app-builder', 'app-builder', 'HaoNgo232', 'Synapse-Desktop', 'community', 'app-builder HaoNgo232 Synapse-Desktop community App-Builder能够提取代码库的上下文，并安全地应用AI建议的补丁 App-Builderはコードベースのコンテキストを抽出して、AIの提案されたパッチを安全に適用します 앱 빌ダー는 코드베이스의 컨텍스트를 추출하여 AI가 제안한 패치를 안전하게 적용합니다 El constructor de aplicaciones utiliza inteligencia artificial para extraer contexto de código y aplicar parches sugeridos por IA de manera segura Le constructeur d''applications utilise l''intelligence artificielle pour extraire le contexte de code et appliquer des correctifs suggérés par l''IA de manière sécurisée Der App-Builder nutzt Künstliche Intelligenz, um Kontext aus Codebasis zu extrahieren und von KI vorgeschlagene Patches sicher anzuwenden O app-builder é uma ferramenta de IA que ajuda a extrair contexto de codebase e aplicar patches de IA de forma segura ИИ Агент app-builder - это инструмент, который помогает извлечь контекст кодовой базы и безопасно применить патчи ИИ أداة app-builder هي أداة ذكاء اصطناعي تساعد على استخراج سياق قاعدة الشفرة وتطبيق تصحيحات ذكية Extract codebase context for any LLM (ChatGPT, Claude, Gemini) and safely apply AI-suggested patches with preview, 如何使用App-Builder 什么是AI智能开发工具 App-Builder替代品 App-Builder安装 App-Builder设置指南 AI开发工具比较 代码开发最佳实践 代码库优化 Extract codebase context for any LLM (ChatGPT, Claude, Gemini) and safely apply AI-suggested patches with preview,');
