INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ItsMattG/property-tracker/ralph-execute', 'ralph-execute', 'ItsMattG', 'property-tracker', 'community', 'ralph-execute ItsMattG property-tracker community ai australia drizzle-orm fintech nextjs open-banking postgresql property-investment react saas tailwindcss trpc typescript ralph-execute AI智能代理是一款澳大利亚房产投资跟踪平台，连接银行、自动分类交易和生成ATO报告 ralph-execute AIエージェントは、オーストラリアの不動産投資トラッキングプラットフォームで、銀行に接続し、取引を自動で分類し、ATOレポートを生成する ralph-execute AI 에이전트는 호주 부동산 투자 추적 플랫폼으로, 은행에 연결하여 거래를 자동으로 분류하고 ATO 보고서를 생성합니다 ralph-execute es una herramienta de AI que conecta con BrickTrack, una plataforma de seguimiento de inversiones inmobiliarias en Australia, para automatizar la categorización de transacciones y generar informes para la ATO ralph-execute est un outil d''IA qui se connecte à BrickTrack, une plateforme de suivi d''investissements immobiliers en Australie, pour automatiser la catégorisation des transactions et générer des rapports pour l''ATO ralph-execute ist ein KI-Tool, das sich mit BrickTrack, einer australischen Plattform für die Verfolgung von Immobilieninvestitionen, verbindet, um die Kategorisierung von Transaktionen zu automatisieren und Berichte für die ATO zu generieren O ralph-execute é uma ferramenta de IA que conecta ao seu banco, categoriza transações automaticamente para impostos e gera relatórios prontos para a ATO ИИ Агент ralph-execute - это инструмент, который подключается к вашему банку, автоматически категоризирует транзакции для налогов и генерирует отчеты, готовые для ATO وكلاء الذكاء الاصطناعي ralph-execute هو أداة تتواصل مع بنوكك، وتصنف المعاملات تلقائيًا للضرائب، وتنشئ تقارير جاهزة للهيئة الأسترالية للضرائب BrickTrack is an Australian property investment tracking platform that connects to your bank, automatically categorizes transactions for tax, and generates ATO-ready reports. 如何使用ralph-execute AI智能代理 什么是Open Banking ralph-execute AI智能代理安装 Next.js和React开发 PostgreSQL和drizzle-orm教程 澳大利亚房产投资跟踪工具 ATO报告生成 BrickTrack is an Australian property investment tracking platform that connects to your bank, automatically categorizes transactions for tax, and generates ATO-ready reports.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aget-framework/template-executive-aget/aget-review-budget', 'community', 'aget-framework', 'template-executive-aget', 'aget-framework/template-executive-aget', 'aget-review-budget', 0, 0, 57, '2026-03-07T01:49:01.795Z', '2026-03-07T03:23:35.668Z', '74f999ad785c94b35eff79f3191d40e8fcd05296079a8c3e9eb6eb3152b3fdc8', '{"id":"aget-framework/template-executive-aget/aget-review-budget","name":"aget-review-budget","description":{"en":"The aget-review-budget skill provides strategic financial analysis and optimization recommendations for high-level decision-making, benefiting financial advisors and business leaders. It reviews budget allocation, ROI, and resource distribution.","zh":"aget-review-budget 是一个战略模板，用于高级分析和方向，提供预算分配、ROI 和资源分配的优化建议","ja":"aget-review-budget は、高レベルの分析と方向性を提供する戦略テンプレートで、予算分配、ROI、リソース配分の最適化を推奨します","ko":"aget-review-budget는 고급 분석 및 方向을 위한 전략 템플릿으로, 예산 할당, ROI, 리소스 분배의 최적화를 권장합니다","es":"aget-review-budget es una plantilla estratégica para análisis y dirección de alto nivel que proporciona recomendaciones de optimización financiera.","fr":"aget-review-budget est un modèle stratégique pour l''analyse et la direction de haut niveau qui fournit des recommandations d''optimisation financière.","de":"aget-review-budget ist eine strategische Vorlage für die Analyse und Richtung auf hohem Niveau, die Empfehlungen für die Finanzoptimierung bereitstellt.","pt":"O aget-review-budget é uma ferramenta de análise de orçamento que ajuda a otimizar a alocação de recursos. Fornece recomendações de análise financeira e direção estratégica","ru":"ИИ Агент aget-review-budget - это инструмент анализа бюджета, помогающий оптимизировать распределение ресурсов. Предоставляет рекомендации финансового анализа и стратегического руководства","ar":"أداة الذكاء الاصطناعي aget-review-budget هي أداة لاستعراض الميزانية تساعد على تحسين توزيع الموارد. توفر التوصيات التحليل المالي والتوجيه الاستراتيجي"},"seo":{"title":{"en":"aget-review-budget: Financial Analysis and Optimization S...","zh":"aget-review-budget 设置指南：优化预算分配和 ROI 分析","ja":"aget-review-budget のベストプラクティス：予算分析と ROI 最適化","ko":"aget-review-budget 설정 가이드: 예산 할당 및 ROI 분석 최적화","es":"aget-review-budget: Guía de configuración para análisis d...","fr":"aget-review-budget: Guide de mise en place pour l''analyse...","de":"aget-review-budget: Einrichtungsleitfaden für Budgetanalyse","pt":"Guia de Configuração do aget-review-budget para Análise d...","ru":"Настройка ИИ Агента aget-review-budget для Анализа Бюджета","ar":"دليل إعداد أداة الذكاء الاصطناعي aget-review-budget لاستع..."},"description":{"en":"Unlock data-driven financial decisions with aget-review-budget. Discover how to review budget allocation, calculate ROI, and optimize resource distribution -...","zh":"了解如何使用 aget-review-budget 优化预算分配、计算 ROI 和资源分配，以实现财务分析和优化","ja":"aget-review-budget を使用して予算分配、ROI、リソース配分を最適化し、財務分析と最適化を実現する方法について学びます","ko":"aget-review-budget를 사용하여 예산 할당, ROI, 리소스 분배를 최적화하고 재무 분석 및 최적화를 달성하는 방법에 대해 알아보세요","es":"Optimice su asignación de presupuesto con aget-review-budget. Obtenga recomendaciones de análisis y optimización financieros.","fr":"Optimisez votre allocation budgétaire avec aget-review-budget. Obtenez des recommandations d''analyse et d''optimisation financières.","de":"Optimieren Sie Ihre Budgetzuweisung mit aget-review-budget. Erhalten Sie Empfehlungen für Finanzanalyse und -optimierung.","pt":"Aprenda a configurar o aget-review-budget para análise de orçamento e otimização de recursos. Desenvolva habilidades de análise financeira com essa ferrament...","ru":"Узнайте, как настроить ИИ Агент aget-review-budget для анализа бюджета и оптимизации ресурсов. Развивайте навыки финансового анализа с помощью этого инструме...","ar":"تعرف على كيفية إعداد أداة الذكاء الاصطناعي aget-review-budget لاستعراض الميزانية وضمان التحسين المالي. طور مهاراتك في التحليل المالي باستخدام أدوات الذكاء ال..."},"definition":{"en":"aget-review-budget is a strategic template for financial analysis, extending the Advisor archetype to provide high-level direction and optimization recommendations.","zh":"aget-review-budget 是一个 AI 工具，用于分析和优化预算分配、ROI 和资源分配","ja":"aget-review-budget は、予算分配、ROI、リソース配分を分析し、最適化する AI エージェントです","ko":"aget-review-budget는 예산 할당, ROI, 리소스 분배를 분석 및 최적화하는 AI 에이전트입니다","es":"aget-review-budget es una herramienta de análisis de presupuesto que proporciona recomendaciones de optimización financiera.","fr":"aget-review-budget est un outil d''analyse budgétaire qui fournit des recommandations d''optimisation financière.","de":"aget-review-budget ist ein Budgetanalyse-Tool, das Empfehlungen für die Finanzoptimierung bereitstellt.","pt":"O que é aget-review-budget? É uma ferramenta de IA para análise de orçamento e otimização de recursos","ru":"Что такое ИИ Агент aget-review-budget? Это инструмент ИИ для анализа бюджета и оптимизации ресурсов","ar":"ما هي أداة الذكاء الاصطناعي aget-review-budget؟ هي أداة ذكاء اصطناعي لاستعراض الميزانية وضمان التحسين المالي"},"features":{"en":["Gathers budget data, including planned allocation and actual expenditure","Categorizes expenditures by type, department/project, and priority","Calculates ROI based on investment amount and return measurement","Provides financial analysis and optimization recommendations","Supports time period scope for budget data analysis","Enables categorization of expenditures by operational, capital, and other types"],"zh":["预算数据收集和分析","支出分类和优先级排序","ROI 计算和优化建议","资源分配和优化","财务分析和报告"],"ja":["予算データの収集と分析","支出の分類と優先順位付け","ROI の計算と最適化の提案","リソース配分と最適化","財務分析とレポート"],"ko":["예산 데이터 수집 및 분석","지출 분류 및 우선순위 지정","ROI 계산 및 최적화 제안","리소스 분배 및 최적화","재무 분석 및 보고"],"es":["Análisis de asignación de presupuesto","Categorización de gastos por tipo y departamento","Cálculo de ROI y medición del rendimiento","Recomendaciones de optimización financiera","Análisis de datos de presupuesto y gastos"],"fr":["Analyse de l''allocation budgétaire","Catégorisation des dépenses par type et département","Calcul du ROI et mesure du rendement","Recommandations d''optimisation financière","Analyse des données budgétaires et de dépenses"],"de":["Analyse der Budgetzuweisung","Kategorisierung von Ausgaben nach Art und Abteilung","Berechnung des ROI und Messung der Rendite","Empfehlungen für die Finanzoptimierung","Analyse der Budget- und Ausgabendaten"],"pt":["Análise de alocação de orçamento","Categorização de despesas por tipo e departamento","Cálculo de ROI e recomendações de otimização","Análise de desempenho financeiro e direção estratégica","Suporte à tomada de decisões financeiras informadas"],"ru":["Анализ распределения бюджета","Категоризация расходов по типу и отделу","Расчет ROI и рекомендации по оптимизации","Анализ финансовых результатов и стратегическое руководство","Поддержка принятия обоснованных финансовых решений"],"ar":["تحليل توزيع الميزانية","تصنيف النفقات حسب النوع والقسم","حساب العائد على الاستثمار وتوصيات التحسين","تحليل الأداء المالي والتوجيه الاستراتيجي","دعم اتخاذ القرارات المالية المدروسة"]},"keywords":{"en":["how to use aget-review-budget","what is aget-review-budget","aget-review-budget alternative","aget-review-budget vs financial advisor tools","aget-review-budget install","aget-review-budget setup guide","financial analysis with aget-review-budget","ROI calculation using aget-review-budget","budget optimization with aget-review-budget"],"zh":["AI 工具","预算分配","ROI 分析","资源分配","财务分析","aget-review-budget","AIエージェント","预算优化","ROI 优化"],"ja":["AI エージェント","予算分配","ROI 分析","リソース配分","財務分析","aget-review-budget","AI ツール","予算最適化","ROI 最適化"],"ko":["AI 에이전트","예산 할당","ROI 분석","리소스 분배","재무 분석","aget-review-budget","AI 툴","예산 최적화","ROI 최적화"],"es":["análisis de presupuesto","optimización financiera","ROI","asignación de presupuesto","herramientas de análisis de presupuesto","aget-review-budget","presupuesto empresarial","finanzas empresariales","análisis de datos de presupuesto"],"fr":["analyse budgétaire","optimisation financière","ROI","allocation budgétaire","outils d''analyse budgétaire","aget-review-budget","budget d''entreprise","finances d''entreprise","analyse de données budgétaires"],"de":["Budgetanalyse","Finanzoptimierung","ROI","Budgetzuweisung","Budgetanalyse-Tools","aget-review-budget","Unternehmensbudget","Unternehmensfinanzen","Budgetdatenanalyse"],"pt":["aget-review-budget","análise de orçamento","otimização de recursos","análise financeira","ROI","desenvolvimento de habilidades de análise","ferramentas de IA para análise de orçamento"],"ru":["ИИ Агент aget-review-budget","анализ бюджета","оптимизация ресурсов","финансовый анализ","ROI","развитие навыков финансового анализа","инструменты ИИ для анализа бюджета"],"ar":["أداة الذكاء الاصطناعي aget-review-budget","استعراض الميزانية","تحسين توزيع الموارد","التحليل المالي","عائد الاستثمار","تطوير مهارات التحليل المالي","أدوات الذكاء الاصطناعي لاستعراض الميزانية"]}},"owner":"aget-framework","repo":"template-executive-aget","repoPath":"aget-framework/template-executive-aget","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.795Z","topics":[],"category":"community","skillMd":{"name":"aget-review-budget","description":"Review budget allocation and ROI","bodyPreview":"# aget-review-budget\n\nReview budget allocation, ROI, and resource distribution. Provides financial analysis and optimization recommendations.\n\n## Instructions\n\nWhen this skill is invoked:\n\n1. **Gather Budget Data**\n   - Planned allocation\n   - Actual expenditure\n   - Time period scope\n\n2. **Categorize Expenditures**\n   - By type (operational, capital, etc.)\n   - By department/project\n   - By priority\n\n3. **Calculate ROI**\n   - Investment amount\n   - Return measurement\n   - ROI percentage\n\n4. **V","body":"# aget-review-budget\n\nReview budget allocation, ROI, and resource distribution. Provides financial analysis and optimization recommendations.\n\n## Instructions\n\nWhen this skill is invoked:\n\n1. **Gather Budget Data**\n   - Planned allocation\n   - Actual expenditure\n   - Time period scope\n\n2. **Categorize Expenditures**\n   - By type (operational, capital, etc.)\n   - By department/project\n   - By priority\n\n3. **Calculate ROI**\n   - Investment amount\n   - Return measurement\n   - ROI percentage\n\n4. **Variance Analysis**\n   - Planned vs. actual\n   - Significant variances\n   - Root causes\n\n5. **Optimization Opportunities**\n   - Cost reduction areas\n   - Reallocation suggestions\n   - Efficiency improvements\n\n## Output Format\n\n```markdown\n## Budget Review: [Period/Scope]\n\n### Overview\n\n| Metric | Value |\n|--------|-------|\n| Total Budget | $[X] |\n| Total Spent | $[Y] |\n| Variance | $[Z] ([N]%) |\n| Period | [Date range] |\n\n---\n\n### Expenditure by Category\n\n| Category | Planned | Actual | Variance |\n|----------|---------|--------|----------|\n| [Cat 1] | $[X] | $[Y] | $[Z] |\n| [Cat 2] | $[X] | $[Y] | $[Z] |\n| **Total** | $[X] | $[Y] | $[Z] |\n\n---\n\n### ROI Analysis\n\n| Investment | Cost | Return | ROI |\n|------------|------|--------|-----|\n| [Project 1] | $[X] | $[Y] | [N]% |\n| [Project 2] | $[X] | $[Y] | [N]% |\n\n---\n\n### Variance Analysis\n\n#### Significant Variances\n\n1. **[Category]**: $[Amount] ([N]%)\n   - Root cause: [Explanation]\n   - Action: [Recommended response]\n\n---\n\n### Optimization Recommendations\n\n1. **[Area]**: [Recommendation]\n   - Potential savings: $[X]\n   - Implementation effort: [Low/Med/High]\n\n---\n\n### Risks\n\n- [Financial risk to monitor]\n```\n\n## Constraints\n\n- **C1**: NEVER fabricate financial data — financial integrity essential\n- **C2**: NEVER make spending decisions — executive reviews, doesn''t automate decisions\n- **C3**: NEVER expose sensitive financial details in logs — financial data requires confidentiality\n\n## Related\n\n- SKILL-026: aget-review-budget specification\n- ONTOLOGY_executive.yaml: Budget, ROI, Delegation concepts\n- CAP-EXE-002: Budget Review capability\n"},"lastSynced":"2026-03-07T03:23:35.668Z","agentAnalysis":{"suitability":{"en":"Ideal for Financial Analysis Agents requiring advanced budget optimization and ROI calculation capabilities.","zh":"适合需要高级预算优化和ROI计算能力的金融分析代理。","ja":"高度な予算最適化とROI計算機能を必要とする金融分析エージェントに最適です。","ko":"고급 예산 최적화 및 ROI 계산 기능이 필요한 금융 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis Financiero que requieren capacidades de optimización de presupuesto y cálculo de ROI avanzadas.","fr":"Idéal pour les Agents d''Analyse Financière nécessitant des capacités d''optimisation de budget et de calcul de ROI avancées.","de":"Ideal für Finanzanalyse-Agents, die erweiterte Budget-Optimierungs- und ROI-Berechnungsfähigkeiten benötigen.","pt":"Ideal para Agentes de Análise Financeira que exigem otimização orçamentária avançada e capacidades de cálculo de ROI.","ru":"Идеально для финансовых аналитических агентов, требующих продвинутой оптимизации бюджета и возможностей расчета ROI.","ar":"مثالي لعمليات تحليل مالي يتطلب تحسين الميزانية المتقدمة وقدرات حساب ROI."},"recommendation":{"en":"Empowers agents to review budget allocations, calculate return on investment (ROI), and provide optimization recommendations using categorized expenditures and time period scope analysis, leveraging financial data such as planned allocation, actual expenditure, and investment amounts.","zh":"赋予代理审查预算分配、计算投资回报率（ROI）和提供优化建议的能力，使用分类支出和时间范围分析，利用财务数据（如计划分配、实际支出和投资金额）。","ja":"予算配分の確認、投資収益率（ROI）の計算、分類された支出と時期範囲分析を使用した最適化の提案を行う機能をエージェントに提供する。財務データ（計画配分、実際の支出、投資額など）を活用する。","ko":"예산 할당을 검토하고 투자 수익률(ROI)을 계산하며, 분류된 지출과 기간 범위 분석을 사용하여 최적화 제안을 제공하는 기능을 에이전트에 제공합니다. 금융 데이터(예상 할당, 실제 지출, 투자 금액 등)를 활용합니다.","es":"Habilita a los agentes a revisar las asignaciones de presupuesto, calcular la rentabilidad de la inversión (ROI) y proporcionar recomendaciones de optimización utilizando gastos categorizados y análisis de alcance de período de tiempo, aprovechando datos financieros como la asignación planificada, el gasto real y las cantidades de inversión.","fr":"Permet aux agents d''examiner les allocations budgétaires, de calculer le rendement des investissements (ROI) et de fournir des recommandations d''optimisation en utilisant des dépenses catégorisées et une analyse de la portée de la période de temps, en exploitant des données financières telles que l''allocation planifiée, le dépense réel et les montants d''investissement.","de":"Ermächtigt Agents, Budgetzuweisungen zu überprüfen, die Rentabilität der Investition (ROI) zu berechnen und Optimierungsempfehlungen unter Verwendung kategorisierter Ausgaben und Analyse des Zeitraumumsatzes zu geben, indem finanzielle Daten wie geplante Zuweisung, tatsächlicher Aufwand und Investitionsbeträge genutzt werden.","pt":"Habilita os agentes a revisar alocações orçamentárias, calcular o retorno sobre o investimento (ROI) e fornecer recomendações de otimização usando despesas categorizadas e análise de escopo de período de tempo, aproveitando dados financeiros como alocação planejada, despesa real e montantes de investimento.","ru":"Наделяет агентов возможностью рассматривать распределение бюджета, рассчитывать доходность инвестиций (ROI) и предоставлять рекомендации по оптимизации с использованием категоризированных расходов и анализа временного масштаба, используя финансовые данные, такие как запланированная распределение, фактическая трата и суммы инвестиций.","ar":"تمكين الوكلاء من مراجعة التخصيصات الميزانية، وحساب العائد على الاستثمار (ROI) وتقديم توصيات لتحسين الخدمات باستخدام النفقات المصنفة وتحليل نطاق الفترة الزمنية، واستخدام البيانات المالية مثل التخصيص المخطط له والنفقات الفعلية ومبالغ الاستثمار."},"useCases":{"en":["Analyzing budget allocations for operational and capital expenditures","Calculating ROI for departmental projects","Optimizing resource distribution based on priority and ROI percentage"],"zh":["分析运营和资本支出的预算分配","计算部门项目的ROI","根据优先级和ROI百分比优化资源分配"],"ja":["運用と資本支出の予算配分を分析する","部門プロジェクトのROIを計算する","優先順位とROIパーセンテージに基づいてリソース配分を最適化する"],"ko":["운용과 자본 지출의 예산 할당을 분석하는 것","부서 프로젝트의 ROI를 계산하는 것","우선순위와 ROI 퍼센트에 따라 리소스 분배를 최적화하는 것"],"es":["Análisis de asignaciones de presupuesto para gastos operativos y de capital","Cálculo de ROI para proyectos departamentales","Optimización de la distribución de recursos en función de la prioridad y el porcentaje de ROI"],"fr":["Analyse des allocations budgétaires pour les dépenses opérationnelles et en capital","Calcul du ROI pour les projets départementaux","Optimisation de la distribution des ressources en fonction de la priorité et du pourcentage de ROI"],"de":["Analyse von Budgetzuweisungen für betriebliche und Kapitalausgaben","Berechnung von ROI für Abteilungsprojekte","Optimierung der Ressourcenverteilung basierend auf Priorität und ROI-Prozentsatz"],"pt":["Analisar alocações orçamentárias para despesas operacionais e de capital","Calcular ROI para projetos departamentais","Otimizar distribuição de recursos com base em prioridade e percentagem de ROI"],"ru":["Анализ распределения бюджета для операционных и капитальных расходов","Расчет ROI для департаментских проектов","Оптимизация распределения ресурсов на основе приоритета и процента ROI"],"ar":["تحليل التخصيصات الميزانية للنفقات التشغيلية ورأس المال","حساب ROI لمشاريع الإدارة","تحسين توزيع الموارد بناءً على الأهمية والنسبة المئوية للعائد على الاستثمار"]},"limitations":{"en":["Requires access to financial data and budget information","Limited to financial analysis and optimization"],"zh":["需要访问财务数据和预算信息","仅限金融分析和优化"],"ja":["財務データと予算情報へのアクセスが必要","金融分析と最適化のみに限定される"],"ko":["금융 데이터와 예산 정보에 대한 액세스가 필요함","금융 분석 및 최적화에만 제한됨"],"es":["Requiere acceso a datos financieros y información de presupuesto","Limitado al análisis y optimización financieros"],"fr":["Nécessite un accès aux données financières et aux informations budgétaires","Limité à l''analyse et à l''optimisation financières"],"de":["Erfordert Zugriff auf Finanzdaten und Budgetinformationen","Begrenzt auf Finanzanalyse und -optimierung"],"pt":["Exige acesso a dados financeiros e informações orçamentárias","Limitado à análise e otimização financeira"],"ru":["Требует доступа к финансовым данным и бюджетной информации","Ограничен финансовым анализом и оптимизацией"],"ar":["يتطلب الوصول إلى البيانات المالية ومعلومات الميزانية","محدود بالتحليل والتحسين المالي"]},"version":4},"contentHash":"74f999ad785c94b35eff79f3191d40e8fcd05296079a8c3e9eb6eb3152b3fdc8","qualityScore":57}');
