INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aget-framework/template-executive-aget/aget-review-budget', 'aget-review-budget', 'aget-framework', 'template-executive-aget', 'community', 'aget-review-budget aget-framework template-executive-aget community The aget-review-budget skill provides strategic financial analysis and optimization recommendations for high-level decision-making, benefiting financial advisors and business leaders. It reviews budget allocation, ROI, and resource distribution. aget-review-budget 是一个战略模板，用于高级分析和方向，提供预算分配、ROI 和资源分配的优化建议 aget-review-budget は、高レベルの分析と方向性を提供する戦略テンプレートで、予算分配、ROI、リソース配分の最適化を推奨します aget-review-budget는 고급 분석 및 方向을 위한 전략 템플릿으로, 예산 할당, ROI, 리소스 분배의 최적화를 권장합니다 aget-review-budget es una plantilla estratégica para análisis y dirección de alto nivel que proporciona recomendaciones de optimización financiera. aget-review-budget est un modèle stratégique pour l''analyse et la direction de haut niveau qui fournit des recommandations d''optimisation financière. aget-review-budget ist eine strategische Vorlage für die Analyse und Richtung auf hohem Niveau, die Empfehlungen für die Finanzoptimierung bereitstellt. O aget-review-budget é uma ferramenta de análise de orçamento que ajuda a otimizar a alocação de recursos. Fornece recomendações de análise financeira e direção estratégica ИИ Агент aget-review-budget - это инструмент анализа бюджета, помогающий оптимизировать распределение ресурсов. Предоставляет рекомендации финансового анализа и стратегического руководства أداة الذكاء الاصطناعي aget-review-budget هي أداة لاستعراض الميزانية تساعد على تحسين توزيع الموارد. توفر التوصيات التحليل المالي والتوجيه الاستراتيجي how to use aget-review-budget what is aget-review-budget aget-review-budget alternative aget-review-budget vs financial advisor tools aget-review-budget install aget-review-budget setup guide financial analysis with aget-review-budget ROI calculation using aget-review-budget budget optimization with aget-review-budget AI 工具 预算分配 ROI 分析 资源分配 财务分析 aget-review-budget AIエージェント 预算优化 ROI 优化 Gathers budget data, including planned allocation and actual expenditure Categorizes expenditures by type, department/project, and priority Calculates ROI based on investment amount and return measurement Provides financial analysis and optimization recommendations Supports time period scope for budget data analysis Enables categorization of expenditures by operational, capital, and other types aget-review-budget is a strategic template for financial analysis, extending the Advisor archetype to provide high-level direction and optimization recommendations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mhiggs82/parentwise_summary_site/shadcn-ui', 'community', 'mhiggs82', 'parentwise_summary_site', 'mhiggs82/parentwise_summary_site', 'shadcn-ui', 0, 0, 57, '2026-03-06T06:23:00.171Z', '2026-03-06T07:37:50.306Z', '2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304', '{"id":"mhiggs82/parentwise_summary_site/shadcn-ui","name":"shadcn-ui","description":{"en":"shadcn-ui is a collection of reusable components for frontend engineers, built with Radix UI and Tailwind CSS. It helps developers integrate and customize components following best practices.","zh":"shadcn-ui 是一个基于 Radix UI 和 Tailwind CSS 的可定制组件集合，帮助开发者构建美观和可访问的应用程序","ja":"shadcn-ui は、Radix UI と Tailwind CSS で構築されたカスタマイズ可能なコンポーネントのコレクションであり、開発者が美しくてアクセシブルなアプリケーションを構築するのに役立ちます","ko":"shadcn-ui는 Radix UI 및 Tailwind CSS 기반의 커스터마이즈 가능한 컴포넌트 컬렉션으로 개발자가 아름답고 접근 가능한 애플리케이션을 구축하는 데 도움을 줍니다","es":"shadcn-ui es una colección de componentes personalizables y accesibles para desarrolladores frontend, construidos con Radix UI y Tailwind CSS.","fr":"shadcn-ui est une collection de composants personnalisables et accessibles pour les développeurs frontend, construits avec Radix UI et Tailwind CSS.","de":"shadcn-ui ist eine Sammlung von anpassbaren und zugänglichen Komponenten für Frontend-Entwickler, die mit Radix UI und Tailwind CSS erstellt wurden.","pt":"shadcn-ui é uma coleção de componentes UI personalizáveis construídos com Radix UI e Tailwind CSS para melhorar a experiência do usuário","ru":"shadcn-ui - это коллекция настраиваемых компонентов UI, построенных с помощью Radix UI и Tailwind CSS для улучшения пользовательского опыта","ar":"shadcn-ui هو مجموعة من مكونات واجهة المستخدم القابلة للتعديل التي تم بناؤها باستخدام Radix UI و Tailwind CSS لتحسين تجربة المستخدم"},"seo":{"title":{"en":"shadcn-ui: Radix UI Component Integration Setup Guide | A...","zh":"shadcn-ui 集成指南 - 基于 Radix UI 和 Tailwind CSS 的可定制组件","ja":"shadcn-ui 導入ガイド - Radix UI と Tailwind CSS で構築されたカスタマイズ可能な...","ko":"shadcn-ui 설정 가이드 - Radix UI 및 Tailwind CSS 기반의 커스터마이즈 가능한...","es":"Guía de configuración de shadcn-ui para desarrolladores","fr":"Guide d''intégration de shadcn-ui pour les développeurs","de":"Einrichtungsleitfaden für shadcn-ui-Entwickler","pt":"Guia de Integração shadcn-ui: Componentes UI Personalizáveis","ru":"ИИ Агент shadcn-ui: Руководство по Настройке Компонентов","ar":"دليل التكامل shadcn-ui: مكونات واجهة المستخدم القابلة للت..."},"description":{"en":"Discover how to integrate shadcn-ui components with Radix UI and Tailwind CSS. Learn best practices for customizing and copying components into your project.","zh":"了解如何将 shadcn-ui 集成到您的项目中，利用其可定制和可访问的组件，提升开发效率","ja":"shadcn-ui をプロジェクトに統合する方法を学び、カスタマイズ可能でアクセシブルなコンポーネントを活用して開発効率を高める","ko":"shadcn-ui를 프로젝트에 통합하는 방법을 알아보고 커스터마이즈 가능하고 접근 가능한 컴포넌트를 활용하여 개발 효율성을 높여보세요","es":"Descubre cómo integrar shadcn-ui en tus proyectos con Radix UI, Base UI y Tailwind CSS para una experiencia de usuario personalizada","fr":"Découvrez comment intégrer shadcn-ui dans vos projets avec Radix UI, Base UI et Tailwind CSS pour une expérience utilisateur personnalisée","de":"Erfahren Sie, wie Sie shadcn-ui in Ihre Projekte mit Radix UI, Base UI und Tailwind CSS integrieren, um eine personalisierte Benutzeroberfläche zu erstellen","pt":"Aprenda a integrar componentes shadcn-ui em seu projeto com nossa guia passo a passo e melhore a experiência do usuário","ru":"Узнайте, как интегрировать компоненты shadcn-ui в свой проект с помощью нашего пошагового руководства и улучшите пользовательский опыт","ar":"تعلم كيفية دمج مكونات shadcn-ui في مشروعك باستخدام دليلنا خطوة بخطوة وتحسين تجربة المستخدم"},"definition":{"en":"shadcn-ui is a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS.","zh":"shadcn-ui 是一个可定制组件集合，不是组件库，允许开发者复制和自定义组件","ja":"shadcn-ui はコンポーネント ライブラリではなく、カスタマイズ可能なコンポーネントのコレクションであり、開発者がコンポーネントをコピーしてカスタマイズできるようにします","ko":"shadcn-ui는 컴포넌트 라이브러리가 아닌 커스터마이즈 가능한 컴포넌트 컬렉션으로 개발자가 컴포넌트를 복사하여 커스터마이즈할 수 있게 합니다","es":"shadcn-ui es una colección de componentes reutilizables para aplicaciones web, no una biblioteca de componentes","fr":"shadcn-ui est une collection de composants réutilisables pour les applications web, et non une bibliothèque de composants","de":"shadcn-ui ist eine Sammlung von wiederverwendbaren Komponenten für Webanwendungen, kein Komponentenframework","pt":"shadcn-ui é uma coleção de componentes UI reutilizáveis que podem ser copiados em um projeto para personalizar a interface do usuário","ru":"shadcn-ui - это коллекция повторно используемых компонентов UI, которые можно копировать в проект для настройки пользовательского интерфейса","ar":"shadcn-ui هي مجموعة من مكونات واجهة المستخدم القابلة لإعادة الاستخدام التي يمكن نسخها في مشروع لتعديل واجهة المستخدم"},"features":{"en":["Provides full ownership of components by copying into projects","Built with Radix UI and Tailwind CSS for accessibility and customization","Allows for customization of components following best practices","Supports integration with Base UI for extended functionality","Enables developers to discover and integrate components easily","Follows a non-component library approach for flexibility"],"zh":["基于 Radix UI 和 Tailwind CSS 的可定制组件","支持复制和自定义组件","提供全面的可访问性和美观的组件","适用于构建美观和可访问的应用程序","支持使用 Base UI 和 Tailwind CSS"],"ja":["Radix UI と Tailwind CSS で構築されたカスタマイズ可能なコンポーネント","コンポーネントのコピーとカスタマイズをサポート","包括的なアクセシビリティと美観のコンポーネントを提供","美しくてアクセシブルなアプリケーションの構築に適しています","Base UI と Tailwind CSS の使用をサポート"],"ko":["Radix UI 및 Tailwind CSS 기반의 커스터마이즈 가능한 컴포넌트","컴포넌트 복사 및 커스터마이즈 지원","포괄적인 접근성 및 아름다운 컴포넌트 제공","아름답고 접근 가능한 애플리케이션 구축에 적합","Base UI 및 Tailwind CSS 사용 지원"],"es":["Componentes personalizables con Radix UI","Integración con Tailwind CSS para una mayor flexibilidad","Accesibilidad y diseño responsivo","No requiere una biblioteca de componentes","Copia y pega de componentes en tu proyecto","Compatibilidad con Base UI"],"fr":["Composants personnalisables avec Radix UI","Intégration avec Tailwind CSS pour une plus grande flexibilité","Accessibilité et conception responsive","N''a pas besoin d''une bibliothèque de composants","Copier-coller de composants dans votre projet","Compatibilité avec Base UI"],"de":["Anpassbare Komponenten mit Radix UI","Integration mit Tailwind CSS für eine größere Flexibilität","Zugänglichkeit und responsives Design","Benötigt keine Komponentenbibliothek","Kopieren und Einfügen von Komponenten in Ihr Projekt","Kompatibilität mit Base UI"],"pt":["Componentes UI personalizáveis construídos com Radix UI","Integração com Tailwind CSS para estilos personalizados","Coleção de componentes reutilizáveis para projetos frontend","Compatibilidade com projetos Base UI","Acessibilidade e design responsivo"],"ru":["Настройиваемые компоненты UI, построенные с помощью Radix UI","Интеграция с Tailwind CSS для настраиваемых стилей","Коллекция повторно используемых компонентов для проектов frontend","Совместимость с проектами Base UI","Доступность и адаптивный дизайн"],"ar":["مكونات واجهة المستخدم القابلة للتعديل التي تم بناؤها باستخدام Radix UI","التكامل مع Tailwind CSS لأسلوب تعديل","مجموعة من مكونات واجهة المستخدم القابلة لإعادة الاستخدام لمشاريع frontend","التوافق مع مشاريع Base UI","إمكانية الوصول وتصميم مستجيب"]},"keywords":{"en":["how to use shadcn-ui","shadcn-ui alternative","shadcn-ui install","what is shadcn-ui","shadcn-ui vs radix ui","shadcn-ui setup guide","shadcn-ui customization","shadcn-ui component integration","shadcn-ui and tailwind css"],"zh":["shadcn-ui","Radix UI","Tailwind CSS","可定制组件","可访问性","美观","应用程序开发","前端工程","AIエージェント"],"ja":["shadcn-ui","Radix UI","Tailwind CSS","カスタマイズ可能なコンポーネント","アクセシビリティ","美観","アプリケーション開発","フロントエンドエンジニア","AIエージェント"],"ko":["shadcn-ui","Radix UI","Tailwind CSS","커스터마이즈 가능한 컴포넌트","접근성","아름다움","애플리케이션 개발","프론트엔드 엔지니어","AI 에이전트"],"es":["shadcn-ui","Radix UI","Tailwind CSS","Base UI","componentes personalizables","accesibilidad web","diseño responsivo","desarrollo frontend","herramientas de desarrollo web"],"fr":["shadcn-ui","Radix UI","Tailwind CSS","Base UI","composants personnalisables","accessibilité web","conception responsive","développement frontend","outils de développement web"],"de":["shadcn-ui","Radix UI","Tailwind CSS","Base UI","anpassbare Komponenten","Zugänglichkeit im Web","responsives Design","Frontend-Entwicklung","Webentwicklungstools"],"pt":["shadcn-ui","componentes UI personalizáveis","Radix UI","Tailwind CSS","projetos frontend","integração de componentes","desenvolvimento web","interface do usuário"],"ru":["shadcn-ui","настраиваемые компоненты UI","Radix UI","Tailwind CSS","проекты frontend","интеграция компонентов","веб-разработка","пользовательский интерфейс"],"ar":["shadcn-ui","مكونات واجهة المستخدم القابلة للتعديل","Radix UI","Tailwind CSS","مشاريع frontend","دمج المكونات","تطوير الويب","واجهة المستخدم"]}},"owner":"mhiggs82","repo":"parentwise_summary_site","repoPath":"mhiggs82/parentwise_summary_site","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.171Z","topics":[],"category":"community","skillMd":{"name":"shadcn-ui","description":"Expert guidance for integrating and building applications with shadcn/ui components, including component discovery, installation, customization, and best practices.","bodyPreview":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full owner","body":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full ownership**: Components live in your codebase, not node_modules\n- **Complete customization**: Modify styling, behavior, and structure freely, including choosing between Radix UI or Base UI primitives\n- **No version lock-in**: Update components selectively at your own pace\n- **Zero runtime overhead**: No library bundle, just the code you need\n\n## Component Discovery and Installation\n\n### 1. Browse Available Components\n\nUse the shadcn MCP tools to explore the component catalog and Registry Directory:\n- **List all components**: Use `list_components` to see the complete catalog\n- **Get component metadata**: Use `get_component_metadata` to understand props, dependencies, and usage\n- **View component demos**: Use `get_component_demo` to see implementation examples\n\n### 2. Component Installation\n\nThere are two approaches to adding components:\n\n**A. Direct Installation (Recommended)**\n```bash\nnpx shadcn@latest add [component-name]\n```\n\nThis command:\n- Downloads the component source code (adapting to your config: Radix vs Base UI)\n- Installs required dependencies\n- Places files in `components/ui/`\n- Updates your `components.json` config\n\n**B. Manual Integration**\n1. Use `get_component` to retrieve the source code\n2. Create the file in `components/ui/[component-name].tsx`\n3. Install peer dependencies manually\n4. Adjust imports if needed\n\n### 3. Registry and Custom Registries\n\nIf working with a custom registry (defined in `components.json`) or exploring the Registry Directory:\n- Use `get_project_registries` to list available registries\n- Use `list_items_in_registries` to see registry-specific components\n- Use `view_items_in_registries` for detailed component information\n- Use `search_items_in_registries` to find specific components\n\n## Project Setup\n\n### Initial Configuration\n\nFor **new projects**, use the `create` command to customize everything (style, fonts, component library):\n\n```bash\nnpx shadcn@latest create\n```\n\nFor **existing projects**, initialize configuration:\n\n```bash\nnpx shadcn@latest init\n```\n\nThis creates `components.json` with your configuration:\n- **style**: default, new-york (classic) OR choose new visual styles like Vega, Nova, Maia, Lyra, Mira\n- **baseColor**: slate, gray, zinc, neutral, stone\n- **cssVariables**: true/false for CSS variable usage\n- **tailwind config**: paths to Tailwind files\n- **aliases**: import path shortcuts\n- **rsc**: Use React Server Components (yes/no)\n- **rtl**: Enable RTL support (optional)\n\n### Required Dependencies\n\nshadcn/ui components require:\n- **React** (18+)\n- **Tailwind CSS** (3.0+)\n- **Primitives**: Radix UI OR Base UI (depending on your choice)\n- **class-variance-authority** (for variant styling)\n- **clsx** and **tailwind-merge** (for class composition)\n\n## Component Architecture\n\n### File Structure\n```\nsrc/\n├── components/\n│   ├── ui/              # shadcn components\n│   │   ├── button.tsx\n│   │   ├── card.tsx\n│   │   └── dialog.tsx\n│   └── [custom]/        # your composed components\n│       └── user-card.tsx\n├── lib/\n│   └── utils.ts         # cn() utility\n└── app/\n    └── page.tsx\n```\n\n### The `cn()` Utility\n\nAll shadcn components use the `cn()` helper for class merging:\n\n```typescript\nimport { clsx, type ClassValue } from \"clsx\"\nimport { twMerge } from \"tailwind-merge\"\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs))\n}\n```\n\nThis allows you to:\n- Override default styles without conflicts\n- Conditionally apply classes\n- Merge Tailwind classes intelligently\n\n## Customization Best Practices\n\n### 1. Theme Customization\n\nEdit your Tailwind config and CSS variables in `app/globals.css`:\n\n```css\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --primary: 221.2 83.2% 53.3%;\n    /* ... more variables */\n  }\n  \n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    /* ... dark mode overrides */\n  }\n}\n```\n\n### 2. Component Variants\n\nUse `class-variance-authority` (cva) for variant logic:\n\n```typescript\nimport { cva } from \"class-variance-authority\"\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center rounded-md\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground\",\n        outline: \"border border-input\",\n      },\n      size: {\n        default: \"h-10 px-4 py-2\",\n        sm: \"h-9 rounded-md px-3\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n```\n\n### 3. Extending Components\n\nCreate wrapper components in `components/` (not `components/ui/`):\n\n```typescript\n// components/custom-button.tsx\nimport { Button } from \"@/components/ui/button\"\nimport { Loader2 } from \"lucide-react\"\n\nexport function LoadingButton({ \n  loading, \n  children, \n  ...props \n}: ButtonProps & { loading?: boolean }) {\n  return (\n    <Button disabled={loading} {...props}>\n      {loading && <Loader2 className=\"mr-2 h-4 w-4 animate-spin\" />}\n      {children}\n    </Button>\n  )\n}\n```\n\n## Blocks and Complex Components\n\nshadcn/ui provides complete UI blocks (authentication forms, dashboards, etc.):\n\n1. **List available blocks**: Use `list_blocks` with optional category filter\n2. **Get block source**: Use `get_block` with the block name\n3. **Install blocks**: Many blocks include multiple component files\n\nBlocks are organized by category:\n- **calendar**: Calendar interfaces\n- **dashboard**: Dashboard layouts\n- **login**: Authentication flows\n- **sidebar**: Navigation sidebars\n- **products**: E-commerce components\n\n## Accessibility\n\nAll shadcn/ui components are built on Radix UI primitives, ensuring:\n- **Keyboard navigation**: Full keyboard support out of the box\n- **Screen reader support**: Proper ARIA attributes\n- **Focus management**: Logical focus flow\n- **Disabled states**: Proper disabled and aria-disabled handling\n\nWhen customizing, maintain accessibility:\n- Keep ARIA attributes\n- Preserve keyboard handlers\n- Test with screen readers\n- Maintain focus indicators\n\n## Common Patterns\n\n### Form Building\n```typescript\nimport { Button } from \"@/components/ui/button\"\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\n// Use with react-hook-form for validation\nimport { useForm } from \"react-hook-form\"\n```\n\n### Dialog/Modal Patterns\n```typescript\nimport {\n  Dialog,\n  DialogContent,\n  DialogDescription,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from \"@/components/ui/dialog\"\n```\n\n### Data Display\n```typescript\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"@/components/ui/table\"\n```\n\n## Troubleshooting\n\n### Import Errors\n- Check `components.json` for correct alias configuration\n- Verify `tsconfig.json` includes the `@` path alias:\n  ```json\n  {\n    \"compilerOptions\": {\n      \"paths\": {\n        \"@/*\": [\"./src/*\"]\n      }\n    }\n  }\n  ```\n\n### Style Conflicts\n- Ensure Tailwind CSS is properly configured\n- Check that `globals.css` is imported in your root layout\n- Verify CSS variable names match between components and theme\n\n### Missing Dependencies\n- Run component installation via CLI to auto-install deps\n- Manually check `package.json` for required Radix UI packages\n- Use `get_component_metadata` to see dependency lists\n\n### Version Compatibility\n- shadcn/ui v4 requires React 18+ and Next.js 13+ (if using Next.js)\n- Some components require specific Radix UI versions\n- Check documentation for breaking changes between versions\n\n## Validation and Quality\n\nBefore committing components:\n1. **Type check**: Run `tsc --noEmit` to verify TypeScript\n2. **Lint**: Run your linter to catch style issues\n3. **Test accessibility**: Use tools like axe DevTools\n4. **Visual QA**: Test in light and dark modes\n5. **Responsive check**: Verify behavior at different breakpoints\n\n## Resources\n\nRefer to the following resource files for detailed guidance:\n- `resources/setup-guide.md` - Step-by-step project initialization\n- `resources/component-catalog.md` - Complete component reference\n- `resources/customization-guide.md` - Theming and variant patterns\n- `resources/migration-guide.md` - Upgrading from other UI libraries\n\n## Examples\n\nSee the `examples/` directory for:\n- Complete component implementations\n- Form patterns with validation\n- Dashboard layouts\n- Authentication flows\n- Data table implementations\n"},"lastSynced":"2026-03-06T07:37:50.306Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents specializing in customizable UI component integration with Radix UI and Tailwind CSS.","zh":"非常适合专门从事可定制UI组件集成的Radix UI和Tailwind CSS的前端代理。","ja":"Radix UIとTailwind CSSを使用したカスタマイズ可能なUIコンポーネントの統合を専門とするフロントエンドエージェントに最適。","ko":"Radix UI와 Tailwind CSS를 사용한 사용자 정의 가능한 UI 구성 요소 통합을 전문으로 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que se especializan en la integración de componentes de interfaz de usuario personalizables con Radix UI y Tailwind CSS.","fr":"Parfait pour les agents Frontend qui se spécialisent dans l''intégration de composants d''interface utilisateur personnalisables avec Radix UI et Tailwind CSS.","de":"Perfekt für Frontend-Agenten, die sich auf die Integration von anpassbaren Benutzeroberflächenkomponenten mit Radix UI und Tailwind CSS spezialisieren.","pt":"Perfeito para Agentes Frontend especializados em integração de componentes de UI personalizáveis com Radix UI e Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, специализирующихся на интеграции настраиваемых компонентов UI с Radix UI и Tailwind CSS.","ar":"مثالي للوكلاء الأمامية الذين يركزون على دمج مكونات واجهة المستخدم القابلة για التخصيص مع Radix UI و Tailwind CSS."},"recommendation":{"en":"Empowers agents to integrate and customize accessible components following best practices with shadcn-ui, utilizing Radix UI and Tailwind CSS for seamless frontend development.","zh":"赋予代理集成和自定义可访问组件的能力，遵循最佳实践，使用shadcn-ui，利用Radix UI和Tailwind CSS实现无缝的前端开发。","ja":"shadcn-uiを使用して、Radix UIとTailwind CSSを利用して、エージェントがベストプラクティスに従ったアクセス可能なコンポーネントを統合およびカスタマイズできるようにします。","ko":"shadcn-ui를 사용하여 에이전트가 최고의 관행을 따르며 Radix UI와 Tailwind CSS를 사용하여 접근 가능한 구성 요소를 통합 및 사용자 정의할 수 있도록 합니다.","es":"Habilita a los agentes a integrar y personalizar componentes accesibles siguiendo las mejores prácticas con shadcn-ui, utilizando Radix UI y Tailwind CSS para un desarrollo frontend sin problemas.","fr":"Permet aux agents d''intégrer et de personnaliser des composants accessibles en suivant les meilleures pratiques avec shadcn-ui, en utilisant Radix UI et Tailwind CSS pour un développement frontend sans accroc.","de":"Ermächtigt Agenten, zugängliche Komponenten unter Einhaltung der besten Praktiken mit shadcn-ui zu integrieren und anzupassen, indem Radix UI und Tailwind CSS für eine reibungslose Frontend-Entwicklung verwendet werden.","pt":"Habilita os agentes a integrar e personalizar componentes acessíveis seguindo as melhores práticas com shadcn-ui, utilizando Radix UI e Tailwind CSS para desenvolvimento de frontend sem interrupções.","ru":"Наделяет агентов возможностью интегрировать и настраивать доступные компоненты, следуя лучшим практикам с shadcn-ui, используя Radix UI и Tailwind CSS для бесперебойного разработки frontend.","ar":"يمنح الوكلاء القدرة على دمج مكونات قابلة للوصول وتخصيصها اتباعًا لأفضل الممارسات مع shadcn-ui، مستخدمين Radix UI و Tailwind CSS من أجل تطوير واجهة المستخدم الأمامية دون انقطاع."},"useCases":{"en":["Integrating reusable UI components into existing projects","Customizing shadcn-ui components for enhanced accessibility","Streamlining frontend development with pre-designed UI elements"],"zh":["将可复用的UI组件集成到现有项目中","自定义shadcn-ui组件以提高可访问性","使用预设计的UI元素简化前端开发"],"ja":["既存のプロジェクトに再利用可能なUIコンポーネントを統合する","shadcn-uiコンポーネントをカスタマイズしてアクセシビリティを高める","事前に設計されたUI要素を使用してフロントエンド開発を合理化する"],"ko":["기존 프로젝트에 재사용 가능한 UI 구성 요소를 통합하는 것","shadcn-ui 구성 요소를 사용자 정의하여 접근성을 향상시키는 것","사전設計된 UI 요소를 사용하여 프론트엔드 개발을 간소화하는 것"],"es":["Integrar componentes de interfaz de usuario reutilizables en proyectos existentes","Personalizar componentes de shadcn-ui para una mayor accesibilidad","Optimizar el desarrollo frontend con elementos de interfaz de usuario pre diseñados"],"fr":["Intégrer des composants d''interface utilisateur réutilisables dans des projets existants","Personnaliser des composants shadcn-ui pour une meilleure accessibilité","Optimiser le développement frontend avec des éléments d''interface utilisateur préconçus"],"de":["Wiederverwendbare Benutzeroberflächenkomponenten in bestehende Projekte integrieren","Komponenten von shadcn-ui für eine verbesserte Zugänglichkeit anpassen","Frontend-Entwicklung mit vorgefertigten Benutzeroberflächenelementen optimieren"],"pt":["Integrar componentes de UI reutilizáveis em projetos existentes","Personalizar componentes shadcn-ui para acessibilidade aprimorada","Otimizar desenvolvimento de frontend com elementos de UI pré-projetados"],"ru":["Интегрировать повторно используемые компоненты UI в существующие проекты","Настроить компоненты shadcn-ui для улучшения доступности","Оптимизировать разработку frontend с помощью предварительно спроектированных элементов UI"],"ar":["دمج مكونات واجهة المستخدم القابلة لإعادة الاستخدام في مشاريع موجودة","تخصيص مكونات shadcn-ui لتحسين سهولة الوصول","تحسين تطوير واجهة المستخدم الأمامية باستخدام عناصر واجهة المستخدم المصممة مسبقًا"]},"limitations":{"en":["Not a traditional component library, requires copying components into projects","Dependent on Radix UI and Tailwind CSS for functionality"],"zh":["不是传统的组件库，需要将组件复制到项目中","依赖Radix UI和Tailwind CSS进行功能实现"],"ja":["従来のコンポーネントライブラリではなく、コンポーネントをプロジェクトにコピーする必要がある","Radix UIとTailwind CSSに依存して機能する"],"ko":["전통적인 구성 요소 라이브러리가 아닌 프로젝트에 구성 요소를 복사해야 함","Radix UI와 Tailwind CSS에 의존하여 기능을 구현함"],"es":["No es una biblioteca de componentes tradicional, requiere copiar componentes en proyectos","Dependiente de Radix UI y Tailwind CSS para la funcionalidad"],"fr":["Ce n''est pas une bibliothèque de composants traditionnelle, nécessite de copier des composants dans des projets","Dépendante de Radix UI et Tailwind CSS pour la fonctionnalité"],"de":["Keine traditionelle Komponentenbibliothek, erfordert das Kopieren von Komponenten in Projekte","Abhängig von Radix UI und Tailwind CSS für die Funktionalität"],"pt":["Não é uma biblioteca de componentes tradicional, requer cópia de componentes para projetos","Dependente de Radix UI e Tailwind CSS para funcionalidade"],"ru":["Не является традиционной библиотекой компонентов, требует копирования компонентов в проекты","Зависит от Radix UI и Tailwind CSS для функциональности"],"ar":["ليست مكتبة مكونات تقليدية، تتطلب نسخ مكونات إلى المشاريع","متعلقة ب Radix UI و Tailwind CSS لتحقيق الوظائف"]},"version":4},"contentHash":"2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304","qualityScore":57}');
