INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mhiggs82/parentwise_summary_site/shadcn-ui', 'shadcn-ui', 'mhiggs82', 'parentwise_summary_site', 'community', 'shadcn-ui mhiggs82 parentwise_summary_site community shadcn-ui is a collection of reusable components for frontend engineers, built with Radix UI and Tailwind CSS. It helps developers integrate and customize components following best practices. shadcn-ui 是一个基于 Radix UI 和 Tailwind CSS 的可定制组件集合，帮助开发者构建美观和可访问的应用程序 shadcn-ui は、Radix UI と Tailwind CSS で構築されたカスタマイズ可能なコンポーネントのコレクションであり、開発者が美しくてアクセシブルなアプリケーションを構築するのに役立ちます shadcn-ui는 Radix UI 및 Tailwind CSS 기반의 커스터마이즈 가능한 컴포넌트 컬렉션으로 개발자가 아름답고 접근 가능한 애플리케이션을 구축하는 데 도움을 줍니다 shadcn-ui es una colección de componentes personalizables y accesibles para desarrolladores frontend, construidos con Radix UI y Tailwind CSS. shadcn-ui est une collection de composants personnalisables et accessibles pour les développeurs frontend, construits avec Radix UI et Tailwind CSS. shadcn-ui ist eine Sammlung von anpassbaren und zugänglichen Komponenten für Frontend-Entwickler, die mit Radix UI und Tailwind CSS erstellt wurden. shadcn-ui é uma coleção de componentes UI personalizáveis construídos com Radix UI e Tailwind CSS para melhorar a experiência do usuário shadcn-ui - это коллекция настраиваемых компонентов UI, построенных с помощью Radix UI и Tailwind CSS для улучшения пользовательского опыта shadcn-ui هو مجموعة من مكونات واجهة المستخدم القابلة للتعديل التي تم بناؤها باستخدام Radix UI و Tailwind CSS لتحسين تجربة المستخدم how to use shadcn-ui shadcn-ui alternative shadcn-ui install what is shadcn-ui shadcn-ui vs radix ui shadcn-ui setup guide shadcn-ui customization shadcn-ui component integration shadcn-ui and tailwind css shadcn-ui Radix UI Tailwind CSS 可定制组件 可访问性 美观 应用程序开发 前端工程 AIエージェント Provides full ownership of components by copying into projects Built with Radix UI and Tailwind CSS for accessibility and customization Allows for customization of components following best practices Supports integration with Base UI for extended functionality Enables developers to discover and integrate components easily Follows a non-component library approach for flexibility shadcn-ui is a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS.');
