INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('3commas-io/commas-claude/python-testing-patterns', 'python-testing-patterns', '3commas-io', 'commas-claude', 'community', 'python-testing-patterns 3commas-io commas-claude community This skill provides a comprehensive guide to implementing robust testing strategies in Python using pytest, fixtures, mocking, and test-driven development practices, benefiting Python developers and QA engineers. Python 测试模式是一份全面指南，用于在 Python 中使用 pytest、fixtures、mocking 和 TDD 实现强大测试策略 Python テスト パターンは、pytest、fixtures、mocking、TDD を使用して Python で強力なテスト戦略を実現するための包括的なガイドです 파이썬 테스트 패턴은 pytest, fixtures, mocking 및 TDD를 사용하여 Python에서 강력한 테스트 전략을 구현하는ための 포괄적인 가이드입니다 Este repositorio proporciona patrones de prueba de Python para implementar estrategias de prueba robustas con pytest. Aprende a escribir unit tests, setup test suites y más Ce référentiel fournit des modèles de tests Python pour mettre en œuvre des stratégies de test robustes avec pytest. Apprenez à écrire des unit tests, configurer des suites de tests et plus Dieses Repository bietet Python-Testmuster, um robuste Teststrategien mit pytest zu implementieren. Lernen Sie, Unit-Tests zu schreiben, Test-Suiten einzurichten und mehr Este repositório oferece um guia abrangente para implementar estratégias de teste em Python Этот репозиторий предоставляет комплексное руководство по реализации стратегий тестирования в Python هذا المستودع يقدم دليل شاملا لتنفيذ استراتيجيات الاختبار في بايثون python testing patterns how to use pytest python testing best practices test-driven development tutorial python testing patterns setup guide pytest vs unittest python testing patterns install python testing patterns alternative python testing patterns example python testing patterns documentation Python 测试 pytest fixtures mocking TDD 单元测试 集成测试 异步代码测试 并发操作测试 Implements test-driven development (TDD) practices Sets up test suites and test infrastructure using pytest Creates integration tests for APIs and services Mocks external dependencies and services Tests async code and concurrent operations Uses fixtures and parameterization for efficient testing python-testing-patterns is a repository of shared agents and skills for implementing robust testing strategies in Python using pytest, fixtures, and TDD.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Parthivjoshi29/agent-skills-npm-package/shadcn-ui', 'community', 'Parthivjoshi29', 'agent-skills-npm-package', 'Parthivjoshi29/agent-skills-npm-package', 'shadcn-ui', 0, 0, 57, '2026-03-06T06:23:00.171Z', '2026-03-06T07:37:41.774Z', '2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304', '{"id":"Parthivjoshi29/agent-skills-npm-package/shadcn-ui","name":"shadcn-ui","description":{"en":"shadcn-ui helps frontend engineers build applications with beautifully designed components, utilizing Radix UI or Base UI and Tailwind CSS. It benefits developers seeking customizable and accessible UI elements.","zh":"shadcn-ui是一个集合了Radix UI和Tailwind CSS的可访问且自定义的组件集合，帮助开发者发现、集成和自定义组件","ja":"shadcn-uiは、Radix UIとTailwind CSSを組み合わせたアクセシブルでカスタマイズ可能なコンポーネントのコレクションです。開発者がコンポーネントを発見、統合、カスタマイズするのを支援します","ko":"shadcn-ui는 Radix UI와 Tailwind CSS를 결합한 접근성과 사용자 정의가 가능한 컴포넌트의 집합으로, 개발자가 컴포넌트를 발견, 통합 및 사용자 정의하는 것을 지원합니다","es":"shadcn-ui es una colección de componentes reutilizables para mejorar la accesibilidad y personalización de tus aplicaciones","fr":"shadcn-ui est un ensemble de composants réutilisables pour améliorer l''accessibilité et la personnalisation de vos applications","de":"shadcn-ui ist eine Sammlung von wiederverwendbaren Komponenten zur Verbesserung der Zugänglichkeit und Anpassungsfähigkeit Ihrer Anwendungen","pt":"shadcn-ui é uma coleção de componentes reutilizáveis projetados com Radix UI, Base UI e Tailwind CSS para desenvolvedores frontend","ru":"shadcn-ui — это коллекция повторно используемых компонентов, разработанных с помощью Radix UI, Base UI и Tailwind CSS для frontend-разработчиков","ar":"شادسن-وي هو مجموعة من المكونات القابلة لإعادة الاستخدام المصممة باستخدام Radix UI و Base UI و Tailwind CSS لمنصة التطوير الأمامية"},"seo":{"title":{"en":"shadcn-ui: Radix UI Component Integration Setup Guide | A...","zh":"shadcn-ui集成指南：Radix UI和Tailwind CSS最佳实践","ja":"shadcn-uiのセットアップガイド：Radix UIとTailwind CSSのベストプラクティス","ko":"shadcn-ui 설정 가이드: Radix UI와 Tailwind CSS를 위한 최적화된 구성 요소","es":"Guía para integrar shadcn-ui en tus proyectos","fr":"Configurer shadcn-ui pour vos applications","de":"shadcn-ui Einrichten: Leitfaden für Entwickler","pt":"Guia de Integração shadcn-ui: Melhores Práticas para Dese...","ru":"ИИ Агент shadcn-ui: Руководство по Интеграции и Настройке","ar":"إعداد شادسن-وي: دليل أفضل الممارسات لل مبرمجين"},"description":{"en":"Discover how to integrate shadcn-ui components into your project, leveraging Radix UI and Tailwind CSS for accessible and customizable UI elements - get star...","zh":"了解如何使用shadcn-ui构建可访问且自定义的组件，包括Radix UI和Tailwind CSS的最佳实践","ja":"shadcn-uiを使用してアクセシブルでカスタマイズ可能なコンポーネントを構築する方法を学びます。Radix UIとTailwind CSSのベストプラクティスを含みます","ko":"shadcn-ui를 사용하여 접근성과 사용자 정의가 가능한 컴포넌트를 구축하는 방법에 대해 알아보세요. Radix UI와 Tailwind CSS의 최적화된 구성 요소를 포함합니다","es":"Aprende a integrar shadcn-ui en tus proyectos con nuestra guía paso a paso y mejora la accesibilidad y personalización de tus aplicaciones","fr":"Découvrez comment configurer shadcn-ui pour améliorer l''accessibilité et la personnalisation de vos applications avec nos meilleures pratiques","de":"Erfahren Sie, wie Sie shadcn-ui in Ihre Projekte integrieren und die Zugänglichkeit und Anpassungsfähigkeit Ihrer Anwendungen verbessern","pt":"Aprenda a integrar shadcn-ui em seu projeto com nossas melhores práticas e dicas de personalização para desenvolvedores","ru":"Узнайте, как интегрировать shadcn-ui в ваш проект с нашими лучшими практиками и советами по настройке для разработчиков","ar":"تعرف على كيفية دمج شادسن-وي في مشروعك مع أفضل الممارسات وأفكار التخصيص لمطوري البرمجيات"},"definition":{"en":"shadcn-ui is a collection of reusable, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS, designed for frontend engineers.","zh":"shadcn-ui是一个不需要额外的组件库的、可复用且可访问的组件集合","ja":"shadcn-uiは、追加のコンポーネントライブラリを必要としない再利用可能でアクセシブルなコンポーネントのコレクションです","ko":"shadcn-ui는 추가적인 컴포넌트 라이브러리가 필요 없는 재사용 가능하고 접근성 있는 컴포넌트의 집합입니다","es":"shadcn-ui es una colección de componentes UI personalizables y accesibles construidos con Radix UI y Tailwind CSS","fr":"shadcn-ui est un ensemble de composants UI personnalisables et accessibles construits avec Radix UI et Tailwind CSS","de":"shadcn-ui ist eine Sammlung von anpassbaren und zugänglichen UI-Komponenten, die mit Radix UI und Tailwind CSS erstellt wurden","pt":"shadcn-ui é uma coleção de componentes de interface do usuário reutilizáveis","ru":"shadcn-ui — это коллекция повторно используемых компонентов пользовательского интерфейса","ar":"شادسن-وي هي مجموعة من مكونات واجهة المستخدم القابلة لإعادة الاستخدام"},"features":{"en":["Utilizes Radix UI for building accessible and customizable components","Leverages Base UI for creating consistent and reusable UI elements","Integrates with Tailwind CSS for styling and layout management","Provides full ownership of components by copying them into projects","Follows best practices for component discovery, integration, and customization","Supports customization of components for unique application needs"],"zh":["使用Radix UI和Tailwind CSS构建","可访问且自定义的组件","不需要额外的组件库","支持开发者发现、集成和自定义组件","提供全面的所有权和控制权","支持Base UI和其他流行的UI框架"],"ja":["Radix UIとTailwind CSSを使用した構築","アクセシブルでカスタマイズ可能なコンポーネント","追加のコンポーネントライブラリを必要としない","開発者がコンポーネントを発見、統合、カスタマイズするのを支援","包括的な所有権と制御を提供","Base UIおよびその他の人気のUIフレームワークをサポート"],"ko":["Radix UI와 Tailwind CSS를 사용한 구축","접근성과 사용자 정의가 가능한 컴포넌트","추가적인 컴포넌트 라이브러리가 필요 없음","개발자가 컴포넌트를 발견, 통합 및 사용자 정의하는 것을 지원","전체적인 소유권과 제어를 제공","Base UI 및 기타 인기 있는 UI 프레임워크를 지원"],"es":["Componentes personalizables con Radix UI","Compatibilidad con Tailwind CSS","Accesibilidad mejorada","Código abierto y reutilizable","Integración sencilla en proyectos existentes"],"fr":["Composants personnalisables avec Radix UI","Compatibilité avec Tailwind CSS","Accessibilité améliorée","Code ouvert et réutilisable","Intégration simple dans les projets existants"],"de":["Anpassbare Komponenten mit Radix UI","Kompatibilität mit Tailwind CSS","Verbesserte Zugänglichkeit","Offener und wiederverwendbarer Code","Einfache Integration in bestehende Projekte"],"pt":["Componentes personalizáveis com Tailwind CSS","Integração com Radix UI e Base UI","Coleção de componentes reutilizáveis","Desenvolvido para frontend engineers","Suporte à acessibilidade"],"ru":["Настраиваемые компоненты с помощью Tailwind CSS","Интеграция с Radix UI и Base UI","Коллекция повторно используемых компонентов","Разработано для frontend-разработчиков","Поддержка доступности"],"ar":["مكونات قابلة للتخصيص مع Tailwind CSS","التكامل مع Radix UI و Base UI","مجموعة من المكونات القابلة لإعادة الاستخدام","تم تطويره لمنصة التطوير الأمامية","دعم سهولة الوصول"]},"keywords":{"en":["how to use shadcn-ui","shadcn-ui alternative","shadcn-ui vs radix ui","shadcn-ui install","shadcn-ui setup guide","what is shadcn-ui","shadcn-ui component library","shadcn-ui customization","shadcn-ui accessibility"],"zh":["shadcn-ui","Radix UI","Tailwind CSS","可访问组件","自定义组件","不需要额外的组件库","开发者工具","前端开发","AIエージェント"],"ja":["shadcn-ui","Radix UI","Tailwind CSS","アクセシブルコンポーネント","カスタマイズ可能なコンポーネント","追加のコンポーネントライブラリを必要としない","開発者ツール","フロントエンド開発","AIエージェント"],"ko":["shadcn-ui","Radix UI","Tailwind CSS","접근성 컴포넌트","사용자 정의가 가능한 컴포넌트","추가적인 컴포넌트 라이브러리가 필요 없음","개발자 도구","프론트엔드 개발","AI 에이전트"],"es":["shadcn-ui","componentes UI","Radix UI","Tailwind CSS","accesibilidad","personalización","desarrollo web","integración de componentes"],"fr":["shadcn-ui","composants UI","Radix UI","Tailwind CSS","accessibilité","personnalisation","développement web","intégration de composants"],"de":["shadcn-ui","UI-Komponenten","Radix UI","Tailwind CSS","Zugänglichkeit","Anpassungsfähigkeit","Webentwicklung","Integration von Komponenten"],"pt":["shadcn-ui","componentes reutilizáveis","Radix UI","Base UI","Tailwind CSS","desenvolvimento frontend","acessibilidade","personalização de componentes"],"ru":["shadcn-ui","повторно используемые компоненты","Radix UI","Base UI","Tailwind CSS","frontend-разработка","доступность","настройка компонентов"],"ar":["شادسن-وي","مكونات قابلة لإعادة الاستخدام","Radix UI","Base UI","Tailwind CSS","تطوير البرمجيات الأمامية","سهولة الوصول","تخصيص المكونات"]}},"owner":"Parthivjoshi29","repo":"agent-skills-npm-package","repoPath":"Parthivjoshi29/agent-skills-npm-package","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.171Z","topics":[],"category":"community","skillMd":{"name":"shadcn-ui","description":"Expert guidance for integrating and building applications with shadcn/ui components, including component discovery, installation, customization, and best practices.","bodyPreview":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full owner","body":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full ownership**: Components live in your codebase, not node_modules\n- **Complete customization**: Modify styling, behavior, and structure freely, including choosing between Radix UI or Base UI primitives\n- **No version lock-in**: Update components selectively at your own pace\n- **Zero runtime overhead**: No library bundle, just the code you need\n\n## Component Discovery and Installation\n\n### 1. Browse Available Components\n\nUse the shadcn MCP tools to explore the component catalog and Registry Directory:\n- **List all components**: Use `list_components` to see the complete catalog\n- **Get component metadata**: Use `get_component_metadata` to understand props, dependencies, and usage\n- **View component demos**: Use `get_component_demo` to see implementation examples\n\n### 2. Component Installation\n\nThere are two approaches to adding components:\n\n**A. Direct Installation (Recommended)**\n```bash\nnpx shadcn@latest add [component-name]\n```\n\nThis command:\n- Downloads the component source code (adapting to your config: Radix vs Base UI)\n- Installs required dependencies\n- Places files in `components/ui/`\n- Updates your `components.json` config\n\n**B. Manual Integration**\n1. Use `get_component` to retrieve the source code\n2. Create the file in `components/ui/[component-name].tsx`\n3. Install peer dependencies manually\n4. Adjust imports if needed\n\n### 3. Registry and Custom Registries\n\nIf working with a custom registry (defined in `components.json`) or exploring the Registry Directory:\n- Use `get_project_registries` to list available registries\n- Use `list_items_in_registries` to see registry-specific components\n- Use `view_items_in_registries` for detailed component information\n- Use `search_items_in_registries` to find specific components\n\n## Project Setup\n\n### Initial Configuration\n\nFor **new projects**, use the `create` command to customize everything (style, fonts, component library):\n\n```bash\nnpx shadcn@latest create\n```\n\nFor **existing projects**, initialize configuration:\n\n```bash\nnpx shadcn@latest init\n```\n\nThis creates `components.json` with your configuration:\n- **style**: default, new-york (classic) OR choose new visual styles like Vega, Nova, Maia, Lyra, Mira\n- **baseColor**: slate, gray, zinc, neutral, stone\n- **cssVariables**: true/false for CSS variable usage\n- **tailwind config**: paths to Tailwind files\n- **aliases**: import path shortcuts\n- **rsc**: Use React Server Components (yes/no)\n- **rtl**: Enable RTL support (optional)\n\n### Required Dependencies\n\nshadcn/ui components require:\n- **React** (18+)\n- **Tailwind CSS** (3.0+)\n- **Primitives**: Radix UI OR Base UI (depending on your choice)\n- **class-variance-authority** (for variant styling)\n- **clsx** and **tailwind-merge** (for class composition)\n\n## Component Architecture\n\n### File Structure\n```\nsrc/\n├── components/\n│   ├── ui/              # shadcn components\n│   │   ├── button.tsx\n│   │   ├── card.tsx\n│   │   └── dialog.tsx\n│   └── [custom]/        # your composed components\n│       └── user-card.tsx\n├── lib/\n│   └── utils.ts         # cn() utility\n└── app/\n    └── page.tsx\n```\n\n### The `cn()` Utility\n\nAll shadcn components use the `cn()` helper for class merging:\n\n```typescript\nimport { clsx, type ClassValue } from \"clsx\"\nimport { twMerge } from \"tailwind-merge\"\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs))\n}\n```\n\nThis allows you to:\n- Override default styles without conflicts\n- Conditionally apply classes\n- Merge Tailwind classes intelligently\n\n## Customization Best Practices\n\n### 1. Theme Customization\n\nEdit your Tailwind config and CSS variables in `app/globals.css`:\n\n```css\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --primary: 221.2 83.2% 53.3%;\n    /* ... more variables */\n  }\n  \n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    /* ... dark mode overrides */\n  }\n}\n```\n\n### 2. Component Variants\n\nUse `class-variance-authority` (cva) for variant logic:\n\n```typescript\nimport { cva } from \"class-variance-authority\"\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center rounded-md\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground\",\n        outline: \"border border-input\",\n      },\n      size: {\n        default: \"h-10 px-4 py-2\",\n        sm: \"h-9 rounded-md px-3\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n```\n\n### 3. Extending Components\n\nCreate wrapper components in `components/` (not `components/ui/`):\n\n```typescript\n// components/custom-button.tsx\nimport { Button } from \"@/components/ui/button\"\nimport { Loader2 } from \"lucide-react\"\n\nexport function LoadingButton({ \n  loading, \n  children, \n  ...props \n}: ButtonProps & { loading?: boolean }) {\n  return (\n    <Button disabled={loading} {...props}>\n      {loading && <Loader2 className=\"mr-2 h-4 w-4 animate-spin\" />}\n      {children}\n    </Button>\n  )\n}\n```\n\n## Blocks and Complex Components\n\nshadcn/ui provides complete UI blocks (authentication forms, dashboards, etc.):\n\n1. **List available blocks**: Use `list_blocks` with optional category filter\n2. **Get block source**: Use `get_block` with the block name\n3. **Install blocks**: Many blocks include multiple component files\n\nBlocks are organized by category:\n- **calendar**: Calendar interfaces\n- **dashboard**: Dashboard layouts\n- **login**: Authentication flows\n- **sidebar**: Navigation sidebars\n- **products**: E-commerce components\n\n## Accessibility\n\nAll shadcn/ui components are built on Radix UI primitives, ensuring:\n- **Keyboard navigation**: Full keyboard support out of the box\n- **Screen reader support**: Proper ARIA attributes\n- **Focus management**: Logical focus flow\n- **Disabled states**: Proper disabled and aria-disabled handling\n\nWhen customizing, maintain accessibility:\n- Keep ARIA attributes\n- Preserve keyboard handlers\n- Test with screen readers\n- Maintain focus indicators\n\n## Common Patterns\n\n### Form Building\n```typescript\nimport { Button } from \"@/components/ui/button\"\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\n// Use with react-hook-form for validation\nimport { useForm } from \"react-hook-form\"\n```\n\n### Dialog/Modal Patterns\n```typescript\nimport {\n  Dialog,\n  DialogContent,\n  DialogDescription,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from \"@/components/ui/dialog\"\n```\n\n### Data Display\n```typescript\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"@/components/ui/table\"\n```\n\n## Troubleshooting\n\n### Import Errors\n- Check `components.json` for correct alias configuration\n- Verify `tsconfig.json` includes the `@` path alias:\n  ```json\n  {\n    \"compilerOptions\": {\n      \"paths\": {\n        \"@/*\": [\"./src/*\"]\n      }\n    }\n  }\n  ```\n\n### Style Conflicts\n- Ensure Tailwind CSS is properly configured\n- Check that `globals.css` is imported in your root layout\n- Verify CSS variable names match between components and theme\n\n### Missing Dependencies\n- Run component installation via CLI to auto-install deps\n- Manually check `package.json` for required Radix UI packages\n- Use `get_component_metadata` to see dependency lists\n\n### Version Compatibility\n- shadcn/ui v4 requires React 18+ and Next.js 13+ (if using Next.js)\n- Some components require specific Radix UI versions\n- Check documentation for breaking changes between versions\n\n## Validation and Quality\n\nBefore committing components:\n1. **Type check**: Run `tsc --noEmit` to verify TypeScript\n2. **Lint**: Run your linter to catch style issues\n3. **Test accessibility**: Use tools like axe DevTools\n4. **Visual QA**: Test in light and dark modes\n5. **Responsive check**: Verify behavior at different breakpoints\n\n## Resources\n\nRefer to the following resource files for detailed guidance:\n- `resources/setup-guide.md` - Step-by-step project initialization\n- `resources/component-catalog.md` - Complete component reference\n- `resources/customization-guide.md` - Theming and variant patterns\n- `resources/migration-guide.md` - Upgrading from other UI libraries\n\n## Examples\n\nSee the `examples/` directory for:\n- Complete component implementations\n- Form patterns with validation\n- Dashboard layouts\n- Authentication flows\n- Data table implementations\n"},"lastSynced":"2026-03-06T07:37:41.774Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing customizable and accessible UI components with Radix UI, Base UI, and Tailwind CSS integration.","zh":"非常适合需要可定制和可访问的UI组件的前端代理，集成了Radix UI、Base UI和Tailwind CSS。","ja":"フロントエンドエージェントがカスタマイズ可能でアクセス可能なUIコンポーネントを必要とする場合に最適です。Radix UI、Base UI、Tailwind CSSを統合しています。","ko":"사용자 정의 가능한_accessible한 UI 컴포넌트가 필요한 프론트엔드 에이전트에 적합합니다. Radix UI, Base UI 및 Tailwind CSS를 통합합니다.","es":"Perfecto para agentes Frontend que necesitan componentes de UI personalizables y accesibles con integración de Radix UI, Base UI y Tailwind CSS.","fr":"Parfait pour les agents Frontend ayant besoin de composants d''interface utilisateur personnalisables et accessibles avec une intégration de Radix UI, Base UI et Tailwind CSS.","de":"Perfekt für Frontend-Agents, die benutzerdefinierte und zugängliche Benutzeroberflächenkomponenten mit Radix UI-, Base UI- und Tailwind CSS-Integration benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de componentes de UI personalizáveis e acessíveis com integração do Radix UI, Base UI e Tailwind CSS.","ru":"Идеально подходит для фронтенд-агентов, которым требуются настраиваемые и доступные компоненты UI с интеграцией Radix UI, Base UI и Tailwind CSS.","ar":"مثالي للوكلاء في واجهة المستخدم الذين يحتاجون إلى مكونات واجهة المستخدم القابلة للتعديل والمتوافقة مع Radix UI و Base UI و Tailwind CSS."},"recommendation":{"en":"Empowers agents to integrate beautifully designed components with full ownership, utilizing Radix UI or Base UI and Tailwind CSS for customizable and accessible UI elements, following best practices for component discovery and customization.","zh":"赋予代理集成漂亮设计的组件的全部权利，利用Radix UI或Base UI和Tailwind CSS进行可定制和可访问的UI元素，并遵循最佳实践进行组件发现和定制。","ja":"エージェントが美しくデザインされたコンポーネントを統合し、フルオーナーシップを持ち、Radix UIまたはBase UIとTailwind CSSを使用してカスタマイズ可能でアクセス可能なUI要素を作成し、コンポーネントの発見とカスタマイズのベストプラクティスに従うことができます。","ko":"에이전트가 아름답게 설계된 컴포넌트를 통합하여 전체 소유권을持ち고, Radix UI 또는 Base UI와 Tailwind CSS를 사용하여 사용자 정의 및 접근 가능한 UI 요소를 만들며, 컴포넌트 검색 및 사용자 정의에 대한 최선의 방법을 따릅니다.","es":"Habilita a los agentes a integrar componentes hermosamente diseñados con total propiedad, utilizando Radix UI o Base UI y Tailwind CSS para elementos de UI personalizables y accesibles, siguiendo las mejores prácticas para el descubrimiento y personalización de componentes.","fr":"Permet aux agents d''intégrer des composants conçus de manière élégante avec une propriété totale, en utilisant Radix UI ou Base UI et Tailwind CSS pour des éléments d''interface utilisateur personnalisables et accessibles, en suivant les meilleures pratiques pour la découverte et la personnalisation de composants.","de":"Ermöglicht es Agenten, wunderschön gestaltete Komponenten mit voller Eigentümerschaft zu integrieren, indem sie Radix UI oder Base UI und Tailwind CSS für benutzerdefinierte und zugängliche Benutzeroberflächenelemente verwenden, und dabei die besten Praktiken für die Entdeckung und Anpassung von Komponenten befolgen.","pt":"Permite que os agentes integrem componentes projetados com beleza, com total propriedade, utilizando Radix UI ou Base UI e Tailwind CSS para elementos de UI personalizáveis e acessíveis, seguindo as melhores práticas para descoberta e personalização de componentes.","ru":"Наделяет агентов возможностью интегрировать красиво спроектированные компоненты с полной собственностью, используя Radix UI или Base UI и Tailwind CSS для настраиваемых и доступных элементов UI, следуя лучшим практикам для открытия и настройки компонентов.","ar":"يمنح الوكلاء القدرة على دمج المكونات المصممة بشكل جميل مع ملكية كاملة، باستخدام Radix UI أو Base UI و Tailwind CSS لمكونات واجهة المستخدم القابلة للتعديل والمتوافقة، اتباعًا لأفضل الممارسات لاكتشاف مكونات واجهة المستخدم وتعديلها."},"useCases":{"en":["Integrating accessible UI components into web applications","Customizing shadcn-ui components for brand consistency","Building applications with reusable UI elements using Radix UI and Tailwind CSS"],"zh":["将可访问的UI组件集成到Web应用程序中","为品牌一致性定制shadcn-ui组件","使用Radix UI和Tailwind CSS构建具有可重用UI元素的应用程序"],"ja":["Webアプリケーションにアクセス可能なUIコンポーネントを統合する","ブランドの一貫性のためにshadcn-uiコンポーネントをカスタマイズする","Radix UIとTailwind CSSを使用して再利用可能なUI要素を持つアプリケーションを構築する"],"ko":["접근 가능한 UI 컴포넌트를 웹 애플리케이션에 통합하는 것","브랜드 일관성을 위해 shadcn-ui 컴포넌트를 사용자 정의하는 것","Radix UI 및 Tailwind CSS를 사용하여 재사용 가능한 UI 요소를 갖춘 애플리케이션을 구축하는 것"],"es":["Integrar componentes de UI accesibles en aplicaciones web","Personalizar componentes shadcn-ui para la coherencia de la marca","Crear aplicaciones con elementos de UI reutilizables utilizando Radix UI y Tailwind CSS"],"fr":["Intégrer des composants d''interface utilisateur accessibles dans des applications web","Personnaliser les composants shadcn-ui pour la cohérence de la marque","Créer des applications avec des éléments d''interface utilisateur réutilisables en utilisant Radix UI et Tailwind CSS"],"de":["Integrieren von zugänglichen Benutzeroberflächenkomponenten in Webanwendungen","Anpassen von shadcn-ui-Komponenten für Markenkontinuität","Erstellen von Anwendungen mit wiederverwendbaren Benutzeroberflächenelementen unter Verwendung von Radix UI und Tailwind CSS"],"pt":["Integrar componentes de UI acessíveis em aplicações web","Personalizar componentes shadcn-ui para consistência de marca","Construir aplicações com elementos de UI reutilizáveis usando Radix UI e Tailwind CSS"],"ru":["Интегрировать доступные компоненты UI в веб-приложения","Настроить компоненты shadcn-ui для соответствия бренду","Разрабатывать приложения с повторно используемыми элементами UI с помощью Radix UI и Tailwind CSS"],"ar":["دمج مكونات واجهة المستخدم المتوافقة في تطبيقات الويب","تخصيص مكونات shadcn-ui لتوافق العلامة التجارية","بناء التطبيقات باستخدام عناصر واجهة المستخدم القابلة لإعادة الاستخدام مع Radix UI و Tailwind CSS"]},"limitations":{"en":["Not a traditional component library, requires copying components into projects"],"zh":["不是传统的组件库，需要将组件复制到项目中"],"ja":["従来のコンポーネントライブラリではなく、コンポーネントをプロジェクトにコピーする必要がある"],"ko":["전통적인 컴포넌트 라이브러리가 아니므로, 컴포넌트를 프로젝트에 복사해야 함"],"es":["No es una biblioteca de componentes tradicional, requiere copiar componentes en proyectos"],"fr":["N''est pas une bibliothèque de composants traditionnelle, nécessite de copier des composants dans des projets"],"de":["Ist keine herkömmliche Komponentenbibliothek, erfordert das Kopieren von Komponenten in Projekte"],"pt":["Não é uma biblioteca de componentes tradicional, requer copiar componentes para projetos"],"ru":["Не является традиционной библиотекой компонентов, требует копирования компонентов в проекты"],"ar":["ليست مكتبة مكونات تقليدية، تتطلب نسخ المكونات إلى المشاريع"]},"version":4},"contentHash":"2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304","qualityScore":57}');
