INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Parthivjoshi29/agent-skills-npm-package/shadcn-ui', 'shadcn-ui', 'Parthivjoshi29', 'agent-skills-npm-package', 'community', 'shadcn-ui Parthivjoshi29 agent-skills-npm-package community shadcn-ui helps frontend engineers build applications with beautifully designed components, utilizing Radix UI or Base UI and Tailwind CSS. It benefits developers seeking customizable and accessible UI elements. shadcn-ui是一个集合了Radix UI和Tailwind CSS的可访问且自定义的组件集合，帮助开发者发现、集成和自定义组件 shadcn-uiは、Radix UIとTailwind CSSを組み合わせたアクセシブルでカスタマイズ可能なコンポーネントのコレクションです。開発者がコンポーネントを発見、統合、カスタマイズするのを支援します shadcn-ui는 Radix UI와 Tailwind CSS를 결합한 접근성과 사용자 정의가 가능한 컴포넌트의 집합으로, 개발자가 컴포넌트를 발견, 통합 및 사용자 정의하는 것을 지원합니다 shadcn-ui es una colección de componentes reutilizables para mejorar la accesibilidad y personalización de tus aplicaciones shadcn-ui est un ensemble de composants réutilisables pour améliorer l''accessibilité et la personnalisation de vos applications shadcn-ui ist eine Sammlung von wiederverwendbaren Komponenten zur Verbesserung der Zugänglichkeit und Anpassungsfähigkeit Ihrer Anwendungen shadcn-ui é uma coleção de componentes reutilizáveis projetados com Radix UI, Base UI e Tailwind CSS para desenvolvedores frontend shadcn-ui — это коллекция повторно используемых компонентов, разработанных с помощью Radix UI, Base UI и Tailwind CSS для frontend-разработчиков شادسن-وي هو مجموعة من المكونات القابلة لإعادة الاستخدام المصممة باستخدام Radix UI و Base UI و Tailwind CSS لمنصة التطوير الأمامية how to use shadcn-ui shadcn-ui alternative shadcn-ui vs radix ui shadcn-ui install shadcn-ui setup guide what is shadcn-ui shadcn-ui component library shadcn-ui customization shadcn-ui accessibility shadcn-ui Radix UI Tailwind CSS 可访问组件 自定义组件 不需要额外的组件库 开发者工具 前端开发 AIエージェント Utilizes Radix UI for building accessible and customizable components Leverages Base UI for creating consistent and reusable UI elements Integrates with Tailwind CSS for styling and layout management Provides full ownership of components by copying them into projects Follows best practices for component discovery, integration, and customization Supports customization of components for unique application needs shadcn-ui is a collection of reusable, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS, designed for frontend engineers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mhiggs82/parentwise_summary_site_2/shadcn-ui', 'community', 'mhiggs82', 'parentwise_summary_site_2', 'mhiggs82/parentwise_summary_site_2', 'shadcn-ui', 0, 0, 57, '2026-03-06T06:23:00.171Z', '2026-03-06T07:37:51.207Z', '2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304', '{"id":"mhiggs82/parentwise_summary_site_2/shadcn-ui","name":"shadcn-ui","description":{"en":"shadcn-ui is a collection of reusable components for frontend engineers. It helps developers discover, integrate, and customize components following best practices.","zh":"shadcn-ui 是一个使用 Radix UI 和 Tailwind CSS 构建的可访问性和自定义的组件集合。它提供了全面的所有权和灵活性","ja":"shadcn-ui は、Radix UI と Tailwind CSS を使用して構築された、カスタマイズ可能でアクセシブルなコンポーネントのコレクションです。全面的所有権と柔軟性を提供します","ko":"shadcn-ui는 Radix UI와 Tailwind CSS를 사용하여 구축된 사용자 정의 가능하고 접근 가능한 컴포넌트의 모음입니다. 완전한 소유권과 유연성을 제공합니다","es":"shadcn-ui es una colección de componentes personalizables construidos con Radix UI y Tailwind CSS. Aprende a integrarlos en tus proyectos","fr":"shadcn-ui est une collection de composants personnalisables construits avec Radix UI et Tailwind CSS. Apprenez à les intégrer dans vos projets","de":"shadcn-ui ist eine Sammlung von anpassbaren Komponenten, die mit Radix UI und Tailwind CSS erstellt wurden. Erfahren Sie, wie Sie sie in Ihre Projekte integrieren können","pt":"shadcn-ui é uma coleção de componentes UI personalizáveis e acessíveis construídos com Radix UI e Tailwind CSS.","ru":"shadcn-ui - это коллекция настраиваемых и доступных компонентов UI, построенных с помощью Radix UI и Tailwind CSS.","ar":"شادسن-يوي هي مجموعة من مكونات واجهة المستخدم القابلة للتعديل والوصول مبنية مع راديكس يوي وتايلويند سي اس."},"seo":{"title":{"en":"shadcn-ui: Setup Guide for AI Agents | AI Agent Skill","zh":"shadcn-ui 集成指南 - 使用 Radix UI 和 Tailwind CSS","ja":"shadcn-ui のセットアップガイド - AIエージェントによるカスタマイズ","ko":"shadcn-ui 설정 가이드 - Radix UI와 Tailwind CSS를 이용한 컴포넌트 통합","es":"Guía de configuración de shadcn-ui: Integración de compon...","fr":"Guide d''intégration de shadcn-ui: Composants personnalisa...","de":"Einrichtungsanleitung für shadcn-ui: Integration von Komp...","pt":"Guia de Configuração shadcn-ui: Componentes UI Personaliz...","ru":"ИИ Агенты shadcn-ui: Руководство по Настройке Компонентов","ar":"دليل إعداد شادسن-يوي: مكونات واجهة المستخدم القابلة للتعديل"},"description":{"en":"Discover how to integrate shadcn-ui components with Radix UI and Tailwind CSS. Learn best practices for customization and get started with shadcn-ui today!","zh":"了解 shadcn-ui 的核心原则和技术细节，发现如何使用 Radix UI 和 Tailwind CSS 进行可访问性和自定义的组件集成","ja":"shadcn-ui を使用して、AIエージェントによるカスタマイズと Radix UI、Tailwind CSS の組み込みを実現する方法を学びます","ko":"shadcn-ui의 핵심 원칙과 기술 세부 사항을 살펴보고 Radix UI와 Tailwind CSS를 사용하여 접근성 및 사용자 정의 가능한 컴포넌트를 통합하는 방법을 발견합니다","es":"Aprende a integrar shadcn-ui en tus proyectos con nuestra guía de configuración. Descubre cómo personalizar componentes con Radix UI y Tailwind CSS","fr":"Découvrez comment intégrer shadcn-ui dans vos projets avec notre guide de configuration. Personnalisez des composants avec Radix UI et Tailwind CSS","de":"Erfahren Sie, wie Sie shadcn-ui in Ihre Projekte integrieren können. Entdecken Sie, wie Sie Komponenten mit Radix UI und Tailwind CSS anpassen können","pt":"Aprenda a integrar e personalizar componentes shadcn-ui com Radix UI, Base UI e Tailwind CSS para criar aplicações acessíveis e personalizadas.","ru":"Узнайте, как интегрировать и настраивать компоненты shadcn-ui с помощью Radix UI, Base UI и Tailwind CSS для создания доступных и настраиваемых приложений.","ar":"تعلم كيفية دمج ومخصصة مكونات شادسن-يوي مع راديكس يوي وبيس يوي وتايلويند سي اس لإنشاء تطبيقات قابلة للوصول ومخصصة."},"definition":{"en":"shadcn-ui is a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS.","zh":"shadcn-ui 是一个不需要组件库的、可复用的组件集合，使用 Radix UI 和 Tailwind CSS 构建","ja":"shadcn-ui は、コンポーネントライブラリを必要とせず、Radix UI と Tailwind CSS を使用して構築された再利用可能なコンポーネントのコレクションです","ko":"shadcn-ui는 컴포넌트 라이브러리가 필요하지 않은 재사용 가능한 컴포넌트의 모음으로 Radix UI와 Tailwind CSS를 사용하여 구축됩니다","es":"shadcn-ui es una colección de componentes reutilizables que se copian en el proyecto, no una biblioteca de componentes","fr":"shadcn-ui est une collection de composants réutilisables qui sont copiés dans le projet, et non une bibliothèque de composants","de":"shadcn-ui ist eine Sammlung von wiederverwendbaren Komponenten, die in das Projekt kopiert werden, keine Komponentenbibliothek","pt":"shadcn-ui é uma coleção de componentes UI reutilizáveis que podem ser copiados e personalizados para projetos.","ru":"shadcn-ui - это коллекция повторно используемых компонентов UI, которые можно копировать и настраивать для проектов.","ar":"شادسن-يوي هي مجموعة من مكونات واجهة المستخدم القابلة لإعادة الاستخدام التي يمكن نسخها وتخصيصها للمشاريع."},"features":{"en":["Provides full ownership of components by copying them into the project","Supports customization using Radix UI or Base UI","Integrates with Tailwind CSS for styling","Allows for discoverability and integration of components following best practices","Enables developers to work with a collection of reusable components","Built with accessibility in mind"],"zh":["使用 Radix UI 构建的可访问性组件","Tailwind CSS 支持的自定义样式","全面的所有权和灵活性","不需要组件库的再利用性","可集成到现有项目中"],"ja":["Radix UI を使用して構築されたアクセシブルなコンポーネント","Tailwind CSS によるカスタマイズ可能なスタイル","全面的所有権と柔軟性","コンポーネントライブラリを必要とせずに再利用可能","既存のプロジェクトに統合可能"],"ko":["Radix UI를 사용하여 구축된 접근 가능한 컴포넌트","Tailwind CSS를 통한 사용자 정의 가능한 스타일","완전한 소유권과 유연성","컴포넌트 라이브러리가 필요하지 않은 재사용 가능","기존 프로젝트에 통합 가능"],"es":["Componentes personalizables con Radix UI","Integración con Tailwind CSS","Colección de componentes reutilizables","No requiere una biblioteca de componentes","Permite la personalización de componentes","Compatibilidad con proyectos de frontend"],"fr":["Composants personnalisables avec Radix UI","Intégration avec Tailwind CSS","Collection de composants réutilisables","N''a pas besoin d''une bibliothèque de composants","Permet la personnalisation de composants","Compatibilité avec les projets de frontend"],"de":["Anpassbare Komponenten mit Radix UI","Integration mit Tailwind CSS","Sammlung von wiederverwendbaren Komponenten","Benötigt keine Komponentenbibliothek","Ermöglicht die Anpassung von Komponenten","Kompatibilität mit Frontend-Projekten"],"pt":["Componentes UI personalizáveis com Radix UI","Compatibilidade com Base UI e Tailwind CSS","Acessibilidade e customização de componentes","Código reutilizável e flexível","Integração fácil com projetos existentes"],"ru":["Настраиваемые компоненты UI с помощью Radix UI","Совместимость с Base UI и Tailwind CSS","Доступность и настройка компонентов","Переиспользуемый и гибкий код","Легкая интеграция с существующими проектами"],"ar":["مكونات واجهة المستخدم القابلة للتعديل مع راديكس يوي","التوافق مع بيس يوي وتايلويند سي اس","إمكانية الوصول وتخصيص المكونات","كود قابل لإعادة الاستخدامและมرونة","دمج سهل مع المشاريع الحالية"]},"keywords":{"en":["how to use shadcn-ui","shadcn-ui alternative","shadcn-ui setup guide","what is shadcn-ui","shadcn-ui vs radix ui","shadcn-ui install","shadcn-ui customization","shadcn-ui and tailwind css","shadcn-ui best practices"],"zh":["shadcn-ui","Radix UI","Tailwind CSS","可访问性组件","自定义样式","全面的所有权","再利用性","组件集成"],"ja":["shadcn-ui","Radix UI","Tailwind CSS","AIエージェント","アクセシブルなコンポーネント","カスタマイズ可能なスタイル","全面的所有権","再利用性","コンポーネントの統合"],"ko":["shadcn-ui","Radix UI","Tailwind CSS","AI 도구","접근 가능한 컴포넌트","사용자 정의 가능한 스타일","완전한 소유권","재사용 가능","컴포넌트 통합"],"es":["shadcn-ui","integración de componentes","Radix UI","Tailwind CSS","personalización de componentes","frontend","desarrollo web","herramientas de desarrollo","bibliotecas de componentes"],"fr":["shadcn-ui","intégration de composants","Radix UI","Tailwind CSS","personnalisation de composants","frontend","développement web","outils de développement","bibliothèques de composants"],"de":["shadcn-ui","Integration von Komponenten","Radix UI","Tailwind CSS","Anpassung von Komponenten","Frontend","Webentwicklung","Entwicklungstools","Komponentenbibliotheken"],"pt":["shadcn-ui","componentes UI personalizáveis","Radix UI","Base UI","Tailwind CSS","acessibilidade","customização","reutilização de código"],"ru":["shadcn-ui","настраиваемые компоненты UI","Radix UI","Base UI","Tailwind CSS","доступность","настройка","переиспользуемый код"],"ar":["شادسن-يوي","مكونات واجهة المستخدم القابلة للتعديل","راديكس يوي","بيس يوي","تايلويند سي اس","إمكانية الوصول","تخصيص","كود قابل لإعادة الاستخدام"]}},"owner":"mhiggs82","repo":"parentwise_summary_site_2","repoPath":"mhiggs82/parentwise_summary_site_2","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.171Z","topics":[],"category":"community","skillMd":{"name":"shadcn-ui","description":"Expert guidance for integrating and building applications with shadcn/ui components, including component discovery, installation, customization, and best practices.","bodyPreview":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full owner","body":"# shadcn/ui Component Integration\n\nYou are a frontend engineer specialized in building applications with shadcn/ui—a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS. You help developers discover, integrate, and customize components following best practices.\n\n## Core Principles\n\nshadcn/ui is **not a component library**—it''s a collection of reusable components that you copy into your project. This gives you:\n- **Full ownership**: Components live in your codebase, not node_modules\n- **Complete customization**: Modify styling, behavior, and structure freely, including choosing between Radix UI or Base UI primitives\n- **No version lock-in**: Update components selectively at your own pace\n- **Zero runtime overhead**: No library bundle, just the code you need\n\n## Component Discovery and Installation\n\n### 1. Browse Available Components\n\nUse the shadcn MCP tools to explore the component catalog and Registry Directory:\n- **List all components**: Use `list_components` to see the complete catalog\n- **Get component metadata**: Use `get_component_metadata` to understand props, dependencies, and usage\n- **View component demos**: Use `get_component_demo` to see implementation examples\n\n### 2. Component Installation\n\nThere are two approaches to adding components:\n\n**A. Direct Installation (Recommended)**\n```bash\nnpx shadcn@latest add [component-name]\n```\n\nThis command:\n- Downloads the component source code (adapting to your config: Radix vs Base UI)\n- Installs required dependencies\n- Places files in `components/ui/`\n- Updates your `components.json` config\n\n**B. Manual Integration**\n1. Use `get_component` to retrieve the source code\n2. Create the file in `components/ui/[component-name].tsx`\n3. Install peer dependencies manually\n4. Adjust imports if needed\n\n### 3. Registry and Custom Registries\n\nIf working with a custom registry (defined in `components.json`) or exploring the Registry Directory:\n- Use `get_project_registries` to list available registries\n- Use `list_items_in_registries` to see registry-specific components\n- Use `view_items_in_registries` for detailed component information\n- Use `search_items_in_registries` to find specific components\n\n## Project Setup\n\n### Initial Configuration\n\nFor **new projects**, use the `create` command to customize everything (style, fonts, component library):\n\n```bash\nnpx shadcn@latest create\n```\n\nFor **existing projects**, initialize configuration:\n\n```bash\nnpx shadcn@latest init\n```\n\nThis creates `components.json` with your configuration:\n- **style**: default, new-york (classic) OR choose new visual styles like Vega, Nova, Maia, Lyra, Mira\n- **baseColor**: slate, gray, zinc, neutral, stone\n- **cssVariables**: true/false for CSS variable usage\n- **tailwind config**: paths to Tailwind files\n- **aliases**: import path shortcuts\n- **rsc**: Use React Server Components (yes/no)\n- **rtl**: Enable RTL support (optional)\n\n### Required Dependencies\n\nshadcn/ui components require:\n- **React** (18+)\n- **Tailwind CSS** (3.0+)\n- **Primitives**: Radix UI OR Base UI (depending on your choice)\n- **class-variance-authority** (for variant styling)\n- **clsx** and **tailwind-merge** (for class composition)\n\n## Component Architecture\n\n### File Structure\n```\nsrc/\n├── components/\n│   ├── ui/              # shadcn components\n│   │   ├── button.tsx\n│   │   ├── card.tsx\n│   │   └── dialog.tsx\n│   └── [custom]/        # your composed components\n│       └── user-card.tsx\n├── lib/\n│   └── utils.ts         # cn() utility\n└── app/\n    └── page.tsx\n```\n\n### The `cn()` Utility\n\nAll shadcn components use the `cn()` helper for class merging:\n\n```typescript\nimport { clsx, type ClassValue } from \"clsx\"\nimport { twMerge } from \"tailwind-merge\"\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs))\n}\n```\n\nThis allows you to:\n- Override default styles without conflicts\n- Conditionally apply classes\n- Merge Tailwind classes intelligently\n\n## Customization Best Practices\n\n### 1. Theme Customization\n\nEdit your Tailwind config and CSS variables in `app/globals.css`:\n\n```css\n@layer base {\n  :root {\n    --background: 0 0% 100%;\n    --foreground: 222.2 84% 4.9%;\n    --primary: 221.2 83.2% 53.3%;\n    /* ... more variables */\n  }\n  \n  .dark {\n    --background: 222.2 84% 4.9%;\n    --foreground: 210 40% 98%;\n    /* ... dark mode overrides */\n  }\n}\n```\n\n### 2. Component Variants\n\nUse `class-variance-authority` (cva) for variant logic:\n\n```typescript\nimport { cva } from \"class-variance-authority\"\n\nconst buttonVariants = cva(\n  \"inline-flex items-center justify-center rounded-md\",\n  {\n    variants: {\n      variant: {\n        default: \"bg-primary text-primary-foreground\",\n        outline: \"border border-input\",\n      },\n      size: {\n        default: \"h-10 px-4 py-2\",\n        sm: \"h-9 rounded-md px-3\",\n      },\n    },\n    defaultVariants: {\n      variant: \"default\",\n      size: \"default\",\n    },\n  }\n)\n```\n\n### 3. Extending Components\n\nCreate wrapper components in `components/` (not `components/ui/`):\n\n```typescript\n// components/custom-button.tsx\nimport { Button } from \"@/components/ui/button\"\nimport { Loader2 } from \"lucide-react\"\n\nexport function LoadingButton({ \n  loading, \n  children, \n  ...props \n}: ButtonProps & { loading?: boolean }) {\n  return (\n    <Button disabled={loading} {...props}>\n      {loading && <Loader2 className=\"mr-2 h-4 w-4 animate-spin\" />}\n      {children}\n    </Button>\n  )\n}\n```\n\n## Blocks and Complex Components\n\nshadcn/ui provides complete UI blocks (authentication forms, dashboards, etc.):\n\n1. **List available blocks**: Use `list_blocks` with optional category filter\n2. **Get block source**: Use `get_block` with the block name\n3. **Install blocks**: Many blocks include multiple component files\n\nBlocks are organized by category:\n- **calendar**: Calendar interfaces\n- **dashboard**: Dashboard layouts\n- **login**: Authentication flows\n- **sidebar**: Navigation sidebars\n- **products**: E-commerce components\n\n## Accessibility\n\nAll shadcn/ui components are built on Radix UI primitives, ensuring:\n- **Keyboard navigation**: Full keyboard support out of the box\n- **Screen reader support**: Proper ARIA attributes\n- **Focus management**: Logical focus flow\n- **Disabled states**: Proper disabled and aria-disabled handling\n\nWhen customizing, maintain accessibility:\n- Keep ARIA attributes\n- Preserve keyboard handlers\n- Test with screen readers\n- Maintain focus indicators\n\n## Common Patterns\n\n### Form Building\n```typescript\nimport { Button } from \"@/components/ui/button\"\nimport { Input } from \"@/components/ui/input\"\nimport { Label } from \"@/components/ui/label\"\n\n// Use with react-hook-form for validation\nimport { useForm } from \"react-hook-form\"\n```\n\n### Dialog/Modal Patterns\n```typescript\nimport {\n  Dialog,\n  DialogContent,\n  DialogDescription,\n  DialogHeader,\n  DialogTitle,\n  DialogTrigger,\n} from \"@/components/ui/dialog\"\n```\n\n### Data Display\n```typescript\nimport {\n  Table,\n  TableBody,\n  TableCell,\n  TableHead,\n  TableHeader,\n  TableRow,\n} from \"@/components/ui/table\"\n```\n\n## Troubleshooting\n\n### Import Errors\n- Check `components.json` for correct alias configuration\n- Verify `tsconfig.json` includes the `@` path alias:\n  ```json\n  {\n    \"compilerOptions\": {\n      \"paths\": {\n        \"@/*\": [\"./src/*\"]\n      }\n    }\n  }\n  ```\n\n### Style Conflicts\n- Ensure Tailwind CSS is properly configured\n- Check that `globals.css` is imported in your root layout\n- Verify CSS variable names match between components and theme\n\n### Missing Dependencies\n- Run component installation via CLI to auto-install deps\n- Manually check `package.json` for required Radix UI packages\n- Use `get_component_metadata` to see dependency lists\n\n### Version Compatibility\n- shadcn/ui v4 requires React 18+ and Next.js 13+ (if using Next.js)\n- Some components require specific Radix UI versions\n- Check documentation for breaking changes between versions\n\n## Validation and Quality\n\nBefore committing components:\n1. **Type check**: Run `tsc --noEmit` to verify TypeScript\n2. **Lint**: Run your linter to catch style issues\n3. **Test accessibility**: Use tools like axe DevTools\n4. **Visual QA**: Test in light and dark modes\n5. **Responsive check**: Verify behavior at different breakpoints\n\n## Resources\n\nRefer to the following resource files for detailed guidance:\n- `resources/setup-guide.md` - Step-by-step project initialization\n- `resources/component-catalog.md` - Complete component reference\n- `resources/customization-guide.md` - Theming and variant patterns\n- `resources/migration-guide.md` - Upgrading from other UI libraries\n\n## Examples\n\nSee the `examples/` directory for:\n- Complete component implementations\n- Form patterns with validation\n- Dashboard layouts\n- Authentication flows\n- Data table implementations\n"},"lastSynced":"2026-03-06T07:37:51.207Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing reusable, accessible, and customizable UI components built with Radix UI, Base UI, and Tailwind CSS.","zh":"非常适合需要可重用、可访问和可定制UI组件的前端代理，使用Radix UI、Base UI和Tailwind CSS构建。","ja":"Radix UI、Base UI、Tailwind CSSを使用して構築された再利用可能な、アクセス可能な、カスタマイズ可能なUIコンポーネントを必要とするフロントエンドエージェントに最適です。","ko":"Radix UI, Base UI, Tailwind CSS로 구축된 재사용 가능하고 접근 가능하며 사용자 지정 가능한 UI 컴포넌트가 필요한 프론트엔드 에이전트에게 완벽합니다.","es":"Perfecto para agentes frontend que necesitan componentes de interfaz de usuario reutilizables, accesibles y personalizables construidos con Radix UI, Base UI y Tailwind CSS.","fr":"Parfait pour les agents frontend ayant besoin de composants d''interface utilisateur réutilisables, accessibles et personnalisables construits avec Radix UI, Base UI et Tailwind CSS.","de":"Perfekt für Frontend-Agents, die wiederverwendbare, zugängliche und anpassbare Benutzeroberflächenkomponenten benötigen, die mit Radix UI, Base UI und Tailwind CSS erstellt wurden.","pt":"Perfeito para Agentes Frontend que precisam de componentes de UI reutilizáveis, acessíveis e personalizáveis construídos com Radix UI, Base UI e Tailwind CSS.","ru":"Идеально подходит для агентов Frontend, которым необходимы повторно используемые, доступные и настраиваемые компоненты UI, построенные с помощью Radix UI, Base UI и Tailwind CSS.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذين يحتاجون إلى مكونات واجهة المستخدم القابلة لإعادة الاستخدام والمتوافقة والقابلة للتعديل المصنعة باستخدام Radix UI و Base UI و Tailwind CSS."},"recommendation":{"en":"Empowers agents to discover, integrate, and customize UI components following best practices, leveraging full ownership of the components by copying them into their project, and utilizing libraries like Radix UI and Tailwind CSS for seamless integration.","zh":"赋予代理发现、集成和自定义UI组件的能力，遵循最佳实践，通过将组件复制到项目中实现对组件的完全所有权，并利用Radix UI和Tailwind CSS等库实现无缝集成。","ja":"ベストプラクティスに従ってUIコンポーネントを検出、統合、カスタマイズするエージェントをEmpowerし、コンポーネントをプロジェクトにコピーすることでコンポーネントの完全な所有権を持ち、Radix UIやTailwind CSSなどのライブラリを利用してシームレスな統合を行う。","ko":"에이전트가 UI 컴포넌트를 발견하고 통합 및 사용자 정의할 수 있도록 하는 동시에 최고의實踐을 따르며, 컴포넌트를 프로젝트에 복사하여 컴포넌트에 대한 완전한 소유권을 가지며, Radix UI 및 Tailwind CSS 등의 라이브러리를 사용하여 무결점 통합을 구현할 수 있습니다.","es":"Permite a los agentes descubrir, integrar y personalizar componentes de interfaz de usuario siguiendo las mejores prácticas, aprovechando la propiedad total de los componentes copiándolos en su proyecto y utilizando bibliotecas como Radix UI y Tailwind CSS para una integración sin problemas.","fr":"Permet aux agents de découvrir, d''intégrer et de personnaliser des composants d''interface utilisateur en suivant les meilleures pratiques, en exploitant la pleine propriété des composants en les copiant dans leur projet et en utilisant des bibliothèques comme Radix UI et Tailwind CSS pour une intégration sans heurts.","de":"Ermöglicht es den Agenten, Benutzeroberflächenkomponenten zu entdecken, zu integrieren und anzupassen, indem sie bewährte Verfahren befolgen, die volle Kontrolle über die Komponenten übernehmen, indem sie diese in ihr Projekt kopieren, und Bibliotheken wie Radix UI und Tailwind CSS für eine nahtlose Integration nutzen.","pt":"Permite que os agentes descubram, integrem e personalizem componentes de UI seguindo as melhores práticas, aproveitando a propriedade total dos componentes copiando-os para o seu projeto e utilizando bibliotecas como Radix UI e Tailwind CSS para integração sem problemas.","ru":"Наделяет агентов возможностью обнаруживать, интегрировать и настраивать компоненты UI, следуя лучшим практикам, используя полную собственность компонентов, копируя их в проект, и используя библиотеки, такие как Radix UI и Tailwind CSS, для беспроблемной интеграции.","ar":"يمكن للوكلاء اكتشاف وتكامل وتعديل مكونات واجهة المستخدم اتباعاً لأفضل الممارسات، و Sử باستخدام ملكية كاملة للمكونات عن طريق نسخها إلى مشروعهم، واستخدام مكتبات مثل Radix UI و Tailwind CSS من أجل التكامل السلس."},"useCases":{"en":["Integrating accessible UI components into web applications","Customizing reusable components for tailored user experiences","Discovering and utilizing pre-built UI components for rapid frontend development"],"zh":["将可访问的UI组件集成到Web应用程序中","为定制的用户体验而定制可重用组件","发现和利用预建UI组件进行快速的前端开发"],"ja":["Webアプリケーションにアクセス可能なUIコンポーネントを統合する","カスタマイズされたユーザー体験のために再利用可能なコンポーネントをカスタマイズする","事前に構築されたUIコンポーネントを発見し、利用して迅速なフロントエンド開発を行う"],"ko":["웹 애플리케이션에 접근 가능한 UI 컴포넌트를 통합하는 것","사용자 정의 사용자 경험을 위한 재사용 가능한 컴포넌트를 사용자 정의하는 것","사전 구축된 UI 컴포넌트를 발견하고 사용하여 빠른 프론트엔드 개발을 수행하는 것"],"es":["Integrar componentes de interfaz de usuario accesibles en aplicaciones web","Personalizar componentes reutilizables para experiencias de usuario personalizadas","Descubrir y utilizar componentes de interfaz de usuario preconstruidos para un desarrollo frontend rápido"],"fr":["Intégrer des composants d''interface utilisateur accessibles dans des applications web","Personnaliser des composants réutilisables pour des expériences utilisateur sur mesure","Découvrir et utiliser des composants d''interface utilisateur préconstruits pour un développement frontend rapide"],"de":["Zugängliche Benutzeroberflächenkomponenten in Webanwendungen integrieren","Wiederverwendbare Komponenten für maßgeschneiderte Benutzererfahrungen anpassen","Vorab erstellte Benutzeroberflächenkomponenten entdecken und für eine schnelle Frontend-Entwicklung nutzen"],"pt":["Integrar componentes de UI acessíveis em aplicações web","Personalizar componentes reutilizáveis para experiências de usuário personalizadas","Descobrir e utilizar componentes de UI pré-construídos para desenvolvimento rápido de frontend"],"ru":["Интегрировать доступные компоненты UI в веб-приложения","Настроить повторно используемые компоненты для индивидуальных пользовательских опытов","Обнаружить и использовать предварительно построенные компоненты UI для быстрого разработки frontend"],"ar":["دمج مكونات واجهة المستخدم المتوافقة في تطبيقات الويب","تعديل مكونات قابلة لإعادة الاستخدام لتجارب مستخدم مخصصة","اكتشاف واستخدام مكونات واجهة المستخدم المسبقة البناء من أجل تطوير واجهة المستخدم الأمامية السريع"]},"limitations":{"en":["Not a traditional component library, requires copying components into the project","Specifically designed for use with Radix UI, Base UI, and Tailwind CSS"],"zh":["不是传统的组件库，需要将组件复制到项目中","专门为使用Radix UI、Base UI和Tailwind CSS设计"],"ja":["従来のコンポーネントライブラリではなく、コンポーネントをプロジェクトにコピーする必要がある","Radix UI、Base UI、Tailwind CSSを使用するように特別に設計されている"],"ko":["전통적인 컴포넌트 라이브러리가 아니며, 컴포넌트를 프로젝트에 복사해야 함","Radix UI, Base UI, Tailwind CSS를 사용하도록 특별히 설계됨"],"es":["No es una biblioteca de componentes tradicional, requiere copiar componentes en el proyecto","Diseñado específicamente para su uso con Radix UI, Base UI y Tailwind CSS"],"fr":["N''est pas une bibliothèque de composants traditionnelle, nécessite de copier des composants dans le projet","Conçu spécifiquement pour une utilisation avec Radix UI, Base UI et Tailwind CSS"],"de":["Keine herkömmliche Komponentenbibliothek, erfordert das Kopieren von Komponenten in das Projekt","Speziell für die Verwendung mit Radix UI, Base UI und Tailwind CSS entwickelt"],"pt":["Não é uma biblioteca de componentes tradicional, requer a cópia de componentes para o projeto","Projetada especificamente para uso com Radix UI, Base UI e Tailwind CSS"],"ru":["Не является традиционной библиотекой компонентов, требует копирования компонентов в проект","Специально разработана для использования с Radix UI, Base UI и Tailwind CSS"],"ar":["ليست مكتبة مكونات تقليدية، تتطلب نسخ المكونات إلى المشروع","صممت خصيصاً للاستخدام مع Radix UI و Base UI و Tailwind CSS"]},"version":4},"contentHash":"2ddfe599ac2ba631ca019f7b6e37ee5df9cd34f83fc016f6ea9d4ba5bbfa0304","qualityScore":57}');
