INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mhiggs82/parentwise_summary_site_2/shadcn-ui', 'shadcn-ui', 'mhiggs82', 'parentwise_summary_site_2', 'community', 'shadcn-ui mhiggs82 parentwise_summary_site_2 community shadcn-ui is a collection of reusable components for frontend engineers. It helps developers discover, integrate, and customize components following best practices. shadcn-ui 是一个使用 Radix UI 和 Tailwind CSS 构建的可访问性和自定义的组件集合。它提供了全面的所有权和灵活性 shadcn-ui は、Radix UI と Tailwind CSS を使用して構築された、カスタマイズ可能でアクセシブルなコンポーネントのコレクションです。全面的所有権と柔軟性を提供します shadcn-ui는 Radix UI와 Tailwind CSS를 사용하여 구축된 사용자 정의 가능하고 접근 가능한 컴포넌트의 모음입니다. 완전한 소유권과 유연성을 제공합니다 shadcn-ui es una colección de componentes personalizables construidos con Radix UI y Tailwind CSS. Aprende a integrarlos en tus proyectos shadcn-ui est une collection de composants personnalisables construits avec Radix UI et Tailwind CSS. Apprenez à les intégrer dans vos projets shadcn-ui ist eine Sammlung von anpassbaren Komponenten, die mit Radix UI und Tailwind CSS erstellt wurden. Erfahren Sie, wie Sie sie in Ihre Projekte integrieren können shadcn-ui é uma coleção de componentes UI personalizáveis e acessíveis construídos com Radix UI e Tailwind CSS. shadcn-ui - это коллекция настраиваемых и доступных компонентов UI, построенных с помощью Radix UI и Tailwind CSS. شادسن-يوي هي مجموعة من مكونات واجهة المستخدم القابلة للتعديل والوصول مبنية مع راديكس يوي وتايلويند سي اس. how to use shadcn-ui shadcn-ui alternative shadcn-ui setup guide what is shadcn-ui shadcn-ui vs radix ui shadcn-ui install shadcn-ui customization shadcn-ui and tailwind css shadcn-ui best practices shadcn-ui Radix UI Tailwind CSS 可访问性组件 自定义样式 全面的所有权 再利用性 组件集成 Provides full ownership of components by copying them into the project Supports customization using Radix UI or Base UI Integrates with Tailwind CSS for styling Allows for discoverability and integration of components following best practices Enables developers to work with a collection of reusable components Built with accessibility in mind shadcn-ui is a collection of beautifully designed, accessible, and customizable components built with Radix UI or Base UI and Tailwind CSS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CongSofwareEngineer/hodiencong-info/tailwind-design-system', 'community', 'CongSofwareEngineer', 'hodiencong-info', 'CongSofwareEngineer/hodiencong-info', 'tailwind-design-system', 0, 0, 57, '2026-03-07T01:49:01.625Z', '2026-03-07T02:13:11.718Z', 'd010d2f9bb19b6aca7c51f460fb9b32564dbebc09610ea873abb636232d2fe26', '{"id":"CongSofwareEngineer/hodiencong-info/tailwind-design-system","name":"tailwind-design-system","description":{"en":"The tailwind-design-system skill helps developers create production-ready design systems with Tailwind CSS v4, including component variants and accessibility features. It benefits developers building component libraries and implementing design tokens.","zh":"Tailwind 设计系统是一个使用 Tailwind CSS v4 搭建生产就绪的设计系统，包括 CSS-first 配置、设计令牌和组件变体","ja":"Tailwind デザイン システムは、Tailwind CSS v4 を使用して生産性の高いデザイン システムを構築するもので、CSS-first 構成、デザイン トークン、コンポーネント バリアントを含みます","ko":"Tailwind 디자인 시스템은 Tailwind CSS v4를 사용하여 생산 준비가 된 디자인 시스템을 구축하는 것으로, CSS-first 구성, 디자인 토큰, 컴포넌트 버전을 포함합니다","es":"Tailwind Design System es una herramienta para crear sistemas de diseño personalizados con Tailwind CSS v4, incluyendo configuración CSS-first, tokens de diseño y componentes receptivos","fr":"Tailwind Design System est un outil pour créer des systèmes de design personnalisés avec Tailwind CSS v4, incluant une configuration CSS-first, des jetons de design et des composants réactifs","de":"Tailwind Design System ist ein Tool zum Erstellen benutzerdefinierter Design-Systeme mit Tailwind CSS v4, einschließlich CSS-First-Konfiguration, Design-Tokens und responsiven Komponenten","pt":"O Tailwind Design System é uma ferramenta para criar sistemas de design produção-prontos com Tailwind CSS v4.","ru":"Система дизайна Tailwind - это инструмент для создания производственных систем дизайна с Tailwind CSS v4.","ar":"نظام تصميم Tailwind هو أداة لإنشاء أنظمة تصميم جاهزة للإنتاج مع Tailwind CSS v4."},"seo":{"title":{"en":"tailwind-design-system: Setup Guide for AI Agents | AI Ag...","zh":"Tailwind 设计系统 Setup 指南 - AIエージェント","ja":"Tailwind デザイン システムのベスト プラクティス - AIエージェント","ko":"Tailwind 디자인 시스템 구축 가이드 - AI 에이전트","es":"Guía de configuración de Tailwind Design System para desa...","fr":"Configurer Tailwind Design System : Le guide des meilleur...","de":"Tailwind Design System Einrichten: Eine Anleitung für Ent...","pt":"Guia de Configuração do Tailwind Design System","ru":"Настройка системы дизайна Tailwind: ИИ Агенты","ar":"إعداد نظام تصميم Tailwind: أدوات ذكاء اصطناعي"},"description":{"en":"Unlock the full potential of Tailwind CSS v4 with our tailwind-design-system skill, featuring CSS-first configuration and design tokens. Get started today!","zh":"了解如何使用 Tailwind CSS v4 搭建生产就绪的设计系统，包括 CSS-first 配置、设计令牌、组件变体、响应式模式和无障碍功能","ja":"Tailwind CSS v4 を使用して生産性の高いデザイン システムを構築する方法について学びます。CSS-first 構成、デザイン トークン、コンポーネント バリアント、レスポンシブ パターン、アクセシビリティ機能など","ko":"Tailwind CSS v4를 사용하여 생산 준비가 된 디자인 시스템을 구축하는 방법에 대해 알아보세요. CSS-first 구성, 디자인 토큰, 컴포넌트 버전, 반응형 패턴, 접근성 기능 등","es":"Aprenda a crear sistemas de diseño personalizados con Tailwind CSS v4 y mejore la experiencia del usuario con componentes receptivos y accesibles","fr":"Découvrez comment créer des systèmes de design personnalisés avec Tailwind CSS v4 et améliorez l''expérience utilisateur avec des composants réactifs et acces...","de":"Erfahren Sie, wie Sie benutzerdefinierte Design-Systeme mit Tailwind CSS v4 erstellen und die Benutzererfahrung mit responsiven und zugänglichen Komponenten ...","pt":"Aprenda a criar sistemas de design produção-prontos com Tailwind CSS v4, incluindo configuração CSS-first e tokens de design","ru":"Создайте производственные системы дизайна с Tailwind CSS v4, включая конфигурацию CSS-first и дизайн-токены","ar":"ابني أنظمة تصميم جاهزة للإنتاج مع Tailwind CSS v4، بما في ذلك تكوين CSS-first وأساطير التصميم"},"definition":{"en":"tailwind-design-system is a skill that enables building production-ready design systems with Tailwind CSS v4, including CSS-first configuration, design tokens, and accessibility.","zh":"Tailwind 设计系统是一种使用 Tailwind CSS v4 搭建的设计系统","ja":"Tailwind デザイン システムは、Tailwind CSS v4 を使用して構築されたデザイン システムの一種です","ko":"Tailwind 디자인 시스템은 Tailwind CSS v4를 사용하여 구축된 디자인 시스템의 한 종류입니다","es":"Tailwind Design System es una herramienta de diseño que permite crear sistemas de diseño personalizados con Tailwind CSS v4","fr":"Tailwind Design System est un outil de design qui permet de créer des systèmes de design personnalisés avec Tailwind CSS v4","de":"Tailwind Design System ist ein Design-Tool, mit dem benutzerdefinierte Design-Systeme mit Tailwind CSS v4 erstellt werden können","pt":"O que é Tailwind Design System? É uma ferramenta para criar sistemas de design com Tailwind CSS v4.","ru":"Что такое система дизайна Tailwind? Это инструмент для создания систем дизайна с Tailwind CSS v4.","ar":"ما هو نظام تصميم Tailwind؟ إنه أداة لإنشاء أنظمة تصميم مع Tailwind CSS v4."},"features":{"en":["Builds production-ready design systems with Tailwind CSS v4","Supports CSS-first configuration for customizable designs","Includes design tokens for consistent theming","Offers component variants for flexible UI components","Enables responsive patterns for adaptive layouts","Prioritizes accessibility for inclusive design"],"zh":["CSS-first 配置","设计令牌","组件变体","响应式模式","无障碍功能"],"ja":["CSS-first 構成","デザイン トークン","コンポーネント バリアント","レスポンシブ パターン","アクセシビリティ機能"],"ko":["CSS-first 구성","디자인 토큰","컴포넌트 버전","반응형 패턴","접근성 기능"],"es":["Configuración CSS-first para personalizar el diseño","Tokens de diseño para crear un lenguaje de diseño consistente","Componentes receptivos para una experiencia de usuario óptima","Patrones de diseño accesibles para cumplir con los estándares de accesibilidad","Compatibilidad con Tailwind CSS v4 para proyectos de última generación"],"fr":["Configuration CSS-first pour personnaliser la conception","Jetons de design pour créer un langage de conception cohérent","Composants réactifs pour une expérience utilisateur optimale","Modèles de conception accessibles pour répondre aux normes d''accessibilité","Compatibilité avec Tailwind CSS v4 pour les projets de dernière génération"],"de":["CSS-First-Konfiguration für die Anpassung des Designs","Design-Tokens für die Erstellung einer konsistenten Design-Sprache","Responsive-Komponenten für eine optimale Benutzererfahrung","Zugängliche Design-Muster für die Einhaltung von Zugänglichkeitsstandards","Kompatibilität mit Tailwind CSS v4 für Projekte der neuesten Generation"],"pt":["Configuração CSS-first","Tokens de design","Variantes de componentes","Padrões responsivos","Acessibilidade"],"ru":["Конфигурация CSS-first","Дизайн-токены","Варианты компонентов","Отзывчивые шаблоны","Доступность"],"ar":["تكوين CSS-first","أساطير التصميم","مختلفات المكونات","نماذج استجابة","إمكانية الوصول"]},"keywords":{"en":["how to use tailwind-design-system","tailwind-design-system setup guide","tailwind-design-system vs bootstrap","tailwind-design-system install","what is tailwind-design-system","tailwind-design-system alternative","tailwind css v4 tutorial","design tokens in tailwind","responsive design with tailwind"],"zh":["Tailwind 设计系统","Tailwind CSS v4","CSS-first 配置","设计令牌","组件变体","响应式模式","无障碍功能","AIエージェント"],"ja":["Tailwind デザイン システム","Tailwind CSS v4","CSS-first 構成","デザイン トークン","コンポーネント バリアント","レスポンシブ パターン","アクセシビリティ機能","AIエージェント"],"ko":["Tailwind 디자인 시스템","Tailwind CSS v4","CSS-first 구성","디자인 토큰","컴포넌트 버전","반응형 패턴","접근성 기능","AI 에이전트"],"es":["tailwind design system","tailwind css v4","diseño de sistemas","configuración css-first","tokens de diseño","componentes receptivos","patrones de diseño accesibles","herramientas de diseño","desarrollo web"],"fr":["tailwind design system","tailwind css v4","conception de systèmes","configuration css-first","jetons de design","composants réactifs","modèles de conception accessibles","outils de conception","développement web"],"de":["tailwind design system","tailwind css v4","design-systeme","css-first-konfiguration","design-tokens","responsive-komponenten","zugängliche design-muster","design-tools","web-entwicklung"],"pt":["Tailwind Design System","Tailwind CSS v4","sistemas de design","configuração CSS-first","tokens de design","componentes","responsivo","acessibilidade"],"ru":["Система дизайна Tailwind","Tailwind CSS v4","системы дизайна","конфигурация CSS-first","дизайн-токены","компоненты","отзывчивые","доступность","ИИ Агенты"],"ar":["نظام تصميم Tailwind","Tailwind CSS v4","أنظمة التصميم","تكوين CSS-first","أساطير التصميم","مكونات","استجابة","إمكانية الوصول","أدوات ذكاء اصطناعي"]}},"owner":"CongSofwareEngineer","repo":"hodiencong-info","repoPath":"CongSofwareEngineer/hodiencong-info","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.625Z","topics":[],"category":"community","skillMd":{"name":"tailwind-design-system","description":"Build scalable design systems with Tailwind CSS v4, design tokens, component libraries, and responsive patterns. Use when creating component libraries, implementing design systems, or standardizing UI patterns.","bodyPreview":"# Tailwind Design System (v4)\n\nBuild production-ready design systems with Tailwind CSS v4, including CSS-first configuration, design tokens, component variants, responsive patterns, and accessibility.\n\n> **Note**: This skill targets Tailwind CSS v4 (2024+). For v3 projects, refer to the [upgrade guide](https://tailwindcss.com/docs/upgrade-guide).\n\n## When to Use This Skill\n\n- Creating a component library with Tailwind v4\n- Implementing design tokens and theming with CSS-first configuration\n- Bui","body":"# Tailwind Design System (v4)\n\nBuild production-ready design systems with Tailwind CSS v4, including CSS-first configuration, design tokens, component variants, responsive patterns, and accessibility.\n\n> **Note**: This skill targets Tailwind CSS v4 (2024+). For v3 projects, refer to the [upgrade guide](https://tailwindcss.com/docs/upgrade-guide).\n\n## When to Use This Skill\n\n- Creating a component library with Tailwind v4\n- Implementing design tokens and theming with CSS-first configuration\n- Building responsive and accessible components\n- Standardizing UI patterns across a codebase\n- Migrating from Tailwind v3 to v4\n- Setting up dark mode with native CSS features\n\n## Key v4 Changes\n\n| v3 Pattern                            | v4 Pattern                                                            |\n| ------------------------------------- | --------------------------------------------------------------------- |\n| `tailwind.config.ts`                  | `@theme` in CSS                                                       |\n| `@tailwind base/components/utilities` | `@import \"tailwindcss\"`                                               |\n| `darkMode: \"class\"`                   | `@custom-variant dark (&:where(.dark, .dark *))`                      |\n| `theme.extend.colors`                 | `@theme { --color-*: value }`                                         |\n| `require(\"tailwindcss-animate\")`      | CSS `@keyframes` in `@theme` + `@starting-style` for entry animations |\n\n## Quick Start\n\n```css\n/* app.css - Tailwind v4 CSS-first configuration */\n@import \"tailwindcss\";\n\n/* Define your theme with @theme */\n@theme {\n  /* Semantic color tokens using OKLCH for better color perception */\n  --color-background: oklch(100% 0 0);\n  --color-foreground: oklch(14.5% 0.025 264);\n\n  --color-primary: oklch(14.5% 0.025 264);\n  --color-primary-foreground: oklch(98% 0.01 264);\n\n  --color-secondary: oklch(96% 0.01 264);\n  --color-secondary-foreground: oklch(14.5% 0.025 264);\n\n  --color-muted: oklch(96% 0.01 264);\n  --color-muted-foreground: oklch(46% 0.02 264);\n\n  --color-accent: oklch(96% 0.01 264);\n  --color-accent-foreground: oklch(14.5% 0.025 264);\n\n  --color-destructive: oklch(53% 0.22 27);\n  --color-destructive-foreground: oklch(98% 0.01 264);\n\n  --color-border: oklch(91% 0.01 264);\n  --color-ring: oklch(14.5% 0.025 264);\n\n  --color-card: oklch(100% 0 0);\n  --color-card-foreground: oklch(14.5% 0.025 264);\n\n  /* Ring offset for focus states */\n  --color-ring-offset: oklch(100% 0 0);\n\n  /* Radius tokens */\n  --radius-sm: 0.25rem;\n  --radius-md: 0.375rem;\n  --radius-lg: 0.5rem;\n  --radius-xl: 0.75rem;\n\n  /* Animation tokens - keyframes inside @theme are output when referenced by --animate-* variables */\n  --animate-fade-in: fade-in 0.2s ease-out;\n  --animate-fade-out: fade-out 0.2s ease-in;\n  --animate-slide-in: slide-in 0.3s ease-out;\n  --animate-slide-out: slide-out 0.3s ease-in;\n\n  @keyframes fade-in {\n    from {\n      opacity: 0;\n    }\n    to {\n      opacity: 1;\n    }\n  }\n\n  @keyframes fade-out {\n    from {\n      opacity: 1;\n    }\n    to {\n      opacity: 0;\n    }\n  }\n\n  @keyframes slide-in {\n    from {\n      transform: translateY(-0.5rem);\n      opacity: 0;\n    }\n    to {\n      transform: translateY(0);\n      opacity: 1;\n    }\n  }\n\n  @keyframes slide-out {\n    from {\n      transform: translateY(0);\n      opacity: 1;\n    }\n    to {\n      transform: translateY(-0.5rem);\n      opacity: 0;\n    }\n  }\n}\n\n/* Dark mode variant - use @custom-variant for class-based dark mode */\n@custom-variant dark (&:where(.dark, .dark *));\n\n/* Dark mode theme overrides */\n.dark {\n  --color-background: oklch(14.5% 0.025 264);\n  --color-foreground: oklch(98% 0.01 264);\n\n  --color-primary: oklch(98% 0.01 264);\n  --color-primary-foreground: oklch(14.5% 0.025 264);\n\n  --color-secondary: oklch(22% 0.02 264);\n  --color-secondary-foreground: oklch(98% 0.01 264);\n\n  --color-muted: oklch(22% 0.02 264);\n  --color-muted-foreground: oklch(65% 0.02 264);\n\n  --color-accent: oklch(22% 0.02 264);\n  --color-accent-foreground: oklch(98% 0.01 264);\n\n  --color-destructive: oklch(42% 0.15 27);\n  --color-destructive-foreground: oklch(98% 0.01 264);\n\n  --color-border: oklch(22% 0.02 264);\n  --color-ring: oklch(83% 0.02 264);\n\n  --color-card: oklch(14.5% 0.025 264);\n  --color-card-foreground: oklch(98% 0.01 264);\n\n  --color-ring-offset: oklch(14.5% 0.025 264);\n}\n\n/* Base styles */\n@layer base {\n  * {\n    @apply border-border;\n  }\n\n  body {\n    @apply bg-background text-foreground antialiased;\n  }\n}\n```\n\n## Core Concepts\n\n### 1. Design Token Hierarchy\n\n```\nBrand Tokens (abstract)\n    └── Semantic Tokens (purpose)\n        └── Component Tokens (specific)\n\nExample:\n    oklch(45% 0.2 260) → --color-primary → bg-primary\n```\n\n### 2. Component Architecture\n\n```\nBase styles → Variants → Sizes → States → Overrides\n```\n\n## Patterns\n\n### Pattern 1: CVA (Class Variance Authority) Components\n\n```typescript\n// components/ui/button.tsx\nimport { Slot } from ''@radix-ui/react-slot''\nimport { cva, type VariantProps } from ''class-variance-authority''\nimport { cn } from ''@/lib/utils''\n\nconst buttonVariants = cva(\n  // Base styles - v4 uses native CSS variables\n  ''inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50'',\n  {\n    variants: {\n      variant: {\n        default: ''bg-primary text-primary-foreground hover:bg-primary/90'',\n        destructive: ''bg-destructive text-destructive-foreground hover:bg-destructive/90'',\n        outline: ''border border-border bg-background hover:bg-accent hover:text-accent-foreground'',\n        secondary: ''bg-secondary text-secondary-foreground hover:bg-secondary/80'',\n        ghost: ''hover:bg-accent hover:text-accent-foreground'',\n        link: ''text-primary underline-offset-4 hover:underline'',\n      },\n      size: {\n        default: ''h-10 px-4 py-2'',\n        sm: ''h-9 rounded-md px-3'',\n        lg: ''h-11 rounded-md px-8'',\n        icon: ''size-10'',\n      },\n    },\n    defaultVariants: {\n      variant: ''default'',\n      size: ''default'',\n    },\n  }\n)\n\nexport interface ButtonProps\n  extends React.ButtonHTMLAttributes<HTMLButtonElement>,\n    VariantProps<typeof buttonVariants> {\n  asChild?: boolean\n}\n\n// React 19: No forwardRef needed\nexport function Button({\n  className,\n  variant,\n  size,\n  asChild = false,\n  ref,\n  ...props\n}: ButtonProps & { ref?: React.Ref<HTMLButtonElement> }) {\n  const Comp = asChild ? Slot : ''button''\n  return (\n    <Comp\n      className={cn(buttonVariants({ variant, size, className }))}\n      ref={ref}\n      {...props}\n    />\n  )\n}\n\n// Usage\n<Button variant=\"destructive\" size=\"lg\">Delete</Button>\n<Button variant=\"outline\">Cancel</Button>\n<Button asChild><Link href=\"/home\">Home</Link></Button>\n```\n\n### Pattern 2: Compound Components (React 19)\n\n```typescript\n// components/ui/card.tsx\nimport { cn } from ''@/lib/utils''\n\n// React 19: ref is a regular prop, no forwardRef\nexport function Card({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div\n      ref={ref}\n      className={cn(\n        ''rounded-lg border border-border bg-card text-card-foreground shadow-sm'',\n        className\n      )}\n      {...props}\n    />\n  )\n}\n\nexport function CardHeader({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div\n      ref={ref}\n      className={cn(''flex flex-col space-y-1.5 p-6'', className)}\n      {...props}\n    />\n  )\n}\n\nexport function CardTitle({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLHeadingElement> & { ref?: React.Ref<HTMLHeadingElement> }) {\n  return (\n    <h3\n      ref={ref}\n      className={cn(''text-2xl font-semibold leading-none tracking-tight'', className)}\n      {...props}\n    />\n  )\n}\n\nexport function CardDescription({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLParagraphElement> & { ref?: React.Ref<HTMLParagraphElement> }) {\n  return (\n    <p\n      ref={ref}\n      className={cn(''text-sm text-muted-foreground'', className)}\n      {...props}\n    />\n  )\n}\n\nexport function CardContent({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div ref={ref} className={cn(''p-6 pt-0'', className)} {...props} />\n  )\n}\n\nexport function CardFooter({\n  className,\n  ref,\n  ...props\n}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> }) {\n  return (\n    <div\n      ref={ref}\n      className={cn(''flex items-center p-6 pt-0'', className)}\n      {...props}\n    />\n  )\n}\n\n// Usage\n<Card>\n  <CardHeader>\n    <CardTitle>Account</CardTitle>\n    <CardDescription>Manage your account settings</CardDescription>\n  </CardHeader>\n  <CardContent>\n    <form>...</form>\n  </CardContent>\n  <CardFooter>\n    <Button>Save</Button>\n  </CardFooter>\n</Card>\n```\n\n### Pattern 3: Form Components\n\n```typescript\n// components/ui/input.tsx\nimport { cn } from ''@/lib/utils''\n\nexport interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {\n  error?: string\n  ref?: React.Ref<HTMLInputElement>\n}\n\nexport function Input({ className, type, error, ref, ...props }: InputProps) {\n  return (\n    <div className=\"relative\">\n      <input\n        type={type}\n        className={cn(\n          ''flex h-10 w-full rounded-md border border-border bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50'',\n          error && ''border-destructive focus-visible:ring-destructive'',\n          className\n        )}\n        ref={ref}\n        aria-invalid={!!error}\n        aria-describedby={error ? `${props.id}-error` : undefined}\n        {...props}\n      />\n      {error && (\n        <p\n          id={`${props.id}-error`}\n          className=\"mt-1 text-sm text-destructive\"\n          role=\"alert\"\n        >\n          {error}\n        </p>\n      )}\n    </div>\n  )\n}\n\n// components/ui/label.tsx\nimport { cva, type VariantProps } from ''class-variance-authority''\n\nconst labelVariants = cva(\n  ''text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70''\n)\n\nexport function Label({\n  className,\n  ref,\n  ...props\n}: React.LabelHTMLAttributes<HTMLLabelElement> & { ref?: React.Ref<HTMLLabelElement> }) {\n  return (\n    <label ref={ref} className={cn(labelVariants(), className)} {...props} />\n  )\n}\n\n// Usage with React Hook Form + Zod\nimport { useForm } from ''react-hook-form''\nimport { zodResolver } from ''@hookform/resolvers/zod''\nimport { z } from ''zod''\n\nconst schema = z.object({\n  email: z.string().email(''Invalid email address''),\n  password: z.string().min(8, ''Password must be at least 8 characters''),\n})\n\nfunction LoginForm() {\n  const { register, handleSubmit, formState: { errors } } = useForm({\n    resolver: zodResolver(schema),\n  })\n\n  return (\n    <form onSubmit={handleSubmit(onSubmit)} className=\"space-y-4\">\n      <div className=\"space-y-2\">\n        <Label htmlFor=\"email\">Email</Label>\n        <Input\n          id=\"email\"\n          type=\"email\"\n          {...register(''email'')}\n          error={errors.email?.message}\n        />\n      </div>\n      <div className=\"space-y-2\">\n        <Label htmlFor=\"password\">Password</Label>\n        <Input\n          id=\"password\"\n          type=\"password\"\n          {...register(''password'')}\n          error={errors.password?.message}\n        />\n      </div>\n      <Button type=\"submit\" className=\"w-full\">Sign In</Button>\n    </form>\n  )\n}\n```\n\n### Pattern 4: Responsive Grid System\n\n```typescript\n// components/ui/grid.tsx\nimport { cn } from ''@/lib/utils''\nimport { cva, type VariantProps } from ''class-variance-authority''\n\nconst gridVariants = cva(''grid'', {\n  variants: {\n    cols: {\n      1: ''grid-cols-1'',\n      2: ''grid-cols-1 sm:grid-cols-2'',\n      3: ''grid-cols-1 sm:grid-cols-2 lg:grid-cols-3'',\n      4: ''grid-cols-1 sm:grid-cols-2 lg:grid-cols-4'',\n      5: ''grid-cols-2 sm:grid-cols-3 lg:grid-cols-5'',\n      6: ''grid-cols-2 sm:grid-cols-3 lg:grid-cols-6'',\n    },\n    gap: {\n      none: ''gap-0'',\n      sm: ''gap-2'',\n      md: ''gap-4'',\n      lg: ''gap-6'',\n      xl: ''gap-8'',\n    },\n  },\n  defaultVariants: {\n    cols: 3,\n    gap: ''md'',\n  },\n})\n\ninterface GridProps\n  extends React.HTMLAttributes<HTMLDivElement>,\n    VariantProps<typeof gridVariants> {}\n\nexport function Grid({ className, cols, gap, ...props }: GridProps) {\n  return (\n    <div className={cn(gridVariants({ cols, gap, className }))} {...props} />\n  )\n}\n\n// Container component\nconst containerVariants = cva(''mx-auto w-full px-4 sm:px-6 lg:px-8'', {\n  variants: {\n    size: {\n      sm: ''max-w-screen-sm'',\n      md: ''max-w-screen-md'',\n      lg: ''max-w-screen-lg'',\n      xl: ''max-w-screen-xl'',\n      ''2xl'': ''max-w-screen-2xl'',\n      full: ''max-w-full'',\n    },\n  },\n  defaultVariants: {\n    size: ''xl'',\n  },\n})\n\ninterface ContainerProps\n  extends React.HTMLAttributes<HTMLDivElement>,\n    VariantProps<typeof containerVariants> {}\n\nexport function Container({ className, size, ...props }: ContainerProps) {\n  return (\n    <div className={cn(containerVariants({ size, className }))} {...props} />\n  )\n}\n\n// Usage\n<Container>\n  <Grid cols={4} gap=\"lg\">\n    {products.map((product) => (\n      <ProductCard key={product.id} product={product} />\n    ))}\n  </Grid>\n</Container>\n```\n\n### Pattern 5: Native CSS Animations (v4)\n\n```css\n/* In your CSS file - native @starting-style for entry animations */\n@theme {\n  --animate-dialog-in: dialog-fade-in 0.2s ease-out;\n  --animate-dialog-out: dialog-fade-out 0.15s ease-in;\n}\n\n@keyframes dialog-fade-in {\n  from {\n    opacity: 0;\n    transform: scale(0.95) translateY(-0.5rem);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n@keyframes dialog-fade-out {\n  from {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n  to {\n    opacity: 0;\n    transform: scale(0.95) translateY(-0.5rem);\n  }\n}\n\n/* Native popover animations using @starting-style */\n[popover] {\n  transition:\n    opacity 0.2s,\n    transform 0.2s,\n    display 0.2s allow-discrete;\n  opacity: 0;\n  transform: scale(0.95);\n}\n\n[popover]:popover-open {\n  opacity: 1;\n  transform: scale(1);\n}\n\n@starting-style {\n  [popover]:popover-open {\n    opacity: 0;\n    transform: scale(0.95);\n  }\n}\n```\n\n```typescript\n// components/ui/dialog.tsx - Using native popover API\nimport * as DialogPrimitive from ''@radix-ui/react-dialog''\nimport { cn } from ''@/lib/utils''\n\nconst DialogPortal = DialogPrimitive.Portal\n\nexport function DialogOverlay({\n  className,\n  ref,\n  ...props\n}: React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay> & {\n  ref?: React.Ref<HTMLDivElement>\n}) {\n  return (\n    <DialogPrimitive.Overlay\n      ref={ref}\n      className={cn(\n        ''fixed inset-0 z-50 bg-black/80'',\n        ''data-[state=open]:animate-fade-in data-[state=closed]:animate-fade-out'',\n        className\n      )}\n      {...props}\n    />\n  )\n}\n\nexport function DialogContent({\n  className,\n  children,\n  ref,\n  ...props\n}: React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> & {\n  ref?: React.Ref<HTMLDivElement>\n}) {\n  return (\n    <DialogPortal>\n      <DialogOverlay />\n      <DialogPrimitive.Content\n        ref={ref}\n        className={cn(\n          ''fixed left-1/2 top-1/2 z-50 grid w-full max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 border border-border bg-background p-6 shadow-lg sm:rounded-lg'',\n          ''data-[state=open]:animate-dialog-in data-[state=closed]:animate-dialog-out'',\n          className\n        )}\n        {...props}\n      >\n        {children}\n      </DialogPrimitive.Content>\n    </DialogPortal>\n  )\n}\n```\n\n### Pattern 6: Dark Mode with CSS (v4)\n\n```typescript\n// providers/ThemeProvider.tsx - Simplified for v4\n''use client''\n\nimport { createContext, useContext, useEffect, useState } from ''react''\n\ntype Theme = ''dark'' | ''light'' | ''system''\n\ninterface ThemeContextType {\n  theme: Theme\n  setTheme: (theme: Theme) => void\n  resolvedTheme: ''dark'' | ''light''\n}\n\nconst ThemeContext = createContext<ThemeContextType | undefined>(undefined)\n\nexport function ThemeProvider({\n  children,\n  defaultTheme = ''system'',\n  storageKey = ''theme'',\n}: {\n  children: React.ReactNode\n  defaultTheme?: Theme\n  storageKey?: string\n}) {\n  const [theme, setTheme] = useState<Theme>(defaultTheme)\n  const [resolvedTheme, setResolvedTheme] = useState<''dark'' | ''light''>(''light'')\n\n  useEffect(() => {\n    const stored = localStorage.getItem(storageKey) as Theme | null\n    if (stored) setTheme(stored)\n  }, [storageKey])\n\n  useEffect(() => {\n    const root = document.documentElement\n    root.classList.remove(''light'', ''dark'')\n\n    const resolved = theme === ''system''\n      ? (window.matchMedia(''(prefers-color-scheme: dark)'').matches ? ''dark'' : ''light'')\n      : theme\n\n    root.classList.add(resolved)\n    setResolvedTheme(resolved)\n\n    // Update meta theme-color for mobile browsers\n    const metaThemeColor = document.querySelector(''meta[name=\"theme-color\"]'')\n    if (metaThemeColor) {\n      metaThemeColor.setAttribute(''content'', resolved === ''dark'' ? ''#09090b'' : ''#ffffff'')\n    }\n  }, [theme])\n\n  return (\n    <ThemeContext.Provider value={{\n      theme,\n      setTheme: (newTheme) => {\n        localStorage.setItem(storageKey, newTheme)\n        setTheme(newTheme)\n      },\n      resolvedTheme,\n    }}>\n      {children}\n    </ThemeContext.Provider>\n  )\n}\n\nexport const useTheme = () => {\n  const context = useContext(ThemeContext)\n  if (!context) throw new Error(''useTheme must be used within ThemeProvider'')\n  return context\n}\n\n// components/ThemeToggle.tsx\nimport { Moon, Sun } from ''lucide-react''\nimport { useTheme } from ''@/providers/ThemeProvider''\n\nexport function ThemeToggle() {\n  const { resolvedTheme, setTheme } = useTheme()\n\n  return (\n    <Button\n      variant=\"ghost\"\n      size=\"icon\"\n      onClick={() => setTheme(resolvedTheme === ''dark'' ? ''light'' : ''dark'')}\n    >\n      <Sun className=\"size-5 rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0\" />\n      <Moon className=\"absolute size-5 rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100\" />\n      <span className=\"sr-only\">Toggle theme</span>\n    </Button>\n  )\n}\n```\n\n## Utility Functions\n\n```typescript\n// lib/utils.ts\nimport { type ClassValue, clsx } from \"clsx\";\nimport { twMerge } from \"tailwind-merge\";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n\n// Focus ring utility\nexport const focusRing = cn(\n  \"focus-visible:outline-none focus-visible:ring-2\",\n  \"focus-visible:ring-ring focus-visible:ring-offset-2\",\n);\n\n// Disabled utility\nexport const disabled = \"disabled:pointer-events-none disabled:opacity-50\";\n```\n\n## Advanced v4 Patterns\n\n### Custom Utilities with `@utility`\n\nDefine reusable custom utilities:\n\n```css\n/* Custom utility for decorative lines */\n@utility line-t {\n  @apply relative before:absolute before:top-0 before:-left-[100vw] before:h-px before:w-[200vw] before:bg-gray-950/5 dark:before:bg-white/10;\n}\n\n/* Custom utility for text gradients */\n@utility text-gradient {\n  @apply bg-gradient-to-r from-primary to-accent bg-clip-text text-transparent;\n}\n```\n\n### Theme Modifiers\n\n```css\n/* Use @theme inline when referencing other CSS variables */\n@theme inline {\n  --font-sans: var(--font-inter), system-ui;\n}\n\n/* Use @theme static to always generate CSS variables (even when unused) */\n@theme static {\n  --color-brand: oklch(65% 0.15 240);\n}\n\n/* Import with theme options */\n@import \"tailwindcss\" theme(static);\n```\n\n### Namespace Overrides\n\n```css\n@theme {\n  /* Clear all default colors and define your own */\n  --color-*: initial;\n  --color-white: #fff;\n  --color-black: #000;\n  --color-primary: oklch(45% 0.2 260);\n  --color-secondary: oklch(65% 0.15 200);\n\n  /* Clear ALL defaults for a minimal setup */\n  /* --*: initial; */\n}\n```\n\n### Semi-transparent Color Variants\n\n```css\n@theme {\n  /* Use color-mix() for alpha variants */\n  --color-primary-50: color-mix(in oklab, var(--color-primary) 5%, transparent);\n  --color-primary-100: color-mix(\n    in oklab,\n    var(--color-primary) 10%,\n    transparent\n  );\n  --color-primary-200: color-mix(\n    in oklab,\n    var(--color-primary) 20%,\n    transparent\n  );\n}\n```\n\n### Container Queries\n\n```css\n@theme {\n  --container-xs: 20rem;\n  --container-sm: 24rem;\n  --container-md: 28rem;\n  --container-lg: 32rem;\n}\n```\n\n## v3 to v4 Migration Checklist\n\n- [ ] Replace `tailwind.config.ts` with CSS `@theme` block\n- [ ] Change `@tailwind base/components/utilities` to `@import \"tailwindcss\"`\n- [ ] Move color definitions to `@theme { --color-*: value }`\n- [ ] Replace `darkMode: \"class\"` with `@custom-variant dark`\n- [ ] Move `@keyframes` inside `@theme` blocks (ensures keyframes output with theme)\n- [ ] Replace `require(\"tailwindcss-animate\")` with native CSS animations\n- [ ] Update `h-10 w-10` to `size-10` (new utility)\n- [ ] Remove `forwardRef` (React 19 passes ref as prop)\n- [ ] Consider OKLCH colors for better color perception\n- [ ] Replace custom plugins with `@utility` directives\n\n## Best Practices\n\n### Do''s\n\n- **Use `@theme` blocks** - CSS-first configuration is v4''s core pattern\n- **Use OKLCH colors** - Better perceptual uniformity than HSL\n- **Compose with CVA** - Type-safe variants\n- **Use semantic tokens** - `bg-primary` not `bg-blue-500`\n- **Use `size-*`** - New shorthand for `w-* h-*`\n- **Add accessibility** - ARIA attributes, focus states\n\n### Don''ts\n\n- **Don''t use `tailwind.config.ts`** - Use CSS `@theme` instead\n- **Don''t use `@tailwind` directives** - Use `@import \"tailwindcss\"`\n- **Don''t use `forwardRef`** - React 19 passes ref as prop\n- **Don''t use arbitrary values** - Extend `@theme` instead\n- **Don''t hardcode colors** - Use semantic tokens\n- **Don''t forget dark mode** - Test both themes\n\n## Resources\n\n- [Tailwind CSS v4 Documentation](https://tailwindcss.com/docs)\n- [Tailwind v4 Beta Announcement](https://tailwindcss.com/blog/tailwindcss-v4-beta)\n- [CVA Documentation](https://cva.style/docs)\n- [shadcn/ui](https://ui.shadcn.com/)\n- [Radix Primitives](https://www.radix-ui.com/primitives)\n"},"lastSynced":"2026-03-07T02:13:11.718Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing streamlined CSS-first design system implementation with Tailwind CSS v4","zh":"非常适合需要简化CSS优先设计系统实现的前端代理，使用Tailwind CSS v4","ja":"Tailwind CSS v4を使用したCSSファーストの設計システムの実装を合理化する必要があるフロントエンドエージェントに最適","ko":"Tailwind CSS v4를 사용하여 간소화된 CSS 우선 디자인 시스템 구현이 필요한 프론트엔드 에이전트에 완벽함","es":"Perfecto para agentes Frontend que necesitan una implementación de sistema de diseño con Tailwind CSS v4 de forma optimizada","fr":"Parfait pour les agents Frontend ayant besoin d''une mise en œuvre de système de conception CSS-first optimisée avec Tailwind CSS v4","de":"Perfekt für Frontend-Agenten, die eine strukturierte Implementierung des CSS-erstes Designsystems mit Tailwind CSS v4 benötigen","pt":"Perfeito para Agentes Frontend que necessitam de implementação de design system com Tailwind CSS v4 de forma eficiente","ru":"Идеально подходит для агентов Frontend, которым необходима упрощенная реализация системы дизайна на основе CSS с Tailwind CSS v4","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى تنفيذ نظام تصميم أول مع CSS باستخدام Tailwind CSS v4"},"recommendation":{"en":"Empowers agents to build production-ready design systems with CSS-first configuration, design tokens, component variants, and accessibility features using Tailwind CSS v4, enabling seamless integration of responsive patterns and theming","zh":"使代理能够使用Tailwind CSS v4构建生产就绪的设计系统，具有CSS优先配置、设计令牌、组件变体和可访问性功能，实现响应式模式和主题的无缝集成","ja":"Tailwind CSS v4を使用して、CSSファーストの設定、デザイントークン、コンポーネントバリアント、アクセシビリティ機能を備えた本番環境対応の設計システムを構築する能力をエージェントに提供し、レスポンシブパターンとテーマ設定のシームレスな統合を実現","ko":"Tailwind CSS v4를 사용하여 CSS 우선 구성, 디자인 토큰, 컴포넌트 변형 및 접근성 기능을 갖춘 프로덕션 준비가 된 디자인 시스템을 구축할 수 있도록 에이전트에게 권한을 부여하며 반응형 패턴과 테마 설정의 원활한 통합을 가능하게 함","es":"Habilita a los agentes a crear sistemas de diseño listos para producción con configuración CSS-first, tokens de diseño, variantes de componentes y funciones de accesibilidad utilizando Tailwind CSS v4, lo que permite una integración sin problemas de patrones responsivos y temas","fr":"Permet aux agents de créer des systèmes de conception prêts pour la production avec une configuration CSS-first, des jetons de conception, des variantes de composants et des fonctionnalités d''accessibilité en utilisant Tailwind CSS v4, permettant ainsi une intégration transparente de modèles responsives et de thèmes","de":"Ermächtigt Agenten, produktionssreife Designsysteme mit CSS-erster Konfiguration, Design-Tokens, Komponenten-Varianten und Zugänglichkeitsfunktionen mit Tailwind CSS v4 zu erstellen, wodurch eine nahtlose Integration von responsiven Mustern und Themen ermöglicht wird","pt":"Habilita os agentes a construir sistemas de design prontos para produção com configuração CSS-first, tokens de design, variantes de componentes e recursos de acessibilidade usando Tailwind CSS v4, permitindo integração perfeita de padrões responsivos e temas","ru":"Позволяет агентам создавать системы дизайна, готовые к производству, с конфигурацией CSS-first, токенами дизайна, вариантами компонентов и функциями доступности, используя Tailwind CSS v4, что обеспечивает бесшовную интеграцию отзывчивых паттернов и тем","ar":"تمكن الوكلاء من بناء أنظمة التصميم الجاهزة للإنتاج مع تكوين CSS-first، رموز التصميم، إصدارات المكونات وميزات إمكانية الوصول باستخدام Tailwind CSS v4، مما يتيح دمجًا متسلسلاً للأنماط المستجيبة وتعريفات السمات"},"useCases":{"en":["Creating component libraries with customizable variants and accessibility features","Implementing design tokens and theming with CSS-first configuration for consistent branding","Building responsive and accessible UI components with Tailwind CSS v4"],"zh":["使用可自定义变体和可访问性功能创建组件库","使用CSS优先配置实现设计令牌和主题，确保品牌一致性","使用Tailwind CSS v4构建响应式和可访问的UI组件"],"ja":["カスタマイズ可能なバリアントとアクセシビリティ機能を備えたコンポーネントライブラリの作成","一貫したブランディングのためのCSSファースト設定によるデザイントークンとテーマ設定の実装","Tailwind CSS v4を使用したレスポンシブでアクセシブルなUIコンポーネントの構築"],"ko":["사용자 정의 가능한 변형 및 접근성 기능을 갖춘 컴포넌트 라이브러리 생성","일관된 브랜딩을 위한 CSS 우선 구성으로 디자인 토큰 및 테마 설정 구현","Tailwind CSS v4를 사용한 반응형 및 접근성 UI 컴포넌트 구축"],"es":["Crear bibliotecas de componentes con variantes personalizables y funciones de accesibilidad","Implementar tokens de diseño y temas con configuración CSS-first para una marca consistente","Construir componentes de UI responsivos y accesibles con Tailwind CSS v4"],"fr":["Créer des bibliothèques de composants avec des variants personnalisables et des fonctionnalités d''accessibilité","Mettre en œuvre des jetons de conception et des thèmes avec une configuration CSS-first pour une marque cohérente","Construire des composants d''interface utilisateur responsives et accessibles avec Tailwind CSS v4"],"de":["Erstellen von Komponentenbibliotheken mit anpassbaren Varianten und Zugänglichkeitsfunktionen","Implementieren von Design-Tokens und Themen mit CSS-erster Konfiguration für eine konsistente Marke","Erstellen von responsiven und zugänglichen Benutzeroberflächen-Komponenten mit Tailwind CSS v4"],"pt":["Criar bibliotecas de componentes com variantes personalizadas e recursos de acessibilidade","Implementar tokens de design e temas com configuração CSS-first para marcação consistente","Construir componentes de UI responsivos e acessíveis com Tailwind CSS v4"],"ru":["Создание библиотек компонентов с настраиваемыми вариантами и функциями доступности","Реализация токенов дизайна и тем с конфигурацией CSS-first для последовательного брендинга","Postroenie отзывчивых и доступных компонентов UI с помощью Tailwind CSS v4"],"ar":["إنشاء مكتبات المكونات مع الإصدارات المخصصة وميزات إمكانية الوصول","تنفيذ رموز التصميم وتعريفات السمات مع تكوين CSS-first للعلامة التجارية المتسقة","بناء مكونات واجهة المستخدم المستجيبة وإمكانية الوصول مع Tailwind CSS v4"]},"limitations":{"en":["Requires Tailwind CSS v4 (2024+)","Not compatible with Tailwind CSS v3 projects without upgrade"],"zh":["需要Tailwind CSS v4（2024+版本）","不兼容未升级的Tailwind CSS v3项目"],"ja":["Tailwind CSS v4（2024年以降）が必要","アップグレードなしではTailwind CSS v3プロジェクトと互換性なし"],"ko":["Tailwind CSS v4 (2024+) 필요","업그레이드 없이는 Tailwind CSS v3 프로젝트와 호환되지 않음"],"es":["Requiere Tailwind CSS v4 (2024+)","No es compatible con proyectos Tailwind CSS v3 sin actualización"],"fr":["Nécessite Tailwind CSS v4 (2024+)","N''est pas compatible avec les projets Tailwind CSS v3 sans mise à niveau"],"de":["Benötigt Tailwind CSS v4 (2024+)","Nicht kompatibel mit Tailwind CSS v3-Projekten ohne Upgrade"],"pt":["Exige Tailwind CSS v4 (2024+)","Não é compatível com projetos Tailwind CSS v3 sem atualização"],"ru":["Требует Tailwind CSS v4 (2024+)","Не совместимо с проектами Tailwind CSS v3 без обновления"],"ar":["يتطلب Tailwind CSS v4 (2024+)","غير متوافق مع مشاريع Tailwind CSS v3 بدون تحديث"]},"version":4},"contentHash":"d010d2f9bb19b6aca7c51f460fb9b32564dbebc09610ea873abb636232d2fe26","qualityScore":57}');
