INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CongSofwareEngineer/hodiencong-info/tailwind-design-system', 'tailwind-design-system', 'CongSofwareEngineer', 'hodiencong-info', 'community', 'tailwind-design-system CongSofwareEngineer hodiencong-info community The tailwind-design-system skill helps developers create production-ready design systems with Tailwind CSS v4, including component variants and accessibility features. It benefits developers building component libraries and implementing design tokens. Tailwind 设计系统是一个使用 Tailwind CSS v4 搭建生产就绪的设计系统，包括 CSS-first 配置、设计令牌和组件变体 Tailwind デザイン システムは、Tailwind CSS v4 を使用して生産性の高いデザイン システムを構築するもので、CSS-first 構成、デザイン トークン、コンポーネント バリアントを含みます Tailwind 디자인 시스템은 Tailwind CSS v4를 사용하여 생산 준비가 된 디자인 시스템을 구축하는 것으로, CSS-first 구성, 디자인 토큰, 컴포넌트 버전을 포함합니다 Tailwind Design System es una herramienta para crear sistemas de diseño personalizados con Tailwind CSS v4, incluyendo configuración CSS-first, tokens de diseño y componentes receptivos Tailwind Design System est un outil pour créer des systèmes de design personnalisés avec Tailwind CSS v4, incluant une configuration CSS-first, des jetons de design et des composants réactifs Tailwind Design System ist ein Tool zum Erstellen benutzerdefinierter Design-Systeme mit Tailwind CSS v4, einschließlich CSS-First-Konfiguration, Design-Tokens und responsiven Komponenten O Tailwind Design System é uma ferramenta para criar sistemas de design produção-prontos com Tailwind CSS v4. Система дизайна Tailwind - это инструмент для создания производственных систем дизайна с Tailwind CSS v4. نظام تصميم Tailwind هو أداة لإنشاء أنظمة تصميم جاهزة للإنتاج مع Tailwind CSS v4. how to use tailwind-design-system tailwind-design-system setup guide tailwind-design-system vs bootstrap tailwind-design-system install what is tailwind-design-system tailwind-design-system alternative tailwind css v4 tutorial design tokens in tailwind responsive design with tailwind Tailwind 设计系统 Tailwind CSS v4 CSS-first 配置 设计令牌 组件变体 响应式模式 无障碍功能 AIエージェント Builds production-ready design systems with Tailwind CSS v4 Supports CSS-first configuration for customizable designs Includes design tokens for consistent theming Offers component variants for flexible UI components Enables responsive patterns for adaptive layouts Prioritizes accessibility for inclusive design tailwind-design-system is a skill that enables building production-ready design systems with Tailwind CSS v4, including CSS-first configuration, design tokens, and accessibility.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Smana/cloud-native-ref/spec', 'community', 'Smana', 'cloud-native-ref', 'Smana/cloud-native-ref', 'spec', 89, 15, 56, '2026-02-19T17:56:40Z', '2026-03-06T06:32:45.169Z', 'f027afc083c4e4be8915da73a6f04a3ace31322ae7134ec4ad208a609fdc1102', '{"id":"Smana/cloud-native-ref/spec","name":"spec","description":{"en":"The spec skill helps developers create lightweight specifications for cloud native platform changes, benefiting from upfront design. It supports Kubernetes, security, and DevOps.","zh":"Spec Skill 是一个云原生平台参考，用于创建轻量级规范以提高开发效率。支持 Kubernetes 和安全配置","ja":"Spec Skill はクラウドネイティブプラットフォームの参考であり、開発効率を向上させるための軽量規約を作成するために使用されます。Kubernetes とセキュリティ設定をサポート","ko":"Spec Skill 은 클라우드 네이티브 플랫폼 참조로 개발 효율을 높이는軽量 규약을 생성하는 데 사용됩니다. 쿠버네티스 및 보안 구성 지원","es":"Spec es un agente de IA que permite crear especificaciones ligeras para cambios en plataformas cloud nativas. Ayuda a mejorar la seguridad y la infraestructura","fr":"Spec est un outil d''IA qui permet de créer des spécifications légères pour les modifications de plateformes cloud natives. Il aide à améliorer la sécurité et l''infrastructure","de":"Spec ist ein AI-Tool, das die Erstellung von leichten Spezifikationen für Änderungen in cloud-nativen Plattformen ermöglicht. Es hilft bei der Verbesserung der Sicherheit und Infrastruktur","pt":"O Spec é uma plataforma cloud nativa opinada que permite criar especificações leves para alterações que beneficiam de design prévio, incluindo composições, infraestrutura e segurança","ru":"Spec - это справочник по облачным платформам, который позволяет создавать легкие спецификации для изменений, которые выигрывают от предварительного проектирования, включая состав, инфраструктуру и безопасность","ar":"Spec هو منصة سحابية ذات آراء تسمح بإنشاء مواصفات خفيفة لالتغييرات التي تستفيد من التصميم المسبق، بما في ذلك التكوين والبنية التحتية والأمان"},"seo":{"title":{"en":"Spec: Cloud Native Platform Reference Setup Guide | AI Ag...","zh":"Spec Setup Guide: 云原生平台参考","ja":"Spec を使用したクラウドネイティブプラットフォームの構成","ko":"Spec 설정 가이드: 클라우드 네이티브 플랫폼 참조","es":"Guía de configuración de Spec para plataformas cloud nativas","fr":"Guide de mise en place de Spec pour les plateformes cloud...","de":"Einrichtungsleitfaden für Spec in cloud-nativen Plattformen","pt":"Guia de Configuração do Spec: Plataforma Cloud Nativa","ru":"Настройка ИИ Агента Spec: Справочник по облачным платформам","ar":"دليل إعداد Spec: منصة سحابية أصيلة"},"description":{"en":"Unlock efficient cloud native platform management with spec. Learn how to create lightweight specifications for changes and streamline your workflow today!","zh":"了解 Spec Skill 的功能和使用方法，创建轻量级规范以提高云原生平台的开发效率，支持 Kubernetes 和安全配置","ja":"Spec Skill を使用してクラウドネイティブプラットフォームの開発効率を向上させるための軽量規約を作成する方法を学びます。Kubernetes とセキュリティ設定をサポート","ko":"Spec Skill 의 기능과 사용 방법을 알아보고 클라우드 네이티브 플랫폼의 개발 효율을 높이는軽量 규약을 생성하세요. 쿠버네티스 및 보안 구성 지원","es":"Aprende a crear especificaciones ligeras para cambios en plataformas cloud con Spec. Descubre cómo utilizar este agente de IA para mejorar la seguridad y la ...","fr":"Découvrez comment créer des spécifications légères pour les modifications de plateformes cloud avec Spec. Améliorez la sécurité et l''infrastructure avec cet ...","de":"Erfahren Sie, wie Sie mit Spec leichte Spezifikationen für Änderungen in cloud-nativen Plattformen erstellen. Verbessern Sie die Sicherheit und Infrastruktur...","pt":"Aprenda a criar especificações leves para alterações que beneficiam de design prévio com o Spec, uma plataforma cloud nativa opinada","ru":"Изучите, как создавать легкие спецификации для изменений, которые выигрывают от предварительного проектирования с помощью Spec, справочника по облачным платф...","ar":"تعلم كيفية إنشاء مواصفات خفيفة لالتغييرات التي تستفيد من التصميم المسبق مع Spec، منصة سحابية ذات آراء"},"definition":{"en":"Spec is an opinionated cloud native platform reference for creating lightweight specifications, supporting types such as composition, infrastructure, security, and platform.","zh":"Spec Skill 是一种云原生平台参考，用于创建轻量级规范","ja":"Spec Skill はクラウドネイティブプラットフォームの参考であり、軽量規約を作成するために使用されます","ko":"Spec Skill 은 클라우드 네이티브 플랫폼 참조로 軽量 규약을 생성하는 데 사용됩니다","es":"Spec es un agente de IA que permite crear especificaciones ligeras para cambios en plataformas cloud nativas","fr":"Spec est un outil d''IA qui permet de créer des spécifications légères pour les modifications de plateformes cloud natives","de":"Spec ist ein AI-Tool, das die Erstellung von leichten Spezifikationen für Änderungen in cloud-nativen Plattformen ermöglicht","pt":"O Spec é uma plataforma de referência para plataformas cloud nativas que permite criar especificações leves para alterações","ru":"Spec - это справочник по облачным платформам, который позволяет создавать легкие спецификации для изменений","ar":"Spec هو منصة مرجعية لمنصات السحابة الأصلية التي تسمح بإنشاء مواصفات خفيفة لالتغييرات"},"features":{"en":["Creates specifications using `/spec` command with optional types: composition, infrastructure, security, or platform","Supports Kubernetes and DevOps workflows for efficient cloud native platform management","Enables creation of specifications for major infrastructure changes, such as VPC, EKS, and IAM","Facilitates security changes, including network policies, RBAC, and PKI","Infers specification type from description or asks for clarification when omitted"],"zh":["支持 Kubernetes","安全配置","轻量级规范创建","云原生平台参考","支持多种类型的规范创建（composition、infrastructure、security、platform）"],"ja":["Kubernetes をサポート","セキュリティ設定","軽量規約の作成","クラウドネイティブプラットフォームの参考","複数のタイプの規約を作成することをサポート（composition、infrastructure、security、platform）"],"ko":["쿠버네티스 지원","보안 구성","軽量 규약 생성","클라우드 네이티브 플랫폼 참조","다양한 유형의 규약 생성 지원（composition、infrastructure、security、platform）"],"es":["Creación de especificaciones ligeras para cambios en plataformas cloud","Soporte para tipos de especificaciones: composición, infraestructura, seguridad y plataforma","Uso de comandos CLI para crear y gestionar especificaciones","Integración con tecnologías como Kubernetes y Crossplane","Mejora de la seguridad y la infraestructura en plataformas cloud"],"fr":["Création de spécifications légères pour les modifications de plateformes cloud","Prise en charge de types de spécifications : composition, infrastructure, sécurité et plateforme","Utilisation de commandes CLI pour créer et gérer des spécifications","Intégration avec des technologies comme Kubernetes et Crossplane","Amélioration de la sécurité et de l''infrastructure dans les plateformes cloud"],"de":["Erstellung von leichten Spezifikationen für Änderungen in cloud-nativen Plattformen","Unterstützung von Spezifikationstypen: Zusammensetzung, Infrastruktur, Sicherheit und Plattform","Verwendung von CLI-Befehlen zum Erstellen und Verwalten von Spezifikationen","Integration mit Technologien wie Kubernetes und Crossplane","Verbesserung der Sicherheit und Infrastruktur in cloud-nativen Plattformen"],"pt":["Criação de especificações leves para alterações","Suporte a composições, infraestrutura e segurança","Tipos de especificações: composição, infraestrutura, segurança e plataforma","Uso de comandos CLI para criar especificações","Integração com tecnologias como Kubernetes e Crossplane"],"ru":["Создание легких спецификаций для изменений","Поддержка состава, инфраструктуры и безопасности","Типы спецификаций: состав, инфраструктура, безопасность и платформа","Использование команд CLI для создания спецификаций","Интеграция с технологиями như Kubernetes и Crossplane"],"ar":["إنشاء مواصفات خفيفة لالتغييرات","دعم التكوين والبنية التحتية والأمان","أنواع المواصفات: التكوين والبنية التحتية والأمان والمنصة","استخدام أوامر CLI لإنشاء المواصفات","التكامل مع تقنيات مثل Kubernetes و Crossplane"]},"keywords":{"en":["how to use spec for cloud native platforms","spec alternative for Kubernetes management","spec vs Terraform for infrastructure as code","spec install guide for DevOps teams","spec setup for security and compliance","what is spec in cloud native platform management","spec benefits for crossplane compositions","spec best practices for AI agents"],"zh":["Spec Skill","云原生平台","Kubernetes","安全配置","轻量级规范","云原生平台参考","AIエージェント","云计算","DevOps"],"ja":["Spec Skill","クラウドネイティブプラットフォーム","Kubernetes","セキュリティ設定","軽量規約","クラウドネイティブプラットフォームの参考","AIエージェント","クラウドコンピューティング","DevOps"],"ko":["Spec Skill","클라우드 네이티브 플랫폼","쿠버네티스","보안 구성","軽量 규약","클라우드 네이티브 플랫폼 참조","AI 에이전트","클라우드 컴퓨팅","DevOps"],"es":["Spec","plataformas cloud nativas","especificaciones ligeras","seguridad en la nube","infraestructura en la nube","Kubernetes","Crossplane","CLI","agente de IA","herramientas de desarrollo"],"fr":["Spec","plateformes cloud natives","spécifications légères","sécurité dans le cloud","infrastructure dans le cloud","Kubernetes","Crossplane","CLI","outil d''IA","outils de développement"],"de":["Spec","cloud-nativen Plattformen","leichte Spezifikationen","Sicherheit in der Cloud","Infrastruktur in der Cloud","Kubernetes","Crossplane","CLI","AI-Tool","Entwicklungstools"],"pt":["spec","plataforma cloud nativa","especificações leves","composições","infraestrutura","segurança","Kubernetes","Crossplane","CLI"],"ru":["spec","облачная платформа","легкие спецификации","состав","инфраструктура","безопасность","Kubernetes","Crossplane","CLI","ИИ Агенты"],"ar":["spec","منصة سحابية","مواصفات خفيفة","تكوين","بنية تحتية","أمان","Kubernetes","Crossplane","CLI","أدوات الذكاء الاصطناعي"]}},"owner":"Smana","repo":"cloud-native-ref","repoPath":"Smana/cloud-native-ref","stars":89,"forks":15,"updatedAt":"2026-02-19T17:56:40Z","topics":["cloud","devops","kubernetes","security"],"category":"community","skillMd":{"name":"spec","description":"Create a specification for non-trivial changes. Creates GitHub issue + spec file in a dedicated directory.","bodyPreview":"# Spec Skill\n\nCreate lightweight specifications for changes that benefit from upfront design.\n\n## Usage\n\n```\n/spec \"description\"\n/spec composition \"Add Valkey caching\"\n/spec infrastructure \"Add GPU node pool\"\n```\n\n**Types** (optional): `composition` | `infrastructure` | `security` | `platform`\n\nIf type is omitted, infer from description or ask.\n\n## When to Use\n\n- New Crossplane compositions\n- Major infrastructure changes (VPC, EKS, IAM)\n- Security changes (network policies, RBAC, PKI)\n- Multi-co","body":"# Spec Skill\n\nCreate lightweight specifications for changes that benefit from upfront design.\n\n## Usage\n\n```\n/spec \"description\"\n/spec composition \"Add Valkey caching\"\n/spec infrastructure \"Add GPU node pool\"\n```\n\n**Types** (optional): `composition` | `infrastructure` | `security` | `platform`\n\nIf type is omitted, infer from description or ask.\n\n## When to Use\n\n- New Crossplane compositions\n- Major infrastructure changes (VPC, EKS, IAM)\n- Security changes (network policies, RBAC, PKI)\n- Multi-component platform features\n\n## When NOT to Use\n\n- Version bumps, documentation-only, single-file bug fixes, minor config tweaks\n\n## Workflow\n\n### 1. Generate Identifiers\n\n```bash\n# Next spec number (3 digits)\nMAX_NUM=$(find docs/specs -name \"spec.md\" -path \"*/[0-9]*\" 2>/dev/null | \\\n  sed ''s|.*/\\([0-9]*\\)-.*|\\1|'' | sort -rn | head -1)\nSPEC_NUM=$(printf \"%03d\" $((10#${MAX_NUM:-0} + 1)))\n\n# Slug from description (3-4 meaningful words, kebab-case)\n# Filter stop words, take meaningful words, join with hyphens\n```\n\n### 2. Create GitHub Issue\n\n```bash\nISSUE_URL=$(gh issue create \\\n  --title \"[SPEC] ${TITLE}\" \\\n  --label \"spec,spec:draft\" \\\n  --body \"## Summary\n${DESCRIPTION}\n\n## Spec Directory\n\\`docs/specs/${SPEC_NUM}-${SLUG}/\\`\n\n---\n_Lightweight spec. See spec file for details._\")\n\nISSUE_NUM=$(echo \"$ISSUE_URL\" | grep -oP ''issues/\\K\\d+$'')\n```\n\n**Labels used**:\n- `spec` - All specification issues\n- `spec:draft` - Initial state (add manually: `spec:implementing` when work starts, `spec:done` when archived)\n\n### 3. Create Spec Directory and File\n\n```bash\nSPEC_DIR=\"docs/specs/${SPEC_NUM}-${SLUG}\"\nmkdir -p \"$SPEC_DIR\"\n```\n\nCopy template from `docs/specs/templates/spec.md` and fill:\n- `SPEC-XXX` → `SPEC-${SPEC_NUM}`\n- `#XXX` → `#${ISSUE_NUM}`\n- `YYYY-MM-DD` → current date\n- `[Title]` → from description\n\n### 4. Link in Issue\n\n```bash\ngh issue comment ${ISSUE_NUM} --body \"Spec created: [\\`${SPEC_DIR}/spec.md\\`](${SPEC_DIR}/spec.md)\"\n```\n\n### 5. Output\n\n```\nSpec created:\n\n  Issue: https://github.com/Smana/cloud-native-ref/issues/XXX (label: spec:draft)\n  Spec:  docs/specs/XXX-slug/spec.md\n\nNext:\n  1. Fill in the spec (use /clarify for [NEEDS CLARIFICATION] sections)\n  2. Run /spec-status to see pipeline overview\n  3. When starting work: gh issue edit XXX --remove-label \"spec:draft\" --add-label \"spec:implementing\"\n  4. Implement the changes\n  5. Reference in PR: \"Implements #XXX\"\n  6. After merge: spec is auto-archived by GitHub Action\n```\n\n## Template Location\n\n`docs/specs/templates/spec.md` (~80 lines)\n\n## Clarifications\n\nUse `/clarify` to resolve `[NEEDS CLARIFICATION: ...]` markers with structured options, or discuss conversationally with Claude.\n\n## Integration\n\n- `/spec` creates spec + issue with `spec:draft` label (this skill)\n- `/spec-status` shows pipeline overview (Draft/Implementing/Done counts)\n- `/clarify` resolves [NEEDS CLARIFICATION] markers with structured options\n- `/create-pr` auto-detects specs and references issue\n- `/commit` for commits\n- GitHub Action auto-archives specs on PR merge\n"},"lastSynced":"2026-03-06T06:32:45.169Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Native Agents requiring efficient specification creation for Kubernetes, security, and DevOps changes.","zh":"适用于需要为Kubernetes、安全和DevOps更改创建高效规范的云原生代理。","ja":"Kubernetes、セキュリティ、およびDevOpsの変更に対する効率的な仕様作成を必要とするクラウドネイティブエージェントに適しています。","ko":"Kubernetes, 보안 및 DevOps 변경에 대한 효율적인 사양 생성이 필요한 클라우드 네이티브 에이전트에 적합합니다.","es":"Ideal para Agentes Nativos en la Nube que requieren una creación de especificaciones eficiente para Kubernetes, seguridad y cambios de DevOps.","fr":"Idéal pour les agents Cloud Native nécessitant une création d''espécifications efficace pour Kubernetes, la sécurité et les modifications DevOps.","de":"Ideal für Cloud-Native-Agents, die eine effiziente Spezifikationserstellung für Kubernetes, Sicherheit und DevOps-Änderungen erfordern.","pt":"Ideal para Agentes Nativos em Nuvem que requerem criação eficiente de especificações para Kubernetes, segurança e alterações de DevOps.","ru":"Идеально подходит для облачных агентов, требующих эффективного создания спецификаций для Kubernetes, безопасности и изменений DevOps.","ar":"مثالي لعميل الحوسبة السحابية الأصلي الذي يتطلب إنشاء مواصفات فعال لكوبيرنيتس، وأمان، وتغييرات ديڤأوبس."},"recommendation":{"en":"Empowers agents to generate lightweight specifications for cloud native platform changes, supporting upfront design with types such as composition, infrastructure, security, and platform, leveraging Kubernetes and DevOps protocols.","zh":"赋予代理生成针对云原生平台更改的轻量级规范的能力，支持前期设计，包括组合、基础设施、安全和平台等类型，利用Kubernetes和DevOps协议。","ja":"クラウドネイティブプラットフォームの変更に対する軽量仕様を生成するエージェントの能力を提供し、前期設計をサポートし、コンポジション、インフラストラクチャ、セキュリティ、プラットフォームなどのタイプを含み、KubernetesおよびDevOpsプロトコルを利用します。","ko":"클라ウ드 네이티브 플랫폼 변경에 대한 경량 사양을 생성하는 에이전트의 능력을 제공하며, 사전 설계를 지원하며, 구성, 인프라, 보안 및 플랫폼과 같은 유형을 포함하며, Kubernetes 및 DevOps 프로토콜을 활용합니다.","es":"Habilita a los agentes para generar especificaciones ligeras para cambios en la plataforma de cloud nativa, que admiten el diseño previo con tipos como composición, infraestructura, seguridad y plataforma, aprovechando los protocolos de Kubernetes y DevOps.","fr":"Permet aux agents de générer des spécifications légères pour les modifications de plateforme cloud native, prenant en charge la conception préalable avec des types tels que la composition, l''infrastructure, la sécurité et la plateforme, en exploitant les protocoles Kubernetes et DevOps.","de":"Ermächtigt Agenten, leichtgewichtige Spezifikationen für Änderungen an der Cloud-Native-Plattform zu erstellen, die eine vorherige Auslegung mit Typen wie Zusammensetzung, Infrastruktur, Sicherheit und Plattform unterstützen, indem sie die Kubernetes- und DevOps-Protokolle nutzen.","pt":"Habilita os agentes a gerar especificações leves para alterações de plataforma nativa em nuvem, com suporte ao design prévio com tipos como composição, infraestrutura, segurança e plataforma, aproveitando os protocolos Kubernetes e DevOps.","ru":"Наделяет агентов возможностью генерировать легкие спецификации для изменений облачной платформы, поддерживая предварительный дизайн с типами, такими как композиция, инфраструктура, безопасность и платформа, используя протоколы Kubernetes и DevOps.","ar":"يمنح الوكلاء القدرة على توليد مواصفات خفيفة لتعديلات منصة سحابية أصلية، تدعم التصميم المسبق بالأنواع مثل التركيب والبنية التحتية والأمان والمنصة، مستفيدة من بروتوكولات كوبيرنيتس وديڤأوبس."},"useCases":{"en":["Creating specifications for new Crossplane compositions","Designing major infrastructure changes like VPC or EKS","Developing security changes including network policies or RBAC"],"zh":["为新Crossplane组合创建规范","设计主要基础设施更改，如VPC或EKS","开发包括网络策略或RBAC在内的安全更改"],"ja":["新しいCrossplaneコンポジションの仕様を作成する","VPCまたはEKSのような主要なインフラストラクチャの変更を設計する","ネットワークポリシーまたはRBACを含むセキュリティの変更を開発する"],"ko":["새로운 Crossplane 구성에 대한 사양 생성","VPC 또는 EKS와 같은 주요 인프라 변경 설계","네트워크 정책 또는 RBAC와 같은 보안 변경 개발"],"es":["Crear especificaciones para nuevas composiciones de Crossplane","Diseñar cambios importantes en la infraestructura como VPC o EKS","Desarrollar cambios de seguridad que incluyen políticas de red o RBAC"],"fr":["Créer des spécifications pour de nouvelles compositions Crossplane","Concevoir des modifications majeures de l''infrastructure telles que VPC ou EKS","Développer des modifications de sécurité incluant des politiques de réseau ou RBAC"],"de":["Erstellen von Spezifikationen für neue Crossplane-Zusammensetzungen","Entwerfen wichtiger Infrastrukturänderungen wie VPC oder EKS","Entwickeln von Sicherheitsänderungen, einschließlich Netzwerkrichtlinien oder RBAC"],"pt":["Criação de especificações para novas composições Crossplane","Projeto de alterações de infraestrutura significativas, como VPC ou EKS","Desenvolvimento de alterações de segurança, incluindo políticas de rede ou RBAC"],"ru":["Создание спецификаций для новых композиций Crossplane","Проектирование значительных изменений инфраструктуры, таких как VPC или EKS","Разработка изменений безопасности, включая сетевые политики или RBAC"],"ar":["إنشاء مواصفات لتركيبات كروس بلان الجديدة","تصميم تغييرات بنية تحتية كبيرة مثل ڤي بي سي أو إي كي إس","تطوير تغييرات أمنية تشمل سياسات الشبكة أو آر باك"]},"limitations":{"en":["Requires description or type inference for specification creation","Limited to specific use cases like new compositions, major infrastructure changes, security changes, and multi-cloud deployments"],"zh":["规范创建需要描述或类型推断","仅限于特定用例，如新组合、主要基础设施更改、安全更改和多云部署"],"ja":["仕様作成には説明またはタイプ推論が必要","新しいコンポジション、主要なインフラストラクチャの変更、セキュリティの変更、多クラウド展開などの特定のユースケースに限定される"],"ko":["사양 생성에는 설명 또는 유형 추론이 필요","새로운 구성, 주요 인프라 변경, 보안 변경 및 멀티 클라우드 배포와 같은 특정 사용 사례에만 제한"],"es":["Requiere inferencia de descripción o tipo para la creación de especificaciones","Limitado a casos de uso específicos como nuevas composiciones, cambios importantes en la infraestructura, cambios de seguridad y implementaciones de varios clouds"],"fr":["Nécessite une inférence de description ou de type pour la création de spécifications","Limité à des cas d''utilisation spécifiques tels que de nouvelles compositions, des modifications majeures de l''infrastructure, des modifications de sécurité et des déploiements multinuages"],"de":["Benötigt Beschreibungs- oder Typinferenz für die Spezifikationserstellung","Begrenzt auf bestimmte Anwendungsfälle wie neue Zusammensetzungen, wichtige Infrastrukturänderungen, Sicherheitsänderungen und Multi-Cloud-Bereitstellungen"],"pt":["Exige descrição ou inferência de tipo para criação de especificação","Limitado a casos de uso específicos, como novas composições, alterações de infraestrutura significativas, alterações de segurança e implantações multi-nuvem"],"ru":["Требует описания или вывода типа для создания спецификации","Ограничен конкретными случаями использования, такими как новые композиции, значительные изменения инфраструктуры, изменения безопасности и многооблачные развертывания"],"ar":["يتطلب وصفا أو استنتاج نوع لإنشاء مواصفة","محدود لحالات استخدام محددة مثل التركيبات الجديدة، وتغييرات البنية التحتية الكبيرة، وتغييرات الأمان، والتنصيب السحابي المتعدد"]},"version":4},"contentHash":"f027afc083c4e4be8915da73a6f04a3ace31322ae7134ec4ad208a609fdc1102","qualityScore":56}');
