INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Smana/cloud-native-ref/spec', 'spec', 'Smana', 'cloud-native-ref', 'community', 'spec Smana cloud-native-ref community cloud devops kubernetes security The spec skill helps developers create lightweight specifications for cloud native platform changes, benefiting from upfront design. It supports Kubernetes, security, and DevOps. Spec Skill 是一个云原生平台参考，用于创建轻量级规范以提高开发效率。支持 Kubernetes 和安全配置 Spec Skill はクラウドネイティブプラットフォームの参考であり、開発効率を向上させるための軽量規約を作成するために使用されます。Kubernetes とセキュリティ設定をサポート Spec Skill 은 클라우드 네이티브 플랫폼 참조로 개발 효율을 높이는軽量 규약을 생성하는 데 사용됩니다. 쿠버네티스 및 보안 구성 지원 Spec es un agente de IA que permite crear especificaciones ligeras para cambios en plataformas cloud nativas. Ayuda a mejorar la seguridad y la infraestructura Spec est un outil d''IA qui permet de créer des spécifications légères pour les modifications de plateformes cloud natives. Il aide à améliorer la sécurité et l''infrastructure Spec ist ein AI-Tool, das die Erstellung von leichten Spezifikationen für Änderungen in cloud-nativen Plattformen ermöglicht. Es hilft bei der Verbesserung der Sicherheit und Infrastruktur O Spec é uma plataforma cloud nativa opinada que permite criar especificações leves para alterações que beneficiam de design prévio, incluindo composições, infraestrutura e segurança Spec - это справочник по облачным платформам, который позволяет создавать легкие спецификации для изменений, которые выигрывают от предварительного проектирования, включая состав, инфраструктуру и безопасность Spec هو منصة سحابية ذات آراء تسمح بإنشاء مواصفات خفيفة لالتغييرات التي تستفيد من التصميم المسبق، بما في ذلك التكوين والبنية التحتية والأمان how to use spec for cloud native platforms spec alternative for Kubernetes management spec vs Terraform for infrastructure as code spec install guide for DevOps teams spec setup for security and compliance what is spec in cloud native platform management spec benefits for crossplane compositions spec best practices for AI agents Spec Skill 云原生平台 Kubernetes 安全配置 轻量级规范 云原生平台参考 AIエージェント 云计算 DevOps Creates specifications using `/spec` command with optional types: composition, infrastructure, security, or platform Supports Kubernetes and DevOps workflows for efficient cloud native platform management Enables creation of specifications for major infrastructure changes, such as VPC, EKS, and IAM Facilitates security changes, including network policies, RBAC, and PKI Infers specification type from description or asks for clarification when omitted Spec is an opinionated cloud native platform reference for creating lightweight specifications, supporting types such as composition, infrastructure, security, and platform.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('indexnetwork/index/update-pr', 'community', 'indexnetwork', 'index', 'indexnetwork/index', 'update-pr', 86, 16, 56, '2026-03-03T01:57:27Z', '2026-03-06T06:33:24.762Z', 'd8e864f745236399be3e5af1008d6c8c6ab667050dda99ebb522ba83bdf5d119', '{"id":"indexnetwork/index/update-pr","name":"update-pr","description":{"en":"The update-pr skill enables AI agents to create and update GitHub PRs efficiently, benefiting developers with automated changelog descriptions and streamlined workflows.","zh":"update-pr 技能用于创建和更新 PR，包括使用 GitHub CLI 和 changelog 风格的描述","ja":"update-pr スキルは、GitHub CLI と changelog スタイルの説明を使用して PR を作成および更新します","ko":"update-pr 스킬은 GitHub CLI와 changelog 스타일의 설명을 사용하여 PR를 생성하고 업데이트합니다","es":"update-pr es una habilidad para agentes de IA que automatiza la creación y actualización de solicitudes de extracción en GitHub","fr":"update-pr est une compétence pour les agents d''IA qui automatise la création et la mise à jour des demandes d''extraction sur GitHub","de":"update-pr ist eine Fähigkeit für KI-Agents, die die Erstellung und Aktualisierung von Pull-Requests in GitHub automatisiert","pt":"O update-pr é uma habilidade que permite criar e atualizar pull requests de forma eficiente, utilizando o GitHub CLI e changelog-style body.","ru":"Update-pr — это навык, который позволяет создавать и обновлять запросы на включение изменений эффективно, используя GitHub CLI и changelog-style body для ИИ Агентов.","ar":"update-pr هو مهارة تسمح بإنشاء وتحديث طلبات السحب بفعالية، باستخدام GitHub CLI و changelog-style body لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"update-pr: Streamlined GitHub PR Management for AI Agents...","zh":"update-pr Setup Guide: GitHub CLI 工具","ja":"update-pr を使用した PR 更新方法","ko":"update-pr 설정 가이드: GitHub CLI 사용","es":"Guía de configuración de update-pr para agentes de IA","fr":"Guide de configuration de update-pr pour les agents d''IA","de":"Einrichtungsleitfaden für update-pr in KI-Agents","pt":"Guia de Configuração do update-pr: Melhores Práticas para...","ru":"Настройка update-pr: Руководство по Лучшим Практикам для ...","ar":"دليل إعداد update-pr: أفضل الممارسات للطورين باستخدام أدو..."},"description":{"en":"Discover how update-pr simplifies GitHub PR creation and updates with changelog-style descriptions and git log integration - get started now!","zh":"学习如何使用 update-pr 技能创建和更新 PR，包括 GitHub CLI 和 changelog 风格的描述","ja":"update-pr スキルを使用して PR を作成および更新する方法について説明します","ko":"update-pr 스킬을 사용하여 PR를 생성하고 업데이트하는 방법에 대해 알아보세요","es":"Aprende a configurar update-pr para agentes de IA con GitHub CLI y mejores prácticas para PRs","fr":"Découvrez comment configurer update-pr pour les agents d''IA avec GitHub CLI et les meilleures pratiques pour les PR","de":"Erfahren Sie, wie Sie update-pr für KI-Agents mit GitHub CLI und Best Practices für PRs konfigurieren","pt":"Aprenda a configurar o update-pr para melhorar o fluxo de trabalho de desenvolvimento com o GitHub CLI e changelog-style body","ru":"Узнайте, как настроить update-pr для улучшения рабочего процесса разработки с помощью GitHub CLI и changelog-style body для ИИ Агентов","ar":"تعلم كيفية إعداد update-pr لتحسين تدفق عمل التطوير باستخدام GitHub CLI و changelog-style body لأدوات الذكاء الاصطناعي"},"definition":{"en":"update-pr is a discovery protocol skill that automates GitHub PR creation and updates using git log and changelog-style descriptions.","zh":"update-pr 是一种用于创建和更新 PR 的技能，使用 GitHub CLI 和 changelog 风格的描述","ja":"update-pr は、GitHub CLI と changelog スタイルの説明を使用して PR を作成および更新するスキルです","ko":"update-pr는 GitHub CLI와 changelog 스타일의 설명을 사용하여 PR를 생성하고 업데이트하는 스킬입니다","es":"update-pr es una habilidad de agente de IA que utiliza el protocolo de descubrimiento para crear y actualizar PRs en GitHub","fr":"update-pr est une compétence d''agent d''IA qui utilise le protocole de découverte pour créer et mettre à jour des PR sur GitHub","de":"update-pr ist eine Fähigkeit von KI-Agents, die das Discovery-Protokoll verwendet, um PRs in GitHub zu erstellen und zu aktualisieren","pt":"O update-pr é uma habilidade de agente que automatiza a criação e atualização de pull requests no GitHub.","ru":"Update-pr — это навык агента, который автоматизирует создание и обновление запросов на включение изменений в GitHub для ИИ Агентов.","ar":"update-pr هو مهارة وسيطة تؤتمة إنشاء وتحديث طلبات السحب في GitHub لأدوات الذكاء الاصطناعي."},"features":{"en":["Creates PRs into upstream/dev using GitHub CLI (gh)","Generates descriptions from commits using git log","Writes changelog-style PR bodies with grouped changes","Supports existing branch inspection via gh pr view","Automates PR updates with new features, bug fixes, and refactors"],"zh":["使用 GitHub CLI 创建 PR","从提交历史记录中生成 changelog 风格的描述","支持 New Features、Bug Fixes、Refactors、Documentation 和 Tests 的分组","使用 gh pr view 命令查看现有分支的 PR"],"ja":["GitHub CLI を使用して PR を作成","コミット履歴から changelog スタイルの説明を生成","New Features、Bug Fixes、Refactors、Documentation、Tests のグループ化をサポート","gh pr view コマンドを使用して既存のブランチの PR を表示"],"ko":["GitHub CLI를 사용하여 PR을 생성","커밋 기록에서 changelog 스타일의 설명을 생성","New Features, Bug Fixes, Refactors, Documentation, Tests의 그룹화 지원","gh pr view 명령을 사용하여 기존 분기의 PR을 표시"],"es":["Creación de PRs en GitHub utilizando GitHub CLI","Descripción de PRs basada en commits","Cuerpo de PR en estilo de registro de cambios","Soporte para agrupar cambios en categorías como nuevas características, correcciones de errores y refactorizaciones","Integración con el protocolo de descubrimiento para agentes de IA"],"fr":["Création de PR sur GitHub à l''aide de GitHub CLI","Description de PR basée sur les commits","Corps de PR au format de journal des modifications","Prise en charge du regroupement des modifications en catégories telles que nouvelles fonctionnalités, corrections de bogues et refactorisations","Intégration au protocole de découverte pour les agents d''IA"],"de":["Erstellung von PRs in GitHub mit GitHub CLI","Beschreibung von PRs basierend auf Commits","PR-Body im Format eines Change-Logs","Unterstützung für die Gruppierung von Änderungen in Kategorien wie neue Funktionen, Fehlerkorrekturen und Refactorings","Integration in das Discovery-Protokoll für KI-Agents"],"pt":["Criação de pull requests no repositório upstream/dev","Utilização do GitHub CLI para automatizar o processo","Descrição do PR em estilo changelog","Agrupamento de alterações em categorias como Novas Funcionalidades, Correções de Bugs e Refatorações","Inclusão de commits e descrições de alterações"],"ru":["Создание запросов на включение изменений в репозиторий upstream/dev","Использование GitHub CLI для автоматизации процесса для ИИ Агентов","Описание PR в стиле changelog","Группировка изменений по категориям, таким как новые функции, исправления ошибок и рефакторинг","Включение коммитов и описаний изменений"],"ar":["إنشاء طلبات السحب في مستودع upstream/dev","استخدام GitHub CLI لتأتمة العملية لأدوات الذكاء الاصطناعي","وصف طلب السحب بأسلوب changelog","تجميع التغييرات في فئات مثل ميزات جديدة وتصحيح أخطاء وإعادة هيكلة","إدراج التعديلات ووصف التغييرات"]},"keywords":{"en":["how to use update-pr","update-pr setup guide","github pr management","update-pr vs git flow","what is update-pr","update-pr install","ai agent github integration","update-pr alternative","update-pr documentation"],"zh":["update-pr","GitHub CLI","changelog","PR 创建","PR 更新","AIエージェント","GIT 工具"],"ja":["update-pr","GitHub CLI","changelog","PR 作成","PR 更新","AIエージェント","GIT ツール"],"ko":["update-pr","GitHub CLI","changelog","PR 생성","PR 업데이트","AI 에이전트","GIT 툴"],"es":["agentes de IA","update-pr","GitHub CLI","protocolo de descubrimiento","creación de PRs","actualización de PRs","mejores prácticas para PRs","registros de cambios","integración con GitHub"],"fr":["agents d''IA","update-pr","GitHub CLI","protocole de découverte","création de PR","mise à jour de PR","meilleures pratiques pour les PR","journaux des modifications","intégration avec GitHub"],"de":["KI-Agents","update-pr","GitHub CLI","Discovery-Protokoll","Erstellung von PRs","Aktualisierung von PRs","Best Practices für PRs","Change-Logs","Integration mit GitHub"],"pt":["update-pr","GitHub CLI","changelog-style body","criação de pull requests","automatização de fluxo de trabalho","desenvolvimento de software","ferramentas de desenvolvimento","agente de desenvolvimento"],"ru":["update-pr","GitHub CLI","changelog-style body","создание запросов на включение изменений","автоматизация рабочего процесса","разработка программного обеспечения","инструменты разработки","ИИ Агенты","агент разработки"],"ar":["update-pr","GitHub CLI","changelog-style body","إنشاء طلبات السحب","تأتمة تدفق العمل","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي","وكلاء التطوير"]}},"owner":"indexnetwork","repo":"index","repoPath":"indexnetwork/index","stars":86,"forks":16,"updatedAt":"2026-03-03T01:57:27Z","topics":["agent-frameworks","agentic-workflows","agents","composability","discovery","intent-driven-orchestration","intent-matching","intents","interoperability","privacy-preserving","staking","web3"],"category":"community","skillMd":{"name":"update-pr","description":"Create and update pull requests with GitHub CLI (gh) into upstream/dev, using changelog-style descriptions. Use when the user asks to create a PR, update a PR, open a pull request, or refresh PR title, body, or status (draft/ready/close/reopen).","bodyPreview":"# Creating and Updating PRs\n\n## Creating a PR\n\n1. **Target**: Open the PR into `upstream/dev` using the GitHub CLI (`gh`).\n2. **Describe from commits**: On the branch, inspect commits (e.g. `git log upstream/dev..HEAD --oneline` or `gh pr view` for an existing branch) to build the description.\n3. **Changelog-style body**: Write the PR description as a changelog, grouping changes into:\n   - **New Features**\n   - **Bug Fixes**\n   - **Refactors**\n   - **Documentation**\n   - **Tests**\n   Include onl","body":"# Creating and Updating PRs\n\n## Creating a PR\n\n1. **Target**: Open the PR into `upstream/dev` using the GitHub CLI (`gh`).\n2. **Describe from commits**: On the branch, inspect commits (e.g. `git log upstream/dev..HEAD --oneline` or `gh pr view` for an existing branch) to build the description.\n3. **Changelog-style body**: Write the PR description as a changelog, grouping changes into:\n   - **New Features**\n   - **Bug Fixes**\n   - **Refactors**\n   - **Documentation**\n   - **Tests**\n   Include only sections that apply; omit empty ones.\n\n**Commands:**\n\n```bash\n# Inspect commits on current branch vs upstream/dev\ngit log upstream/dev..HEAD --oneline\n\n# Create PR (replace <owner>/<repo> with actual upstream, e.g. from git remote)\ngh pr create --base dev --repo <owner>/<repo> --title \"feat(scope): short description\" --body \"...\"\n```\n\n**Body template:**\n\n```markdown\n## New Features\n- Bullet per feature\n\n## Bug Fixes\n- Bullet per fix\n\n## Refactors\n- Bullet per refactor\n\n## Documentation\n- Bullet per doc change\n\n## Tests\n- Bullet per test change\n```\n\n---\n\n## Updating a PR\n\n1. **Locate the PR**: Use `gh pr list` or `gh pr view` (when on the branch) to find the PR.\n2. **Update content**: Refresh title, body, or both from:\n   - Current commits on the branch (`git log upstream/dev..HEAD --oneline`), or\n   - Explicit user instructions.\n3. **Changelog-style**: Keep the description in changelog form (same sections as above).\n4. **Status** (when requested):\n   - Mark ready for review: `gh pr ready <number>`\n   - Mark as draft: `gh pr edit <number> --draft`\n   - Close: `gh pr close <number>`\n   - Reopen: `gh pr reopen <number>`\n\n**Commands:**\n\n```bash\n# Edit title and/or body\ngh pr edit <number> --title \"feat(scope): new title\" --body \"$(cat pr-body.md)\"\n\n# Status\ngh pr ready <number>\ngh pr edit <number> --draft\ngh pr close <number>\ngh pr reopen <number>\n```\n\n---\n\n## Examples\n\n**Create PR from branch:**\n\n```bash\ngh pr create --base dev --repo owner/repo --title \"feat(chat): render opportunity cards in message stream\" --body \"## New Features\n- Render opportunity cards inline in chat message stream\n\n## Bug Fixes\n- Fix scroll position when new messages load\"\n```\n\n**Update existing PR:**\n\n```bash\ngh pr edit 42 --title \"feat(chat): opportunity cards in stream\" --body \"$(cat pr-body.md)\"\ngh pr ready 42\n```\n"},"lastSynced":"2026-03-06T06:33:24.762Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub-integrated Agents requiring efficient PR management and automated changelog generation.","zh":"适用于需要高效PR管理和自动变更日志生成的GitHub集成Agent。","ja":"GitHubとの統合が必要で、効率的なPR管理と自動的な変更ログの生成が必要なエージェントに最適。","ko":"효율적인 PR 관리 및 자동 변경 로그 생성이 필요한 GitHub 통합 에이전트에 적합합니다.","es":"Ideal para agentes integrados con GitHub que requieren una gestión eficiente de solicitudes de extracción y generación automática de registros de cambios.","fr":"Idéal pour les agents intégrés à GitHub nécessitant une gestion efficace des demandes de tirage et une génération automatique de journaux de modifications.","de":"Ideal für GitHub-integrierte Agenten, die eine effiziente PR-Verwaltung und automatische Changelog-Erstellung erfordern.","pt":"Ideal para Agentes integrados ao GitHub que exigem gerenciamento de PR eficiente e geração automática de changelog.","ru":"Идеально для агентов, интегрированных с GitHub, требующих эффективного управления PR и автоматического создания журнала изменений.","ar":"مثالي للوكلاء المتكاملة مع GitHub التي تتطلب إدارة PR فعالة وتوليد سجل التغييرات التلقائي."},"recommendation":{"en":"Empowers agents to create and update GitHub PRs using the GitHub CLI, generating changelog-style descriptions and streamlining developer workflows with features like commit inspection and description building.","zh":"赋予代理创建和更新GitHub PR的能力，使用GitHub CLI生成类似变更日志的描述，并通过提交检查和描述构建等功能简化开发人员的工作流程。","ja":"エージェントがGitHub CLIを使用してGitHub PRを作成および更新する機能を提供し、変更ログスタイルの説明を生成し、コミットの検査や説明の構築などの機能で開発者のワークフローを合理化します。","ko":"에이전트가 GitHub CLI를 사용하여 GitHub PR를 생성 및 업데이트할 수 있는 기능을 제공하며, 변경 로그 스타일의 설명을 생성하고, 커밋 검사 및 설명 구축 등의 기능으로 개발자 워크플로우를 간소화합니다.","es":"Permite a los agentes crear y actualizar solicitudes de extracción de GitHub utilizando la GitHub CLI, generando descripciones de estilo de registro de cambios y optimizando los flujos de trabajo de los desarrolladores con características como inspección de confirmaciones y creación de descripciones.","fr":"Permet aux agents de créer et de mettre à jour des demandes de tirage GitHub en utilisant la GitHub CLI, en générant des descriptions de style journal des modifications et en rationalisant les flux de travail des développeurs avec des fonctionnalités comme l''inspection des validations et la construction de descriptions.","de":"Ermöglicht es den Agenten, GitHub-PRs mit der GitHub CLI zu erstellen und zu aktualisieren, generiert beschreibungen im Changelog-Stil und rationalisiert die Entwickler-Workflows mit Funktionen wie Commit-Inspektion und Beschreibungserstellung.","pt":"Habilita os agentes a criar e atualizar PRs do GitHub usando o GitHub CLI, gerando descrições no estilo changelog e otimizando os fluxos de trabalho dos desenvolvedores com recursos como inspeção de commit e construção de descrições.","ru":"Наделяет агентов возможностью создавать и обновлять PR в GitHub с помощью GitHub CLI, генерируя описания в стиле журнала изменений и оптимизируя рабочие процессы разработчиков с помощью функций, таких как осмотр коммитов и построение описаний.","ar":"تمكين الوكلاء من إنشاء وتحديث طلبات السحب على GitHub باستخدام واجهة سطر أوامر GitHub، وتوليد описات بنمط سجل التغييرات وتبسيط تدفقات العمل للمطورين باستخدام ميزات مثل فحص الإلتزام وإنشاء الوصف."},"useCases":{"en":["Automating PR creation with detailed changelog descriptions","Updating existing PRs with new commits and changelog entries","Streamlining developer workflows by generating PR descriptions from commit history"],"zh":["使用详细的变更日志描述自动创建PR","使用新提交和变更日志项更新现有的PR","通过从提交历史记录生成PR描述来简化开发人员的工作流程"],"ja":["詳細な変更ログの説明を使用してPRを自動的に作成する","新しいコミットと変更ログのエントリを使用して既存のPRを更新する","コミット履歴からPRの説明を生成して開発者のワークフローを合理化する"],"ko":["상세한 변경 로그 설명을 사용하여 PR를 자동으로 생성하는 것","새로운 커밋 및 변경 로그 항목을 사용하여 기존 PR를 업데이트하는 것","커밋 기록에서 PR 설명을 생성하여 개발자 워크플로우를 간소화하는 것"],"es":["Automatizar la creación de solicitudes de extracción con descripciones de registros de cambios detalladas","Actualizar solicitudes de extracción existentes con nuevos commits y entradas de registros de cambios","Optimizar los flujos de trabajo de los desarrolladores generando descripciones de solicitudes de extracción a partir del historial de commits"],"fr":["Automatiser la création de demandes de tirage avec des descriptions de journaux de modifications détaillées","Mettre à jour des demandes de tirage existantes avec de nouveaux commits et des entrées de journaux de modifications","Rationaliser les flux de travail des développeurs en générant des descriptions de demandes de tirage à partir de l''historique des validations"],"de":["Automatisieren der PR-Erstellung mit detaillierten Changelog-Beschreibungen","Aktualisieren bestehender PRs mit neuen Commits und Changelog-Einträgen","Optimieren der Entwickler-Workflows durch Generieren von PR-Beschreibungen aus dem Commit-Verlauf"],"pt":["Automatizar a criação de PR com descrições detalhadas do changelog","Atualizar PRs existentes com novos commits e entradas do changelog","Otimizar fluxos de trabalho dos desenvolvedores gerando descrições de PR a partir do histórico de commits"],"ru":["Автоматизация создания PR с подробными описаниями журнала изменений","Обновление существующих PR с новыми коммитами и записями журнала изменений","Оптимизация рабочих процессов разработчиков путем генерации описаний PR из истории коммитов"],"ar":["أتمتة إنشاء طلبات السحب مع описات مفصلة لسجل التغييرات","تحديث طلبات السحب الحالية مع الإلتزامات الجديدة ومدخلات سجل التغييرات","تبسيط تدفقات العمل للمطورين عن طريق توليدوصف طلبات السحب من تاريخ الإلتزام"]},"limitations":{"en":["Requires GitHub CLI installation and configuration","Limited to GitHub PRs, not compatible with other version control systems"],"zh":["需要安装和配置GitHub CLI","仅限于GitHub PR，不兼容其他版本控制系统"],"ja":["GitHub CLIのインストールと構成が必要","GitHub PRのみに対応しており、他のバージョン管理システムとは互換性がない"],"ko":["GitHub CLI 설치 및 구성이 필요합니다.","GitHub PR만 해당되며 다른 버전 관리 시스템과 호환되지 않습니다."],"es":["Requiere la instalación y configuración de GitHub CLI","Limitado a solicitudes de extracción de GitHub, no compatible con otros sistemas de control de versiones"],"fr":["Nécessite l''installation et la configuration de la GitHub CLI","Limité aux demandes de tirage GitHub, non compatible avec d''autres systèmes de contrôle de version"],"de":["Benötigt die Installation und Konfiguration von GitHub CLI","Begrenzt auf GitHub-PRs, nicht kompatibel mit anderen Versionskontrollsystemen"],"pt":["Requer instalação e configuração do GitHub CLI","Limitado a PRs do GitHub, não compatível com outros sistemas de controle de versão"],"ru":["Требует установки и настройки GitHub CLI","Ограничен до PR в GitHub, не совместим с другими системами контроля версий"],"ar":["يتطلب تثبيت وتهيئة واجهة سطر أوامر GitHub","محدود لطلبات السحب على GitHub، غير متوافق مع أنظمة تحكم الإصدار الأخرى"]},"version":4},"contentHash":"d8e864f745236399be3e5af1008d6c8c6ab667050dda99ebb522ba83bdf5d119","qualityScore":56}');
