INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('indexnetwork/index/update-pr', 'update-pr', 'indexnetwork', 'index', 'community', 'update-pr indexnetwork index community agent-frameworks agentic-workflows agents composability discovery intent-driven-orchestration intent-matching intents interoperability privacy-preserving staking web3 The update-pr skill enables AI agents to create and update GitHub PRs efficiently, benefiting developers with automated changelog descriptions and streamlined workflows. update-pr 技能用于创建和更新 PR，包括使用 GitHub CLI 和 changelog 风格的描述 update-pr スキルは、GitHub CLI と changelog スタイルの説明を使用して PR を作成および更新します update-pr 스킬은 GitHub CLI와 changelog 스타일의 설명을 사용하여 PR를 생성하고 업데이트합니다 update-pr es una habilidad para agentes de IA que automatiza la creación y actualización de solicitudes de extracción en GitHub update-pr est une compétence pour les agents d''IA qui automatise la création et la mise à jour des demandes d''extraction sur GitHub update-pr ist eine Fähigkeit für KI-Agents, die die Erstellung und Aktualisierung von Pull-Requests in GitHub automatisiert O update-pr é uma habilidade que permite criar e atualizar pull requests de forma eficiente, utilizando o GitHub CLI e changelog-style body. Update-pr — это навык, который позволяет создавать и обновлять запросы на включение изменений эффективно, используя GitHub CLI и changelog-style body для ИИ Агентов. update-pr هو مهارة تسمح بإنشاء وتحديث طلبات السحب بفعالية، باستخدام GitHub CLI و changelog-style body لأدوات الذكاء الاصطناعي. how to use update-pr update-pr setup guide github pr management update-pr vs git flow what is update-pr update-pr install ai agent github integration update-pr alternative update-pr documentation update-pr GitHub CLI changelog PR 创建 PR 更新 AIエージェント GIT 工具 Creates PRs into upstream/dev using GitHub CLI (gh) Generates descriptions from commits using git log Writes changelog-style PR bodies with grouped changes Supports existing branch inspection via gh pr view Automates PR updates with new features, bug fixes, and refactors update-pr is a discovery protocol skill that automates GitHub PR creation and updates using git log and changelog-style descriptions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mag123c/toktrack/next', 'community', 'mag123c', 'toktrack', 'mag123c/toktrack', 'next', 52, 2, 56, '2026-02-27T11:54:02Z', '2026-03-06T06:35:38.267Z', 'c154a149c8371838d33e93c3aa23ba3921b17a693a43bb102ba804e406b1d9bc', '{"id":"mag123c/toktrack/next","name":"next","description":{"en":"next is an ultra-fast token and cost tracker for LLM token usage, benefiting developers working with AI tools like Claude Code. It streamlines token tracking and cost monitoring.","zh":"Next是一个超快的令牌和成本跟踪工具，用于LLM令牌使用情况的分析","ja":"Nextは、LLMトークン使用状況の分析に使用される超高速のトークンとコスト追跡ツールです","ko":"Next는 LLM 토큰 사용 상황을 분석하는 데 사용되는 초고속 토큰 및 비용 추적 도구입니다","es":"Next es una herramienta de seguimiento ultra-rápida de tokens y costos para LLM, ideal para proyectos de desarrollo de IA como Claude Code","fr":"Next est un outil de suivi ultra-rapide de tokens et de coûts pour LLM, idéal pour les projets de développement d''IA tels que Claude Code","de":"Next ist ein ultra-schnelles Tool für die Verfolgung von Token und Kosten für LLM, ideal für IA-Entwicklungsprojekte wie Claude Code","pt":"O Next é uma ferramenta de rastreamento de tokens de LLM para desenvolvedores, permitindo a otimização do uso de recursos de IA.","ru":"Next - это ультрабыстрый отслеживание токенов LLM для ИИ Агентов, позволяющий оптимизировать использование ресурсов ИИ.","ar":"Next هي أداة تتبع توكنات LLM السريعة للوكلاء الذكاء الاصطناعي، مما يسمح بتحسين استخدام موارد الذكاء الاصطناعي."},"seo":{"title":{"en":"next: Ultra-Fast Token Tracker for AI Agents | AI Agent S...","zh":"Next AI工具快速入门指南","ja":"Next AIエージェントのセットアップガイド","ko":"Next AI 에이전트 설정 가이드","es":"Guía de configuración de Next: seguimiento ultra-rápido d...","fr":"Guide de configuration de Next : suivi ultra-rapide de to...","de":"Next-Konfigurationsleitfaden: Ultra-schnelles Token- und ...","pt":"Guia de Configuração do Next: Ferramenta de Rastreamento ...","ru":"Настройка Next: Ультрабыстрый отслеживание токенов LLM дл...","ar":"دليل إعداد Next: أداة تتبع توكنات LLM السريعة للوكلاء الذ..."},"description":{"en":"Discover how next simplifies LLM token usage tracking. Learn to set up and use next for optimized AI billing and cost monitoring.","zh":"了解Next AI工具的功能和特点，实现超快的令牌和成本跟踪","ja":"Next AIエージェントの機能と特徴を紹介します。超高速のトークンとコスト追跡を実現","ko":"Next AI 에이전트의 기능과 특징을 알아보세요. 초고속 토큰 및 비용 추적을 구현합니다","es":"Descubre cómo Next te ayuda a rastrear tokens y costos de LLM de manera ultra-rápida, optimizando tus proyectos de desarrollo de IA","fr":"Découvrez comment Next vous aide à suivre les tokens et les coûts de LLM de manière ultra-rapide, optimisant vos projets de développement d''IA","de":"Erfahren Sie, wie Next Ihnen hilft, Token und Kosten von LLM ultra-schnell zu verfolgen und Ihre IA-Entwicklungsprojekte zu optimieren","pt":"Aprenda a configurar o Next, uma ferramenta de rastreamento de tokens de LLM para desenvolvedores, e otimize o uso de recursos de IA","ru":"Узнайте, как настроить Next, ультрабыстрый отслеживание токенов LLM для ИИ Агентов, и оптимизируйте использование ресурсов ИИ","ar":"تعرف على كيفية إعداد Next، أداة تتبع توكنات LLM السريعة للوكلاء الذكاء الاصطناعي، واضبط استخدام موارد الذكاء الاصطناعي"},"definition":{"en":"next is an ultra-fast token and cost tracking tool for LLM token usage, designed to simplify AI billing and cost monitoring.","zh":"Next是一种AI工具，用于跟踪LLM令牌使用情况和成本","ja":"Nextは、LLMトークン使用状況とコストを追跡するAIエージェントの一種です","ko":"Next는 LLM 토큰 사용 상황과 비용을 추적하는 AI 에이전트의 일종입니다","es":"Next es un agente de IA que proporciona un seguimiento ultra-rápido de tokens y costos para LLM","fr":"Next est un agent d''IA qui fournit un suivi ultra-rapide de tokens et de coûts pour LLM","de":"Next ist ein IA-Agent, der ein ultra-schnelles Tracking von Token und Kosten für LLM bietet","pt":"O Next é uma ferramenta de rastreamento de tokens de LLM que ajuda desenvolvedores a otimizar o uso de recursos de IA.","ru":"Next - это инструмент отслеживания токенов LLM, помогающий разработчикам оптимизировать использование ресурсов ИИ.","ar":"Next هي أداة تتبع توكنات LLM التي تساعد المطورين على تحسين استخدام موارد الذكاء الاصطناعي."},"features":{"en":["Reads planning files with date prefix (YYYYMMDD-) for efficient tracking","Analyzes Git log using commands like ''git log --oneline -5'' for version control","Identifies current phase and counts completed/total tasks for project management","Presents token usage and cost data in a terminal-based user interface (TUI)","Supports multiple CLI tools, including Codex-CLI and Gemini-CLI, for flexible integration"],"zh":["支持CLI命令行界面","集成Git Log和Analyze功能","提供超快的令牌和成本跟踪","支持多种LLM令牌使用情况分析","使用Rust语言开发","提供TUI文本用户界面"],"ja":["CLIコマンドラインインターフェースをサポート","Git LogとAnalyze機能を統合","超高速のトークンとコスト追跡を提供","複数のLLMトークン使用状況分析をサポート","Rust言語で開発","TUIテキストユーザーインターフェースを提供"],"ko":["CLI 명령줄 인터페이스 지원","Git Log 및 Analyze 기능 통합","초고속 토큰 및 비용 추적 제공","다중 LLM 토큰 사용 상황 분석 지원","Rust 언어로 개발","TUI 텍스트 사용자 인터페이스 제공"],"es":["Seguimiento ultra-rápido de tokens y costos para LLM","Compatibilidad con herramientas de desarrollo de IA como Claude Code","Interfaz de línea de comandos (CLI) para una fácil integración","Análisis de registros de Git para una mejor comprensión del proyecto","Identificación de la fase actual y seguimiento de tareas completadas"],"fr":["Suivi ultra-rapide de tokens et de coûts pour LLM","Compatibilité avec des outils de développement d''IA tels que Claude Code","Interface de ligne de commande (CLI) pour une intégration facile","Analyse des journaux Git pour une meilleure compréhension du projet","Identification de la phase actuelle et suivi des tâches complétées"],"de":["Ultra-schnelles Tracking von Token und Kosten für LLM","Kompatibilität mit IA-Entwicklungs-Tools wie Claude Code","Kommandozeilen-Schnittstelle (CLI) für eine einfache Integration","Analyse von Git-Logs für ein besseres Verständnis des Projekts","Identifizierung der aktuellen Phase und Verfolgung abgeschlossener Aufgaben"],"pt":["Rastreamento de tokens de LLM em tempo real","Integração com Git Log e Analyze","Suporte a múltiplos CLI, incluindo Codex-CLI e Gemini-CLI","Interface de usuário baseada em TUI para facilidade de uso","Identificação de fase atual e contagem de tarefas concluídas","Suporte a linguagens de programação como Rust"],"ru":["Отслеживание токенов LLM в режиме реального времени","Интеграция с Git Log и Analyze","Поддержка нескольких CLI, включая Codex-CLI и Gemini-CLI","Интерфейс пользователя на основе TUI для простоты использования","Определение текущей фазы и подсчет выполненных задач","Поддержка языков программирования, таких как Rust"],"ar":["تتبع توكنات LLM في الوقت الفعلي","التكامل مع Git Log و Analyze","دعم عدة CLI، بما في ذلك Codex-CLI و Gemini-CLI","واجهة المستخدم dựa على TUI لسهولة الاستخدام","تحديد المرحلة الحالية وعد التasks المكتملة","دعم لغات البرمجة مثل Rust"]},"keywords":{"en":["how to use next for AI token tracking","next alternative for LLM cost monitoring","next vs OpenAI for token usage","next install guide for developers","what is next in AI billing","next setup for Claude Code integration","next ultra-fast token tracker","LLM token usage tracking with next","AI cost monitoring tools like next"],"zh":["Next AI工具","LLM令牌使用情况分析","超快令牌跟踪","AI工具设置","CLI命令行界面","Git Log分析","Rust开发","TUI文本用户界面"],"ja":["Next AIエージェント","LLMトークン使用状況分析","超高速トークン追跡","AIエージェント設定","CLIコマンドラインインターフェース","Git Log分析","Rust開発","TUIテキストユーザーインターフェース"],"ko":["Next AI 에이전트","LLM 토큰 사용 상황 분석","초고속 토큰 추적","AI 에이전트 설정","CLI 명령줄 인터페이스","Git Log 분석","Rust 개발","TUI 텍스트 사용자 인터페이스"],"es":["seguimiento de tokens LLM","costos de LLM","herramientas de desarrollo de IA","Claude Code","CLI","análisis de registros de Git","agente de IA","seguimiento de costos","optimización de proyectos de IA"],"fr":["suivi de tokens LLM","coûts de LLM","outils de développement d''IA","Claude Code","CLI","analyse des journaux Git","agent d''IA","suivi de coûts","optimisation de projets d''IA"],"de":["Token-Tracking LLM","Kosten von LLM","IA-Entwicklungs-Tools","Claude Code","CLI","Git-Log-Analyse","IA-Agent","Kosten-Tracking","Optimierung von IA-Projekten"],"pt":["rastreamento de tokens de LLM","otimização de recursos de IA","desenvolvimento de software","ferramentas de desenvolvimento","linguagem de programação Rust","CLI","TUI","Git Log","Analyze"],"ru":["отслеживание токенов LLM","оптимизация ресурсов ИИ","разработка программного обеспечения","инструменты разработки","язык программирования Rust","CLI","TUI","Git Log","Analyze"],"ar":["تتبع توكنات LLM","تحسين موارد الذكاء الاصطناعي","تطوير البرمجيات","أدوات التطوير","لغة البرمجة Rust","CLI","TUI","Git Log","Analyze"]}},"owner":"mag123c","repo":"toktrack","repoPath":"mag123c/toktrack","stars":52,"forks":2,"updatedAt":"2026-02-27T11:54:02Z","topics":["ai-billing","ai-coding","ai-cost","ai-tools","anthropic","claude-code","cli","codex-cli","cost-monitor","cost-tracking","developer-tools","gemini-cli","llm","multi-cli","openai","rust","terminal","token-tracker","token-usage","tui"],"category":"community","skillMd":{"name":"next","description":"Session start - check progress, suggest next task","bodyPreview":"# Next\n\n## Flow\n```\nRead Planning → Git Log → Analyze → Present → Suggest /clarify\n```\n\n## Execution\n\n1. **Read Planning**\n   ```bash\n   # Read ONLY the latest planning file (by date prefix YYYYMMDD-)\n   # e.g., 20260205-improvements.md > 20260128-cli-parsers.md\n   # Check checkbox status: [ ] incomplete, [x] complete\n   ```\n\n2. **Git Log**\n   ```bash\n   git log --oneline -5\n   git status --short\n   ```\n\n3. **Analyze**\n   - Identify current phase\n   - Count completed/total tasks\n   - Identify ne","body":"# Next\n\n## Flow\n```\nRead Planning → Git Log → Analyze → Present → Suggest /clarify\n```\n\n## Execution\n\n1. **Read Planning**\n   ```bash\n   # Read ONLY the latest planning file (by date prefix YYYYMMDD-)\n   # e.g., 20260205-improvements.md > 20260128-cli-parsers.md\n   # Check checkbox status: [ ] incomplete, [x] complete\n   ```\n\n2. **Git Log**\n   ```bash\n   git log --oneline -5\n   git status --short\n   ```\n\n3. **Analyze**\n   - Identify current phase\n   - Count completed/total tasks\n   - Identify next priority task\n\n4. **Present** (table format)\n   | Phase | Status | Progress |\n   |-------|--------|----------|\n   | Phase 0 | ✅ | 5/5 |\n   | Phase 1 | 🔄 | 3/4 |\n\n5. **Suggest**\n   - Summarize next task\n   - Suggest running `/clarify`\n\n## Output Format\n```markdown\n## Current Status\n- Phase: {current_phase}\n- Progress: {completed}/{total} tasks\n\n## Next Task\n**{task_id}: {task_name}**\n{brief_description}\n\n## Action\nRun `/clarify` to start: {task_summary}\n```\n\n## Rules\n- **Read only the latest dated planning file** (highest YYYYMMDD- prefix)\n- If no planning files → infer from git log + code state\n- Keep output concise (5-10 lines)\n- Always suggest /clarify connection\n"},"lastSynced":"2026-03-06T06:35:38.267Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Developer Agents needing streamlined LLM token tracking and cost monitoring, particularly those working with Claude Code.","zh":"非常适合需要简化LLM令牌跟踪和成本监控的AI开发人员代理，特别是那些使用Claude Code的代理","ja":"LLMトークンの追跡とコスト監視を簡素化する必要があるAI開発者エージェントに最適です。特に、Claude Codeを使用するエージェントに適しています","ko":"LLM 토큰 추적 및 비용 모니터링을 간소화하는 데 필요한 AI 개발자 에이전트에게 완벽합니다. 특히 Claude Code를 사용하는 에이전트에게 적합합니다","es":"Perfecto para Agentes de Desarrollo de IA que necesitan un seguimiento y monitoreo de costos de tokens LLM optimizados, especialmente aquellos que trabajan con Claude Code.","fr":"Parfait pour les agents de développement d''IA nécessitant un suivi et une surveillance des coûts de jetons LLM rationalisés, en particulier ceux qui travaillent avec Claude Code.","de":"Perfekt für AI-Entwicklungsagenten, die ein optimiertes LLM-Token-Tracking und -Kostenmonitoring benötigen, insbesondere solche, die mit Claude Code arbeiten.","pt":"Perfeito para Agentes de Desenvolvedores de IA que necessitam de rastreamento de tokens LLM e monitoramento de custos simplificados, particularmente aqueles que trabalham com Claude Code.","ru":"Идеально подходит для агентов разработчиков ИИ, которым необходим упрощенный отслеживание токенов LLM и мониторинг затрат, особенно для тех, кто работает с Claude Code.","ar":"مثالي لعميل مطور الذكاء الاصطناعي الذي يحتاج إلى تتبع رمز توكين LLM وبث شاشة مراقبة التكلفة بسهولة، ولا سيما أولئك الذين يعملون مع Claude Code."},"recommendation":{"en":"Empowers agents to efficiently track token usage and monitor costs, utilizing ultra-fast token tracking and Git log analysis, and presenting findings in a clear and actionable manner, leveraging markdown files like improvements.md and cli-parsers.md.","zh":"赋予代理高效跟踪令牌使用情况和监控成本的能力，利用超快的令牌跟踪和Git日志分析，并以清晰且可执行的方式呈现结果，利用类似improvements.md和cli-parsers.md的markdown文件","ja":"エージェントにトークンの使用状況を効率的に追跡し、コストを監視する能力を付与します。超高速のトークン追跡とGitログ分析を利用し、結果を明確かつ実行可能な方法で提示します。improvements.mdやcli-parsers.mdのようなマークダウンファイルを利用します","ko":"에이전트가 토큰 사용량을 효율적으로 추적하고 비용을 모니터링할 수 있는 능력을 부여합니다. 초고속 토큰 추적 및 Git 로그 분석을 활용하고 결과를 명확하고 실행 가능한 방식으로 제시합니다. improvements.md 및 cli-parsers.md와 같은 마크다운 파일을 사용합니다","es":"Habilita a los agentes a realizar un seguimiento eficiente del uso de tokens y a monitorear los costos, utilizando un seguimiento de tokens ultra-rápido y análisis de registros de Git, y presentando los hallazgos de manera clara y accionable, aprovechando archivos markdown como improvements.md y cli-parsers.md.","fr":"Permet aux agents de suivre efficacement l''utilisation des jetons et de surveiller les coûts, en utilisant un suivi de jetons ultra-rapide et une analyse des journaux Git, et en présentant les résultats de manière claire et exploitable, en utilisant des fichiers markdown comme improvements.md et cli-parsers.md.","de":"Ermöglicht es den Agenten, den Tokenverbrauch effizient zu verfolgen und die Kosten zu überwachen, indem es ein ultra-schnelles Token-Tracking und eine Git-Log-Analyse nutzt und die Ergebnisse in einer klaren und umsetzbaren Weise präsentiert, indem es Markdown-Dateien wie improvements.md und cli-parsers.md nutzt.","pt":"Habilita os agentes a rastrear o uso de tokens de forma eficiente e monitorar os custos, utilizando o rastreamento de tokens ultra-rápido e análise de logs do Git, e apresentando as descobertas de forma clara e prática, aproveitando arquivos markdown como improvements.md e cli-parsers.md.","ru":"Наделяет агентов возможностью эффективно отслеживать использование токенов и мониторить затраты, используя сверхбыстрое отслеживание токенов и анализ журналов Git, и представляя результаты в ясной и действенной форме, используя файлы markdown, такие как improvements.md и cli-parsers.md.","ar":"يمنح الوكيل القدرة على تتبع استخدام رمز التوكن بفعالية ومراقبة التكاليف، باستخدام تتبع رمز التوكن السريع للغاية وتحليل سجلات Git، وعرض النتائج بطريقة واضحة وواقعية، واستخدام ملفات markdown مثل improvements.md وcli-parsers.md."},"useCases":{"en":["Automating token usage tracking for LLM-based projects","Analyzing Git logs to identify project progress and completion rates","Streamlining cost monitoring for AI tool deployments like Claude Code"],"zh":["自动化LLM 기반 프로젝트의 토큰 사용량 추적","Git 로그를 분석하여 프로젝트 진행 상황과 완료率를 식별하는 것","Claude Code와 같은 AI 도구 배포를 위한 비용 모니터링을 간소화하는 것"],"ja":["LLMベースのプロジェクトのトークン使用状況の追跡を自動化すること","Gitログを分析してプロジェクトの進捗状況と完了率を特定すること","Claude CodeのようなAIツールの展開のためのコスト監視を簡素化すること"],"ko":["LLM 기반 프로젝트의 토큰 사용량 추적을 자동화하는 것","Git 로그를 분석하여 프로젝트의 진행 상황과 완료율을 식별하는 것","Claude Code와 같은 AI 도구 배포를 위한 비용 모니터링을 간소화하는 것"],"es":["Automatizar el seguimiento del uso de tokens para proyectos basados en LLM","Analizar registros de Git para identificar el progreso y las tasas de finalización del proyecto","Optimizar la supervisión de costos para implementaciones de herramientas de IA como Claude Code"],"fr":["Automatiser le suivi de l''utilisation des jetons pour les projets basés sur LLM","Analyser les journaux Git pour identifier les progrès et les taux d''achèvement du projet","Rationaliser la surveillance des coûts pour les déploiements d''outils d''IA comme Claude Code"],"de":["Automatisieren der Verfolgung des Tokenverbrauchs für LLM-basierte Projekte","Analysieren von Git-Logs, um den Projektfortschritt und die Fertigstellungsrate zu ermitteln","Optimieren der Kostenüberwachung für AI-Tool-Implementierungen wie Claude Code"],"pt":["Automatizar o rastreamento do uso de tokens para projetos baseados em LLM","Analizar logs do Git para identificar o progresso e as taxas de conclusão do projeto","Simplificar a monitoração de custos para implantações de ferramentas de IA como o Claude Code"],"ru":["Автоматизировать отслеживание использования токенов для проектов на основе LLM","Анализировать журналы Git для определения прогресса и скорости завершения проекта","Упрощать мониторинг затрат для развертывания инструментов ИИ, таких как Claude Code"],"ar":["تأتمة تتبع استخدام رمز التوكن لمشاريع تعتمد على LLM","تحليل سجلات Git لتحديد التقدم ومعدلات الانتهاء من المشروع","تبسيط مراقبة التكاليف لتنفيذ أدوات الذكاء الاصطناعي مثل Claude Code"]},"limitations":{"en":["Requires access to Git repository logs","Limited to markdown files with specific date prefix format (YYYYMMDD-)","Dependent on checkbox status for task completion tracking"],"zh":["需要访问Git仓库日志","仅限具有特定日期前缀格式（YYYYMMDD-）的markdown文件","依赖于复选框状态以跟踪任务完成情况"],"ja":["Gitリポジトリログへのアクセスが必要","特定の日付プレフィックス形式（YYYYMMDD-）を持つマークダウンファイルのみ","タスク完了の追跡にはチェックボックスの状態に依存する"],"ko":["Git 저장소 로그에 액세스할 수 있어야 함","특정 날짜 접두사 형식(YYYYMMDD-)(을)를 가진 마크다운 파일만 해당","작업 완료를 추적하기 위해 체크박스 상태에 의존"],"es":["Requiere acceso a los registros del repositorio Git","Limitado a archivos markdown con formato de prefijo de fecha específico (YYYYMMDD-)","Dependiente del estado del checkbox para el seguimiento de la finalización de tareas"],"fr":["Nécessite un accès aux journaux du référentiel Git","Limité aux fichiers markdown avec un format de préfixe de date spécifique (YYYYMMDD-)","Dépendant de l''état de la case à cocher pour le suivi de l''achèvement des tâches"],"de":["Benötigt Zugriff auf die Git-Repository-Logs","Begrenzt auf Markdown-Dateien mit spezifischem Datumspräfix-Format (YYYYMMDD-)","Abhängig vom Status des Kontrollkästchens für die Aufgabenabschlussverfolgung"],"pt":["Exige acesso aos logs do repositório Git","Limitado a arquivos markdown com formato de prefixo de data específico (YYYYMMDD-)","Dependente do status da caixa de seleção para rastreamento de conclusão de tarefas"],"ru":["Требует доступа к журналам репозитория Git","Ограничен файлами markdown с определенным форматом префикса даты (YYYYMMDD-)","Зависит от статуса флажка для отслеживания завершения задач"],"ar":["يتطلب الوصول إلى سجلات مستودع Git","محدود bằng ملفات markdown مع تنسيق بادئة التاريخ المحدد (YYYYMMDD-)","يعتمد على حالة خانة الاختيار لتتبع إكمال المهام"]},"version":4},"contentHash":"c154a149c8371838d33e93c3aa23ba3921b17a693a43bb102ba804e406b1d9bc","qualityScore":56}');
