INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mag123c/toktrack/next', 'next', 'mag123c', 'toktrack', 'community', 'next mag123c toktrack community ai-billing ai-coding ai-cost ai-tools anthropic claude-code cli codex-cli cost-monitor cost-tracking developer-tools gemini-cli llm multi-cli openai rust terminal token-tracker token-usage tui next is an ultra-fast token and cost tracker for LLM token usage, benefiting developers working with AI tools like Claude Code. It streamlines token tracking and cost monitoring. Next是一个超快的令牌和成本跟踪工具，用于LLM令牌使用情况的分析 Nextは、LLMトークン使用状況の分析に使用される超高速のトークンとコスト追跡ツールです Next는 LLM 토큰 사용 상황을 분석하는 데 사용되는 초고속 토큰 및 비용 추적 도구입니다 Next es una herramienta de seguimiento ultra-rápida de tokens y costos para LLM, ideal para proyectos de desarrollo de IA como Claude Code Next est un outil de suivi ultra-rapide de tokens et de coûts pour LLM, idéal pour les projets de développement d''IA tels que Claude Code Next ist ein ultra-schnelles Tool für die Verfolgung von Token und Kosten für LLM, ideal für IA-Entwicklungsprojekte wie Claude Code O Next é uma ferramenta de rastreamento de tokens de LLM para desenvolvedores, permitindo a otimização do uso de recursos de IA. Next - это ультрабыстрый отслеживание токенов LLM для ИИ Агентов, позволяющий оптимизировать использование ресурсов ИИ. Next هي أداة تتبع توكنات LLM السريعة للوكلاء الذكاء الاصطناعي، مما يسمح بتحسين استخدام موارد الذكاء الاصطناعي. how to use next for AI token tracking next alternative for LLM cost monitoring next vs OpenAI for token usage next install guide for developers what is next in AI billing next setup for Claude Code integration next ultra-fast token tracker LLM token usage tracking with next AI cost monitoring tools like next Next AI工具 LLM令牌使用情况分析 超快令牌跟踪 AI工具设置 CLI命令行界面 Git Log分析 Rust开发 TUI文本用户界面 Reads planning files with date prefix (YYYYMMDD-) for efficient tracking Analyzes Git log using commands like ''git log --oneline -5'' for version control Identifies current phase and counts completed/total tasks for project management Presents token usage and cost data in a terminal-based user interface (TUI) Supports multiple CLI tools, including Codex-CLI and Gemini-CLI, for flexible integration next is an ultra-fast token and cost tracking tool for LLM token usage, designed to simplify AI billing and cost monitoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('straubt1/tfx/reflection', 'community', 'straubt1', 'tfx', 'straubt1/tfx', 'reflection', 91, 16, 56, '2026-03-07T15:50:29Z', '2026-03-08T01:58:21.981Z', '460e93261d33204e5827ff4e41d642baff5d5a6dfc8e1c2871971f15ef899d83', '{"id":"straubt1/tfx/reflection","name":"reflection","description":{"en":"Reflection is a skill that helps identify lessons from code review sessions, capturing them in CLAUDE.md for future reference. It benefits developers by reviewing conversation history and code diffs.","zh":"反思技能用于优化TFx和Terraform Enterprise，通过回顾整个对话历史和代码差异来提高开发效率","ja":"リフレクションスキルはTFxとTerraform Enterpriseを最適化するために使用され、全会話履歴とコード差分をレビューすることで開発効率を向上させる","ko":"반성 스킬은 TFx와 Terraform Enterprise를 최적화하기 위해 사용되며, 전체 대화 기록과 코드 차이를 검토하여 개발 효율을 향상시킵니다","es":"Reflection es una habilidad que ayuda a identificar lecciones de sesiones anteriores para mejorar proyectos con TFx y Terraform.","fr":"Reflection est une compétence qui aide à identifier les leçons des sessions précédentes pour améliorer les projets avec TFx et Terraform.","de":"Reflection ist eine Fähigkeit, die dabei hilft, Lektionen aus früheren Sitzungen zu identifizieren, um Projekte mit TFx und Terraform zu verbessern.","pt":"A reflexão é um processo para identificar lições aprendidas durante uma sessão, utilizando o TFx como ferramenta de linha de comando.","ru":"Отражение - это процесс выявления уроков, полученных во время сессии, с использованием TFx как командной строки.","ar":"الانعكاس هو عملية لتحديد الدروس المستفادة خلال جلسة، باستخدام TFx كأداة سطر أوامر."},"seo":{"title":{"en":"Reflection: Code Review and Lesson Capture Guide | AI Age...","zh":"反思技能设置指南 - 优化TFx和Terraform企业版","ja":"リフレクションスキルセットアップガイド - TFxとTerraform Enterpriseの最適化","ko":"반성 스킬 설정 가이드 - TFx와 Terraform Enterprise 최적화","es":"Guía de configuración de Reflection para identificar lecc...","fr":"Guide de configuration de Reflection pour identifier les ...","de":"Reflection-Setup-Leitfaden zur Identifizierung von Lektionen","pt":"Guia de Configuração de Reflexão com Ferramentas de AI","ru":"ИИ Агенты: Настройка Инструмента Отражения","ar":"دليل إعداد أداة الانعكاس باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage reflection for efficient code review and knowledge retention. Learn to identify key lessons and improve future sessions with this AI...","zh":"了解反思技能如何帮助您优化TFx和Terraform Enterprise，提高开发效率","ja":"リフレクションスキルを使用してTFxとTerraform Enterpriseを最適化し、開発効率を向上させる","ko":"반성 스킬을 사용하여 TFx와 Terraform Enterprise를 최적화하고 개발 효율을 향상시키는 방법","es":"Aprende a utilizar Reflection para identificar lecciones y mejorar tus proyectos con TFx y Terraform","fr":"Découvrez comment utiliser Reflection pour identifier les leçons et améliorer vos projets avec TFx et Terraform","de":"Erfahren Sie, wie Sie Reflection verwenden, um Lektionen zu identifizieren und Ihre Projekte mit TFx und Terraform zu verbessern","pt":"Aprenda a configurar a reflexão com o TFx, uma ferramenta de linha de comando para HCP Terraform e Terraform Enterprise.","ru":"Настройте инструмент отражения с помощью TFx, независимой командной строки для HCP Terraform и Terraform Enterprise.","ar":"تعلم كيفية إعداد أداة الانعكاس باستخدام TFx، وهو أداة سطر أوامر لغرض HCP Terraform وTerraform Enterprise."},"definition":{"en":"Reflection is a process of reviewing entire conversation history and code diffs to capture key lessons and decisions in CLAUDE.md.","zh":"反思技能是一种用于优化TFx和Terraform Enterprise的技术，通过回顾和分析对话历史和代码差异","ja":"リフレクションスキルはTFxとTerraform Enterpriseを最適化するための技術であり、会話履歴とコード差分をレビューおよび分析する","ko":"반성 스킬은 TFx와 Terraform Enterprise를 최적화하기 위한 기술로, 대화 기록과 코드 차이를 검토하고 분석합니다","es":"Reflection es una habilidad que identifica lecciones de sesiones anteriores para mejorar la toma de decisiones","fr":"Reflection est une compétence qui identifie les leçons des sessions précédentes pour améliorer la prise de décision","de":"Reflection ist eine Fähigkeit, die Lektionen aus früheren Sitzungen identifiziert, um die Entscheidungsfindung zu verbessern","pt":"Reflexão é o processo de revisar a história de conversa para capturar lições aprendidas.","ru":"Отражение - это процесс пересмотра истории разговора для фиксации уроков.","ar":"الانعكاس هو عملية مراجعة تاريخ المحادثة لتحديد الدروس المستفادة."},"features":{"en":["Reviews entire conversation history for lesson capture","Utilizes code diffs as supplementary context","Integrates with Git to review current branch and changes","Runs commands like `git branch --show-current` and `git diff --stat HEAD`","Captures lessons in CLAUDE.md for future reference","Supports efficient code review and knowledge retention"],"zh":["支持TFx和Terraform Enterprise","回顾整个对话历史","代码差异分析","Git分支和提交状态查看","优化开发效率"],"ja":["TFxとTerraform Enterpriseをサポート","全会話履歴のレビュー","コード差分の分析","Gitブランチとコミット状態の確認","開発効率の最適化"],"ko":["TFx와 Terraform Enterprise 지원","전체 대화 기록 검토","코드 차이 분석","Git 브랜치와 커밋 상태 확인","개발 효율 최적화"],"es":["Revisa el historial de conversación completo","Utiliza diffs de código como contexto suplementario","Identifica lecciones de sesiones anteriores con TFx y Terraform","Mejora la toma de decisiones con información de sesiones anteriores","Integra con CLI de TFx para mejorar la productividad"],"fr":["Examinez l''historique de conversation complet","Utilisez des diffs de code comme contexte supplémentaire","Identifiez les leçons des sessions précédentes avec TFx et Terraform","Améliorez la prise de décision avec des informations de sessions précédentes","Intégrez avec la CLI de TFx pour améliorer la productivité"],"de":["Überprüfen Sie die vollständige Konversationshistorie","Verwenden Sie Code-Diffs als zusätzlichen Kontext","Identifizieren Sie Lektionen aus früheren Sitzungen mit TFx und Terraform","Verbessern Sie die Entscheidungsfindung mit Informationen aus früheren Sitzungen","Integrieren Sie mit der TFx-CLI, um die Produktivität zu verbessern"],"pt":["Revisão da história de conversa","Utilização do TFx como ferramenta de linha de comando","Integração com HCP Terraform e Terraform Enterprise","Análise de diffs de código","Gerenciamento de branch e commits"],"ru":["Пересмотр истории разговора","Использование TFx как командной строки","Интеграция с HCP Terraform и Terraform Enterprise","Анализ diffs кода","Управление ветками и коммитами"],"ar":["مراجعة تاريخ المحادثة","استخدام TFx كأداة سطر أوامر","التكامل مع HCP Terraform وTerraform Enterprise","تحليل فروق الكود","إدارة الفروع والالتزامات"]},"keywords":{"en":["how to use reflection in code review","what is reflection in software development","reflection alternative to manual note-taking","reflection vs code review tools","reflection install guide for AI agents","reflection setup for efficient knowledge retention","reflection for developers","reflection and Git integration","reflection for code lesson capture"],"zh":["反思技能","TFx","Terraform Enterprise","开发效率","代码优化","Git分支","AIエージェント","CLI工具"],"ja":["リフレクションスキル","TFx","Terraform Enterprise","開発効率","コード最適化","Gitブランチ","AIエージェント","CLIツール"],"ko":["반성 스킬","TFx","Terraform Enterprise","개발 효율","코드 최적화","Git 브랜치","AI 에이전트","CLI 도구"],"es":["Reflection en TFx","Identificar lecciones con Terraform","Mejorar la toma de decisiones con AI","Herramientas de desarrollo de software","TFx y Terraform","CLI de TFx","Herramientas de productividad para desarrolladores"],"fr":["Reflection dans TFx","Identifier les leçons avec Terraform","Améliorer la prise de décision avec l''IA","Outils de développement de logiciels","TFx et Terraform","CLI de TFx","Outils de productivité pour les développeurs"],"de":["Reflection in TFx","Lektionen mit Terraform identifizieren","Entscheidungsfindung mit KI verbessern","Software-Entwicklungstools","TFx und Terraform","TFx-CLI","Produktivitätstools für Entwickler"],"pt":["reflexão em desenvolvimento","ferramentas de AI para desenvolvedores","TFx","HCP Terraform","Terraform Enterprise","gerenciamento de código","análise de diffs"],"ru":["ИИ Агенты для разработчиков","отражение в разработке","TFx","HCP Terraform","Terraform Enterprise","управление кодом","анализ diffs"],"ar":["أدوات الذكاء الاصطناعي لل مطورين","الانعكاس في التطوير","TFx","HCP Terraform","Terraform Enterprise","إدارة الكود","تحليل فروق"]}},"owner":"straubt1","repo":"tfx","repoPath":"straubt1/tfx","stars":91,"forks":16,"updatedAt":"2026-03-07T15:50:29Z","topics":[],"category":"community","skillMd":{"name":"reflection","description":"This skill should be used when the user says reflection, reflect on the changes, reflect on this session, or asks to capture lessons learned from the current conversation.","bodyPreview":"# Reflection\n\nThe goal is to identify lessons from this session that should be permanently captured in CLAUDE.md — so future sessions benefit without repeating the same mistakes, clarifications, or decisions.\n\nReview the **entire conversation history** — every message, correction, and preference — as the primary source. Code diffs are supplementary.\n\n## Current Git State (supplementary context)\n\n- Branch: !`git branch --show-current`\n- Changes since last commit: !`git diff --stat HEAD`\n- Staged","body":"# Reflection\n\nThe goal is to identify lessons from this session that should be permanently captured in CLAUDE.md — so future sessions benefit without repeating the same mistakes, clarifications, or decisions.\n\nReview the **entire conversation history** — every message, correction, and preference — as the primary source. Code diffs are supplementary.\n\n## Current Git State (supplementary context)\n\n- Branch: !`git branch --show-current`\n- Changes since last commit: !`git diff --stat HEAD`\n- Staged changes: !`git diff --stat --cached`\n\n## Process\n\n1. **Read the full conversation from top to bottom.** Pay attention to:\n   - Questions the user had to answer that should have been obvious from CLAUDE.md\n   - Corrections the user made to your approach or output\n   - Preferences or constraints the user stated (even casually)\n   - Things you got wrong on the first attempt and had to revise\n   - Decisions made about architecture, naming, tooling, or workflow\n   - Anything the user explicitly said to always/never do\n\n2. **Review the diffs** (supplementary) — Read modified files for context on what was built and why, but do not let this overshadow lessons from the conversation itself.\n\n3. **Identify lessons** in these categories:\n   - **Patterns & conventions** — Things that worked well and should be encoded as rules\n   - **Gotchas & pitfalls** — Things that caused confusion, required retries, or were non-obvious\n   - **Architecture decisions** — Choices made that future sessions should know about\n   - **Workflow & communication preferences** — How the user prefers to work, communicate, or receive output\n   - **Outdated/wrong memory** — Anything in CLAUDE.md or MEMORY.md that turned out to be incorrect or missing\n\n4. **Read the current CLAUDE.md** to avoid duplicating what''s already there and to find gaps.\n\n5. **Propose edits to CLAUDE.md** — For each lesson worth keeping, suggest the specific text to add, change, or remove, and where it belongs.\n\n6. **If no lessons are found**, explicitly state: \"No CLAUDE.md updates needed from this session.\" This confirms the session was considered.\n\n7. **Do not apply edits automatically.** Present proposals to the user and wait for approval.\n\n8. **After applying approved edits**, print a brief summary in chat of what changed.\n\n## Output Format\n\n**When lessons are found:**\n```\n## Reflection\n\n### [Category]\n**Lesson**: <what was learned>\n**Proposed CLAUDE.md change**: <exact text, with target section>\n\n---\n(one block per lesson)\n```\n\n**When no lessons are found:**\n```\n## Reflection\n\nNo CLAUDE.md updates needed from this session. The following were considered but already covered or not worth persisting:\n- <item> — already in CLAUDE.md / too session-specific / etc.\n```\n\n**After applying approved changes:**\n```\n## CLAUDE.md updated\n\n- Added: \"<description>\" under ## Section\n- Modified: \"<what changed>\" in ## Section\n- Removed: \"<what was removed>\"\n```\n"},"lastSynced":"2026-03-08T01:58:21.981Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents seeking to enhance knowledge retention through systematic reflection and documentation in CLAUDE.md","zh":"适合于代码审查代理寻求通过系统反思和在CLAUDE.md中的文档记录来增强知识保留的代理","ja":"コードレビューエージェントが体系的な反省とCLAUDE.mdでの文書化を通じて知識の保持を高めようとするエージェントに適する","ko":"코드 리뷰 에이전트가 체계적인 반성과 CLAUDE.md의 문서화를 통해 지식 보유를 향상시키고자 하는 에이전트에게 적합","es":"Ideal para Agentes de Revisión de Código que buscan mejorar la retención del conocimiento a través de la reflexión y documentación sistemáticas en CLAUDE.md","fr":"Idéal pour les Agents de Révision de Code cherchant à améliorer la rétention des connaissances grâce à la réflexion et à la documentation systématiques dans CLAUDE.md","de":"Ideal für Code-Review-Agenten, die das Wissen durch systematische Reflexion und Dokumentation in CLAUDE.md verbessern möchten","pt":"Ideal para Agentes de Revisão de Código que buscam aprimorar a retenção de conhecimento por meio de reflexão e documentação sistemáticas no CLAUDE.md","ru":"Идеально для Агентов Обзора Кодов, стремящихся повысить сохранение знаний посредством систематического размышления и документации в CLAUDE.md","ar":"مثالي لعميل مراجعة الكود الذين يسعون إلى تعزيز استبقاء المعرفة من خلال الانعكاس والتوثيق المنهجي في CLAUDE.md"},"recommendation":{"en":"Empowers agents to systematically review conversation histories and code diffs, capturing key lessons in CLAUDE.md for future reference, thereby enhancing collaborative development and reducing repetitive mistakes through Git state analysis and documentation","zh":"赋予代理系统地审查会话历史和代码差异的能力，并在CLAUDE.md中捕获关键经验以供日后参考，从而通过Git状态分析和文档记录提高协作开发并减少重复错误","ja":"エージェントが会話履歴とコードの差分を体系的にレビューし、CLAUDE.mdに重要な教訓をキャプチャして将来の参考とすることで、Git状態分析と文書化を通じて共同開発を強化し、繰り返しのミスを減らすことができる","ko":"에이전트가 대화 기록과 코드 차이를 체계적으로 검토하고 CLAUDE.md에 주요 교훈을 캡처하여 향후 참조할 수 있도록 하여, Git 상태 분석과 문서화를 통해 협력 개발을 강화하고 반복되는 오류를 줄일 수 있다","es":"Permite a los agentes revisar sistemáticamente los historiales de conversación y las diferencias de código, capturando las lecciones clave en CLAUDE.md para referencia futura, mejorando así el desarrollo colaborativo y reduciendo los errores repetitivos a través del análisis de estado de Git y la documentación","fr":"Permet aux agents de passer en revue systématiquement les historiques de conversation et les différences de code, capturant les leçons clés dans CLAUDE.md pour référence future, améliorant ainsi le développement collaboratif et réduisant les erreurs répétitives grâce à l''analyse d''état Git et à la documentation","de":"Ermächtigt die Agenten, die Konversationshistorien und Code-Änderungen systematisch zu überprüfen, die wichtigsten Lektionen in CLAUDE.md für zukünftige Bezugnahme zu erfassen, wodurch die Zusammenarbeit bei der Entwicklung verbessert und wiederkehrende Fehler durch die Git-Zustandsanalyse und Dokumentation reduziert werden","pt":"Habilita os agentes a revisar sistematicamente os históricos de conversa e as diferenças de código, capturando lições importantes no CLAUDE.md para referência futura, melhorando assim o desenvolvimento colaborativo e reduzindo erros repetitivos por meio da análise do estado do Git e da documentação","ru":"Наделяет агентов возможностью систематически просматривать истории разговоров и различия кода, фиксируя ключевые уроки в CLAUDE.md для последующего обращения, тем самым повышая совместное развитие и снижая повторяющиеся ошибки посредством анализа состояния Git и документации","ar":"يمكن للوكلاء من خلاله مراجعة تاريخ المحادثات وفرق الكود بشكل منهجي، وتسجيل الدروس المهمة في CLAUDE.md للاستشارة في المستقبل، وبالتالي تعزيز التطوير التعاوني وتقليل الأخطاء المتكررة من خلال تحليل حالة الجيت والتوثيق"},"useCases":{"en":["Reviewing conversation histories for lesson identification","Capturing code review insights in CLAUDE.md","Analyzing Git state for supplementary context"],"zh":["审查会话历史以识别经验","在CLAUDE.md中捕获代码审查见解","分析Git状态以获取补充上下文"],"ja":["レッスン識別のための会話履歴のレビュー","CLAUDE.mdへのコードレビューの洞察のキャプチャ","補足的なコンテキストを得るためのGit状態の分析"],"ko":["교훈 식별을 위한 대화 기록 검토","CLAUDE.md에 코드 리뷰 통찰력을 캡처","보충적인 컨텍스트를 얻기 위한 Git 상태 분석"],"es":["Revisar los historiales de conversación para la identificación de lecciones","Capturar perspectivas de revisión de código en CLAUDE.md","Analizar el estado de Git para contexto suplementario"],"fr":["Réviser les historiques de conversation pour l''identification des leçons","Capturer les perspectives d''examen de code dans CLAUDE.md","Analyser l''état Git pour un contexte supplémentaire"],"de":["Überprüfen der Konversationshistorien zur Identifizierung von Lektionen","Erfassung von Code-Review-Einblicken in CLAUDE.md","Analyse des Git-Zustands für ergänzenden Kontext"],"pt":["Revisar históricos de conversa para identificação de lições","Capturar insights de revisão de código no CLAUDE.md","Analizar estado do Git para contexto suplementar"],"ru":["Просмотр истории разговоров для выявления уроков","Фиксация прозрений кодового обзора в CLAUDE.md","Анализ состояния Git для дополнительного контекста"],"ar":["استعراض تاريخ المحادثات لتحديد الدروس","تسجيل رؤى مراجعة الكود في CLAUDE.md","تحليل حالة الجيت لسياق إضافي"]},"limitations":{"en":["Requires access to conversation history and code diffs","CLAUDE.md integration necessary","Git state analysis capabilities needed"],"zh":["需要访问会话历史和代码差异","需要CLAUDE.md集成","需要Git状态分析能力"],"ja":["会話履歴とコードの差分へのアクセスが必要","CLAUDE.mdの統合が必要","Git状態分析機能が必要"],"ko":["대화 기록과 코드 차이 접근이 필요","CLAUDE.md 통합이 필요","Git 상태 분석 기능이 필요"],"es":["Requiere acceso al historial de conversación y a las diferencias de código","Se requiere integración con CLAUDE.md","Se necesitan capacidades de análisis de estado de Git"],"fr":["Nécessite un accès à l''historique de conversation et aux différences de code","Intégration à CLAUDE.md nécessaire","Capacités d''analyse d''état Git nécessaires"],"de":["Erfordert Zugriff auf Konversationshistorie und Code-Änderungen","CLAUDE.md-Integration erforderlich","Git-Zustandsanalysefunktionen erforderlich"],"pt":["Requer acesso ao histórico de conversa e às diferenças de código","Integração do CLAUDE.md necessária","Capacidades de análise do estado do Git necessárias"],"ru":["Требуется доступ к истории разговоров и различиям кода","Необходима интеграция с CLAUDE.md","Необходимы возможности анализа состояния Git"],"ar":["يتطلب الوصول إلى تاريخ المحادثات وفرق الكود","الاندماج مع CLAUDE.md ضروري","ميزات تحليل حالة الجيت ضرورية"]},"version":4},"contentHash":"460e93261d33204e5827ff4e41d642baff5d5a6dfc8e1c2871971f15ef899d83","qualityScore":56}');
