INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('straubt1/tfx/reflection', 'reflection', 'straubt1', 'tfx', 'community', 'reflection straubt1 tfx community Reflection is a skill that helps identify lessons from code review sessions, capturing them in CLAUDE.md for future reference. It benefits developers by reviewing conversation history and code diffs. 反思技能用于优化TFx和Terraform Enterprise，通过回顾整个对话历史和代码差异来提高开发效率 リフレクションスキルはTFxとTerraform Enterpriseを最適化するために使用され、全会話履歴とコード差分をレビューすることで開発効率を向上させる 반성 스킬은 TFx와 Terraform Enterprise를 최적화하기 위해 사용되며, 전체 대화 기록과 코드 차이를 검토하여 개발 효율을 향상시킵니다 Reflection es una habilidad que ayuda a identificar lecciones de sesiones anteriores para mejorar proyectos con TFx y Terraform. Reflection est une compétence qui aide à identifier les leçons des sessions précédentes pour améliorer les projets avec TFx et Terraform. Reflection ist eine Fähigkeit, die dabei hilft, Lektionen aus früheren Sitzungen zu identifizieren, um Projekte mit TFx und Terraform zu verbessern. A reflexão é um processo para identificar lições aprendidas durante uma sessão, utilizando o TFx como ferramenta de linha de comando. Отражение - это процесс выявления уроков, полученных во время сессии, с использованием TFx как командной строки. الانعكاس هو عملية لتحديد الدروس المستفادة خلال جلسة، باستخدام TFx كأداة سطر أوامر. how to use reflection in code review what is reflection in software development reflection alternative to manual note-taking reflection vs code review tools reflection install guide for AI agents reflection setup for efficient knowledge retention reflection for developers reflection and Git integration reflection for code lesson capture 反思技能 TFx Terraform Enterprise 开发效率 代码优化 Git分支 AIエージェント CLI工具 Reviews entire conversation history for lesson capture Utilizes code diffs as supplementary context Integrates with Git to review current branch and changes Runs commands like `git branch --show-current` and `git diff --stat HEAD` Captures lessons in CLAUDE.md for future reference Supports efficient code review and knowledge retention Reflection is a process of reviewing entire conversation history and code diffs to capture key lessons and decisions in CLAUDE.md.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('abhaymundhara/ChatDock/github', 'community', 'abhaymundhara', 'ChatDock', 'abhaymundhara/ChatDock', 'github', 0, 0, 56, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:44.913Z', 'cb243daf7e5a38eb15e25cdde2b4ab36bbfe9f51a774a394fee34cbd38aadd91', '{"id":"abhaymundhara/ChatDock/github","name":"github","description":{"en":"The GitHub skill allows developers to interact with GitHub repositories using the GitHub API, enabling access to tools like repository search and more. It benefits developers working with GitHub repositories.","zh":"GitHub Skill允许您使用GitHub API进行仓库搜索和管理，支持搜索、排序和限制等功能","ja":"GitHubスキルは、GitHub APIを使用したリポジトリ検索と管理を可能にします。検索、ソート、制限など","ko":"GitHub Skill은 GitHub API를 사용하여 저장소를 검색하고 관리할 수 있습니다. 검색, 정렬, 제한 등","es":"La habilidad de GitHub permite interactuar con repositorios utilizando la API de GitHub, con una tasa de solicitud de 60 solicitudes por hora para repositorios públicos","fr":"La compétence GitHub permet d''interagir avec les référentiels en utilisant l''API GitHub, avec un taux de requête de 60 requêtes par heure pour les référentiels publics","de":"Die GitHub-Fähigkeit ermöglicht den Zugriff auf Repositorys über die GitHub-API, mit einer Anfragrate von 60 Anfragen pro Stunde für öffentliche Repositorys","pt":"O GitHub Skill é uma ferramenta que permite interagir com repositórios GitHub usando a API GitHub. Com ele, você pode realizar buscas e acessar repositórios públicos sem necessidade de autenticação.","ru":"GitHub Skill — это инструмент, который позволяет взаимодействовать с репозиториями GitHub с помощью API GitHub. С его помощью вы можете выполнять поиск и доступ к публичным репозиториям без необходимости аутентификации.","ar":"مهارة 吉希ب هي أداة تمكنك من التفاعل مع مستودعات 吉希ب باستخدام واجهة برمجة تطبيقات 吉希ب. يمكنك استخدامها للبحث و الوصول إلى المستودعات العامة دون الحاجة إلى المصادقة."},"seo":{"title":{"en":"GitHub Skill: API-Powered Repository Management for AI Ag...","zh":"GitHub Skill Setup Guide: 使用GitHub API进行仓库搜索","ja":"GitHubスキル設定ガイド: GitHub APIを使用したリポジトリ検索","ko":"GitHub Skill 설정 가이드: GitHub API를 사용한 저장소 검색","es":"Guía de configuración de GitHub: Acceso a repositorios co...","fr":"Guide de configuration GitHub: Interactif avec les référe...","de":"GitHub-Setup-Leitfaden: Lokaler Zugriff auf Repositorys","pt":"Guia de Configuração do GitHub Skill para Desenvolvedores","ru":"Настройка GitHub Skill: Руководство для разработчиков","ar":"دليل إعداد المهارة 吉希ب لل مطورين"},"description":{"en":"Unlock the full potential of GitHub with this AI agent skill, featuring 60 requests/hour for public repositories and 5000 requests/hour with token authentica...","zh":"了解如何使用GitHub Skill进行仓库搜索和管理，包括搜索仓库、排序和限制等功能","ja":"GitHubスキルを使用してリポジトリを検索し、管理する方法を学びます。リポジトリの検索、ソート、制限など","ko":"GitHub Skill을 사용하여 저장소를 검색하고 관리하는 방법을 알아보세요. 저장소 검색, 정렬, 제한 등","es":"Aprende a utilizar la habilidad de GitHub para interactuar con repositorios utilizando la API de GitHub, sin autenticación necesaria para repositorios públicos","fr":"Découvrez comment utiliser la compétence GitHub pour interagir avec les référentiels en utilisant l''API GitHub, sans authentification requise pour les référe...","de":"Erfahren Sie, wie Sie die GitHub-Fähigkeit verwenden, um auf Repositorys zuzugreifen, indem Sie die GitHub-API nutzen, ohne Authentifizierung für öffentliche...","pt":"Aprenda a utilizar o GitHub Skill para interagir com repositórios GitHub usando a API GitHub. Descubra como configurar e usar essa ferramenta para melhorar s...","ru":"Узнайте, как использовать GitHub Skill для взаимодействия с репозиториями GitHub с помощью API GitHub. Ознакомьтесь с настройкой и использованием этого инстр...","ar":"تعرف على كيفية استخدام مهارة 吉希ب للتفاعل مع مستودعات 吉希ب باستخدام واجهة برمجة تطبيقات 吉希ب. اكتشف كيفية ضبط و استخدام هذه الأداة لتحسين إنتاجيتك."},"definition":{"en":"GitHub is a minimal, always-on-top AI assistant for desktop that provides local AI access to GitHub repositories and tools.","zh":"GitHub Skill是一种使用GitHub API进行仓库搜索和管理的AI工具","ja":"GitHubスキルは、GitHub APIを使用したリポジトリ検索と管理を行うAIエージェントです","ko":"GitHub Skill은 GitHub API를 사용하여 저장소를 검색하고 관리하는 AI 도구입니다","es":"La habilidad de GitHub es una herramienta de acceso a repositorios que utiliza la API de GitHub para interactuar con ellos","fr":"La compétence GitHub est un outil d''accès aux référentiels qui utilise l''API GitHub pour interagir avec eux","de":"Die GitHub-Fähigkeit ist ein Tool zum Zugriff auf Repositorys, das die GitHub-API nutzt, um mit ihnen zu interagieren","pt":"O que é GitHub Skill? É uma ferramenta que fornece acesso a repositórios GitHub via API.","ru":"Что такое GitHub Skill? Это инструмент, который обеспечивает доступ к репозиториям GitHub через API.","ar":"ما هي مهارة 吉希ب؟ هي أداة توفر الوصول إلى مستودعات 吉希ب عبر واجهة برمجة التطبيقات."},"features":{"en":["Searches repositories using the GitHub API with optional sorting and limiting","Supports up to 60 requests/hour for public repositories without authentication","Allows up to 5000 requests/hour with token authentication for higher limits","Provides access to GitHub tools like repository search with query parameters","Enables sorting by stars, forks, or updated timestamps for search results"],"zh":["使用GitHub API进行仓库搜索","支持搜索、排序和限制等功能","无需身份验证即可访问公共仓库","可添加令牌以提高请求限制"],"ja":["GitHub APIを使用したリポジトリ検索","検索、ソート、制限などの機能をサポート","公開リポジトリへのアクセスには認証が不要","トークンを追加して要求制限を高めることが可能"],"ko":["GitHub API를 사용하여 저장소를 검색","검색, 정렬, 제한 등의 기능을 지원","공개 저장소에 접근하기 위해 인증이 필요하지 않음","토큰을 추가하여 요청 제한을 높일 수 있음"],"es":["Acceso a repositorios públicos sin autenticación","Tasa de solicitud de 60 solicitudes por hora","Possibilidad de agregar un token para aumentar el límite de solicitudes","Búsqueda de repositorios utilizando la función `github_search_repos`","Acceso a herramientas de GitHub como la búsqueda de repositorios"],"fr":["Accès aux référentiels publics sans authentification","Taux de requête de 60 requêtes par heure","Possibilité d''ajouter un jeton pour augmenter la limite de requêtes","Recherche de référentiels en utilisant la fonction `github_search_repos`","Accès aux outils GitHub tels que la recherche de référentiels"],"de":["Zugriff auf öffentliche Repositorys ohne Authentifizierung","Anfragrate von 60 Anfragen pro Stunde","Möglichkeit, ein Token hinzuzufügen, um das Anfragelimit zu erhöhen","Suche nach Repositorys mithilfe der Funktion `github_search_repos`","Zugriff auf GitHub-Tools wie die Repository-Suche"],"pt":["Busca de repositórios públicos sem autenticação","Acesso a repositórios com até 60 requisições por hora","Possibilidade de adicionar token para aumentar o limite de requisições","Ferramentas de busca avançada, como filtrar por linguagem e estrelas","Integração com a API GitHub para acessar repositórios"],"ru":["Поиск публичных репозиториев без аутентификации","Доступ к репозиториям с до 60 запросов в час","Возможность добавить токен для увеличения лимита запросов","Инструменты расширенного поиска, такие как фильтрация по языку и звездам","Интеграция с API GitHub для доступа к репозиториям"],"ar":["بحث المستودعات العامة بدون مصادقة","الوصول إلى المستودعات مع حتى 60 طلبًا في الساعة","إمكانية إضافة رمز للزيادة الحد من الطلبات","أدوات البحث المتقدم، مثل التصفية حسب اللغة والنجوم","التكامل مع واجهة برمجة تطبيقات 吉希ب للوصول إلى المستودعات"]},"keywords":{"en":["how to use github api","github repository management","github alternative for ai agents","github setup guide for developers","what is github api","github vs gitlab for ai integration","github install for ai agents","github api for repository search","github token authentication for ai"],"zh":["GitHub Skill","GitHub API","仓库搜索","AI工具","AIエージェント","仓库管理","搜索仓库","排序和限制"],"ja":["GitHubスキル","GitHub API","リポジトリ検索","AIエージェント","リポジトリ管理","検索リポジトリ","ソートと制限"],"ko":["GitHub Skill","GitHub API","저장소 검색","AI 도구","AI 에이전트","저장소 관리","검색 저장소","정렬 및 제한"],"es":["herramienta de acceso a repositorios","API de GitHub","acceso a repositorios públicos","autenticación de GitHub","búsqueda de repositorios","github_search_repos","desarrollo de software","herramientas de desarrollo"],"fr":["outil d''accès aux référentiels","API GitHub","accès aux référentiels publics","authentification GitHub","recherche de référentiels","github_search_repos","développement de logiciels","outils de développement"],"de":["Tool zum Zugriff auf Repositorys","GitHub-API","Zugriff auf öffentliche Repositorys","GitHub-Authentifizierung","Repository-Suche","github_search_repos","Software-Entwicklung","Entwicklertools"],"pt":["github skill","api github","repositórios github","busca de repositórios","autenticação github","desenvolvedores github","ferramentas de desenvolvimento github"],"ru":["github skill","api github","репозитории github","поиск репозиториев","аутентификация github","разработчики github","инструменты разработки github"],"ar":["مهارة 吉希ب","واجهة برمجة تطبيقات 吉希ب","مستودعات 吉希ب","بحث المستودعات","مصادقة 吉希ب","مطورو 吉希ب","أدوات تطوير 吉希ب"]}},"owner":"abhaymundhara","repo":"ChatDock","repoPath":"abhaymundhara/ChatDock","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"github","description":"Interact with GitHub repositories using the GitHub API","tags":["github","git","repository","code"],"bodyPreview":"# GitHub Skill\n\nInteract with GitHub repositories using the GitHub API. No authentication required for public repositories (60 requests/hour), but you can add a token in config for higher limits (5000 requests/hour).\n\n## Available Tools\n\nYou have access to the following GitHub tools:\n\n### Search Repositories\n```javascript\ngithub_search_repos({\n  query: \"language:javascript stars:>1000\",\n  sort: \"stars\",  // optional: \"stars\", \"forks\", \"updated\"\n  limit: 10       // optional: max 30\n})\n```\n\n### G","body":"# GitHub Skill\n\nInteract with GitHub repositories using the GitHub API. No authentication required for public repositories (60 requests/hour), but you can add a token in config for higher limits (5000 requests/hour).\n\n## Available Tools\n\nYou have access to the following GitHub tools:\n\n### Search Repositories\n```javascript\ngithub_search_repos({\n  query: \"language:javascript stars:>1000\",\n  sort: \"stars\",  // optional: \"stars\", \"forks\", \"updated\"\n  limit: 10       // optional: max 30\n})\n```\n\n### Get Repository Information\n```javascript\ngithub_get_repo({\n  owner: \"HKUDS\",\n  repo: \"nanobot\"\n})\n```\n\n### List Issues\n```javascript\ngithub_list_issues({\n  owner: \"HKUDS\",\n  repo: \"nanobot\",\n  state: \"open\",  // optional: \"open\", \"closed\", \"all\"\n  limit: 10       // optional: max 30\n})\n```\n\n### Get File Contents\n```javascript\ngithub_get_file({\n  owner: \"HKUDS\",\n  repo: \"nanobot\",\n  path: \"README.md\",\n  branch: \"main\"  // optional\n})\n```\n\n## Examples\n\n**Find popular JavaScript projects:**\n```javascript\ngithub_search_repos({\n  query: \"language:javascript stars:>5000\",\n  sort: \"stars\",\n  limit: 5\n})\n```\n\n**Check repository details:**\n```javascript\ngithub_get_repo({\n  owner: \"facebook\",\n  repo: \"react\"\n})\n```\n\n**Read a specific file:**\n```javascript\ngithub_get_file({\n  owner: \"HKUDS\",\n  repo: \"nanobot\",\n  path: \"nanobot/agent/loop.py\"\n})\n```\n\n## Configuration\n\nTo increase rate limits, add a GitHub token to `~/.chatdock/settings.json`:\n\n```json\n{\n  \"github\": {\n    \"token\": \"ghp_your_token_here\"\n  }\n}\n```\n\nGet a token at: https://github.com/settings/tokens\n"},"lastSynced":"2026-03-08T01:59:44.913Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing seamless GitHub repository integration and API access.","zh":"非常适合需要无缝集成 GitHub 仓库和 API 访问的 Developer Agents。","ja":"GitHub リポジトリのシームレスな統合と API アクセスが必要な Developer Agents に最適です。","ko":"GitHub 저장소와 API 액세스를 無縫に 통합해야 하는 Developer Agents 에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una integración sin problemas con el repositorio de GitHub y acceso a la API.","fr":"Parfait pour les agents de développement nécessitant une intégration transparente avec les référentiels GitHub et un accès à l''API.","de":"Perfekt für Entwickleragenten, die eine nahtlose Integration mit dem GitHub-Repository und API-Zugriff benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de integração de repositório do GitHub sem interrupções e acesso à API.","ru":"Идеально подходит для агентов-разработчиков, которым необходима бесшовная интеграция с репозиторием GitHub и доступ к API.","ar":"مثالي لوسائل وكيل المطورين الذين يحتاجون إلى دمج مستودع GitHub دون انقطاع ووصول إلى API."},"recommendation":{"en":"Empowers agents to interact with GitHub repositories using the GitHub API, enabling advanced repository search and access to tools like sorting and limiting results, all while supporting authentication via tokens for increased request limits, leveraging protocols like HTTP for seamless communication.","zh":"使能代理与 GitHub 仓库交互，使用 GitHub API，实现高级仓库搜索和访问工具，如排序和限制结果，同时支持通过令牌进行身份验证以增加请求限制，利用如 HTTP 的协议实现无缝通信。","ja":"GitHub API を使用して GitHub リポジトリとエージェントのやり取りを可能にし、ソートや結果の制限などの高度なリポジトリ検索やツールへのアクセスを可能にし、同時にトークンによる認証をサポートして要求制限を増やし、HTTP などのプロトコルを利用してシームレスな通信を実現します。","ko":"GitHub API를 사용하여 GitHub 저장소와 에이전트의 상호 작용을 가능하게 하여 고급 저장소 검색 및 도구에 대한 액세스를 가능하게 하며, 결과를 정렬하고 제한하는 등의 작업을 수행할 수 있으며,同時に 토큰을 통한 인증을 지원하여 요청 제한을 늘리고, HTTP 등의 프로토콜을 활용하여 무縫 통신을 구현합니다.","es":"Habilita a los agentes a interactuar con los repositorios de GitHub utilizando la API de GitHub, lo que permite una búsqueda de repositorios avanzada y acceso a herramientas como la ordenación y el límite de resultados, todo mientras admite la autenticación mediante tokens para límites de solicitudes más altos, aprovechando protocolos como HTTP para una comunicación sin problemas.","fr":"Permet aux agents d''interagir avec les référentiels GitHub en utilisant l''API GitHub, ce qui permet une recherche de référentiels avancée et un accès à des outils tels que le tri et la limitation des résultats, le tout en prenant en charge l''authentification par jetons pour des limites de requêtes plus élevées, en exploitant des protocoles comme HTTP pour une communication transparente.","de":"Ermächtigt Agenten, mit GitHub-Repositorys über die GitHub-API zu interagieren, wodurch eine erweiterte Repository-Suche und der Zugriff auf Tools wie Sortierung und Ergebnisbegrenzung ermöglicht werden, und zwar bei gleichzeitiger Unterstützung der Authentifizierung über Token für erhöhte Anfragegrenzwerte, unter Ausnutzung von Protokollen wie HTTP für eine nahtlose Kommunikation.","pt":"Habilita os agentes a interagir com repositórios do GitHub usando a API do GitHub, permitindo uma pesquisa de repositório avançada e acesso a ferramentas como classificação e limitação de resultados, tudo isso enquanto suporta autenticação via tokens para limites de solicitação aumentados, aproveitando protocolos como o HTTP para comunicação sem interrupções.","ru":"Наделяет агентов возможностью взаимодействовать с репозиториями GitHub с помощью API GitHub, обеспечивая расширенный поиск репозиториев и доступ к инструментам, таким как сортировка и ограничение результатов, все это при поддержке аутентификации по токенам для увеличения лимитов запросов, используя протоколы, такие как HTTP, для бесперебойной связи.","ar":"يتمكن الوكيل من التفاعل مع مستودعات GitHub باستخدام واجهة برمجة تطبيقات GitHub، وتمكين البحث المتقدم عن المستودعات وصولاً إلى أدوات مثل فرز نتائج البحث và تحديد النتائج، كل هذا مع دعم التحقق من خلال الرموز المميزة لزيادة حدود الطلبات، واستخدام بروتوكولات مثل بروتوكول HTTP للاتصال السلس."},"useCases":{"en":["Searching repositories by language and star count","Sorting and limiting repository search results","Authenticating with GitHub tokens for higher API request limits"],"zh":["通过语言和星级搜索仓库","对仓库搜索结果进行排序和限制","使用 GitHub 令牌进行身份验证以获得更高的 API 请求限制"],"ja":["言語やスター数でリポジトリを検索する","リポジトリの検索結果をソートして制限する","GitHub トークンを使用して認証してより高い API 要求制限を取得する"],"ko":["언어 및 별점으로 저장소를 검색하는 것","저장소 검색 결과를 정렬하고 제한하는 것","GitHub 토큰을 사용하여 인증하여 더 높은 API 요청 제한을 얻는 것"],"es":["Búsqueda de repositorios por idioma y número de estrellas","Ordenación y limitación de los resultados de la búsqueda de repositorios","Autenticación con tokens de GitHub para límites de solicitudes de API más altos"],"fr":["Recherche de référentiels par langue et nombre d''étoiles","Tri et limitation des résultats de recherche de référentiels","Authentification avec des jetons GitHub pour des limites de requêtes API plus élevées"],"de":["Suche nach Repositorien nach Sprache und Sternenzahl","Sortierung und Begrenzung der Repository-Suchergebnisse","Authentifizierung mit GitHub-Tokens für höhere API-Anfragelimits"],"pt":["Pesquisa de repositórios por linguagem e contagem de estrelas","Classificação e limitação de resultados de pesquisa de repositórios","Autenticação com tokens do GitHub para limites de solicitação de API mais altos"],"ru":["Поиск репозиториев по языку и количеству звезд","Сортировка и ограничение результатов поиска репозиториев","Аутентификация с помощью токенов GitHub для более высоких лимитов запросов API"],"ar":["بحث المستودعات حسب اللغة وعدد النجوم","فرز نتائج البحث عن المستودعات وتحديد النتائج","التحقق من الهوية باستخدام رموز وصول GitHub لزيادة حدود الطلبات على واجهة برمجة التطبيقات"]},"limitations":{"en":["Public repositories limited to 60 requests/hour without authentication","Requires GitHub token for higher limits of 5000 requests/hour"],"zh":["无身份验证时公共仓库每小时请求限制为 60 个","需要 GitHub 令牌才能达到每小时 5000 个请求的更高限制"],"ja":["認証なしの場合、パブリックリポジトリのリクエスト制限は 1 時間あたり 60 件","より高い 1 時間あたり 5000 件のリクエスト制限に到達するには GitHub トークンが必要"],"ko":["인증 없이 공개 저장소의 요청 제한은 1시간당 60개","1시간당 5000개의 요청 제한을 얻으려면 GitHub 토큰가 필요"],"es":["Los repositorios públicos están limitados a 60 solicitudes/hora sin autenticación","Requiere un token de GitHub para límites más altos de 5000 solicitudes/hora"],"fr":["Les référentiels publics sont limités à 60 requêtes/heure sans authentification","Nécessite un jeton GitHub pour des limites plus élevées de 5000 requêtes/heure"],"de":["Öffentliche Repositorys sind ohne Authentifizierung auf 60 Anfragen/Stunde beschränkt","Benötigt ein GitHub-Token für höhere Limits von 5000 Anfragen/Stunde"],"pt":["Repositórios públicos limitados a 60 solicitações/hora sem autenticação","Exige token do GitHub para limites mais altos de 5000 solicitações/hora"],"ru":["Публичные репозитории ограничены 60 запросами в час без аутентификации","Требуется токен GitHub для более высоких лимитов в 5000 запросов в час"],"ar":["مستودعات عامة محدودة ب60 طلبًا في الساعة بدون التحقق من الهوية","يتطلب رمز وصول إلى GitHub للحصول على حدود أعلى تبلغ 5000 طلب في الساعة"]},"version":4},"contentHash":"cb243daf7e5a38eb15e25cdde2b4ab36bbfe9f51a774a394fee34cbd38aadd91","qualityScore":56}');
