INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ftc8569/ftcmetrics/nextauth', 'nextauth', 'ftc8569', 'ftcmetrics', 'community', 'nextauth ftc8569 ftcmetrics community nextauth is an authentication library for FTC Metrics, utilizing OAuth providers and a Prisma database adapter. It benefits developers seeking secure and persistent authentication solutions. NextAuth.js 是一个用于 FTC Metrics 的身份验证库，支持 OAuth 提供者（Google、Discord、GitHub）和 Prisma 数据库适配器 NextAuth.js は FTC Metrics 用の認証ライブラリで、OAuth プロバイダー（Google、Discord、GitHub）と Prisma データベースアダプターをサポートします NextAuth.js는 FTC Metrics용 인증 라이브러리로서 OAuth 제공자(Google, Discord, GitHub) 및 Prisma 데이터베이스 어댑터를 지원합니다 NextAuth es una biblioteca de autenticación que utiliza OAuth y Prisma para una autenticación segura NextAuth est une bibliothèque d''authentification qui utilise OAuth et Prisma pour une authentification sécurisée NextAuth ist eine Authentifizierungsbibliothek, die OAuth und Prisma für eine sichere Authentifizierung verwendet NextAuth é uma biblioteca de autenticação que utiliza OAuth e Prisma para persistência de sessão. Aprenda a configurá-la em suas aplicações NextAuth — это библиотека аутентификации, использующая OAuth и Prisma для сохранения сессий. Узнайте, как настроить ее в ваших приложениях NextAuth هي مكتبة مصادقة تستخدم OAuth و Prisma للاستمرار في الجلسات. تعلم كيفية ضبطها في تطبيقاتك how to use nextauth nextauth setup guide nextauth alternative nextauth vs auth0 nextauth install what is nextauth nextauth authentication nextauth prisma adapter nextauth oauth providers NextAuth.js OAuth Prisma 身份验证 安全 FTC Metrics JavaScript AIエージェント Uses OAuth providers like Google, Discord, and GitHub for authentication Employs a Prisma database adapter for session persistence Supports installation via bun add next-auth@beta Requires creation of auth configuration files like src/lib/auth.ts Integrates with NextAuth.js v5 for authentication management Utilizes the @auth/prisma-adapter for database interactions nextauth is an authentication library that uses OAuth providers and a Prisma database adapter for session persistence, enabling secure authentication for applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yashness/yash-full-stack-personal/streaming', 'community', 'yashness', 'yash-full-stack-personal', 'yashness/yash-full-stack-personal', 'streaming', 0, 0, 56, '2026-03-08T01:57:15.396Z', '2026-03-08T02:06:21.106Z', '1eba670bfee747b44326b133b6ac3eba4e4e768e1839b7a707abc0b204bcc28d', '{"id":"yashness/yash-full-stack-personal/streaming","name":"streaming","description":{"en":"The streaming skill enables AI agents to handle streaming from AI backends using the assistant-stream package. It benefits developers working with AI SDK data streams.","zh":"流媒体技术允许AI后端处理数据流。通过assistant-stream包，可以轻松实现流媒体功能","ja":"ストリーミング技術により、AIバックエンドでデータストリームを処理できます。assistant-streamパッケージを使用すると、ストリーミング機能を簡単に実現できます","ko":"스트리밍 기술을 통해 AI 백엔드에서 데이터 스트림을 처리할 수 있습니다. assistant-stream 패키지를 사용하면 스트리밍 기능을 쉽게 구현할 수 있습니다","es":"El paquete assistant-stream maneja el streaming desde backends de inteligencia artificial. Consulta la documentación para obtener más información.","fr":"Le paquet assistant-stream gère le streaming depuis les backends d''intelligence artificielle. Consultez la documentation pour obtenir plus d''informations.","de":"Das Paket assistant-stream verwaltet das Streaming von KI-Backends. Siehe die Dokumentation für weitere Informationen.","pt":"O pacote assistant-stream é utilizado para lidar com o streaming de backends de IA, fornecendo recursos de dados e transporte.","ru":"Пакет assistant-stream используется для обработки потоковой передачи от бэкендов ИИ, предоставляя функции данных и транспорта.","ar":"تستخدم حزمة assistant-stream لمعالجة البث من الخوادم الخلفية للعمليات الذكية، وتوفر ميزات البيانات والنقل."},"seo":{"title":{"en":"Streaming: Setup Guide for AI Agents | AI Agent Skill","zh":"流媒体设置指南 - AIエージェント流媒体技术","ja":"ストリーミングセットアップガイド - AIエージェントのストリーミング機能","ko":"스트리밍 설정 가이드 - AI 에이전트 스트리밍 기술","es":"Guía de configuración de streaming para agentes de inteli...","fr":"Guide de configuration du streaming pour les outils d''int...","de":"Streaming-Setup-Anleitung für KI-Agenten","pt":"Guia de Configuração de Streaming para Ferramentas de IA","ru":"Руководство по настройке потоковой передачи для ИИ Агентов","ar":"دليل إعداد البث للعمليات الذكية"},"description":{"en":"Discover how to leverage the assistant-stream package for seamless AI backend streaming. Learn more and get started with our expert guide.","zh":"了解流媒体的技术细节和设置方法，包括AI后端流媒体处理和数据流格式","ja":"ストリーミングの技術的詳細と設定方法について学びます。AIバックエンドのストリーミング処理とデータストリーム形式を含みます","ko":"스트리밍의 기술적 세부 사항과 설정 방법을 알아보세요. AI 백엔드의 스트리밍 처리와 데이터 스트림 형식을 포함합니다","es":"Aprende a configurar el streaming para tus agentes de inteligencia artificial con nuestra guía paso a paso","fr":"Découvrez comment configurer le streaming pour vos outils d''intelligence artificielle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie das Streaming für Ihre KI-Agenten mit unserem Schritt-für-Schritt-Leitfaden konfigurieren","pt":"Aprenda a configurar o streaming para ferramentas de IA com o pacote assistant-stream e descubra os recursos de dados e transporte","ru":"Узнайте, как настроить потоковую передачу для ИИ Агентов с помощью пакета assistant-stream и изучите форматы данных и транспорта","ar":"تعلم كيفية إعداد البث للعمليات الذكية باستخدام حزمة assistant-stream واكتشف ميزات البث والترميز"},"definition":{"en":"Streaming is a technology that handles real-time data streams from AI backends, utilizing the assistant-stream package and native assistant-ui formats.","zh":"流媒体是指从AI后端处理数据流的技术","ja":"ストリーミングとは、AIバックエンドでデータストリームを処理する技術です","ko":"스트리밍은 AI 백엔드에서 데이터 스트림을 처리하는 기술입니다","es":"El streaming es una función que permite la transmisión de datos en tiempo real desde backends de inteligencia artificial","fr":"Le streaming est une fonction qui permet la transmission de données en temps réel depuis les backends d''intelligence artificielle","de":"Das Streaming ist eine Funktion, die die Übertragung von Daten in Echtzeit von KI-Backends ermöglicht","pt":"Streaming de IA é a capacidade de transmitir dados em tempo real de backends de IA","ru":"Потоковая передача ИИ - это возможность передавать данные в режиме реального времени от бэкендов ИИ","ar":"البث للعمليات الذكية هو القدرة على بث البيانات في الوقت الفعلي من الخوادم الخلفية للعمليات الذكية"},"features":{"en":["Handles streaming from AI backends using the assistant-stream package","Supports AI SDK data stream format as referenced in data-stream.md","Utilizes native assistant-ui format as outlined in assistant-transport.md","Employs encoders and decoders as detailed in encoders.md","Consults the latest API from assistant-ui.com/llms.txt for optimal performance"],"zh":["支持AI后端流媒体处理","使用assistant-stream包实现流媒体功能","支持数据流格式，包括AI SDK数据流格式和Native assistant-ui格式","提供编码器和解码器用于数据流处理","支持最新的API，详见assistant-ui.com/llms.txt"],"ja":["AIバックエンドのストリーミング処理をサポート","assistant-streamパッケージを使用してストリーミング機能を実現","データストリーム形式をサポート，包括AI SDKデータストリーム形式とNative assistant-ui形式","データストリーム処理に使用するエンコーダーとデコーダーを提供","最新のAPIをサポート，詳細はassistant-ui.com/llms.txtを参照"],"ko":["AI 백엔드의 스트리밍 처리를 지원","assistant-stream 패키지를 사용하여 스트리밍 기능을 구현","데이터 스트림 형식을 지원，包括 AI SDK 데이터 스트림 형식과 Native assistant-ui 형식","데이터 스트림 처리에 사용되는 인코더와 디코더를 제공","최신 API를 지원，詳細は assistant-ui.com/llms.txt를 참조"],"es":["Soporte para el formato de flujo de datos de AI SDK","Compatibilidad con el formato de transporte nativo de assistant-ui","Uso de codificadores y decodificadores para el streaming de datos","Integración con la API de assistant-ui","Compatibilidad con diferentes backends de inteligencia artificial"],"fr":["Prise en charge du format de flux de données de l''AI SDK","Compatibilité avec le format de transport natif de l''interface utilisateur assistante","Utilisation de codeurs et de décodeurs pour le streaming de données","Intégration avec l''API de l''interface utilisateur assistante","Compatibilité avec différents backends d''intelligence artificielle"],"de":["Unterstützung für das Datenstromformat des AI-SDK","Kompatibilität mit dem nativen Transportformat von assistant-ui","Verwendung von Codierern und Decodierern für das Datenstreaming","Integration mit der assistant-ui-API","Kompatibilität mit verschiedenen KI-Backends"],"pt":["Suporte ao formato de dados de stream da AI SDK","Integração com o formato de transporte nativo do assistant-ui","Recursos de codificadores e decodificadores para streaming","Compatibilidade com a API de streaming do assistant-ui","Documentação detalhada para implementação e uso"],"ru":["Поддержка формата данных потоковой передачи ИИ SDK","Интеграция с родным форматом транспорта assistant-ui","Функции кодировщиков и декодировщиков для потоковой передачи","Совместимость с API потоковой передачи assistant-ui","Дetailed документация для реализации и использования"],"ar":["دعم صيغة بث البيانات من SDK للعمليات الذكية","التكامل مع صيغة النقل الأصلية من واجهة المساعد","ميزات المرمزات وفك الترميز للبث","التوافق مع واجهة برمجة التطبيقات البثية لواجهة المساعد","توثيق مفصل للتنفيذ والاستخدام"]},"keywords":{"en":["how to use streaming for AI agents","what is streaming in AI development","streaming alternative for AI backends","streaming vs websockets for AI data","streaming install guide for AI agents","streaming setup for assistant-ui"],"zh":["流媒体技术","AI后端流媒体处理","assistant-stream包","数据流格式","AI SDK数据流格式","Native assistant-ui格式","编码器和解码器","最新API","流媒体设置","AIエージェント流媒体"],"ja":["ストリーミング技術","AIバックエンドのストリーミング処理","assistant-streamパッケージ","データストリーム形式","AI SDKデータストリーム形式","Native assistant-ui形式","エンコーダーとデコーダー","最新API","ストリーミング設定","AIエージェントのストリーミング"],"ko":["스트리밍 기술","AI 백엔드의 스트리밍 처리","assistant-stream 패키지","데이터 스트림 형식","AI SDK 데이터 스트림 형식","Native assistant-ui 형식","인코더와 디코더","최신 API","스트리밍 설정","AI 에이전트의 스트리밍"],"es":["agentes de inteligencia artificial","streaming de datos","formato de flujo de datos de AI SDK","assistant-ui","codificadores y decodificadores","API de inteligencia artificial","desarrollo de aplicaciones de inteligencia artificial"],"fr":["outils d''intelligence artificielle","streaming de données","format de flux de données de l''AI SDK","interface utilisateur assistante","codeurs et décodeurs","API d''intelligence artificielle","développement d''applications d''intelligence artificielle"],"de":["KI-Agenten","Datenstreaming","Datenstromformat des AI-SDK","assistant-ui","Codierer und Decodierer","KI-API","Entwicklung von KI-Anwendungen"],"pt":["streaming de IA","ferramentas de IA","assistant-stream","API de streaming","formato de dados de stream","codificadores e decodificadores","implementação de streaming","guias de configuração de streaming"],"ru":["потоковая передача ИИ","ИИ Агенты","assistant-stream","API потоковой передачи","формат данных потоковой передачи","кодировщики и декодировщики","реализация потоковой передачи","руководства по настройке потоковой передачи"],"ar":["بث العمليات الذكية","أدوات العمليات الذكية","حزمة assistant-stream","واجهة برمجة التطبيقات البثية","صيغة بث البيانات","مرمزات وفك الترميز","تنفيذ البث","دلائل إعداد البث"]}},"owner":"yashness","repo":"yash-full-stack-personal","repoPath":"yashness/yash-full-stack-personal","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.396Z","topics":[],"category":"community","skillMd":{"name":"streaming","description":"Guide for assistant-stream package and streaming protocols. Use when implementing streaming backends, custom protocols, or debugging stream issues.","version":"0.0.1","bodyPreview":"# assistant-ui Streaming\n\n**Always consult [assistant-ui.com/llms.txt](https://assistant-ui.com/llms.txt) for latest API.**\n\nThe `assistant-stream` package handles streaming from AI backends.\n\n## References\n\n- [./references/data-stream.md](./references/data-stream.md) -- AI SDK data stream format\n- [./references/assistant-transport.md](./references/assistant-transport.md) -- Native assistant-ui format\n- [./references/encoders.md](./references/encoders.md) -- Encoders and decoders\n\n## When to Use","body":"# assistant-ui Streaming\n\n**Always consult [assistant-ui.com/llms.txt](https://assistant-ui.com/llms.txt) for latest API.**\n\nThe `assistant-stream` package handles streaming from AI backends.\n\n## References\n\n- [./references/data-stream.md](./references/data-stream.md) -- AI SDK data stream format\n- [./references/assistant-transport.md](./references/assistant-transport.md) -- Native assistant-ui format\n- [./references/encoders.md](./references/encoders.md) -- Encoders and decoders\n\n## When to Use\n\n```\nUsing Vercel AI SDK?\n├─ Yes → toUIMessageStreamResponse() (no assistant-stream needed)\n└─ No → assistant-stream for custom backends\n```\n\n## Installation\n\n```bash\nnpm install assistant-stream\n```\n\n## Custom Streaming Response\n\n```ts\nimport { createAssistantStreamResponse } from \"assistant-stream\";\n\nexport async function POST(req: Request) {\n  return createAssistantStreamResponse(async (stream) => {\n    stream.appendText(\"Hello \");\n    stream.appendText(\"world!\");\n\n    // Tool call example\n    const tool = stream.addToolCallPart({ toolCallId: \"1\", toolName: \"get_weather\" });\n    tool.argsText.append(''{\"city\":\"NYC\"}'');\n    tool.argsText.close();\n    tool.setResponse({ result: { temperature: 22 } });\n\n    stream.close();\n  });\n}\n```\n\n## With useLocalRuntime\n\n`useLocalRuntime` expects `ChatModelRunResult` chunks. Yield content parts for streaming:\n\n```tsx\nimport { useLocalRuntime } from \"@assistant-ui/react\";\n\nconst runtime = useLocalRuntime({\n  model: {\n    async *run({ messages, abortSignal }) {\n      const response = await fetch(\"/api/chat\", {\n        method: \"POST\",\n        body: JSON.stringify({ messages }),\n        signal: abortSignal,\n      });\n\n      const reader = response.body?.getReader();\n      const decoder = new TextDecoder();\n      let buffer = \"\";\n\n      while (reader) {\n        const { done, value } = await reader.read();\n        if (done) break;\n\n        buffer += decoder.decode(value, { stream: true });\n        const parts = buffer.split(\"\\n\");\n        buffer = parts.pop() ?? \"\";\n\n        for (const chunk of parts.filter(Boolean)) {\n          yield { content: [{ type: \"text\", text: chunk }] };\n        }\n      }\n    },\n  },\n});\n```\n\n## Debugging Streams\n\n```ts\nimport { AssistantStream, DataStreamDecoder } from \"assistant-stream\";\n\nconst stream = AssistantStream.fromResponse(response, new DataStreamDecoder());\nfor await (const event of stream) {\n  console.log(\"Event:\", JSON.stringify(event, null, 2));\n}\n```\n\n## Stream Event Types\n\n- `part-start` with `part.type` = `\"text\" | \"reasoning\" | \"tool-call\" | \"source\" | \"file\"`\n- `text-delta` with streamed text\n- `result` with tool results\n- `step-start`, `step-finish`, `message-finish`\n- `error` strings\n\n## Common Gotchas\n\n**Stream not updating UI**\n- Check Content-Type is `text/event-stream`\n- Check for CORS errors\n\n**Tool calls not rendering**\n- `addToolCallPart` needs both `toolCallId` and `toolName`\n- Register tool UI with `makeAssistantToolUI`\n\n**Partial text not showing**\n- Use `text-delta` events for streaming\n"},"lastSynced":"2026-03-08T02:06:21.106Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing real-time data processing from AI backends using the assistant-stream package.","zh":"适合需要从使用 assistant-stream 包的 AI 后端进行实时数据处理的 AI 代理。","ja":"assistant-stream パッケージを使用する AI バックエンドからのリアルタイムデータ処理を必要とする AI エージェントに最適です。","ko":"assistant-stream 패키지를 사용하는 AI 백엔드에서 실시간 데이터 처리가 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan procesamiento de datos en tiempo real desde backends de IA que utilizan el paquete assistant-stream.","fr":"Parfait pour les agents d''IA nécessitant un traitement de données en temps réel à partir de backends d''IA utilisant le paquet assistant-stream.","de":"Perfekt für KI-Agents, die Echtzeit-Datenverarbeitung von KI-Backends benötigen, die das assistant-stream-Paket verwenden.","pt":"Perfeito para Agentes de IA que precisam de processamento de dados em tempo real de backends de IA usando o pacote assistant-stream.","ru":"Идеально подходит для агентов ИИ, которым требуется обработка данных в режиме реального времени из бэкендов ИИ с использованием пакета assistant-stream.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تحتاج إلى معالجة البيانات في الوقت الفعلي من الخوادم الخلفية للذكاء الاصطناعي باستخدام حزمة assistant-stream."},"recommendation":{"en":"Empowers agents to handle streaming data from AI backends using the assistant-stream package, enabling seamless integration with AI SDK data streams and native assistant-ui formats like assistant-transport, with support for various encoders and decoders.","zh":"赋予代理处理来自 AI 后端的流数据的能力，使用 assistant-stream 包，实现与 AI SDK 数据流和本地 assistant-ui 格式（如 assistant-transport）无缝集成，并支持各种编码器和解码器。","ja":"assistant-stream パッケージを使用して、AI バックエンドからのストリーミングデータを処理するエージェントの能力を提供し、AI SDK データストリームとネイティブの assistant-ui 形式（たとえば assistant-transport）とのシームレスな統合を可能にし、さまざまなエンコーダーとデコーダーをサポートします。","ko":"에이전트가 AI 백엔드로부터의 스트리밍 데이터를 처리할 수 있는 기능을 제공하며, assistant-stream 패키지를 사용하여 AI SDK 데이터 스트림과 네이티브 assistant-ui 형식(예: assistant-transport)과의无缝集成을 가능하게 하며, 다양한 인코더와 디코더를 지원합니다.","es":"Habilita a los agentes a manejar flujos de datos de backends de IA utilizando el paquete assistant-stream, permitiendo una integración sin problemas con flujos de datos de SDK de IA y formatos nativos de assistant-ui como assistant-transport, con soporte para varios codificadores y decodificadores.","fr":"Permet aux agents de gérer les flux de données à partir de backends d''IA en utilisant le paquet assistant-stream, permettant une intégration transparente avec les flux de données de SDK d''IA et les formats natifs d''assistant-ui tels que assistant-transport, avec prise en charge de divers encodeurs et décodeurs.","de":"Ermöglicht es Agents, Streaming-Daten von KI-Backends mithilfe des assistant-stream-Pakets zu verarbeiten, wodurch eine nahtlose Integration mit KI-SDK-Datenströmen und nativen assistant-ui-Formaten wie assistant-transport ermöglicht wird, mit Unterstützung für verschiedene Encoder und Decoder.","pt":"Habilita os agentes a lidarem com transmissões de dados de backends de IA usando o pacote assistant-stream, permitindo uma integração perfeita com transmissões de dados de SDK de IA e formatos nativos de interface do usuário do assistente, como o assistente-transporte, com suporte a vários codificadores e decodificadores.","ru":"Наделяет агентов возможностью обрабатывать потоковые данные из бэкендов ИИ с использованием пакета assistant-stream, обеспечивая бесшовную интеграцию с потоками данных SDK ИИ и родными форматами интерфейса пользователя помощника, такими как assistent-transport, с поддержкой различных кодировщиков и декодировщиков.","ar":"تمكين الوكلاء من التعامل مع تدفقات البيانات من الخوادم الخلفية للذكاء الاصطناعي باستخدام حزمة assistant-stream، وتمكين التكامل السلس مع تدفقات بيانات SDK للذكاء الاصطناعي والتنسيقات الأصلية لواجهة المستخدم للوكيل، مثل assistent-transport، مع دعم لمختلف المُشفرات والمُفسرات."},"useCases":{"en":["Streaming AI-generated content in real-time","Processing live data streams from AI backends","Integrating AI SDK data streams with native assistant-ui formats"],"zh":["实时流式传输 AI 生成的内容","处理来自 AI 后端的实时数据流","将 AI SDK 数据流与本地 assistant-ui 格式集成"],"ja":["AI によって生成されたコンテンツのリアルタイムストリーミング","AI バックエンドからのリアルタイムデータストリームの処理","AI SDK データストリームとネイティブの assistant-ui 形式の統合"],"ko":["실시간으로 AI가 생성한 콘텐츠를 스트리밍","AI 백엔드로부터의 실시간 데이터 스트림 처리","AI SDK 데이터 스트림과 네이티브 assistant-ui 형식 통합"],"es":["Transmisión de contenido generado por IA en tiempo real","Procesamiento de flujos de datos en vivo desde backends de IA","Integración de flujos de datos de SDK de IA con formatos nativos de assistant-ui"],"fr":["Diffusion de contenu généré par IA en temps réel","Traitement de flux de données en direct à partir de backends d''IA","Intégration de flux de données de SDK d''IA avec des formats natifs d''assistant-ui"],"de":["Streaming von von KI generiertem Inhalt in Echtzeit","Verarbeitung von Live-Datenströmen von KI-Backends","Integration von KI-SDK-Datenströmen mit nativen assistant-ui-Formaten"],"pt":["Transmissão de conteúdo gerado por IA em tempo real","Processamento de transmissões de dados ao vivo de backends de IA","Integração de transmissões de dados de SDK de IA com formatos nativos de interface do usuário do assistente"],"ru":["Трансляция контента, сгенерированного ИИ, в режиме реального времени","Обработка живых потоков данных из бэкендов ИИ","Интеграция потоков данных SDK ИИ с родными форматами интерфейса пользователя помощника"],"ar":["بث محتوى تم إنشاؤه بواسطة الذكاء الاصطناعي في الوقت الفعلي","معالجة تدفقات البيانات الحية من الخوادم الخلفية للذكاء الاصطناعي","دمج تدفقات بيانات SDK للذكاء الاصطناعي مع التنسيقات الأصلية لواجهة المستخدم للوكيل"]},"limitations":{"en":["Requires the assistant-stream package","Dependent on AI backend data stream availability","Must consult the latest API documentation at assistant-ui.com/llms.txt"],"zh":["需要 assistant-stream 包","依赖于 AI 后端数据流的可用性","必须查阅 assistant-ui.com/llms.txt 的最新 API 文档"],"ja":["assistant-stream パッケージが必要","AI バックエンドのデータストリームの可用性に依存","assistant-ui.com/llms.txt の最新の API ドキュメントを参照する必要がある"],"ko":["assistant-stream 패키지가 필요","AI 백엔드 데이터 스트림의 가용성에 의존","assistant-ui.com/llms.txt의 최신 API 문서를 참조해야 함"],"es":["Requiere el paquete assistant-stream","Dependiente de la disponibilidad de flujos de datos de backends de IA","Debes consultar la última documentación de API en assistant-ui.com/llms.txt"],"fr":["Nécessite le paquet assistant-stream","Dépend de la disponibilité des flux de données de backends d''IA","Vous devez consulter la dernière documentation d''API sur assistant-ui.com/llms.txt"],"de":["Benötigt das assistant-stream-Paket","Abhängig von der Verfügbarkeit von KI-Backend-Datenströmen","Sie müssen die aktuellste API-Dokumentation unter assistant-ui.com/llms.txt konsultieren"],"pt":["Requer o pacote assistant-stream","Dependente da disponibilidade de transmissões de dados de backends de IA","Deve consultar a documentação de API mais recente em assistant-ui.com/llms.txt"],"ru":["Требует пакета assistant-stream","Зависит от наличия потоковых данных бэкендов ИИ","Необходимо ознакомиться с последней документацией API на assistant-ui.com/llms.txt"],"ar":["يتطلب حزمة assistant-stream","يعتمد على توافر تدفقات البيانات من الخوادم الخلفية للذكاء الاصطناعي","يجب استشارة أحدث وثائق API على assistant-ui.com/llms.txt"]},"version":4},"contentHash":"1eba670bfee747b44326b133b6ac3eba4e4e768e1839b7a707abc0b204bcc28d","qualityScore":56}');
