INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yashness/yash-full-stack-personal/streaming', 'streaming', 'yashness', 'yash-full-stack-personal', 'community', 'streaming yashness yash-full-stack-personal community The streaming skill enables AI agents to handle streaming from AI backends using the assistant-stream package. It benefits developers working with AI SDK data streams. 流媒体技术允许AI后端处理数据流。通过assistant-stream包，可以轻松实现流媒体功能 ストリーミング技術により、AIバックエンドでデータストリームを処理できます。assistant-streamパッケージを使用すると、ストリーミング機能を簡単に実現できます 스트리밍 기술을 통해 AI 백엔드에서 데이터 스트림을 처리할 수 있습니다. assistant-stream 패키지를 사용하면 스트리밍 기능을 쉽게 구현할 수 있습니다 El paquete assistant-stream maneja el streaming desde backends de inteligencia artificial. Consulta la documentación para obtener más información. Le paquet assistant-stream gère le streaming depuis les backends d''intelligence artificielle. Consultez la documentation pour obtenir plus d''informations. Das Paket assistant-stream verwaltet das Streaming von KI-Backends. Siehe die Dokumentation für weitere Informationen. O pacote assistant-stream é utilizado para lidar com o streaming de backends de IA, fornecendo recursos de dados e transporte. Пакет assistant-stream используется для обработки потоковой передачи от бэкендов ИИ, предоставляя функции данных и транспорта. تستخدم حزمة assistant-stream لمعالجة البث من الخوادم الخلفية للعمليات الذكية، وتوفر ميزات البيانات والنقل. how to use streaming for AI agents what is streaming in AI development streaming alternative for AI backends streaming vs websockets for AI data streaming install guide for AI agents streaming setup for assistant-ui 流媒体技术 AI后端流媒体处理 assistant-stream包 数据流格式 AI SDK数据流格式 Native assistant-ui格式 编码器和解码器 最新API 流媒体设置 AIエージェント流媒体 Handles streaming from AI backends using the assistant-stream package Supports AI SDK data stream format as referenced in data-stream.md Utilizes native assistant-ui format as outlined in assistant-transport.md Employs encoders and decoders as detailed in encoders.md Consults the latest API from assistant-ui.com/llms.txt for optimal performance Streaming is a technology that handles real-time data streams from AI backends, utilizing the assistant-stream package and native assistant-ui formats.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('openakita/openakita/openakita/skills@file-manager', 'community', 'openakita', 'openakita', 'openakita/openakita', 'openakita/skills@file-manager', 0, 0, 56, '2026-03-08T01:57:15.401Z', '2026-03-08T02:06:45.851Z', '62c0bdae7fe4ec569d3b23caf490a38b8c0a75eaf88cc4421708466c7c8d34d7', '{"id":"openakita/openakita/openakita/skills@file-manager","name":"openakita/skills@file-manager","description":{"en":"The openakita/skills@file-manager skill enables AI agents to perform various file operations, benefiting developers who need to manage files and directories programmatically.","zh":"openakita/skills@file-manager 提供了一套文件和目录管理工具，包括创建、删除、移动、复制文件或目录等功能","ja":"openakita/skills@file-manager はファイルとディレクトリの管理ツールセットを提供します","ko":"openakita/skills@file-manager는 파일과 디렉토리 관리 도구セット을 제공합니다","es":"openakita/skills@file-manager es un framework de asistente de IA de código abierto que proporciona herramientas para gestionar archivos y directorios","fr":"openakita/skills@file-manager est un framework d''assistant IA open source qui fournit des outils pour gérer des fichiers et des répertoires","de":"openakita/skills@file-manager ist ein Open-Source-AI-Assistenten-Framework, das Tools zur Verwaltung von Dateien und Verzeichnissen bietet","pt":"O openakita/skills@file-manager é uma ferramenta de gerenciamento de arquivos e diretórios que permite criar, deletar, mover e copiar arquivos com Python e CLI.","ru":"ИИ Агенты openakita/skills@file-manager - это инструмент для управления файлами и директориями, который позволяет создавать, удалять, перемещать и копировать файлы с помощью Python и CLI.","ar":"أداة الإدارة الملفات openakita/skills@file-manager هي أداة لتنظيم الملفات والمجلدات التي تمكن من إنشاء وحذف ونقل ونسخ الملفات باستخدام Python و CLI"},"seo":{"title":{"en":"openakita/skills@file-manager: File Operations Setup Guid...","zh":"openakita/skills@file-manager 文件管理工具集使用指南","ja":"openakita/skills@file-manager AIエージェントによるファイル管理ベストプラクティス","ko":"openakita/skills@file-manager 파일 관리 도구セット 설정 가이드","es":"Guía de configuración de openakita/skills@file-manager pa...","fr":"Configurer openakita/skills@file-manager pour les dévelop...","de":"Einrichtungsleitfaden für openakita/skills@file-manager f...","pt":"Guia de Configuração do openakita/skills@file-manager par...","ru":"ИИ Агенты: Настройка openakita/skills@file-manager для ра...","ar":"إعداد أداة الإدارة الملفات openakita/skills@file-manager ..."},"description":{"en":"Discover how to leverage openakita/skills@file-manager for efficient file management. Learn to create, delete, and manipulate files with ease. Get started now!","zh":"openakita/skills@file-manager 是一个开源的AI助手框架，提供文件和目录管理工具集，包括创建、删除、移动、复制文件或目录等功能","ja":"openakita/skills@file-manager はオープンソースのAIエージェントフレームワークで、ファイルとディレクトリの管理ツールセットを提供します","ko":"openakita/skills@file-manager는 오픈소스의 AI 에이전트 프레임워크로 파일과 디렉토리 관리 도구セット을 제공합니다","es":"Aprende a utilizar openakita/skills@file-manager para gestionar archivos y directorios de manera efectiva con Python y CLI","fr":"Découvrez comment utiliser openakita/skills@file-manager pour gérer des fichiers et des répertoires avec Python et CLI","de":"Erfahren Sie, wie Sie openakita/skills@file-manager verwenden, um Dateien und Verzeichnisse mit Python und CLI effektiv zu verwalten","pt":"Aprenda a utilizar o openakita/skills@file-manager para gerenciar arquivos e diretórios de forma eficiente com Python e CLI","ru":"Откройте для себя возможности ИИ Агентов с openakita/skills@file-manager для эффективного управления файлами и директориями с помощью Python и CLI","ar":"استخدم أداة الإدارة الملفات openakita/skills@file-manager لتنظيم الملفات والمجلدات بفعالية باستخدام Python و CLI"},"definition":{"en":"openakita/skills@file-manager is an open-source AI assistant framework skill for managing files and directories, providing tools for creation, deletion, and manipulation.","zh":"openakita/skills@file-manager 是一个用于管理文件和目录的工具集","ja":"openakita/skills@file-manager はファイルとディレクトリの管理ツールセットです","ko":"openakita/skills@file-manager는 파일과 디렉토리 관리 도구セット입니다","es":"Un conjunto de herramientas de gestión de archivos y directorios para desarrolladores que utilizan Python y CLI","fr":"Un ensemble d''outils de gestion de fichiers et de répertoires pour les développeurs qui utilisent Python et CLI","de":"Ein Satz von Tools zur Verwaltung von Dateien und Verzeichnissen für Entwickler, die Python und CLI verwenden","pt":"O que é openakita/skills@file-manager? É uma ferramenta de gerenciamento de arquivos e diretórios baseada em Python e CLI.","ru":"Что такое openakita/skills@file-manager? Это инструмент для управления файлами и директориями на основе Python и CLI.","ar":"ما هو openakita/skills@file-manager؟ هو أداة لتنظيم الملفات والمجلدات مبنية على Python و CLI"},"features":{"en":["Lists directory contents using the `list` command with optional recursion and pattern filtering","Reads file contents with the `read` command, supporting encoding specification such as UTF-8","Writes file contents using the `write` command with optional appending","Copies files with the `copy` command, specifying source and destination paths","Moves or renames files using the `move` command"],"zh":["创建、删除、移动、复制文件或目录","读取或写入文件内容","搜索文件","列出目录内容","获取文件信息（大小、修改时间等）","使用Python脚本执行文件操作"],"ja":["ファイルやディレクトリの作成、削除、移動、コピー","ファイル内容の読み取りや書き込み","ファイルの検索","ディレクトリ内容のリスト化","ファイル情報（サイズ、変更時刻等）の取得","Pythonスクリプトを使用したファイル操作"],"ko":["파일이나 디렉토리의 생성, 삭제, 이동, 복사","파일 내용의 읽기 또는 쓰기","파일 검색","디렉토리 내용의 리스트화","파일 정보（크기, 수정 시간 등）的取得","Python 스크립트를 사용한 파일操作"],"es":["Crear, eliminar, mover y copiar archivos y directorios","Lectura y escritura de archivos con encoding personalizable","Búsqueda de archivos y listado de directorios","Obtención de información de archivos, como tamaño y fecha de modificación","Uso de patrones para filtrar archivos y directorios"],"fr":["Créer, supprimer, déplacer et copier des fichiers et des répertoires","Lecture et écriture de fichiers avec encoding personnalisable","Recherche de fichiers et liste de répertoires","Obtention d''informations sur les fichiers, comme la taille et la date de modification","Utilisation de modèles pour filtrer les fichiers et les répertoires"],"de":["Erstellen, löschen, verschieben und kopieren von Dateien und Verzeichnissen","Lesen und schreiben von Dateien mit anpassbarem Encoding","Suchen von Dateien und Auflisten von Verzeichnissen","Abrufen von Dateiinformationen, wie Größe und Änderungsdatum","Verwenden von Mustern zum Filtern von Dateien und Verzeichnissen"],"pt":["Criação e exclusão de arquivos e diretórios","Leitura e escrita de arquivos com Python","Busca de arquivos com padrões de nome","Listagem de diretórios com opção de recursividade","Obtenção de informações de arquivos, como tamanho e data de modificação"],"ru":["Создание и удаление файлов и директорий","Чтение и запись файлов с помощью Python","Поиск файлов по шаблонам названий","Перечисление директорий с возможностью рекурсии","Получение информации о файлах, такой как размер и дата изменения"],"ar":["إنشاء وحذف الملفات والمجلدات","قراءة وكتابة الملفات باستخدام Python","بحث الملفات حسب أنماط الأسماء","قائمة المجلدات مع خيار التكرار","الحصول على معلومات الملفات، مثل الحجم وتاريخ التعديل"]},"keywords":{"en":["how to use openakita/skills@file-manager","openakita/skills@file-manager setup guide","file manager AI agent skills","openakita/skills@file-manager vs file system managers","openakita/skills@file-manager install for AI agents","file operations with openakita/skills@file-manager"],"zh":["openakita/skills@file-manager","AI助手框架","文件管理工具集","Python脚本","文件操作","目录管理","AI工具","文件搜索","文件信息"],"ja":["openakita/skills@file-manager","AIエージェントフレームワーク","ファイル管理ツールセット","Pythonスクリプト","ファイル操作","ディレクトリ管理","AIエージェント","ファイル検索","ファイル情報"],"ko":["openakita/skills@file-manager","AI 에이전트 프레임워크","파일 관리 도구セット","Python 스크립트","파일操作","디렉토리 관리","AI 도구","파일 검색","파일 정보"],"es":["openakita/skills@file-manager","gestión de archivos","gestión de directorios","Python","CLI","herramientas de desarrollo","framework de asistente de IA","IA para desarrolladores"],"fr":["openakita/skills@file-manager","gestion de fichiers","gestion de répertoires","Python","CLI","outils de développement","framework d''assistant IA","IA pour les développeurs"],"de":["openakita/skills@file-manager","Dateiverwaltung","Verzeichnisverwaltung","Python","CLI","Entwicklungstools","AI-Assistenten-Framework","KI für Entwickler"],"pt":["openakita/skills@file-manager","gerenciamento de arquivos","Python","CLI","desenvolvimento de software","ferramentas de produtividade","organização de arquivos","busca de arquivos","leitura e escrita de arquivos"],"ru":["openakita/skills@file-manager","ИИ Агенты","управление файлами","Python","CLI","разработка программного обеспечения","инструменты производительности","организация файлов","поиск файлов","чтение и запись файлов"],"ar":["openakita/skills@file-manager","أداة الإدارة الملفات","تنظيم الملفات","Python","CLI","تطوير البرمجيات","أدوات الإنتاجية","قائمة الملفات","بحث الملفات","قراءة وكتابة الملفات"]}},"owner":"openakita","repo":"openakita","repoPath":"openakita/openakita","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.401Z","topics":[],"category":"community","skillMd":{"name":"openakita/skills@file-manager","description":"|","version":"1.0.0","bodyPreview":"# File Manager\n\n管理文件和目录的工具集。\n\n## When to Use\n\n- 创建、删除、移动、复制文件或目录\n- 读取或写入文件内容\n- 搜索文件\n- 列出目录内容\n- 获取文件信息（大小、修改时间等）\n\n## Instructions\n\n### 列出目录\n\n```bash\npython scripts/file_ops.py list <path> [--recursive] [--pattern \"*.py\"]\n```\n\n### 读取文件\n\n```bash\npython scripts/file_ops.py read <file_path> [--encoding utf-8]\n```\n\n### 写入文件\n\n```bash\npython scripts/file_ops.py write <file_path> --content \"内容\" [--append]\n```\n\n### 复制文件\n\n```bash\npython scripts/file_ops.py copy <source> <destination>\n```\n\n### 移动/重命名\n\n```ba","body":"# File Manager\n\n管理文件和目录的工具集。\n\n## When to Use\n\n- 创建、删除、移动、复制文件或目录\n- 读取或写入文件内容\n- 搜索文件\n- 列出目录内容\n- 获取文件信息（大小、修改时间等）\n\n## Instructions\n\n### 列出目录\n\n```bash\npython scripts/file_ops.py list <path> [--recursive] [--pattern \"*.py\"]\n```\n\n### 读取文件\n\n```bash\npython scripts/file_ops.py read <file_path> [--encoding utf-8]\n```\n\n### 写入文件\n\n```bash\npython scripts/file_ops.py write <file_path> --content \"内容\" [--append]\n```\n\n### 复制文件\n\n```bash\npython scripts/file_ops.py copy <source> <destination>\n```\n\n### 移动/重命名\n\n```bash\npython scripts/file_ops.py move <source> <destination>\n```\n\n### 删除\n\n```bash\npython scripts/file_ops.py delete <path> [--recursive]\n```\n\n### 搜索文件\n\n```bash\npython scripts/file_ops.py search <directory> --pattern \"*.py\" [--content \"search_text\"]\n```\n\n### 获取文件信息\n\n```bash\npython scripts/file_ops.py info <path>\n```\n\n## Output Format\n\n所有操作返回 JSON 格式:\n\n```json\n{\n  \"success\": true,\n  \"operation\": \"list\",\n  \"data\": {\n    \"files\": [\"file1.py\", \"file2.py\"],\n    \"directories\": [\"subdir\"],\n    \"count\": 3\n  }\n}\n```\n\n## Safety Notes\n\n- 删除操作不可恢复，谨慎使用\n- 写入文件会覆盖原有内容（除非使用 --append）\n- 对于重要文件，建议先备份\n"},"lastSynced":"2026-03-08T02:06:45.851Z","agentAnalysis":{"suitability":{"en":"Ideal for System Administration Agents requiring advanced file operation capabilities.","zh":"适用于需要高级文件操作能力的系统管理代理。","ja":"システム管理エージェントが高度なファイル操作機能を必要とする場合に最適です。","ko":"고급 파일操作 기능이 필요한 시스템 관리 에이전트에 적합합니다.","es":"Ideal para agentes de administración de sistemas que requieren capacidades de operación de archivos avanzadas.","fr":"Idéal pour les agents d''administration de système nécessitant des capacités de manipulation de fichiers avancées.","de":"Ideal für Systemadministration-Agents, die erweiterte Dateioperationen erfordern.","pt":"Ideal para Agentes de Administração de Sistema que exigem capacidades avançadas de operação de arquivos.","ru":"Идеально для агентов системного администрирования, требующих расширенных возможностей операций с файлами.","ar":"مثالي لعمليات وكيل إدارة النظام التي تتطلب khảیات متقدمة لعمليات الملفات."},"recommendation":{"en":"Empowers agents to perform comprehensive file management tasks, including creating, deleting, moving, and copying files or directories, using Python scripts with optional recursive and pattern-based searching, and handling file contents with specified encoding.","zh":"赋予代理执行全面的文件管理任务的能力，包括使用Python脚本创建、删除、移动和复制文件或目录，并支持可选的递归和基于模式的搜索，以及使用指定编码处理文件内容。","ja":"エージェントがPythonスクリプトを使用して包括的なファイル管理タスクを実行できるようにします。ファイルやディレクトリの作成、削除、移動、コピーなど、およびオプションの再帰的およびパターンに基づく検索、指定されたエンコードでファイル内容を処理します。","ko":"에이전트가 Python 스크립트를 사용하여 포괄적인 파일 관리 태스크를 수행할 수 있도록 합니다. 파일 또는 디렉토리의 생성, 삭제, 이동, 복사 등을 포함하며, 선택적인 재귀적 및 패턴 기반 검색과 지정된 인코딩으로 파일 내용을 처리할 수 있습니다.","es":"Permite a los agentes realizar tareas de gestión de archivos completas, incluyendo la creación, eliminación, movimiento y copia de archivos o directorios, utilizando scripts de Python con búsqueda recursiva y basada en patrones opcionales, y el manejo de contenidos de archivos con codificación especificada.","fr":"Autorise les agents à effectuer des tâches de gestion de fichiers complètes, notamment la création, la suppression, le déplacement et la copie de fichiers ou de répertoires, en utilisant des scripts Python avec recherche récursive et basée sur des modèles optionnels, et la gestion de contenu de fichiers avec une codage spécifié.","de":"Ermöglicht es den Agents, umfassende Dateiverwaltungsaufgaben durchzuführen, einschließlich Erstellen, Löschen, Verschieben und Kopieren von Dateien oder Verzeichnissen, unter Verwendung von Python-Skripten mit optionaler rekursiver und musterbasierter Suche und der Verarbeitung von Dateiinhalten mit angegebener Codierung.","pt":"Habilita os agentes a realizar tarefas de gerenciamento de arquivos abrangentes, incluindo criar, excluir, mover e copiar arquivos ou diretórios, usando scripts Python com busca recursiva e baseada em padrões opcionais, e manipular conteúdos de arquivos com codificação especificada.","ru":"Наделяет агентов возможностью выполнять комплексные задачи управления файлами, включая создание, удаление, перемещение и копирование файлов или директорий, используя скрипты Python с опциональным рекурсивным и основанным на шаблонах поиском, и обработку содержимого файлов с указанной кодировкой.","ar":"يتمكن الوكلاء من أداء مهام إدارة الملفات الشاملة، بما في ذلك إنشاء وحذف ونقل ونسخ الملفات أو الدلائل، باستخدام سكريبتات Python مع خيارات البحث التكراري والقائم على النمط، ومعالجة محتويات الملفات مع ترميز محدد."},"useCases":{"en":["Automating directory listing and file searching with pattern matching","Generating and modifying file contents programmatically with encoding options","Copying and moving files or directories with precision"],"zh":["使用模式匹配自动执行目录列表和文件搜索","使用编码选项以编程方式生成和修改文件内容","使用精确度复制和移动文件或目录"],"ja":["パターンマッチングを使用したディレクトリリストとファイル検索の自動化","エンコードオプションを使用したファイル内容のプログラムによる生成と変更","精度の高いファイルまたはディレクトリのコピーと移動"],"ko":["패턴 매칭을 사용하여 디렉토리 목록 및 파일 검색 자동화","인코딩 옵션을 사용하여 파일 내용을 프로그래밍 방식으로 생성 및 수정","정밀도 높은 파일 또는 디렉토리의 복사 및 이동"],"es":["Automatización de listado de directorios y búsqueda de archivos con coincidencia de patrones","Generación y modificación de contenidos de archivos de forma programática con opciones de codificación","Copiar y mover archivos o directorios con precisión"],"fr":["Automatisation de la liste de répertoires et de la recherche de fichiers avec correspondance de modèles","Génération et modification de contenu de fichiers de manière programmée avec des options de codage","Copie et déplacement de fichiers ou de répertoires avec précision"],"de":["Automatisierung der Verzeichnisauflistung und der Dateisuche mit Mustervergleich","Erzeugen und Modifizieren von Dateiinhalten programmgesteuert mit Codierungsoptionen","Kopieren und Verschieben von Dateien oder Verzeichnissen mit Präzision"],"pt":["Automatizar a listagem de diretórios e a busca de arquivos com correspondência de padrões","Gerar e modificar conteúdos de arquivos programaticamente com opções de codificação","Copiar e mover arquivos ou diretórios com precisão"],"ru":["Автоматизировать перечисление директорий и поиск файлов с сопоставлением шаблонов","Генерировать и изменять содержимое файлов программно с опциями кодирования","Копировать и перемещать файлы или директории с точностью"],"ar":["توفير قائمة الدلائل والبحث عن الملفات مع مطابقة الأنماط","генерировать وتعديل محتويات الملفات برمجيًا مع خيارات الترميز","نسخ ونقل الملفات أو الدلائل بدقة"]},"limitations":{"en":["Requires Python environment","Dependent on script execution permissions","Limited to file systems accessible by the agent''s Python environment"],"zh":["需要Python环境","依赖脚本执行权限","仅限于代理的Python环境可以访问的文件系统"],"ja":["Python環境が必要","スクリプト実行権限に依存する","エージェントのPython環境がアクセスできるファイルシステムに限定される"],"ko":["Python 환경이 필요합니다.","스크립트 실행 권한에 의존합니다.","에이전트의 Python 환경에서 액세스할 수 있는 파일 시스템에만 제한됩니다."],"es":["Requiere entorno de Python","Dependiente de los permisos de ejecución de scripts","Limitado a los sistemas de archivos accesibles por el entorno de Python del agente"],"fr":["Nécessite un environnement Python","Dépend des autorisations d''exécution de scripts","Limité aux systèmes de fichiers accessibles par l''environnement Python de l''agent"],"de":["Benötigt Python-Umgebung","Abhängig von Skriptausführungsberechtigungen","Begrenzt auf Dateisysteme, die vom Python-Umgebung des Agents zugänglich sind"],"pt":["Requer ambiente Python","Dependente das permissões de execução de scripts","Limitado a sistemas de arquivos acessíveis pelo ambiente Python do agente"],"ru":["Требует среды Python","Зависит от разрешений на выполнение скриптов","Ограничен файловыми системами, доступными для среды Python агента"],"ar":["يتطلب بيئة Python","يتوقف على صلاحيات تشغيل السكريبتات","محدود بنظم الملفات التي يمكن الوصول إليها بواسطة بيئة Python للوكيل"]},"version":4},"contentHash":"62c0bdae7fe4ec569d3b23caf490a38b8c0a75eaf88cc4421708466c7c8d34d7","qualityScore":56}');
