INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TurnaboutHero/oh-my-antigravity/scribe', 'scribe', 'TurnaboutHero', 'oh-my-antigravity', 'community', 'scribe TurnaboutHero oh-my-antigravity community Scribe is a technical documentation specialist for Google Antigravity IDE, providing a multi-agent orchestration framework for efficient project development. It benefits developers by streamlining documentation processes. Scribe 是一个多代理编排框架，用于 Google Antigravity IDE，提供技术文档和 API 参考 Scribe は Google Antigravity IDE 用のマルチエージェントオーケストレーションフレームワークです。技術文書と API リファレンスを提供します Scribe는 Google Antigravity IDE용 多代理 编排 프레임워크입니다. 기술문서 및 API 레퍼런스를 제공합니다 Scribe es un framework de orquestación multiagente para Google Antigravity IDE que facilita la creación de documentación técnica Scribe est un framework d''orchestration multi-agent pour Google Antigravity IDE qui facilite la création de documentation technique Scribe ist ein Framework für die Multi-Agenten-Orchestrierung für Google Antigravity IDE, das die Erstellung von technischer Dokumentation erleichtert O Scribe é um framework de orquestração multi-agente para o Google Antigravity IDE, que fornece documentação técnica especializada Scribe - это фреймворк для мульти-агентной оркестрации для Google Antigravity IDE, который предоставляет техническую документацию специалиста سكريب هو إطار عمل لتنسيق متعدد الوكلاء لجوجل أنتي جرافيتي أي دي إي، يوفر توثيقًا تقنيًا متخصصًا how to use scribe scribe alternative scribe setup guide what is scribe scribe vs google antigravity ide scribe install multi-agent orchestration framework google antigravity ide development technical documentation specialist Scribe 技术文档 Google Antigravity IDE 多代理编排框架 API 参考 TypeScript README.md 快速启动 安装指南 Generates README.md files with project descriptions and features Supports installation via npm with commands like `npm install project-name` Provides Quick Start guides with TypeScript examples, such as `import { Something } from ''project-name'';` Offers API Reference documentation for methods like `Something.run()` Enables brief project descriptions and feature listings in Markdown format Scribe is a multi-agent orchestration framework for Google Antigravity IDE, specializing in technical documentation and project development simplification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('patrykgz/rust-devagent-loop-template/temporal-awareness', 'community', 'patrykgz', 'rust-devagent-loop-template', 'patrykgz/rust-devagent-loop-template', 'temporal-awareness', 0, 0, 56, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:11.551Z', 'aa3b02dfdcc33b57201aa6c19612ac491f63b1d057f9ef9fb559cc551085a22a', '{"id":"patrykgz/rust-devagent-loop-template/temporal-awareness","name":"temporal-awareness","description":{"en":"Temporal-awareness is a Rust template repo that implements a strict back pressure loop for Claude Code, helping developers verify temporal information. It benefits AI agent developers working with date-sensitive queries.","zh":"时间感知是AI代理的关键功能，确保其获取最新的时间信息。该Rust模板实现了严格的回压循环，用于Claude Code","ja":"テンポラルアウェアネスはAIエージェントの重要な機能であり、最新の時間情報を取得することを保証します。このRustテンプレートリポジトリは、Claude Code用の厳密なバックプレッシャー循環を実装しています","ko":"시간 인식은 AI 에이전트의 핵심 기능으로, 최신 시간 정보를 얻는 것을 보장합니다. 이 Rust 템플릿은 Claude Code용 엄격한 백프레셔 루프를 구현합니다","es":"Conciencia temporal para Claude Code mediante un bucle de presión hacia atrás estricto implementado en Rust","fr":"Conscience temporelle pour Claude Code via une boucle de pression arrière stricte implementée en Rust","de":"Temporale Bewusstsein für Claude Code durch eine strenge Rückdruck-Schleife implementiert in Rust","pt":"O temporal-awareness é uma habilidade que implementa um loop de pressão de retorno estrito para Claude Code, permitindo a verificação de informações temporais com comandos Unix.","ru":"Временное осознание - это навык, который реализует строгий цикл обратного давления для Claude Code, позволяя проверять временную информацию с помощью команд Unix.","ar":"الوعي الزمني هو مهارة تنفذ حلقة ضغط متأخرة صارمة ل Claude Code، مما يسمح بفحص المعلومات الزمنية باستخدام أوامر Unix."},"seo":{"title":{"en":"Temporal-Awareness: Setup Guide for AI Agents | AI Agent ...","zh":"时间感知设置指南 - 使用Rust模板实现严格的回压循环","ja":"テンポラルアウェアネス設定ガイド - Claude Code用のRustテンプレートリポジトリ","ko":"시간 인식 설정 가이드 - Rust 템플릿을 사용한 엄격한 백프레셔 루프 구현","es":"Guía de configuración de conciencia temporal para Claude ...","fr":"Guide de mise en place de la conscience temporelle pour C...","de":"Einrichtungsleitfaden für temporale Bewusstsein in Claude...","pt":"Guia de Configuração de Conscientização Temporal para Fer...","ru":"Руководство по настройке временного осознания для ИИ Агентов","ar":"دليل إعداد الوعي الزمني لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to implement temporal-awareness in your AI agent with Unix commands and verify date-sensitive queries. Learn more and get started today!","zh":"了解时间感知的重要性和使用Rust模板实现严格的回压循环，确保您的AI代理始终获取最新的时间信息","ja":"テンポラルアウェアネスの重要性とClaude Code用のRustテンプレートリポジトリを使用した厳密なバックプレッシャー循環の実装方法について","ko":"시간 인식의 중요성과 Rust 템플릿을 사용한 엄격한 백프레셔 루프 구현 방법에 대해 알아보세요","es":"Aprende a implementar un bucle de presión hacia atrás estricto para Claude Code con nuestro repositorio de plantillas de Rust","fr":"Découvrez comment mettre en œuvre une boucle de pression arrière stricte pour Claude Code avec notre référentiel de modèles Rust","de":"Erfahren Sie, wie Sie eine strenge Rückdruck-Schleife für Claude Code mit unserem Rust-Template-Repository implementieren","pt":"Aprenda a implementar um loop de pressão de retorno estrito com Claude Code e verifique informações temporais com comandos Unix","ru":"Изучите реализацию строгого цикла обратного давления с Claude Code и проверку временной информации с помощью команд Unix","ar":"تعرف على كيفية تنفيذ حلقة ضغط متأخرة صارمة مع Claude Code وตรวจสอบ المعلومات الزمنية باستخدام أوامر Unix"},"definition":{"en":"temporal-awareness is a technique for verifying temporal information using Unix commands, ensuring accuracy in date-sensitive queries","zh":"时间感知是AI代理用来感知和处理时间信息的能力，确保其响应日期敏感的查询","ja":"テンポラルアウェアネスは、AIエージェントが時間情報を認識し、処理する能力であり、日付に敏感なクエリに応答することを保証します","ko":"시간 인식은 AI 에이전트가 시간 정보를 인식하고 처리하는 능력으로, 날짜에 민감한 쿼리에 응답하는 것을 보장합니다","es":"Conciencia temporal se refiere a la capacidad de verificar información temporal utilizando comandos Unix","fr":"La conscience temporelle fait référence à la capacité de vérifier les informations temporelles à l''aide de commandes Unix","de":"Temporale Bewusstsein bezieht sich auf die Fähigkeit, zeitliche Informationen mithilfe von Unix-Befehlen zu überprüfen","pt":"Conscientização Temporal é uma habilidade que verifica informações temporais com comandos Unix","ru":"Временное осознание - это навык, который проверяет временную информацию с помощью команд Unix","ar":"الوعي الزمني هو مهارة تفحص المعلومات الزمنية باستخدام أوامر Unix"},"features":{"en":["Implements a strict back pressure loop for Claude Code","Verifies temporal information using Unix commands","Supports GNU date and BSD date commands","Checks for installed date command version","Provides example commands for getting current date/time"],"zh":["使用Rust模板实现严格的回压循环","支持GNU date和BSD date命令","可以检查日期命令的版本","确保AI代理获取最新的时间信息"],"ja":["Rustテンプレートを使用した厳密なバックプレッシャー循環の実装","GNU dateとBSD dateコマンドのサポート","日付コマンドのバージョンの確認","AIエージェントが最新の時間情報を取得することを保証"],"ko":["Rust 템플릿을 사용한 엄격한 백프레셔 루프 구현","GNU date와 BSD date 명령어 지원","날짜 명령어 버전 확인","AI 에이전트가 최신 시간 정보를 얻는 것을 보장"],"es":["Implementación de un bucle de presión hacia atrás estricto para Claude Code","Verificación de información temporal utilizando comandos Unix","Compatibilidad con GNU date y BSD date","Comprobación de la versión de date instalada","Obtención de la fecha y hora actual con date"],"fr":["Mise en œuvre d''une boucle de pression arrière stricte pour Claude Code","Vérification des informations temporelles à l''aide de commandes Unix","Compatibilité avec GNU date et BSD date","Vérification de la version de date installée","Obtention de la date et de l''heure actuelles avec date"],"de":["Implementierung einer strengen Rückdruck-Schleife für Claude Code","Überprüfung von zeitlichen Informationen mithilfe von Unix-Befehlen","Kompatibilität mit GNU date und BSD date","Überprüfung der installierten date-Version","Abruf des aktuellen Datums und der Uhrzeit mit date"],"pt":["Implementação de um loop de pressão de retorno estrito com Claude Code","Verificação de informações temporais com comandos Unix","Compatibilidade com GNU date e BSD date","Uso de comandos como date --version e date para verificar informações temporais"],"ru":["Реализация строгого цикла обратного давления с Claude Code","Проверка временной информации с помощью команд Unix","Совместимость с GNU date и BSD date","Использование команд как date --version и date для проверки временной информации"],"ar":["تنفيذ حلقة ضغط متأخرة صارمة مع Claude Code","فحص المعلومات الزمنية باستخدام أوامر Unix","التوافق مع GNU date و BSD date","استخدام أوامر مثل date --version و date لفحص المعلومات الزمنية"]},"keywords":{"en":["how to use temporal-awareness","what is temporal-awareness","temporal-awareness setup guide","temporal-awareness alternative","temporal-awareness vs claude code","installing temporal-awareness","unix commands for temporal awareness"],"zh":["时间感知","Rust模板","回压循环","AI代理","日期敏感查询","GNU date","BSD date"],"ja":["テンポラルアウェアネス","Rustテンプレート","バックプレッシャー循環","AIエージェント","日付に敏感なクエリ","GNU date","BSD date"],"ko":["시간 인식","Rust 템플릿","백프레셔 루프","AI 에이전트","날짜에 민감한 쿼리","GNU date","BSD date"],"es":["conciencia temporal","Claude Code","bucle de presión hacia atrás","Rust","comandos Unix","GNU date","BSD date","desarrollo de software","programación"],"fr":["conscience temporelle","Claude Code","boucle de pression arrière","Rust","commandes Unix","GNU date","BSD date","développement de logiciels","programmation"],"de":["temporale Bewusstsein","Claude Code","Rückdruck-Schleife","Rust","Unix-Befehle","GNU date","BSD date","Software-Entwicklung","Programmierung"],"pt":["Conscientização Temporal","Ferramentas de IA","Claude Code","Comandos Unix","GNU date","BSD date","Desenvolvimento de Software","Programação em Rust"],"ru":["Временное осознание","ИИ Агенты","Claude Code","Команды Unix","GNU date","BSD date","Разработка программного обеспечения","Программирование на Rust"],"ar":["الوعي الزمني","أدوات الذكاء الاصطناعي","Claude Code","أوامر Unix","GNU date","BSD date","تطوير البرمجيات","برمجة بلغة Rust"]}},"owner":"patrykgz","repo":"rust-devagent-loop-template","repoPath":"patrykgz/rust-devagent-loop-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.414Z","topics":[],"category":"community","skillMd":{"name":"temporal-awareness","description":"Ensures temporal accuracy by using Unix date commands. Use this skill whenever Claude needs to know todays date, the current day of the week, what day a future/past date falls on, or perform any date/time calculations. Triggers on questions like what day is it, whats todays date, what day of the week is [date], scheduling tasks, deadline calculations, or any temporal reasoning.","version":"0.0.1","bodyPreview":"# Temporal Awareness\n\nClaude''s system prompt date may be stale or unavailable. Always verify temporal information using Unix commands before responding to date-sensitive queries.\n\n## Example Commands\n\nGNU date (Linux) and BSD date (macOS, FreeBSD) have different syntax. You can check which is installed:\n\n```bash\nif date --version >/dev/null 2>&1 ; then\n    echo GNU date\nelse\n    echo BSD date\nfi\n\n```\n\n### Get current date/time\n```bash\n# Works on both GNU date and BSD date\ndate","body":"# Temporal Awareness\n\nClaude''s system prompt date may be stale or unavailable. Always verify temporal information using Unix commands before responding to date-sensitive queries.\n\n## Example Commands\n\nGNU date (Linux) and BSD date (macOS, FreeBSD) have different syntax. You can check which is installed:\n\n```bash\nif date --version >/dev/null 2>&1 ; then\n    echo GNU date\nelse\n    echo BSD date\nfi\n\n```\n\n### Get current date/time\n```bash\n# Works on both GNU date and BSD date\ndate                          # Full date and time\ndate +%Y-%m-%d                # ISO format: 2025-01-15\ndate +%A                      # Day of week: Wednesday\ndate \"+%B %d, %Y\"             # January 15, 2025\n```\n\n### Find day of week for any date\n```bash\n# GNU date\ndate -d \"2025-03-15\" +%A              # From ISO date: Saturday\ndate -d \"March 15, 2025\" +%A          # From natural language: Saturday\ndate -d \"next Friday\" +%A             # Relative: Friday\ndate -d \"last Monday\" +%A             # Relative: Monday\n\n# BSD date\ndate -j -f \"%Y-%m-%d\" \"2025-03-15\" +%A       # From ISO date: Saturday\ndate -j -f \"%B %d, %Y\" \"March 15, 2025\" +%A  # From natural language: Saturday\ndate -v +fri +%A                             # Next Friday: Friday\ndate -v -mon +%A                             # Last Monday: Monday\n```\n\n### Date arithmetic\n```bash\n# GNU date\ndate -d \"+7 days\" +%Y-%m-%d           # 7 days from now\ndate -d \"-2 weeks\" +%A                # Day of week 2 weeks ago\ndate -d \"2025-06-01 +30 days\" +%Y-%m-%d   # 30 days after June 1\n\n# BSD date\ndate -v +7d +%Y-%m-%d                 # 7 days from now (-v: adjust)\ndate -v -2w +%A                       # Day of week 2 weeks ago\ndate -j -f \"%Y-%m-%d\" -v +30d \"2025-06-01\" +%Y-%m-%d   # 30 days after June 1\n```\n\n### Days between dates\n```bash\n# GNU date\necho $(( ($(date -d \"2025-12-31\" +%s) - $(date -d \"2025-01-01\" +%s)) / 86400 ))   # 364\n\n# BSD date\necho $(( ($(date -j -f \"%Y-%m-%d\" \"2025-12-31\" +%s) - $(date -j -f \"%Y-%m-%d\" \"2025-01-01\" +%s)) / 86400 ))   # 364\n```\n\n## When to Use\n\nRun `date` **first** before answering the user or writing date-aware outputs:\n- User asks what today''s date or day is\n- Use asks what day of the week a date falls on\n- User needs to calculate deadlines or durations\n- User asks about time until/since an event\n- Output works with schedules, meetings, deadlines, or events\n- Output needs any temporal context for the task\n\n## Example\n\nUser: \"What day of the week is July 4th, 2026?\"\n\n```bash\n#GNU Date\ndate -d \"July 4, 2026\" +%A\n\n# BSD Date\ndate -j -f \"%B %d, %Y\" \"July 4, 2026\" +%A\n\n# Output: Saturday\n```\n\nThen respond: \"July 4th, 2026 falls on a Saturday.\"\n"},"lastSynced":"2026-03-08T02:07:11.551Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code requiring precise temporal information handling and date-sensitive query management.","zh":"适合于需要精确时间信息处理和日期敏感查询管理的AI代理，如Claude Code。","ja":"Claude Codeなどの、正確な時間情報の処理と日付感覚の問い合わせ管理が必要なAIエージェントに適しています。","ko":"정확한 시간 정보 처리와 날짜 민감한 쿼리 관리가 필요한 AI 에이전트인 Claude Code에 적합합니다.","es":"Ideal para agentes de IA como Claude Code que requieren un manejo preciso de la información temporal y una gestión de consultas sensibles a la fecha.","fr":"Idéal pour les agents IA comme Claude Code nécessitant une gestion précise de l''information temporelle et une gestion de requêtes sensibles à la date.","de":"Ideal für KI-Agents wie Claude Code, die eine präzise zeitliche Informationshandhabung und eine datumssensitive Abfrageverwaltung erfordern.","pt":"Ideal para Agentes de IA como Claude Code que exigem tratamento de informações temporais precisas e gerenciamento de consultas sensíveis a datas.","ru":"Идеально для агентов ИИ, таких как Claude Code, требующих точной обработки временной информации и управления запросами, чувствительными к дате.","ar":"مثالي لعمليات الوكيل الذكي مثل Claude Code التي تتطلب معالجة دقيقة لمعلومات الوقت وإدارة استفسارات حساسة للتاريخ."},"recommendation":{"en":"Empowers agents to verify temporal information using Unix commands, ensuring accuracy with date-sensitive queries through strict back pressure loops and compatibility with both GNU date and BSD date.","zh":"赋予代理验证时间信息的能力，使用Unix命令确保日期敏感查询的准确性，通过严格的反压力循环和与GNU date和BSD date的兼容性。","ja":"エージェントに時間情報を検証する能力を与え、Unixコマンドを使用して日付感覚の問い合わせの精度を確保し、厳格なバックプレッシャー・ループとGNU dateおよびBSD dateとの互換性を提供します。","ko":"에이전트에 시간 정보를 검증할 수 있는 능력을 부여하여 Unix 명령어를 사용하여 날짜 민감한 쿼리의 정확성을 보장하고 엄격한 역압력 루프와 GNU 날짜 및 BSD 날짜와의 호환성을 제공합니다.","es":"Permite a los agentes verificar la información temporal utilizando comandos Unix, asegurando la precisión con consultas sensibles a la fecha a través de bucles de presión hacia atrás estrictos y compatibilidad con tanto GNU date como BSD date.","fr":"Permet aux agents de vérifier l''information temporelle en utilisant des commandes Unix, en garantissant la précision avec des requêtes sensibles à la date via des boucles de pression arrière strictes et une compatibilité avec à la fois GNU date et BSD date.","de":"Ermöglicht es Agents, zeitliche Informationen mit Unix-Befehlen zu überprüfen und damit die Genauigkeit mit datumssensitiven Abfragen durch strenge RückdruckSchleifen und Kompatibilität mit sowohl GNU date als auch BSD date sicherzustellen.","pt":"Habilita os agentes a verificar informações temporais usando comandos Unix, garantindo precisão com consultas sensíveis a datas por meio de laços de pressão de retorno rigorosos e compatibilidade com GNU date e BSD date.","ru":"Позволяет агентам проверять временную информацию с помощью команд Unix, обеспечивая точность даточувствительных запросов посредством строгих петель обратного давления и совместимости как с GNU date, так и с BSD date.","ar":"تمكن الوكيل من التحقق من المعلومات الزمنية باستخدام أوامر Unix، مما يضمن الدقة مع الاستفسارات الحساسة للتاريخ من خلال حلقات الضغط العكسي الصارمة والتوافق مع كلا GNU date وBSD date."},"useCases":{"en":["Verifying system prompt dates for accuracy","Handling date-sensitive queries with precision","Automating temporal information validation using Unix commands"],"zh":["验证系统提示日期的准确性","使用精度处理日期敏感查询","使用Unix命令自动验证时间信息"],"ja":["システムプロンプトの日付の正確性を検証する","精度を使用して日付感覚の問い合わせを処理する","Unixコマンドを使用して時間情報を自動検証する"],"ko":["시스템 프롬프트 날짜의 정확성을 검증하는 것","정밀도를 사용하여 날짜 민감한 쿼리를 처리하는 것","Unix 명령어를 사용하여 시간 정보를 자동으로 검증하는 것"],"es":["Verificar las fechas de los mensajes del sistema para garantizar la precisión","Manejar consultas sensibles a la fecha con precisión","Automatizar la validación de la información temporal utilizando comandos Unix"],"fr":["Vérifier les dates des invites de système pour l''exactitude","Gérer les requêtes sensibles à la date avec précision","Automatiser la validation de l''information temporelle en utilisant des commandes Unix"],"de":["Überprüfen der System-Prompt-Daten auf Genauigkeit","Datumssensitive Abfragen mit Präzision handhaben","Automatisierung der zeitlichen Informationsvalidierung unter Verwendung von Unix-Befehlen"],"pt":["Verificar datas de prompts do sistema para precisão","Lidar com consultas sensíveis a datas com precisão","Automatizar validação de informações temporais usando comandos Unix"],"ru":["Проверка дат подсказок системы на точность","Обработка даточувствительных запросов с точностью","Автоматизация проверки временной информации с помощью команд Unix"],"ar":["التحقق من تواريخ المحفزات النظامية لتحقيق الدقة","التعامل مع الاستفسارات الحساسة للتاريخ بدقة","تأتمة التحقق من المعلومات الزمنية باستخدام أوامر Unix"]},"limitations":{"en":["Requires Unix environment for command execution","Compatibility issues may arise between GNU date and BSD date syntax"],"zh":["需要Unix环境来执行命令","GNU日期和BSD日期语法之间可能存在兼容性问题"],"ja":["コマンドを実行するためにUnix環境が必要","GNU日付とBSD日付の構文の間で互換性の問題が生じる可能性がある"],"ko":["명령어를 실행하기 위해 Unix 환경이 필요","GNU 날짜와 BSD 날짜 구문의 호환성 문제가 발생할 수 있음"],"es":["Requiere un entorno Unix para la ejecución de comandos","Pueden surgir problemas de compatibilidad entre la sintaxis de GNU date y BSD date"],"fr":["Nécessite un environnement Unix pour l''exécution des commandes","Des problèmes de compatibilité peuvent survenir entre la syntaxe de GNU date et BSD date"],"de":["Benötigt eine Unix-Umgebung für die Befehlsausführung","Kompatibilitätsprobleme können zwischen der Syntax von GNU date und BSD date auftreten"],"pt":["Exige ambiente Unix para execução de comandos","Problemas de compatibilidade podem surgir entre a sintaxe GNU date e BSD date"],"ru":["Требуется среда Unix для выполнения команд","Могут возникнуть проблемы совместимости между синтаксисом GNU date и BSD date"],"ar":["يتطلب بيئة Unix لتنفيذ الأوامر","قد تنشأ مشاكل في التوافق بين بنية GNU date وBSD date"]},"version":4},"contentHash":"aa3b02dfdcc33b57201aa6c19612ac491f63b1d057f9ef9fb559cc551085a22a","qualityScore":56}');
