INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('patrykgz/rust-devagent-loop-template/temporal-awareness', 'temporal-awareness', 'patrykgz', 'rust-devagent-loop-template', 'community', 'temporal-awareness patrykgz rust-devagent-loop-template community Temporal-awareness is a Rust template repo that implements a strict back pressure loop for Claude Code, helping developers verify temporal information. It benefits AI agent developers working with date-sensitive queries. 时间感知是AI代理的关键功能，确保其获取最新的时间信息。该Rust模板实现了严格的回压循环，用于Claude Code テンポラルアウェアネスはAIエージェントの重要な機能であり、最新の時間情報を取得することを保証します。このRustテンプレートリポジトリは、Claude Code用の厳密なバックプレッシャー循環を実装しています 시간 인식은 AI 에이전트의 핵심 기능으로, 최신 시간 정보를 얻는 것을 보장합니다. 이 Rust 템플릿은 Claude Code용 엄격한 백프레셔 루프를 구현합니다 Conciencia temporal para Claude Code mediante un bucle de presión hacia atrás estricto implementado en Rust Conscience temporelle pour Claude Code via une boucle de pression arrière stricte implementée en Rust Temporale Bewusstsein für Claude Code durch eine strenge Rückdruck-Schleife implementiert in Rust O temporal-awareness é uma habilidade que implementa um loop de pressão de retorno estrito para Claude Code, permitindo a verificação de informações temporais com comandos Unix. Временное осознание - это навык, который реализует строгий цикл обратного давления для Claude Code, позволяя проверять временную информацию с помощью команд Unix. الوعي الزمني هو مهارة تنفذ حلقة ضغط متأخرة صارمة ل Claude Code، مما يسمح بفحص المعلومات الزمنية باستخدام أوامر Unix. how to use temporal-awareness what is temporal-awareness temporal-awareness setup guide temporal-awareness alternative temporal-awareness vs claude code installing temporal-awareness unix commands for temporal awareness 时间感知 Rust模板 回压循环 AI代理 日期敏感查询 GNU date BSD date Implements a strict back pressure loop for Claude Code Verifies temporal information using Unix commands Supports GNU date and BSD date commands Checks for installed date command version Provides example commands for getting current date/time temporal-awareness is a technique for verifying temporal information using Unix commands, ensuring accuracy in date-sensitive queries');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LeeCuongg/stock-flow-qt-food/vercel-deploy', 'community', 'LeeCuongg', 'stock-flow-qt-food', 'LeeCuongg/stock-flow-qt-food', 'vercel-deploy', 0, 0, 56, '2026-03-08T01:57:15.545Z', '2026-03-08T02:11:19.888Z', '31a4a5b49db791207d3e23c68cb43bb4c5e68712db9ed1454cfa0d1ba33ce261', '{"id":"LeeCuongg/stock-flow-qt-food/vercel-deploy","name":"vercel-deploy","description":{"en":"The vercel-deploy skill deploys any project to Vercel instantly, auto-detecting frameworks from package.json. It benefits developers by providing a quick and easy deployment process.","zh":"Vercel 部署工具允许您即时部署任何项目，无需认证。它支持自动检测框架和上传部署。","ja":"Vercel デプロイツールは、認証不要でプロジェクトを即時デプロイできるようにします。自動フレームワーク検出とアップロードデプロイをサポートします。","ko":"Vercel 배포 도구는 인증 없이 즉시 프로젝트를 배포할 수 있습니다. 자동 프레임워크 감지 및 업로드 배포를 지원합니다.","es":"Vercel Deploy es una herramienta que permite deployar proyectos en Vercel de forma instantánea. Puedes deployar cualquier proyecto sin autenticación.","fr":"Vercel Deploy est un outil qui permet de déployer des projets sur Vercel en un éclair. Vous pouvez déployer n''importe quel projet sans authentification.","de":"Vercel Deploy ist ein Tool, mit dem Sie Projekte auf Vercel sofort bereitstellen können. Sie können jedes Projekt ohne Authentifizierung bereitstellen.","pt":"O Vercel Deploy é uma ferramenta que permite implantar projetos no Vercel de forma instantânea, sem necessidade de autenticação.","ru":"Vercel Deploy - это инструмент, который позволяет быстро развернуть проекты на Vercel, без необходимости аутентификации.","ar":"Vercel Deploy هو أداة تنشر المشاريع على Vercel بشكل فوري، دون الحاجة إلى المصادقة."},"seo":{"title":{"en":"Vercel-Deploy: Instant Deployment Setup Guide | AI Agent ...","zh":"Vercel 部署工具：即时部署项目","ja":"Vercel デプロイツール：プロジェクトの即時デプロイ","ko":"Vercel 배포 도구: 프로젝트 즉시 배포","es":"Guía de configuración de Vercel Deploy para desarrolladores","fr":"Configurer Vercel Deploy - Guide de déploiement instantané","de":"Vercel Deploy-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Vercel Deploy: Implantação Instan...","ru":"Настройка Vercel Deploy: Быстрая Загрузка Проектов с ИИ А...","ar":"دليل إعداد Vercel Deploy: نشر فور للمشاريع مع أدوات الذكا..."},"description":{"en":"Deploy projects to Vercel instantly with vercel-deploy. Learn how to use this AI agent skill to streamline your deployment process and get a live site preview","zh":"使用 Vercel 部署工具即时部署您的项目，无需认证。支持自动检测框架和上传部署。","ja":"Vercel デプロイツールを使用してプロジェクトを即時デプロイ。認証不要。自動フレームワーク検出とアップロードデプロイをサポート。","ko":"Vercel 배포 도구를 사용하여 프로젝트를 즉시 배포합니다. 인증이 필요하지 않으며 자동 프레임워크 감지 및 업로드 배포를 지원합니다.","es":"Aprende a deployar proyectos en Vercel de forma instantánea sin autenticación. Descubre cómo funciona y cómo usarlo.","fr":"Découvrez comment déployer vos projets sur Vercel en un éclair sans authentification. Comprenez son fonctionnement et son utilisation.","de":"Erfahren Sie, wie Sie Projekte auf Vercel sofort ohne Authentifizierung bereitstellen. Erfahren Sie, wie es funktioniert und wie es verwendet wird.","pt":"Aprenda a implantar projetos no Vercel de forma instantânea com o Vercel Deploy, sem necessidade de autenticação.","ru":"Узнайте, как быстро развернуть проекты на Vercel с помощью Vercel Deploy, без необходимости аутентификации.","ar":"تعرف على كيفية نشر المشاريع على Vercel بشكل فوري مع Vercel Deploy، دون الحاجة إلى المصادقة."},"definition":{"en":"vercel-deploy is a skill that packages projects into tarballs, excluding node_modules and .git, and uploads them to Vercel for instant deployment","zh":"Vercel 部署工具是一种 AI 工具，用于即时部署项目到 Vercel。","ja":"Vercel デプロイツールは、プロジェクトを Vercel に即時デプロイする AI エージェントです。","ko":"Vercel 배포 도구는 프로젝트를 Vercel에 즉시 배포하는 인공지능 도구입니다.","es":"Vercel Deploy es una herramienta de deploy que permite a los desarrolladores deployar proyectos en Vercel de forma instantánea","fr":"Vercel Deploy est un outil de déploiement qui permet aux développeurs de déployer des projets sur Vercel en un éclair","de":"Vercel Deploy ist ein Bereitstellungstool, das es Entwicklern ermöglicht, Projekte auf Vercel sofort bereitzustellen","pt":"O que é Vercel Deploy? É uma ferramenta de implantação instantânea de projetos no Vercel.","ru":"Что такое Vercel Deploy? Это инструмент быстрой загрузки проектов на Vercel.","ar":"ما هو Vercel Deploy؟ هو أداة لنشر المشاريع على Vercel بشكل فوري."},"features":{"en":["Packages project into a tarball, excluding node_modules and .git","Auto-detects framework from package.json","Uploads project to Vercel deployment service","Returns Preview URL and Claim URL for live site and account transfer","Supports deployment from a directory or .tgz file","Uses deploy.sh script for easy deployment"],"zh":["即时部署项目到 Vercel","自动检测框架从 package.json","上传部署服务","返回预览 URL 和认领 URL"],"ja":["プロジェクトを Vercel に即時デプロイ","package.json から自動フレームワーク検出","アップロードデプロイサービス","プレビュー URL とクレーム URL を返す"],"ko":["프로젝트를 Vercel에 즉시 배포","package.json에서 자동 프레임워크 감지","업로드 배포 서비스","미리 보기 URL 및 클레임 URL 반환"],"es":["Empaqueta tu proyecto en un tarball (excluyendo `node_modules` y `.git`)","Detección automática del framework desde `package.json`","Carga en el servicio de deploy","Devuelve la URL de vista previa (sitio en vivo) y la URL de reclamación (transferencia a tu cuenta de Vercel)","Soporte para deploy de proyectos desde la línea de comandos con `deploy.sh`","No requiere autenticación para deployar proyectos"],"fr":["Empaquette votre projet dans un tarball (en excluant `node_modules` et `.git`)","Détection automatique du framework depuis `package.json`","Téléchargement sur le service de déploiement","Renvoie l''URL de prévisualisation (site en direct) et l''URL de réclamation (transfert vers votre compte Vercel)","Prise en charge du déploiement de projets depuis la ligne de commande avec `deploy.sh`","N''a pas besoin d''authentification pour déployer des projets"],"de":["Packt Ihr Projekt in ein Tarball (ohne `node_modules` und `.git`)","Automatische Framework-Erkennung aus `package.json`","Hochladen auf den Bereitstellungsservice","Gibt die Vorschau-URL (Live-Site) und die Übernahmem-URL (Übertragung auf Ihr Vercel-Konto) zurück","Unterstützung für die Bereitstellung von Projekten von der Kommandozeile mit `deploy.sh`","Benötigt keine Authentifizierung für die Bereitstellung von Projekten"],"pt":["Empacota o projeto em um tarball, excluindo node_modules e .git","Detecta automaticamente o framework a partir do package.json","Faz o upload para o serviço de deploy","Retorna a URL de visualização e a URL de reclamação","Suporta deploy de projetos a partir de um diretório ou arquivo .tgz"],"ru":["Упаковывает проект в tarball, исключая node_modules и .git","Автоматически обнаруживает фреймворк из package.json","Загружает на сервис развертывания","Возвращает URL-превью и URL-заявки","Поддерживает развертывание проектов из директории или файла .tgz"],"ar":["يحزم المشروع في ملف tarball، واستبعاد node_modules و .git","يكتشف تلقائيًا الإطار من package.json","يقلع إلى خدمة النشر","يعيد URL المعاينة و URL المطالبة","يدعم نشر المشاريع من دليل أو ملف .tgz"]},"keywords":{"en":["how to use vercel-deploy","vercel-deploy alternative","vercel-deploy setup guide","what is vercel-deploy","vercel-deploy vs netlify","vercel-deploy install","vercel deployment service","package.json framework detection","tarball deployment"],"zh":["Vercel 部署工具","即时部署","自动检测框架","上传部署服务","AI 工具","Vercel 部署","项目部署"],"ja":["Vercel デプロイツール","即時デプロイ","自動フレームワーク検出","アップロードデプロイサービス","AI エージェント","Vercel デプロイ","プロジェクトデプロイ"],"ko":["Vercel 배포 도구","즉시 배포","자동 프레임워크 감지","업로드 배포 서비스","인공지능 도구","Vercel 배포","프로젝트 배포"],"es":["Vercel Deploy","deploy de proyectos","herramienta de deploy","desarrollo web","deploy en la nube","Herramientas de desarrollo","AI Agentes","desarrollo de aplicaciones"],"fr":["Vercel Deploy","déploiement de projets","outils de déploiement","développement web","déploiement sur le cloud","Outils de développement","Agents IA","développement d''applications"],"de":["Vercel Deploy","Bereitstellung von Projekten","Bereitstellungstools","Webentwicklung","Bereitstellung in der Cloud","Entwicklungstools","KI-Agents","Anwendungsentwicklung"],"pt":["Vercel Deploy","implantação instantânea","não requer autenticação","package.json","node_modules","tarball","deploy de projetos"],"ru":["Vercel Deploy","быстрая загрузка","не требует аутентификации","package.json","node_modules","tarball","развертывание проектов"],"ar":["Vercel Deploy","نشر فوري","لا يتطلب مصادقة","package.json","node_modules","tarball","نشر المشاريع"]}},"owner":"LeeCuongg","repo":"stock-flow-qt-food","repoPath":"LeeCuongg/stock-flow-qt-food","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.545Z","topics":[],"category":"community","skillMd":{"name":"vercel-deploy","description":"Deploy applications and websites to Vercel. Use this skill when the user requests deployment actions such as Deploy my app, Deploy this to production, Create a preview deployment, Deploy and give me the link, or Push this live. No authentication required - returns preview URL and claimable deployment link.","version":"1.0.0","bodyPreview":"# Vercel Deploy\n\nDeploy any project to Vercel instantly. No authentication required.\n\n## How It Works\n\n1. Packages your project into a tarball (excludes `node_modules` and `.git`)\n2. Auto-detects framework from `package.json`\n3. Uploads to deployment service\n4. Returns **Preview URL** (live site) and **Claim URL** (transfer to your Vercel account)\n\n## Usage\n\n```bash\nbash /mnt/skills/user/vercel-deploy/scripts/deploy.sh [path]\n```\n\n**Arguments:**\n- `path` - Directory to deploy, or a `.tgz` file (","body":"# Vercel Deploy\n\nDeploy any project to Vercel instantly. No authentication required.\n\n## How It Works\n\n1. Packages your project into a tarball (excludes `node_modules` and `.git`)\n2. Auto-detects framework from `package.json`\n3. Uploads to deployment service\n4. Returns **Preview URL** (live site) and **Claim URL** (transfer to your Vercel account)\n\n## Usage\n\n```bash\nbash /mnt/skills/user/vercel-deploy/scripts/deploy.sh [path]\n```\n\n**Arguments:**\n- `path` - Directory to deploy, or a `.tgz` file (defaults to current directory)\n\n**Examples:**\n\n```bash\n# Deploy current directory\nbash /mnt/skills/user/vercel-deploy/scripts/deploy.sh\n\n# Deploy specific project\nbash /mnt/skills/user/vercel-deploy/scripts/deploy.sh /path/to/project\n\n# Deploy existing tarball\nbash /mnt/skills/user/vercel-deploy/scripts/deploy.sh /path/to/project.tgz\n```\n\n## Output\n\n```\nPreparing deployment...\nDetected framework: nextjs\nCreating deployment package...\nDeploying...\n✓ Deployment successful!\n\nPreview URL: https://skill-deploy-abc123.vercel.app\nClaim URL:   https://vercel.com/claim-deployment?code=...\n```\n\nThe script also outputs JSON to stdout for programmatic use:\n\n```json\n{\n  \"previewUrl\": \"https://skill-deploy-abc123.vercel.app\",\n  \"claimUrl\": \"https://vercel.com/claim-deployment?code=...\",\n  \"deploymentId\": \"dpl_...\",\n  \"projectId\": \"prj_...\"\n}\n```\n\n## Framework Detection\n\nThe script auto-detects frameworks from `package.json`. Supported frameworks include:\n\n- **React**: Next.js, Gatsby, Create React App, Remix, React Router\n- **Vue**: Nuxt, Vitepress, Vuepress, Gridsome\n- **Svelte**: SvelteKit, Svelte, Sapper\n- **Other Frontend**: Astro, Solid Start, Angular, Ember, Preact, Docusaurus\n- **Backend**: Express, Hono, Fastify, NestJS, Elysia, h3, Nitro\n- **Build Tools**: Vite, Parcel\n- **And more**: Blitz, Hydrogen, RedwoodJS, Storybook, Sanity, etc.\n\nFor static HTML projects (no `package.json`), framework is set to `null`.\n\n## Static HTML Projects\n\nFor projects without a `package.json`:\n- If there''s a single `.html` file not named `index.html`, it gets renamed automatically\n- This ensures the page is served at the root URL (`/`)\n\n## Present Results to User\n\nAlways show both URLs:\n\n```\n✓ Deployment successful!\n\nPreview URL: https://skill-deploy-abc123.vercel.app\nClaim URL:   https://vercel.com/claim-deployment?code=...\n\nView your site at the Preview URL.\nTo transfer this deployment to your Vercel account, visit the Claim URL.\n```\n\n## Troubleshooting\n\n### Network Egress Error\n\nIf deployment fails due to network restrictions (common on claude.ai), tell the user:\n\n```\nDeployment failed due to network restrictions. To fix this:\n\n1. Go to https://claude.ai/settings/capabilities\n2. Add *.vercel.com to the allowed domains\n3. Try deploying again\n```\n"},"lastSynced":"2026-03-08T02:11:19.888Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing instant and automated deployment of web projects to Vercel.","zh":"非常适合需要立即自动部署 Web 项目到 Vercel 的全栈代理","ja":"Vercel に Web プロジェクトを即時自動デプロイする必要があるフルスタックエージェントに最適","ko":"웹 프로젝트를 Vercel에 즉시 자동 배포해야 하는 풀스택 에이전트에게 적합","es":"Perfecto para Agentes Full Stack que necesitan una implementación instantánea y automatizada de proyectos web en Vercel.","fr":"Parfait pour les agents Full Stack ayant besoin d''un déploiement instantané et automatisé de projets web sur Vercel.","de":"Perfekt für Full-Stack-Agents, die eine sofortige und automatisierte Bereitstellung von Webprojekten auf Vercel benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de implantação instantânea e automatizada de projetos web no Vercel.","ru":"Идеально для полнофункциональных агентов, которым требуется мгновенная и автоматическая развертка веб-проектов в Vercel.","ar":"مثالي لعميل الويب الكامل الذي يحتاج إلى نشر فوري وآلي لمشاريع الويب على Vercel."},"recommendation":{"en":"Empowers agents to instantly deploy projects to Vercel using auto-detected frameworks from package.json, supporting tarball uploads and returning live Preview URLs and Claim URLs for easy transfer to personal Vercel accounts.","zh":"使代理能够使用 package.json 中自动检测的框架立即将项目部署到 Vercel，支持 tarball 上传，并返回实时预览 URL 和转移到个人 Vercel 账户的 Claim URL","ja":"エージェントが package.json から自動検出されたフレームワークを使用してプロジェクトを Vercel に即時デプロイできるようにし、tarball のアップロードをサポートし、個人用 Vercel アカウントへの転送のために Claim URL とライブプレビュー URL を返す","ko":"에이전트가 package.json에서 자동으로 감지된 프레임워크를 사용하여 프로젝트를 Vercel에 즉시 배포할 수 있도록 하며, tarball 업로드를 지원하며, 개인용 Vercel 계정으로의 전송을 위해 Claim URL과 실시간 미리 보기 URL을 반환","es":"Habilita a los agentes a implementar proyectos en Vercel de forma instantánea, utilizando frameworks detectados automáticamente desde package.json, y admite cargas de archivos tarball, devolviendo direcciones URL de vista previa en vivo y direcciones URL de reclamación para una transferencia fácil a cuentas personales de Vercel.","fr":"Permet aux agents de déployer instantanément des projets sur Vercel en utilisant des frameworks auto-détectés à partir de package.json, en prenant en charge les téléchargements de fichiers tarball et en renvoyant des adresses URL de prévisualisation en direct et des adresses URL de réclamation pour un transfert facile vers des comptes Vercel personnels.","de":"Ermöglicht es Agents, Projekte auf Vercel sofort zu bereitstellen, indem sie auto-erkannte Frameworks aus package.json verwenden, und unterstützt Tarball-Uploads, während Live-Vorschau-URLs und Anspruch-URLs zurückgegeben werden, um einen einfachen Transfer zu persönlichen Vercel-Konten zu ermöglichen.","pt":"Habilita os agentes a implantar projetos instantaneamente no Vercel, usando estruturas auto-detectadas do package.json, suportando uploads de tarball e retornando URLs de Visualização ao Vivo e URLs de Reivindicação para transferência fácil para contas Vercel pessoais.","ru":"Позволяет агентам мгновенно развертывать проекты в Vercel, используя автоматически обнаруженные фреймворки из package.json, поддерживая загрузку tarball и возвращая живые URL-адреса просмотра и URL-адреса претензии для легкой передачи на личные учетные записи Vercel.","ar":"يمكن للوكلاء نشر المشاريع على الفور على Vercel باستخدام الإطارات التي تم الكشف عنها تلقائيًا من package.json ، ودعم تحميل tarball وإرجاع عناوين URL للعرض المباشر وعناوين URL للادعاء لنقل سهل إلى حسابات Vercel الشخصية."},"useCases":{"en":["Automating deployment of React, Next.js, and other framework-based projects to Vercel","Streamlining the development workflow by instantly deploying projects from local directories or .tgz files","Simplifying the transfer of deployed projects to personal Vercel accounts using Claim URLs"],"zh":["自动将使用 React、Next.js 和其他框架的项目部署到 Vercel","通过即时从本地目录或 .tgz 文件部署项目来简化开发工作流程","使用 Claim URL 简化已部署项目到个人 Vercel 账户的转移"],"ja":["React、Next.js、他のフレームワークを使用したプロジェクトを Vercel に自動デプロイする","ローカルディレクトリまたは .tgz ファイルからのプロジェクトの即時デプロイによって開発ワークフローを合理化する","Claim URL を使用してデプロイされたプロジェクトを個人用 Vercel アカウントに転送するのを簡素化する"],"ko":["React, Next.js 및 기타 프레임워크를 사용한 프로젝트를 Vercel에 자동으로 배포","로컬 디렉토리 또는 .tgz 파일에서 프로젝트를 즉시 배포하여 개발 워크플로우를 최적화","Claim URL을 사용하여 배포된 프로젝트를 개인용 Vercel 계정으로 전송하는 것을 단순화"],"es":["Automatizar la implementación de proyectos basados en React, Next.js y otros frameworks en Vercel","Optimizar el flujo de trabajo de desarrollo implementando proyectos de forma instantánea desde directorios locales o archivos .tgz","Simplificar la transferencia de proyectos implementados a cuentas personales de Vercel utilizando direcciones URL de reclamación"],"fr":["Automatiser le déploiement de projets basés sur React, Next.js et d''autres frameworks sur Vercel","Optimiser le flux de travail de développement en déployant des projets de manière instantanée à partir de répertoires locaux ou de fichiers .tgz","Simplifier le transfert de projets déployés vers des comptes Vercel personnels en utilisant des adresses URL de réclamation"],"de":["Automatisieren der Bereitstellung von auf React, Next.js und anderen Frameworks basierenden Projekten auf Vercel","Optimieren des Entwicklungsworkflows, indem Projekte sofort aus lokalen Verzeichnissen oder .tgz-Dateien bereitgestellt werden","Vereinfachen der Übertragung von bereitgestellten Projekten zu persönlichen Vercel-Konten unter Verwendung von Anspruch-URLs"],"pt":["Automatizar a implantação de projetos baseados em React, Next.js e outros frameworks para o Vercel","Otizar o fluxo de trabalho de desenvolvimento, implantando projetos instantaneamente de diretórios locais ou arquivos .tgz","Simplificar a transferência de projetos implantados para contas Vercel pessoais, usando URLs de Reivindicação"],"ru":["Автоматизировать развертку проектов на основе React, Next.js и других фреймворков в Vercel","Оптимизировать рабочий процесс разработки, развертывая проекты мгновенно из локальных каталогов или файлов .tgz","Упростить передачу развернутых проектов на личные учетные записи Vercel, используя URL-адреса претензии"],"ar":["تأتمتة نشر مشاريع تعتمد على React و Next.js وأطر عمل أخرى على Vercel","تبسيط تدفق العمل التطويري من خلال نشر المشاريع على الفور من المجلدات المحلية أو الملفات .tgz","تسهيل نقل المشاريع المنشورة إلى حسابات Vercel الشخصية باستخدام عناوين URL للادعاء"]},"limitations":{"en":["Requires package.json for framework auto-detection","Excludes node_modules and .git from deployment tarball","No authentication required, but Claim URL needed for transfer to personal Vercel account"],"zh":["需要 package.json 来进行框架自动检测","排除 node_modules 和 .git 在部署 tarball 中","无需认证，但需要 Claim URL 来转移到个人 Vercel 账户"],"ja":["フレームワークの自動検出には package.json が必要","デプロイ tarball から node_modules と .git を除外する","認証は不要だが、個人用 Vercel アカウントへの転送には Claim URL が必要"],"ko":["프레임워크 자동 감지를 위해 package.json이 필요","배포 tarball에서 node_modules 및 .git을 제외","인증은 필요 없지만 개인용 Vercel 계정으로의 전송을 위해 Claim URL이 필요"],"es":["Requiere package.json para la detección automática de frameworks","Excluye node_modules y .git del tarball de implementación","No se requiere autenticación, pero se requiere una dirección URL de reclamación para la transferencia a una cuenta personal de Vercel"],"fr":["Nécessite package.json pour la détection automatique des frameworks","Exclut node_modules et .git du fichier tarball de déploiement","N''a pas besoin d''authentification, mais nécessite une adresse URL de réclamation pour le transfert vers un compte Vercel personnel"],"de":["Benötigt package.json für die automatische Erkennung von Frameworks","Schließt node_modules und .git aus der Bereitstellungs-Tarball aus","Benötigt keine Authentifizierung, aber benötigt eine Anspruch-URL für den Transfer zu einem persönlichen Vercel-Konto"],"pt":["Exige package.json para detecção automática de estruturas","Exclui node_modules e .git do tarball de implantação","Nenhuma autenticação necessária, mas URL de Reivindicação necessária para transferência para conta Vercel pessoal"],"ru":["Требуется package.json для автоматического обнаружения фреймворков","Исключает node_modules и .git из файла развертки tarball","Не требуется аутентификация, но необходим URL-адрес претензии для передачи на личный учетной записи Vercel"],"ar":["يتطلب package.json للكشف التلقائي عن الإطارات","استبعاد node_modules و .git من ملف tarball للنشر","لا تطلب مصادقة، ولكن يتطلب عنوان URL للادعاء لنقل إلى حساب Vercel الشخصي"]},"version":4},"contentHash":"31a4a5b49db791207d3e23c68cb43bb4c5e68712db9ed1454cfa0d1ba33ce261","qualityScore":56}');
