INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AJB-ajb/MeshIt/architecture-review', 'architecture-review', 'AJB-ajb', 'MeshIt', 'community', 'architecture-review AJB-ajb MeshIt community The architecture-review skill performs a codebase health check for Mesh, detecting issues in Next.js, Supabase, and SWR. It benefits developers by identifying duplicated code, anti-patterns, complexity, and inconsistencies. 架构审查是一种代码库健康检查工具，用于检测Next.js和Supabase项目中的重复代码、反模式和复杂性 アーキテクチャレビューは、Next.jsとSupabaseのプロジェクトで重複コード、反パターン、複雑性を検出するコードベースのヘルスチェックツール 아키텍처 리뷰는 Next.js와 Supabase 프로젝트에서 중복 코드, 반 패턴 및 복잡성을 감지하는 코드베이스 헬스 체크 도구 La revisión de arquitectura es una herramienta de código abierto que realiza un análisis de salud del código para Mesh, detectando problemas como código duplicado y anti-patrones L''examen d''architecture est un outil open source qui effectue une analyse de santé du code pour Mesh, détectant des problèmes tels que le code dupliqué et les anti-modèles Die Architekturprüfung ist ein Open-Source-Tool, das eine Code-Health-Check für Mesh durchführt, Probleme wie duplizierten Code und Anti-Muster erkennend O architecture-review é uma ferramenta de análise de arquitetura que detecta código duplicado, anti-padrões e complexidade na pilha Next.js + Supabase + SWR ИИ Агент architecture-review - это инструмент анализа архитектуры, который обнаруживает дублированный код, анти-шаблоны и сложность в стеке Next.js + Supabase + SWR عامل إيه إيه architecture-review هو أداة لمراجعة الهندسة المعمارية التي تكتشف الكود المكرر و أنماط анти والتعقيد في مجموعة Next.js + Supabase + SWR how to use architecture-review what is architecture-review architecture-review alternative architecture-review vs code analysis tools architecture-review install architecture-review setup guide next.js code optimization supabase database analysis swr application debugging 架构审查 Next.js优化 Supabase优化 代码库健康检查 重复代码检测 反模式识别 SWR栈代码检查 AI工具 代码审查 Detects duplicated code in Next.js projects Identifies anti-patterns in Supabase databases Analyzes complexity in SWR-based applications Scans for inconsistencies across the Next.js + Supabase + SWR stack Provides a checklist and categories for code review Utilizes rules-based scanning for individual files Architecture-review is a project-focused matching app that detects duplicated code, anti-patterns, complexity, and inconsistencies across the Next.js + Supabase + SWR stack.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aget-framework/template-advisor-aget/aget-check-evolution', 'community', 'aget-framework', 'template-advisor-aget', 'aget-framework/template-advisor-aget', 'aget-check-evolution', 0, 0, 56, '2026-03-08T01:57:15.616Z', '2026-03-08T02:13:22.752Z', '62225f596bebfa5e6aa19d9cc2fdf738236aaf21bb057aece1bfe1c5b54b6cb3', '{"id":"aget-framework/template-advisor-aget/aget-check-evolution","name":"aget-check-evolution","description":{"en":"aget-check-evolution monitors the health of the .aget/evolution/ directory, providing self-diagnostic capabilities for AI agents to assess file counts, types, and disk usage without supervisor intervention.","zh":"aget-check-evolution 是一个 AI 代理自诊断工具，用于监控 .aget/evolution 目录的健康，包括文件计数、类型、命名约定和磁盘使用情况","ja":"aget-check-evolution は、.aget/evolution ディレクトリのヘルスを監視する AI エージェントの自己診断ツールです。ファイル数、タイプ、命名規則、ディスク使用状況などをチェックします","ko":"aget-check-evolution은 .aget/evolution 디렉토리의 건강을 모니터링하는 AI 에이전트 자기 진단 도구입니다. 파일 수, 유형, 명명 규칙, 디스크 사용량 등을 확인합니다","es":"aget-check-evolution es una plantilla de asesoramiento que monitorea la salud del directorio .aget/evolution. Proporciona capacidades de autodiagnóstico para Agentes de IA.","fr":"aget-check-evolution est un modèle de conseil qui surveille la santé du répertoire .aget/evolution. Il offre des capacités d''auto-diagnostic pour les Outils d''IA.","de":"aget-check-evolution ist eine Beratungsvorlage, die den Zustand des Verzeichnisses .aget/evolution überwacht. Sie bietet Selbst-diagnosefähigkeiten für KI-Agents.","pt":"O aget-check-evolution é uma ferramenta de monitoramento de saúde de diretório que verifica a integridade do diretório .aget/evolution","ru":"Aget-check-evolution - это инструмент для проверки здоровья каталога, который проверяет целостность каталога .aget/evolution","ar":"aget-check-evolution هو أداة مراقبة صحة الدليل التي تتحقق من سلامة الدليل .aget/evolution"},"seo":{"title":{"en":"aget-check-evolution: Health Monitoring for AI Agents | A...","zh":"aget-check-evolution 设置指南：AI 代理自诊断","ja":"aget-check-evolution セットアップガイド：AI エージェントの自己診断","ko":"aget-check-evolution 설정 가이드: AI 에이전트 자기 진단","es":"Guía de configuración de aget-check-evolution para Agente...","fr":"Guide de mise en place de aget-check-evolution pour les O...","de":"Einrichtungsleitfaden für aget-check-evolution für KI-Agents","pt":"Guia de Configuração do aget-check-evolution: Monitoramen...","ru":"Настройка aget-check-evolution: Проверка Здоровья Каталога","ar":"دليل إعداد aget-check-evolution: مراقبة صحة الدليل"},"description":{"en":"Discover how aget-check-evolution helps AI agents self-diagnose evolution directory health issues - learn how to invoke file inventory checks and more today!","zh":"了解如何使用 aget-check-evolution 实现 AI 代理自诊断，监控 .aget/evolution 目录健康","ja":"aget-check-evolution を使用して AI エージェントの自己診断を実現し、.aget/evolution ディレクトリのヘルスを監視する方法について","ko":"aget-check-evolution을 사용하여 AI 에이전트 자기 진단을 구현하고 .aget/evolution 디렉토리 건강을 모니터링하는 방법에 대해 알아보세요","es":"Aprende a monitorear la salud del directorio .aget/evolution con aget-check-evolution y mejora la capacidad de diagnóstico de tus Agentes de IA","fr":"Découvrez comment surveiller la santé du répertoire .aget/evolution avec aget-check-evolution et améliorez la capacité de diagnostic de vos Outils d''IA","de":"Erfahren Sie, wie Sie den Zustand des Verzeichnisses .aget/evolution mit aget-check-evolution überwachen und die Selbstdiagnosefähigkeit Ihrer KI-Agents verb...","pt":"Aprenda a configurar o aget-check-evolution para monitorar a saúde do diretório .aget/evolution e garantir o funcionamento correto dos agentes AGET","ru":"Узнайте, как настроить aget-check-evolution для проверки здоровья каталога .aget/evolution и обеспечить правильную работу агентов AGET","ar":"تعلم كيفية إعداد aget-check-evolution لمراقبة صحة الدليل .aget/evolution وضمان عمل وكلاء AGET بشكل صحيح"},"definition":{"en":"aget-check-evolution is a read-only advisory agent that extends the Worker archetype, enabling AI agents to perform health checks on their evolution directories.","zh":"aget-check-evolution 是一个用于监控 .aget/evolution 目录健康的 AI 代理自诊断工具","ja":"aget-check-evolution は、.aget/evolution ディレクトリのヘルスを監視する AI エージェントの自己診断ツールです","ko":"aget-check-evolution은 .aget/evolution 디렉토리의 건강을 모니터링하는 AI 에이전트 자기 진단 도구입니다","es":"aget-check-evolution es una herramienta de diagnóstico para Agentes de IA que verifica la salud del directorio .aget/evolution","fr":"aget-check-evolution est un outil de diagnostic pour les Outils d''IA qui vérifie la santé du répertoire .aget/evolution","de":"aget-check-evolution ist ein Diagnosewerkzeug für KI-Agents, das den Zustand des Verzeichnisses .aget/evolution überprüft","pt":"O que é aget-check-evolution? É uma ferramenta de monitoramento de saúde de diretório para agentes AGET","ru":"Что такое aget-check-evolution? Это инструмент для проверки здоровья каталога для агентов AGET","ar":"ما هو aget-check-evolution؟ هو أداة مراقبة صحة الدليل لوكلاء AGET"},"features":{"en":["Performs file inventory checks using find and wc commands","Counts total files and files by extension (e.g., .md) in the .aget/evolution directory","Monitors disk usage to prevent storage issues","Provides self-diagnostic capabilities for AI agents","Extends the Worker archetype for read-only advisory agents"],"zh":["文件计数和类型检查","命名约定检查","磁盘使用情况监控","CLI 执行","支持多种文件扩展名"],"ja":["ファイル数とタイプのチェック","命名規則のチェック","ディスク使用状況の監視","CLI 実行","複数のファイル拡張子をサポート"],"ko":["파일 수와 유형 확인","명명 규칙 확인","디스크 사용량 모니터링","CLI 실행","여러 파일 확장자 지원"],"es":["Monitoreo de la salud del directorio .aget/evolution","Verificación de archivos y tipos de archivos","Comprobación de convenciones de nomenclatura","Análisis de uso de disco","Capacidades de autodiagnóstico para Agentes de IA"],"fr":["Surveillance de la santé du répertoire .aget/evolution","Vérification des fichiers et des types de fichiers","Vérification des conventions de nommage","Analyse de l''utilisation du disque","Capacités d''auto-diagnostic pour les Outils d''IA"],"de":["Überwachung des Zustands des Verzeichnisses .aget/evolution","Überprüfung von Dateien und Dateitypen","Überprüfung von Namenskonventionen","Analyse der Festplattennutzung","Selbst-diagnosefähigkeiten für KI-Agents"],"pt":["Verificação de contagem de arquivos","Verificação de tipos de arquivos","Verificação de convenções de nomenclatura","Verificação de uso de disco"],"ru":["Проверка количества файлов","Проверка типов файлов","Проверка соглашений об именовании","Проверка использования диска"],"ar":["التحقق من عدد الملفات","التحقق من أنواع الملفات","التحقق من اتفاقيات التسمية","التحقق من استخدام القرص"]},"keywords":{"en":["how to use aget-check-evolution","aget-check-evolution setup guide","what is aget-check-evolution","aget-check-evolution vs Worker archetype","aget-check-evolution alternative","aget-check-evolution install","AI agent health monitoring","evolution directory management","self-diagnostic AI agents"],"zh":["AI 代理自诊断","aget-check-evolution","AI 工具","监控 .aget/evolution 目录","文件计数","磁盘使用情况","CLI 执行","AI 代理设置","AI 代理最佳实践"],"ja":["AI エージェントの自己診断","aget-check-evolution","AI ツール",".aget/evolution ディレクトリの監視","ファイル数のチェック","ディスク使用状況の監視","CLI 実行","AI エージェントの設定","AI エージェントのベストプラクティス"],"ko":["AI 에이전트 자기 진단","aget-check-evolution","AI 도구",".aget/evolution 디렉토리 모니터링","파일 수 확인","디스크 사용량 모니터링","CLI 실행","AI 에이전트 설정","AI 에이전트 최적화"],"es":["aget-check-evolution","Agentes de IA","Herramientas de diagnóstico","Monitoreo de directorios","Autodiagnóstico","Convenciones de nomenclatura","Uso de disco"],"fr":["aget-check-evolution","Outils d''IA","Outils de diagnostic","Surveillance de répertoires","Auto-diagnostic","Conventions de nommage","Utilisation du disque"],"de":["aget-check-evolution","KI-Agents","Diagnosewerkzeuge","Überwachung von Verzeichnissen","Selbst-diagnose","Namenskonventionen","Festplattennutzung"],"pt":["aget-check-evolution","monitoramento de saúde de diretório","agentes AGET","ferramentas de monitoramento","CLI","bash"],"ru":["aget-check-evolution","проверка здоровья каталога","агенты AGET","инструменты для проверки","CLI","bash","ИИ Агенты"],"ar":["aget-check-evolution","مراقبة صحة الدليل","وكلاء AGET","أدوات المراقبة","CLI","bash","أدوات الذكاء الاصطناعي"]}},"owner":"aget-framework","repo":"template-advisor-aget","repoPath":"aget-framework/template-advisor-aget","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.616Z","topics":[],"category":"community","skillMd":{"name":"aget-check-evolution","description":"Monitor .aget/evolution/ directory health. Validates file counts, naming conventions, disk usage, and returns health status with alerts on anomalies.","version":"1.0.0","bodyPreview":"# /aget-check-evolution\n\nMonitor the health of the `.aget/evolution/` directory by checking file counts, types, naming conventions, and disk usage.\n\n## Purpose\n\nProvide self-diagnostic capability for AGET agents to assess their evolution directory health without supervisor intervention.\n\n## Execution\n\nWhen invoked, perform these checks:\n\n### 1. File Inventory\n\n```bash\n# Count total files\nfind .aget/evolution -type f | wc -l\n\n# Count by extension\nfind .aget/evolution -type f -name \"*.md\" | wc -l","body":"# /aget-check-evolution\n\nMonitor the health of the `.aget/evolution/` directory by checking file counts, types, naming conventions, and disk usage.\n\n## Purpose\n\nProvide self-diagnostic capability for AGET agents to assess their evolution directory health without supervisor intervention.\n\n## Execution\n\nWhen invoked, perform these checks:\n\n### 1. File Inventory\n\n```bash\n# Count total files\nfind .aget/evolution -type f | wc -l\n\n# Count by extension\nfind .aget/evolution -type f -name \"*.md\" | wc -l\nfind .aget/evolution -type f -name \"*.json\" | wc -l\nfind .aget/evolution -type f ! -name \"*.md\" ! -name \"*.json\" | wc -l\n```\n\n### 2. Naming Convention Check\n\nValid L-doc pattern: `L###_*.md` (e.g., `L588_skill_invocation_control_semantics.md`)\n\n```bash\n# Count valid L-doc names\nfind .aget/evolution -type f -name \"L[0-9][0-9][0-9]_*.md\" | wc -l\n\n# Find non-conforming files (excluding index.json)\nfind .aget/evolution -type f ! -name \"L[0-9][0-9][0-9]_*.md\" ! -name \"index.json\" ! -name \"README.md\"\n```\n\n### 3. Disk Usage\n\n```bash\ndu -sh .aget/evolution\n```\n\n### 4. Index Integrity\n\nCheck that `index.json` exists and is valid JSON:\n\n```bash\ntest -f .aget/evolution/index.json && jq empty .aget/evolution/index.json 2>/dev/null && echo \"valid\" || echo \"invalid\"\n```\n\n## Thresholds\n\n| Metric | OK | WARN | CRITICAL |\n|--------|-----|------|----------|\n| Total files | <500 | 500-750 | >750 |\n| Non-standard files | 0-10 | 11-50 | >50 |\n| Disk size | <10MB | 10-25MB | >25MB |\n| Index integrity | valid | - | invalid |\n\n**Note**: Thresholds inherited from supervisor defaults. Research AGET baseline (2026-02-08): 94 files, 800K - well within OK range.\n\n## Output Format\n\nReport the following:\n\n```\n=== /aget-check-evolution ===\n\nDirectory: .aget/evolution/\n\nFile Counts:\n  Total:     [count]\n  L-docs:    [count] (.md matching L###_*.md)\n  Index:     [1 if exists, 0 otherwise]\n  Other:     [count] (non-conforming)\n\nDisk Usage: [size]\n\nIndex Status: [valid/invalid/missing]\n\nNon-Conforming Files:\n  [list any files not matching expected patterns]\n\nHealth Status: [OK | WARN | CRITICAL]\nAlerts:\n  [list any threshold violations]\n```\n\n## Health Status Logic\n\n```\nIF index invalid OR index missing:\n  CRITICAL\nELIF total_files > 750 OR disk > 25MB OR non_standard > 50:\n  CRITICAL\nELIF total_files > 500 OR disk > 10MB OR non_standard > 10:\n  WARN\nELSE:\n  OK\n```\n\n## Constraints\n\n- **C1**: Read-only operation. Never modify files.\n- **C2**: Report ALL findings, even if status is OK.\n- **C3**: List non-conforming files by name for actionability.\n\n## Related Skills\n\n- `/aget-check-sessions` - Sessions directory health\n- `/aget-check-kb` - Knowledge base health\n- `/aget-record-lesson` - Capture findings as L-docs\n\n## Traceability\n\n| Link | Reference |\n|------|-----------|\n| POC | POC-017 |\n| Project | PROJECT_PLAN_AGET_UNIVERSAL_SKILLS.md |\n| Source | Fleet Skill Deployment Report (supervisor) |\n| Baseline | 94 files, 800K (2026-02-08) |\n\n---\n\n*aget-check-evolution v1.0.0*\n*Category: Monitoring*\n*POC-017 Phase 1*\n"},"lastSynced":"2026-03-08T02:13:22.752Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous AI Agents requiring self-diagnostic capabilities to monitor their evolution directory health without external intervention.","zh":"适合需要自我诊断能力的自主AI代理，用于监控其进化目录的健康状况，而无需外部干预。","ja":"外部介入なしで進化ディレクトリのヘルス状態を監視する自診断機能を必要とする自律AIエージェントに最適です。","ko":"외부 개입 없이 진화 디렉토리의 상태를 모니터링할 수 있는 자기 진단 기능이 필요한 자율 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA Autónomos que requieren capacidades de autodiagnóstico para monitorear la salud del directorio de evolución sin intervención externa.","fr":"Idéal pour les Agents d''IA Autonomes nécessitant des capacités d''auto-diagnostic pour surveiller la santé du répertoire d''évolution sans intervention externe.","de":"Ideal für autonome KI-Agents, die Selbstdiagnosefunktionen benötigen, um die Gesundheit des Evolution-Verzeichnisses ohne externe Eingriffe zu überwachen.","pt":"Ideal para Agentes de IA Autônoma que requerem capacidades de autodiagnóstico para monitorar a saúde do diretório de evolução sem intervenção externa.","ru":"Идеально для автономных агентов ИИ, требующих самовосстановительных возможностей для мониторинга здоровья директории эволюции без внешнего вмешательства.","ar":"مثالية للوكلاء الذكية المستقلة التي تتطلب القدرات على التشخيص الذاتي لتقييم صحة دليل التطور دون تدخل خارجي."},"recommendation":{"en":"Empowers agents to assess their evolution directory by checking file counts, types, naming conventions, and disk usage, providing insights into `.aget/evolution/` directory health using Unix commands like `find` and `wc`.","zh":"使代理能够通过检查文件数量、类型、命名约定和磁盘使用情况来评估其进化目录，使用 Unix 命令（如 `find` 和 `wc`）提供对 `.aget/evolution/` 目录健康状况的洞察。","ja":"エージェントがファイル数、タイプ、命名規則、およびディスク使用状況をチェックすることで進化ディレクトリを評価できるようにし、`find` および `wc` などの Unix コマンドを使用して `.aget/evolution/` ディレクトリのヘルス状態に関する洞察を提供します。","ko":"에이전트가 파일 수, 유형, 명명 규칙 및 디스크 사용량을 확인하여 진화 디렉토리를 평가할 수 있도록 하며, `find` 및 `wc`와 같은 Unix 명령을 사용하여 `.aget/evolution/` 디렉토리의 상태에 대한 통찰력을 제공합니다.","es":"Permite a los agentes evaluar su directorio de evolución comprobando los recuentos de archivos, los tipos, las convenciones de nomenclatura y el uso del disco, proporcionando información sobre la salud del directorio `.aget/evolution/` utilizando comandos de Unix como `find` y `wc`.","fr":"Permet aux agents d''évaluer leur répertoire d''évolution en vérifiant les comptes de fichiers, les types, les conventions de dénomination et l''utilisation du disque, fournissant des informations sur la santé du répertoire `.aget/evolution/` en utilisant des commandes Unix comme `find` et `wc`.","de":"Ermöglicht es den Agents, ihr Evolution-Verzeichnis zu bewerten, indem sie Dateizählungen, -typen, Benennungskonventionen und Festplattennutzung überprüfen, und gibt Einblicke in die Gesundheit des Verzeichnisses `.aget/evolution/` mithilfe von Unix-Befehlen wie `find` und `wc`.","pt":"Habilita os agentes a avaliar o diretório de evolução verificando a contagem de arquivos, tipos, convenções de nomenclatura e uso do disco, fornecendo informações sobre a saúde do diretório `.aget/evolution/` usando comandos Unix como `find` e `wc`.","ru":"Позволяет агентам оценить директорию эволюции, проверив количество файлов, типы, соглашения об именовании и использование диска, предоставляя информацию о здоровье директории `.aget/evolution/` с помощью команд Unix, таких как `find` и `wc`.","ar":"تمكّن الوكلاء من تقييم دليل التطور عن طريق التحقق من عدد الملفات وأنواعها وأساليب التسمية واستخدام القرص، وتوفير رؤى حول صحة دليل `.aget/evolution/` باستخدام أوامر Unix مثل `find` و `wc`."},"useCases":{"en":["Monitoring file inventory in the `.aget/evolution/` directory","Debugging disk usage issues within the evolution directory","Validating file naming conventions and types"],"zh":["在 `.aget/evolution/` 目录中监控文件库存","在进化目录内调试磁盘使用问题","验证文件命名约定和类型"],"ja":["`.aget/evolution/` ディレクトリ内のファイルインベントリの監視","進化ディレクトリ内のディスク使用問題のデバッグ","ファイル命名規則とタイプの検証"],"ko":["`.aget/evolution/` 디렉토리 내 파일 인벤토리 모니터링","진화 디렉토리 내 디스크 사용 문제 디버깅","파일 명명 규칙 및 유형 유효성 검사"],"es":["Supervisión del inventario de archivos en el directorio `.aget/evolution/`","Depuración de problemas de uso de disco dentro del directorio de evolución","Validación de convenciones de nomenclatura y tipos de archivos"],"fr":["Supervision de l''inventaire de fichiers dans le répertoire `.aget/evolution/`","Débogage des problèmes d''utilisation du disque à l''intérieur du répertoire d''évolution","Validation des conventions de dénomination et des types de fichiers"],"de":["Überwachung des Dateiinventars im Verzeichnis `.aget/evolution/`","Fehlerbehebung bei Festplatten-Nutzungsproblemen innerhalb des Evolution-Verzeichnisses","Validierung von Benennungskonventionen und Dateitypen"],"pt":["Monitorar o inventário de arquivos no diretório `.aget/evolution/`","Depurar problemas de uso do disco dentro do diretório de evolução","Validar convenções de nomenclatura e tipos de arquivos"],"ru":["Мониторинг инвентаря файлов в директории `.aget/evolution/`","Отладка проблем с использованием диска внутри директории эволюции","Проверка соглашений об именовании и типов файлов"],"ar":["مراقبة جرد الملفات في دليل `.aget/evolution/`","تصحيح مشاكل استخدام القرص داخل دليل التطور","تحقق من أساليب التسمية وأنواع الملفات"]},"limitations":{"en":["Requires filesystem access to the `.aget/evolution/` directory","Limited to monitoring specific directory and file attributes"],"zh":[".aget/evolution/ 目录的文件系统访问权限要求","仅限监控特定目录和文件属性"],"ja":[".aget/evolution/ ディレクトリへのファイルシステムアクセスの必要性","特定のディレクトリとファイル属性の監視のみ"],"ko":[".aget/evolution/ 디렉토리에 대한 파일 시스템 액세스 권한 요구","특정 디렉토리 및 파일 속성의 모니터링만 가능"],"es":["Requiere acceso al sistema de archivos del directorio `.aget/evolution/`","Limitado a la supervisión de atributos de directorios y archivos específicos"],"fr":["Nécessite un accès au système de fichiers du répertoire `.aget/evolution/`","Limité à la surveillance d''attributs de répertoires et de fichiers spécifiques"],"de":["Benötigt Zugriff auf das Dateisystem des Verzeichnisses `.aget/evolution/`","Begrenzt auf die Überwachung spezifischer Verzeichnis- und Dateiattribute"],"pt":["Requer acesso ao sistema de arquivos do diretório `.aget/evolution/`","Limitado ao monitoramento de atributos de diretório e arquivo específicos"],"ru":["Требует доступа к файловой системе директории `.aget/evolution/`","Ограничен мониторингом определенных атрибутов директории и файла"],"ar":["يتطلب الوصول إلى نظام الملفات لدليل `.aget/evolution/`","محدود بمراقبة سمات دليل وملف معينة"]},"version":4},"contentHash":"62225f596bebfa5e6aa19d9cc2fdf738236aaf21bb057aece1bfe1c5b54b6cb3","qualityScore":56}');
