INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aget-framework/template-advisor-aget/aget-check-evolution', 'aget-check-evolution', 'aget-framework', 'template-advisor-aget', 'community', 'aget-check-evolution aget-framework template-advisor-aget community aget-check-evolution monitors the health of the .aget/evolution/ directory, providing self-diagnostic capabilities for AI agents to assess file counts, types, and disk usage without supervisor intervention. aget-check-evolution 是一个 AI 代理自诊断工具，用于监控 .aget/evolution 目录的健康，包括文件计数、类型、命名约定和磁盘使用情况 aget-check-evolution は、.aget/evolution ディレクトリのヘルスを監視する AI エージェントの自己診断ツールです。ファイル数、タイプ、命名規則、ディスク使用状況などをチェックします aget-check-evolution은 .aget/evolution 디렉토리의 건강을 모니터링하는 AI 에이전트 자기 진단 도구입니다. 파일 수, 유형, 명명 규칙, 디스크 사용량 등을 확인합니다 aget-check-evolution es una plantilla de asesoramiento que monitorea la salud del directorio .aget/evolution. Proporciona capacidades de autodiagnóstico para Agentes de IA. aget-check-evolution est un modèle de conseil qui surveille la santé du répertoire .aget/evolution. Il offre des capacités d''auto-diagnostic pour les Outils d''IA. aget-check-evolution ist eine Beratungsvorlage, die den Zustand des Verzeichnisses .aget/evolution überwacht. Sie bietet Selbst-diagnosefähigkeiten für KI-Agents. O aget-check-evolution é uma ferramenta de monitoramento de saúde de diretório que verifica a integridade do diretório .aget/evolution Aget-check-evolution - это инструмент для проверки здоровья каталога, который проверяет целостность каталога .aget/evolution aget-check-evolution هو أداة مراقبة صحة الدليل التي تتحقق من سلامة الدليل .aget/evolution how to use aget-check-evolution aget-check-evolution setup guide what is aget-check-evolution aget-check-evolution vs Worker archetype aget-check-evolution alternative aget-check-evolution install AI agent health monitoring evolution directory management self-diagnostic AI agents AI 代理自诊断 aget-check-evolution AI 工具 监控 .aget/evolution 目录 文件计数 磁盘使用情况 CLI 执行 AI 代理设置 AI 代理最佳实践 Performs file inventory checks using find and wc commands Counts total files and files by extension (e.g., .md) in the .aget/evolution directory Monitors disk usage to prevent storage issues Provides self-diagnostic capabilities for AI agents Extends the Worker archetype for read-only advisory agents aget-check-evolution is a read-only advisory agent that extends the Worker archetype, enabling AI agents to perform health checks on their evolution directories.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MatLumber/Polybot/ddd-tactical-patterns', 'community', 'MatLumber', 'Polybot', 'MatLumber/Polybot', 'ddd-tactical-patterns', 0, 0, 56, '2026-03-07T23:51:16Z', '2026-03-08T02:14:23.144Z', '87c9fbb689db32ca34cca75a2401120e9dd3254c3649e3c0e5b2db5131acab12', '{"id":"MatLumber/Polybot/ddd-tactical-patterns","name":"ddd-tactical-patterns","description":{"en":"The ddd-tactical-patterns skill helps developers translate domain rules into code structures and design aggregate boundaries. It benefits developers working with domain-driven design.","zh":"DDD战术模式是一种将域规则翻译为代码结构的方法，用于设计聚合边界和不变量。","ja":"DDD戦術パターンは、ドメインルールをコード構造に翻訳する方法であり、集約境界と不変量の設計に使用されます。","ko":"DDD 전술 패턴은 도메인 규칙을 코드 구조로 번역하는 방법으로, 집계 경계와 불변량의 설계에 사용됩니다.","es":"Los patrones tácticos DDD ayudan a traducir reglas de dominio en estructuras de código y a diseñar límites de agregados y invariantes","fr":"Les modèles tactiques DDD aident à traduire les règles de domaine en structures de code et à concevoir les limites d''agrégats et les invariants","de":"Die taktischen DDD-Muster helfen, Domänenregeln in Code-Strukturen zu übersetzen und Aggregate-Grenzen und Invarianten zu entwerfen","pt":"Os Padrões Táticos DDD são usados para traduzir regras de domínio em estruturas de código, projetar limites de agregados e invariantes. Saiba como usá-los para refatorar modelos anêmicos em objetos de domínio ricos em comportamento","ru":"DDD Тактические Шаблоны используются для перевода правил домена в кодовые структуры, проектирования границ агрегатов и инвариантов. Узнайте, как использовать их для рефакторинга аномных моделей в поведенчески богатые доменные объекты","ar":"تستخدم الأنماط التكتيكية DDD لترجمة قواعد النطاق إلى هياكل رمز، تصميم حدود المجاميع والثوابت. تعلم كيفية استخدامها لتحويل النماذج الورقة إلى كائنات نطاق غنية السلوك"},"seo":{"title":{"en":"ddd-tactical-patterns: Domain Modeling Best Practices | A...","zh":"DDD战术模式设置指南","ja":"DDD戦術パターンのベストプラクティス","ko":"DDD 전술 패턴 구현 가이드","es":"Patrones Tácticos DDD: Guía de Implementación para Desarr...","fr":"Modèles Tactiques DDD: Meilleures Pratiques pour les Déve...","de":"DDD-Taktische Muster: Einrichtungsleitfaden für Entwickler","pt":"Padrões Táticos DDD: Guia de Configuração","ru":"ИИ Агенты: DDD Тактические Шаблоны - Руководство по Настр...","ar":"وكلاء الذكاء الاصطناعي: أنماط تكتيكية DDD - دليل الإعداد"},"description":{"en":"Master domain-driven design with ddd-tactical-patterns. Learn how to translate domain rules into code structures and design aggregate boundaries. Get started...","zh":"了解DDD战术模式的实现，包括翻译域规则、设计聚合边界和不变量，AIエージェント","ja":"DDD戦術パターンの実装方法を学び、ドメインルールの翻訳、集約境界の設計など、AIエージェント","ko":"DDD 전술 패턴의 구현 방법을 배우고, 도메인 규칙의 번역, 집계 경계의 설계 등, AI Tools","es":"Aprende a aplicar patrones tácticos DDD para mejorar la estructura de tu código y refactorizar modelos anémicos en objetos de dominio ricos en comportamiento","fr":"Découvrez comment appliquer les modèles tactiques DDD pour améliorer la structure de votre code et refactoriser les modèles anémiques en objets de domaine ri...","de":"Erfahren Sie, wie Sie taktische DDD-Muster anwenden, um die Code-Struktur zu verbessern und anämische Modelle in verhaltensreiche Domänen-Objekte zu refactor...","pt":"Aprenda a traduzir regras de domínio em estruturas de código com os Padrões Táticos DDD. Descubra como projetar limites de agregados e invariantes","ru":"Изучите, как переводить правила домена в кодовые структуры с помощью DDD Тактических Шаблонов. Узнайте, как проектировать границы агрегатов и инварианты","ar":"تعلم كيفية ترجمة قواعد النطاق إلى هياكل رمز باستخدام الأنماط التكتيكية DDD. اكتشف كيفية تصميم حدود المجاميع والثوابت"},"definition":{"en":"ddd-tactical-patterns is a skill for implementing domain-driven design tactical patterns, including translating domain rules into code and designing aggregate boundaries.","zh":"DDD战术模式是一种软件设计方法，用于将域规则翻译为代码结构。","ja":"DDD戦術パターンは、ドメインルールをコード構造に翻訳するソフトウェア設計方法です。","ko":"DDD 전술 패턴은 도메인 규칙을 코드 구조로 번역하는 소프트웨어 설계 방법입니다.","es":"Los patrones tácticos DDD son un conjunto de técnicas para traducir reglas de dominio en estructuras de código","fr":"Les modèles tactiques DDD sont un ensemble de techniques pour traduire les règles de domaine en structures de code","de":"Die taktischen DDD-Muster sind eine Sammlung von Techniken, um Domänenregeln in Code-Strukturen zu übersetzen","pt":"Padrões Táticos DDD são técnicas de desenvolvimento de software que ajudam a traduzir regras de domínio em estruturas de código","ru":"DDD Тактические Шаблоны - это техники разработки программного обеспечения, которые помогают переводить правила домена в кодовые структуры","ar":"الأنماط التكتيكية DDD هي تقنيات لتطوير البرمجيات التي تساعد في ترجمة قواعد النطاق إلى هياكل رمز"},"features":{"en":["Translates domain rules into code structures","Designs aggregate boundaries and invariants","Refactors anemic models into behavior-rich domain objects","Defines repository contracts and domain event boundaries","Identifies invariants first and designs accordingly"],"zh":["翻译域规则为代码结构","设计聚合边界和不变量","重构贫血模型为行为丰富的域对象","定义存储库契约和域事件边界"],"ja":["ドメインルールをコード構造に翻訳","集約境界と不変量の設計","貧血モデルを挙動豊かなドメインオブジェクトにリファクタリング","リポジトリ契約とドメインイベント境界の定義"],"ko":["도메인 규칙을 코드 구조로 번역","집계 경계와 불변량의 설계","빈혈 모델을 행동豊かな 도메인 객체로 리팩토링","저장소 계약과 도메인 이벤트 경계의 정의"],"es":["Diseño de límites de agregados y invariantes","Refactorización de modelos anémicos en objetos de dominio ricos en comportamiento","Definición de contratos de repositorio y límites de eventos de dominio","Identificación de invariantes y diseño de estructuras de código","Aplicación de patrones tácticos DDD para mejorar la estructura de código"],"fr":["Conception de limites d''agrégats et d''invariants","Refactorisation de modèles anémiques en objets de domaine riches en comportement","Définition de contrats de référentiel et de limites d''événements de domaine","Identification d''invariants et conception de structures de code","Application de modèles tactiques DDD pour améliorer la structure de code"],"de":["Entwurf von Aggregate-Grenzen und Invarianten","Refactorierung von anämischen Modellen in verhaltensreiche Domänen-Objekte","Definition von Repository-Verträgen und Domänen-Ereignis-Grenzen","Identifizierung von Invarianten und Entwurf von Code-Strukturen","Anwendung von taktischen DDD-Mustern, um die Code-Struktur zu verbessern"],"pt":["Traduzir regras de domínio em estruturas de código","Projetar limites de agregados e invariantes","Refatorar modelos anêmicos em objetos de domínio ricos em comportamento","Definir contratos de repositório e limites de eventos de domínio","Identificar invariantes e projetar agregados"],"ru":["Переводить правила домена в кодовые структуры","Проектировать границы агрегатов и инварианты","Рефакторинг аномных моделей в поведенчески богатые доменные объекты","Определить контракты репозитория и границы доменных событий","Определить инварианты и проектировать агрегаты"],"ar":["ترجمة قواعد النطاق إلى هياكل رمز","تصميم حدود المجاميع والثوابت","تحويل النماذج الورقة إلى كائنات نطاق غنية السلوك","تحديد عقود المستودع وحدود أحداث النطاق","تحديد الثوابت وتصميم المجاميع"]},"keywords":{"en":["how to use ddd-tactical-patterns","ddd-tactical-patterns alternative","ddd-tactical-patterns setup guide","domain-driven design patterns","ddd-tactical-patterns vs domain-driven design","implementing ddd-tactical-patterns in software development"],"zh":["DDD战术模式","域规则翻译","聚合边界设计","不变量设计","AIエージェント","软件设计方法","代码结构设计"],"ja":["DDD戦術パターン","ドメインルール翻訳","集約境界設計","不変量設計","AIエージェント","ソフトウェア設計方法","コード構造設計"],"ko":["DDD 전술 패턴","도메인 규칙 번역","집계 경계 설계","불변량 설계","AI Tools","소프트웨어 설계 방법","코드 구조 설계"],"es":["patrones tácticos DDD","dominio rico en comportamiento","refactorización de modelos anémicos","diseño de agregados","invariantes en DDD","contratos de repositorio","límites de eventos de dominio","mejora de la estructura de código"],"fr":["modèles tactiques DDD","domaine riche en comportement","refactorisation de modèles anémiques","conception d''agrégats","invariants en DDD","contrats de référentiel","limites d''événements de domaine","amélioration de la structure de code"],"de":["taktische DDD-Muster","verhaltensreiches Domänen-Modell","Refactorierung von anämischen Modellen","Entwurf von Aggregate-Grenzen","Invarianten in DDD","Repository-Verträge","Domänen-Ereignis-Grenzen","Verbesserung der Code-Struktur"],"pt":["Padrões Táticos DDD","Desenvolvimento de software","Regras de domínio","Estruturas de código","Agregados","Invariantes","Refatoração","Modelos anêmicos","Objetos de domínio ricos em comportamento"],"ru":["ИИ Агенты","DDD Тактические Шаблоны","Разработка программного обеспечения","Правила домена","Кодовые структуры","Агрегаты","Инварианты","Рефакторинг","Аномные модели","Поведенчески богатые доменные объекты"],"ar":["وكلاء الذكاء الاصطناعي","أنماط تكتيكية DDD","تطوير البرمجيات","قواعد النطاق","هياكل رمز","المجاميع","الثوابت","تحويل","نماذج ورقة","كائنات نطاق غنية السلوك"]}},"owner":"MatLumber","repo":"Polybot","repoPath":"MatLumber/Polybot","stars":0,"forks":0,"updatedAt":"2026-03-07T23:51:16Z","topics":[],"category":"community","skillMd":{"name":"ddd-tactical-patterns","description":"Apply DDD tactical patterns in code using entities, value objects, aggregates, repositories, and domain events with explicit invariants.","tags":["ddd","tactical","aggregates","value-objects","domain-events"],"bodyPreview":"# DDD Tactical Patterns\n\n## Use this skill when\n\n- Translating domain rules into code structures.\n- Designing aggregate boundaries and invariants.\n- Refactoring an anemic model into behavior-rich domain objects.\n- Defining repository contracts and domain event boundaries.\n\n## Do not use this skill when\n\n- You are still defining strategic boundaries.\n- The task is only API documentation or UI layout.\n- Full DDD complexity is not justified.\n\n## Instructions\n\n1. Identify invariants first and design","body":"# DDD Tactical Patterns\n\n## Use this skill when\n\n- Translating domain rules into code structures.\n- Designing aggregate boundaries and invariants.\n- Refactoring an anemic model into behavior-rich domain objects.\n- Defining repository contracts and domain event boundaries.\n\n## Do not use this skill when\n\n- You are still defining strategic boundaries.\n- The task is only API documentation or UI layout.\n- Full DDD complexity is not justified.\n\n## Instructions\n\n1. Identify invariants first and design aggregates around them.\n2. Model immutable value objects for validated concepts.\n3. Keep domain behavior in domain objects, not controllers.\n4. Emit domain events for meaningful state transitions.\n5. Keep repositories at aggregate root boundaries.\n\nIf detailed checklists are needed, open `references/tactical-checklist.md`.\n\n## Example\n\n```typescript\nclass Order {\n  private status: \"draft\" | \"submitted\" = \"draft\";\n\n  submit(itemsCount: number): void {\n    if (itemsCount === 0) throw new Error(\"Order cannot be submitted empty\");\n    if (this.status !== \"draft\") throw new Error(\"Order already submitted\");\n    this.status = \"submitted\";\n  }\n}\n```\n\n## Limitations\n\n- This skill does not define deployment architecture.\n- It does not choose databases or transport protocols.\n- It should be paired with testing patterns for invariant coverage.\n"},"lastSynced":"2026-03-08T02:14:23.144Z","agentAnalysis":{"suitability":{"en":"Ideal for Domain-Driven Design Agents needing to translate domain rules into code structures and design aggregate boundaries.","zh":"适用于需要将领域规则转换为代码结构和设计聚合边界的领域驱动设计代理。","ja":"ドメイン駆動設計エージェントがドメインルールをコード構造に翻訳し、集約境界を設計するために最適です。","ko":"도메인 주도 설계 에이전트가 도메인 규칙을 코드 구조로 변환하고 집계 경계를 설계하는 데 적합합니다.","es":"Ideal para Agentes de Diseño Dirigido por Dominio que necesitan traducir reglas de dominio en estructuras de código y diseñar límites de agregados.","fr":"Idéal pour les agents de conception orientée domaine ayant besoin de traduire les règles de domaine en structures de code et concevoir les limites d''agrégats.","de":"Ideal für Agenten mit Domain-Driven Design, die Domänenregeln in Codestrukturen übersetzen und Aggregatgrenzen entwerfen müssen.","pt":"Ideal para Agentes de Design Dirigido por Domínio que precisam traduzir regras de domínio em estruturas de código e designar limites de agregados.","ru":"Идеально подходит для агентов Domain-Driven Design, которым необходимо переводить правила домена в кодовые структуры и проектировать границы агрегатов.","ar":"مثالي ليعاملات تصميم مدفوعة بال 领域 التي تحتاج إلى ترجمة قواعد المجال إلى هياكل البرمجية وتصميم حدود التجميع."},"recommendation":{"en":"Empowers agents to define repository contracts, design behavior-rich domain objects, and establish domain event boundaries using tactical patterns, refactoring anemic models, and ensuring invariants.","zh":"赋予代理定义存储库契约、设计行为丰富的领域对象并使用战术模式建立领域事件边界、重构贫血模型、确保不变量的能力。","ja":"リポジトリ契約を定義し、戦術パターンを使用してドメインイベント境界を thiết kếし、貧血モデルをリファクタリングし、不変量を確保することで、エージェントにドメインオブジェクトを設計する力を与えます。","ko":"仓库 계약을 정의하고, 전술 패턴을 사용하여 도메인 이벤트 경계를 설계하며, 빈혈 모델을 리팩토링하고, 불변식을 보장함으로써 에이전트가 도메인 객체를 설계할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a definir contratos de repositorio, diseñar objetos de dominio ricos en comportamiento y establecer límites de eventos de dominio utilizando patrones tácticos, refactorizando modelos anémicos y garantizando invariantes.","fr":"Permet aux agents de définir des contrats de référentiel, de concevoir des objets de domaine riches en comportement et d''établir des limites d''événements de domaine en utilisant des modèles tactiques, en refactorisant des modèles anémiques et en garantissant les invariants.","de":"Ermächtigt Agenten, Repository-Verträge zu definieren, verhaltensreiche Domänenobjekte zu entwerfen und Domänenereignisgrenzen unter Verwendung taktischer Muster zu etablieren, anämische Modelle umzubauen und Invarianten sicherzustellen.","pt":"Habilita os agentes a definir contratos de repositório, projetar objetos de domínio ricos em comportamento e estabelecer limites de eventos de domínio usando padrões táticos, refatorando modelos anêmicos e garantindo invariantes.","ru":"Наделяет агентов возможностью определять контракты репозитория, проектировать поведение-богатые объекты домена и устанавливать границы доменных событий с помощью тактических паттернов, рефакторинга анемических моделей и обеспечения инвариантов.","ar":"تمكين الوكلاء من تعريف عقود المستودع وتصميم كائنات المجال الغنية السلوك وتحديد حدود الأحداث المجالية باستخدام الأنماط التكتيكية وإعادة هيكلة النماذج الضعيفة وضمان الثوابت."},"useCases":{"en":["Translating domain rules into code structures for robust domain modeling","Designing aggregate boundaries and invariants for data consistency","Refactoring anemic models into behavior-rich domain objects for improved maintainability"],"zh":["将领域规则转换为代码结构以进行强大的领域建模","设计聚合边界和不变量以确保数据一致性","将贫血模型重构为行为丰富的领域对象以提高可维护性"],"ja":["強健なドメインモデリングのためにドメインルールをコード構造に翻訳する","データの一貫性を確保するために集約境界と不変量を設計する","メンテナンス性を向上させるために貧血モデルをリファクタリングして動作豊富なドメインオブジェクトを作成する"],"ko":["강력한 도메인 모델링을 위해 도메인 규칙을 코드 구조로 변환하는 것","데이터 일관성을 보장하기 위해 집계 경계와 불변식을 설계하는 것","유지 보수를 개선하기 위해 빈혈 모델을 리팩토링하여 행동이 풍부한 도메인 객체를 만드는 것"],"es":["Traducir reglas de dominio en estructuras de código para un modelado de dominio robusto","Diseñar límites de agregados e invariantes para la consistencia de los datos","Reconstruir modelos anémicos en objetos de dominio ricos en comportamiento para una mejor mantenibilidad"],"fr":["Traduire les règles de domaine en structures de code pour un modelage de domaine robuste","Concevoir les limites d''agrégats et les invariants pour la cohérence des données","Réaménager des modèles anémiques en objets de domaine riches en comportement pour une meilleure maintenabilité"],"de":["Domänenregeln in Codestrukturen übersetzen für ein robustes Domänenmodellieren","Aggregatgrenzen und Invarianten für die Datensicherheit entwerfen","Anämische Modelle in verhaltensreiche Domänenobjekte umbauen, um die Wartbarkeit zu verbessern"],"pt":["Traduzir regras de domínio em estruturas de código para modelagem de domínio robusta","Projetar limites de agregados e invariantes para consistência de dados","Refatorar modelos anêmicos em objetos de domínio ricos em comportamento para melhor manutenibilidade"],"ru":["Переводить правила домена в кодовые структуры для прочной моделирования домена","Проектировать границы агрегатов и инварианты для согласованности данных","Рефакторить анемические модели в поведение-богатые объекты домена для улучшения поддерживаемости"],"ar":["ترجمة قواعد المجال إلى هياكل البرمجية لنمذجة المجال القوية","تصميم حدود التجميع والثوابت لاتساق البيانات","إعادة هيكلة النماذج الضعيفة إلى كائنات المجال الغنية السلوك لتحسين الصيانة"]},"limitations":{"en":["Not suitable for defining strategic boundaries","Full DDD complexity must be justified for effective use","Not applicable for tasks limited to API documentation or UI layout"],"zh":["不适合定义战略边界","必须为有效使用提供完整的DDD复杂性","不适用于仅限于API文档或UI布局的任务"],"ja":["戦略的境界を定義するには適していない","効果的な使用のために完全なDDDの複雑さを正当化する必要がある","APIドキュメントやUIレイアウトのみに限定されているタスクには適用できない"],"ko":["전략적 경계를 정의하는 데 적합하지 않음","유효한 사용을 위해 완전한 DDD 복잡성을 정당화해야 함","API 문서 또는 UI 레이아웃에만 제한되는 작업에는 적용할 수 없음"],"es":["No es adecuado para definir límites estratégicos","La complejidad total de DDD debe justificarse para un uso efectivo","No se aplica a tareas limitadas a la documentación de API o la disposición de la interfaz de usuario"],"fr":["N''est pas adapté pour définir les limites stratégiques","La complexité totale de DDD doit être justifiée pour une utilisation efficace","N''est pas applicable aux tâches limitées à la documentation de l''API ou au layout de l''interface utilisateur"],"de":["Nicht geeignet, um strategische Grenzen zu definieren","Die volle DDD-Komplexität muss für eine effektive Verwendung gerechtfertigt werden","Nicht anwendbar für Aufgaben, die auf API-Dokumentation oder Benutzeroberflächen-Layout beschränkt sind"],"pt":["Não é adequado para definir limites estratégicos","A complexidade total do DDD deve ser justificada para uso eficaz","Não é aplicável para tarefas limitadas à documentação da API ou layout da UI"],"ru":["Не подходит для определения стратегических границ","Полная сложность DDD должна быть оправдана для эффективного использования","Не применимо для задач, ограниченных документацией API или макетом UI"],"ar":["ليس مناسبًا لتحديد حدود استراتيجية","يجب تبرير تعقيد DDD الكامل للاستخدام الفعال","لا ينطبق على المهام المحدودة لتوثيق API أو تخطيط واجهة المستخدم"]},"version":4},"contentHash":"87c9fbb689db32ca34cca75a2401120e9dd3254c3649e3c0e5b2db5131acab12","qualityScore":56}');
